window.__D("text/torat-shmuel/c055",{"p":[[2001910232,"מחמת שהגשמי הוא מסך מבדיל ומפריד היחוד עליון, היינו דבחי' יחו\"ע כו', וזהו כי עין בעין יראו<sup data-n=\"2043\">67</sup>, שעין הוא בחי' נבואה גילוי ההעלם כו' שיאיר בחי' גילוי ההעלם דעין דלעילא בחי' יחו\"ע היינו מה שאצלינו בהעלם, בעין דלתתא היינו בבחי' ביטול היש, שבבחי' ביטול היש יאיר ויתגלה בחי' ביטול אמיתי.\n<b>והנה</b> פסוק זה דכי עין בעין יראו, קאי על לע\"ל שהרי אמר אח\"כ בשוב כו', ופירושו שבגשמיות במקום<sup data-n=\"2044\">68</sup> העוה\"ז יומשך אור עליון, ועז\"נ נפלה ולא תוסיף קום<sup data-n=\"2045\">69</sup>, פי' קום הוא מלשון הגבהה ועלייה מלמטה למעלה כענין עליות העולמות בשבת<sup data-n=\"2046\">70</sup> ויו\"ט<sup data-n=\"2047\">71</sup> דהיינו שילוב אד' בהוי', וכמ\"ש בשבת שבת להוי'<sup data-n=\"2048\">72</sup> שהוא השביתה והעלייה בש' הוי', כי ששת ימים עשה<sup data-n=\"2049\">73</sup> הוא בחי' ירידת החיות להוות כלליות הנבראים, ובשבת הוא השביתה והחזרה למקורה כמ\"ש בכ\"ד, וזהו כי בו שבת<sup data-n=\"2050\">74</sup>, שז\"ע שבת להוי', וכן יו\"ט נק' מועדי הוי'<sup data-n=\"2051\">75</sup>, ובבחי' זו של קום לא תוסיף עוד, אלא שיהיו המשכות מלמעלה למטה ובמקום החשך דעכשיו שם ישכון אור א\"ס ב\"ה, והיינו כמארז\"ל עוה\"ב אין בו לא אכילה כו' אלא צדיקים יושבין ונהנין מזיו השכינה<sup data-n=\"2052\">76</sup>, דודאי אין ר\"ל שיהי' ביטול האברים הגשמי', דא\"כ מאי קמ\"ל שאין בו אכו\"ש, שהרי הנשמה קודם בואה לגוף ג\"כ לא הי' שייך בה שום דבר מעניני עוה\"ז ואכילה ושתי', אלא ודאי שעוה\"ב הכוונה על תחה\"מ (ולא על ג\"ע עולם הנשמות<sup data-n=\"2053\">77</sup> שאין זה רבותא כלל) שיהי' גוף ואברים ועכ\"ז לא יצטרכו לאכו\"ש, ולפ\"ז",[["2043","67","<b>כי עין בעין יראו</b>: ישעי' נב, ח. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380811\" data-slug=\"likkutei-torah\" data-id=\"4001380811\">לקו\"ת פ' ראה כג, ד</a>."],["2044","68","<b>שבגשמיות במקום . . באברים הגשמי'</b>: לשון הלקו\"ת ש\"ש סה, ד ואילך בהוספות ובשינויים."],["2045","69","<b>נפלה ולא תוסיף קום</b>: עמוס ה, ב [ושם: לא (וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381213\" data-slug=\"likkutei-torah\" data-id=\"4001381213\">לקו\"ת</a> כאן) — אבל כ\"ה בכ\"מ ומהם: זהר ויחי רלז, ב. פקודי רלט, ב. חידושי אגדות מהרש\"א לברכות ד, ב [ד\"ה לא נאמרה]. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה להבין בתוס' וכו' ב' פי' בציץ על יד הערה 56. לקו\"ת שה\"ש כא, א. מאמרי אדה\"א דברים ח\"א ס\"ע פז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010124\" data-slug=\"or-hatorah-hb\" data-id=\"8159010124\">אוה\"ת</a> בראשית כרך ו ע' 2100. חוקת ס\"ע תתי. נצבים ע' א'ריט. וראה ישעי' כד, כ].\nראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370423\" data-slug=\"torah-or\" data-id=\"3901370423\">תו\"א מג\"א צד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380541\" data-slug=\"likkutei-torah\" data-id=\"4001380541\">לקו\"ת חוקת נו, ב</a>. תצא מא, ב. ש\"ש כאן סה, ד. שה\"ש שם. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתכו. אוה\"ת בראשית שם ואילך."],["2046","70","<b>עליות העולמות בשבת</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540867\" data-slug=\"torat-chaim\" data-id=\"2300540867\">תו\"ח בא ח\"א קכז, א</a> הערה 667."],["2047","71","<b>עליות העולמות . . ויו\"ט</b>: ראה (בנוסף ללקו\"ת כאן) פע\"ח שער מקראי קדש ש\"כ, פ\"א ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370422\" data-slug=\"torah-or\" data-id=\"3901370422\">תו\"א מג\"א צד, א</a>. סה\"מ תרכ\"ז ע' רכ."],["2048","72","<b>שבת להוי'</b>: יתרו כ, י. ואתחנן ה, יד. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380258\" data-slug=\"likkutei-torah\" data-id=\"4001380258\">לקו\"ת בהר מב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370237\" data-slug=\"torah-or\" data-id=\"3901370237\">תו\"א שמות נג, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370292\" data-slug=\"torah-or\" data-id=\"3901370292\">בשלח סה, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370296\" data-slug=\"torah-or\" data-id=\"3901370296\">סו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370311\" data-slug=\"torah-or\" data-id=\"3901370311\">יתרו סט, ד</a>."],["2049","73","<b>כי ששת ימים עשה</b>: יתרו כ, יא. תשא לא, יז."],["2050","74","<b>כי בו שבת</b>: בראשית ב, ג."],["2051","75","<b>מועדי הוי'</b>: אמור כג, ב. ד. לז. מד. עזרא ג, ה."],["2052","76","<b>עוה\"ב . . ונהנין מזיו השכינה</b>: ראה ברכות יז, א. ראה גם (בנוסף ללקו\"ת כאן) מאמרי אדה\"א ויקרא ח\"א ע' קלה ואילך. המשך וככה תרל\"ז פצ\"א. פצ\"ב. וראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540807\" data-slug=\"torat-chaim\" data-id=\"2300540807\">תו\"ח בשלח ח\"א קצה, א</a>. סה\"מ תרל\"ט ח\"ב ע' תקנד ואילך. וש\"נ. תר\"ם ח\"ב ע' תשיט. וש\"נ."],["2053","77","<b>שעוה\"ב הכוונה על תחה\"מ . . עולם הנשמות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380138\" data-slug=\"likkutei-torah\" data-id=\"4001380138\">לקו\"ת צו טו, ג</a>: ”ולפ\"ד הרמב\"ם ז\"ל\" [ראה רמב\"ם הל' תשובה פ\"ח, ה\"ב. פיה\"מ ר\"פ חלק. (אגרת) מאמר תחיית המתים] ”קאי על עולם הנשמות\". ”והרמב\"ן ז\"ל\" [בסוף שער הגמול] ”השיב עליו . . שקאי על זמן תחיית המתים\". ובאוה\"ת חוקת ס\"ע תתט (ועד\"ז בכרך ה ע' א'תרלז): ”ורבינו ז\"ל בכל הדרושים הזכיר רק דעת הרמב\"ן לבד\". ראה גם מאמרי אדה\"א ויקרא ח\"א ע' מו ואילך. וש\"נ."]]],[2001910233,"צ\"ל מאחר שאין בו לא אכילה כו' א\"כ בריאות<sup data-n=\"2054\">78</sup> הגוף והאברים קרביים ואצטומכא יהי' לריק ח\"ו, אלא הענין שגם הגוף הגשמי יהי' ניזון מן הרוחניות, והיינו מה שיהנו מזיו השכינה יהי' זה מזון גם לגוף, וע\"ד משה כשהי' בהר שהי' גופו בשלימות והי' ניזון מרוחניות<sup data-n=\"2055\">79</sup>, רק לאחר שירד מן ההר הי' כלי גופו צריכים למזון מפני שהעולם לא נזדכך עדיין, משא\"כ לע\"ל שיזדכך חומריות העולם וראו כל בשר<sup data-n=\"2056\">80</sup> כו' אזי יהי' נמשך מזון עליון למטה גם במקום החשך בעוה\"ז באברים הגשמי', ולכן לא תוסיף קום בבחי' עליות מלמטלמ\"ע כ\"א שיהי' כי עין בעין יראו שיאיר מלמעלה למטה בחי' עין דלעילא<sup data-n=\"2057\">81</sup>), ועד\"ז יובן בענין דכתי' אשר עין בעין נראה, נראה אותיות אהרן<sup data-n=\"2058\">82</sup> שאהרן כה\"ג ע\"י הציץ שהוא בחי' הסתכלות<sup data-n=\"2059\">83</sup> דעינא עילאה בעינא תתאה (היינו<sup data-n=\"2060\">84</sup> שיהי' הגילוי מבחי' יחודא עילאה בחי' הארת פנים בחי' עיינין שנמשך מבחי' חכמת אדם בחי' ח\"ס תאיר פניו בחי' תיקון ואמת שפנוי משערות כו', בבחי' ד\"ת שנק' עלמא תתאה כו', בחי' ציצית, וזהו ציץ לשון מציץ מן החרכים שפי' רש\"י ל' ראיה כו', וע' לקמן<sup data-n=\"2061\">85</sup> בענין בחי' חרכים שבכותל דקדושה כו', ועכ\"ז צ\"ל שזהו הכל כשיש בחי' ד\"ת תחלה כמ\"ש בדרוש<sup data-n=\"2062\">86</sup> בענין כי עין בעין כו')<sup data-n=\"2063\">87</sup>.\nד) <b>ועתה</b> יובן ענין מ\"ש הנה זה עומד אחר כתלינו<sup data-n=\"2064\">88</sup>, פי' שיש ב' בחי' כותל, הא' הוא בחי' כותל דקדושה שהוא פי' ך\"ו ת\"ל<sup data-n=\"2065\">89</sup>, ך\"ו הוא מספר אותיות ש' הוי'<sup data-n=\"2066\">90</sup>, ת\"ל גימ' ה\"פ ש' אלקים<sup data-n=\"2067\">91</sup>, והיינו להיות יחוד ש' הוי' וש' אלקי' שזהו מ\"ש שמש ומגן הוי' אלקי'<sup data-n=\"2068\">92</sup>, וענין הכותל בקדושה הוא מ\"ש ויסב חזקיהו פניו אל הקיר<sup data-n=\"2069\">93</sup> פי' שהמשיך בחי' פניו דהיינו מ\"ש יאר ה' פניו אליך בקיר הוא בחי' מל'<sup data-n=\"2070\">94</sup> כמ\"ש",[["2054","78","<b>בריאות</b>: בלקו\"ת כאן: בריאת. ראה גם לעיל מאמר ד\"ה ועבדתם את ה\"א ובהערה 117."],["2055","79","<b>משה כשהי' בהר . . מרוחניות</b>: ראה שמו\"ר פמ\"ז, ה. ז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301730240\" data-slug=\"likkutei-sichot\" data-id=\"1301730240\">לקו\"ש תשא כרך לו ע' 172</a> ואילך ובהערות 37 ו39."],["2056","80","<b>וראו כל בשר</b>: ישעי' מ, ה. ראה גם סה\"מ תר\"ם ח\"ב ע' תשנא. וש\"נ."],["2057","81","<b>דלעילא)</b>: סיום הסוגר ניתוסף בכת\"י מעתיק [ראה לעיל הערה 1] ולא נרשם התחלתו."],["2058","82","<b>נראה אותיות אהרן</b>: ראה זהר אמור קג, א ובמק\"מ ובהרמ\"ז שם. מאמרי אדה\"א ויקרא ח\"ב ע' תשסז. וש\"נ. שמות ח\"ב ע' שמ. וש\"נ."],["2059","83","<b>הציץ . . הסתכלות</b>: ראה גם לעיל הערה 6."],["2060","84","<b>(היינו</b>: התחלת הסוגר ניתוסף בכת\"י מעתיק [ראה לעיל הערה 1] ולא נרשם סיומו. וראה לקמן הערה 87."],["2061","85","<b>לקמן</b>: פ\"ד ד\"ה ואמנם."],["2062","86","<b>כמ\"ש בדרוש</b>: פ\"ב ד\"ה ובאמת."],["2063","87","<b>כו')</b>: התחלת הסוגר הוא בריש הפרק."],["2064","88","<b>הנה זה עומד אחר כתלינו</b>: שה\"ש ב, ט."],["2065","89","<b>כותל . . ך\"ו ת\"ל</b>: ראה זהר רע\"מ משפטים קטז, רע\"א. אוה\"ת ישעי' כרך א ע' רכט."],["2066","90","<b>ך\"ו הוא . . ש' הוי'</b>: ראה זהר שם. שו\"ע (ואדה\"ז) או\"ח הל' ציצית סכ\"ד, ס\"ה (ס\"ז)."],["2067","91","<b>ת\"ל גימ' ה\"פ ש' אלקים</b>: מאו\"א מערכת כותל אות טז."],["2068","92","<b>שמש ומגן הוי' אלקי'</b>: תהלים פד, יב."],["2069","93","<b>ויסב חזקיהו פניו אל הקיר</b>: ישעי' לח, ב.\nראה גם לקמן בפנים על יד הערה סג ואילך."],["2070","94","<b>בקיר הוא בחי' מל'</b>: ראה זהר ויחי רכח, ב. תרומה קלג, א. מאו\"א מערכת קיר אות כג."]]],[2001910234,"בזהר שקיר בלשון יון<sup data-n=\"2072\">96</sup> אדון<sup data-n=\"2071\">95</sup> והוא ש' אד'<sup data-n=\"2073\">97</sup>, והיינו להיות יחוד ה' אלקי' ה' אד' (כי ש' אד' וש' אלקים הוא בחי' אחת<sup data-n=\"2074\">98</sup> כנ\"ל<sup data-n=\"2075\">99</sup>, ופי' אד'<sup data-n=\"2076\">100</sup> מל' אדון ואלקי' תקיף<sup data-n=\"2077\">101</sup> כמ\"ש בביאור שובה הנ\"ל<sup data-n=\"2078\">102</sup>), ומכאן למדו בגמרא שהמתפלל צריך שלא יהי' דבר חוצץ בינו לבין הקיר<sup data-n=\"2079\">103</sup>, והיינו כי המתפלל הוא הממשיך בחי' ש' הוי' באמרו ברוך אתה ה', ברוך ל' המשכה<sup data-n=\"2080\">104</sup>, ואומרים ח\"י ברכות נגד ח\"י חוליות השדרה<sup data-n=\"2081\">105</sup> להיות כי הברכה והשפע נמשך דרך בחי' ח\"י חוליות השדרה, וגם ח\"י הוא בחי' יסוד<sup data-n=\"2082\">106</sup> כו' ולכן צ\"ל שלא יהי' הפסק בינו לבין הקיר שלא יהי' דבר חוצץ, והיינו שיומשך ישר לקיר בחי' מל' וז\"ע כותל דקדושה.\n<b>והכותל</b> הב' הוא בחי' כותל בלעו\"ז שהוא מ\"ש ביחזקאל ונתתה אותה קיר ברזל בינך ובין העיר<sup data-n=\"2083\">107</sup> ומכאן ארז\"ל (ברכות דל\"ב ב') שמחרב<sup data-n=\"2084\">108</sup> בהמ\"ק נפסקה חומת ברזל בין ישראל לאביהם שבשמים, שבחי' כותל זה הוא לעומת הקיר דקדושה, והוא בחי' עמלק שהוא בגימ' ברזל עם הכולל<sup data-n=\"2085\">109</sup>, ונק' קיר ברזל, כי ברזל הוא נוק' דקליפה<sup data-n=\"2086\">110</sup> שהוא תכלית הרע והקליפה שמסתיר ומעלים לגמרי על אור ה' וקדושתו ולכן לא נא' ברזל לתרומת המשכן כמ\"ש זהב וכסף ונחושת<sup data-n=\"2087\">111</sup>, אבל ברזל לא נא' וכמ\"ש במד\"ר ס\"פ תרומה<sup data-n=\"2088\">112</sup>, וכן בבנין בהמ\"ק וכל כלי ברזל<sup data-n=\"2089\">113</sup> לא נשמע בבית בהבנותו, וכן גבי המזבח כתי' לא תניף עליהם ברזל<sup data-n=\"2090\">114</sup>, כי חרבך הנפת<sup data-n=\"2091\">115</sup> עלי' ותחללה, והיינו שהברזל פוסל בנגיעה<sup data-n=\"2092\">116</sup>, והוא מפני שהברזל הוא היפך ולעומת",[["2072","96","<b>בלשון יון</b>: אור החמה לזהר שם."],["2071","95","<b>שקיר בלשון יון אדון</b>: ראה זהר ויחי שם. ר\"ח ע\"ז יא, ב ד\"ה יום תגלחת. אוה\"ת תצוה כאן ע' א'תשלז. ישעי' שבהערה 103."],["2073","97","<b>אדון והוא ש' אד'</b>: ראה זהר בראשית טז, סע\"ב. שמות יג, א. שער היחוד והאמונה רפ\"ז. ברכות ז, רע\"ב. אוה\"ת ש\"ש ע' א'תפז ואילך. וראה גם אוה\"ת ויצא ח\"א רא, ב."],["2074","98","<b>ש' אד' וש' אלקים . . אחת</b>: ראה לקו\"ת ש\"ש סה, ד. לעיל מאמר ד\"ה ראה קראתי בשם ובהערה 94."],["2075","99","<b>כנ\"ל</b>: בהמאמר על יד הערה 165."],["2076","100","<b>ופי' אד'</b>: בגוכתי\"ק: ופי' ש' אד'. ואולי נשמט בשגגת המעתיק."],["2077","101","<b>ואלקי' תקיף</b>: שו\"ע אדה\"ז דין כוונת הברכות ס\"ה, ס\"ג."],["2078","102","<b>בביאור שובה הנ\"ל</b>: לקו\"ת ש\"ש סה, ד. ראה לעיל בשולי הגליון על יד הערה טו."],["2079","103","<b>שהמתפלל . . לבין הקיר</b>: ראה ברכות ה, ב. אוה\"ת ישעי' כרך א ע' רכח ואילך."],["2080","104","<b>ברוך ל' המשכה</b>: ראה גם לעיל מאמר ד\"ה קדש ישראל לה' רפ\"ג. וש\"נ."],["2081","105","<b>ח\"י ברכות . . חוליות השדרה</b>: ברכות כח, ב. זהר רע\"מ פינחס רנה, סע\"ב."],["2082","106","<b>ח\"י . . יסוד</b>: ראה זהר מקץ קצג, ב. רע\"מ עקב רעג, ב. פרדס שעה\"כ פ\"ח, מערכת חי. ע\"ח שער הכללים פ\"א. מאו\"א מערכת חי אות כד וביאיר נתיב שם."],["2083","107","<b>ונתתה אותה . . ובין העיר</b>: יחזקאל ד, ג."],["2084","108","<b>שמחרב</b>: אוצ\"ל: משחרב."],["2085","109","<b>עמלק . . ברזל עם הכולל</b>: ראה גם לעיל בהמאמר מגילה נקראת הערה 183."],["2086","110","<b>ברזל הוא נוק' דקליפה</b>: ראה אוה\"ת תרומה ע' א'תיג. תצוה כאן ע' א'תרצב. ע' א'תשלז. ע' א'תשלט. חוקת ע' תשסב. (כרך ו) ע' א'תתצו [ובמהדורת תשנ\"ח כרך א בהוספות ע' 50]."],["2087","111","<b>זהב וכסף ונחושת</b>: תרומה כה, ג."],["2088","112","<b>במד\"ר ס\"פ תרומה</b>: ראה שם פל\"ה, ה."],["2089","113","<b>וכל כלי ברזל</b>: מלכים-א ו, ז [ושם: כל — ראה גם לעיל בהמאמר מגילה נקראת ובהערה 181]."],["2090","114","<b>לא תניף עליהם ברזל</b>: תבוא כז, ה."],["2091","115","<b>כי חרבך הנפת</b>: יתרו כ, כב."],["2092","116","<b>שהברזל פוסל בנגיעה</b>: מדות פ\"ג, מ\"ד."]]],[2001910235,"בחי' המזבח כי המזבח לא נברא אלא להאריך ימיו של אדם, והברזל נברא<sup data-n=\"2093\">117</sup> לקצר ימיו של אדם, פי' המזבח נברא להאריך ימיו של אדם לפי שעל המזבח מקריבין קרבנות, וקרבן בגימ' ארך אפים<sup data-n=\"2094\">118</sup> והיינו שע\"י הקרבן ממשיכין מבחי' אריכא<sup data-n=\"2095\">119</sup> דאנפין להיות נושא עון<sup data-n=\"2096\">120</sup> כו', וגם פי' להאריך ימיו של אדם היינו בחי' אדם דלעילא, וכן בתפלה שבמקום קרבנות<sup data-n=\"2097\">121</sup> הנה ארז\"ל כל המאריך באחד<sup data-n=\"2098\">122</sup> מאריכין לו ימיו ושנותיו, פי' המאריך באחד כשמתבונן היטב איך דכולא קמי' כלא חשיב (בחי' ביטול המדות לאוא\"ס דלאו מכל אינון מדות<sup data-n=\"2099\">123</sup>) עי\"ז ממשיך מבחי' א\"א (בחי' כי לא אדם<sup data-n=\"2100\">124</sup> בבחי' אדם כו').\n<b>ואמנם</b> הברזל לא נברא אלא לקצר ימיו של אדם וזהו בחי' כותל דקליפה קיר ברזל שברזל גימט' עמלק, כי הנה בעמלק כתי' ראשית גוים<sup data-n=\"2101\">125</sup> עמלק פי' ז' גוים הם ז' מדות הרעות<sup data-n=\"2102\">126</sup> שבאדם וראשית גוים הוא עמלק שהוא קליפה שכנגד הדעת<sup data-n=\"2103\">127</sup>, והענין הוא דהנה ארז\"ל אין אדם עובר עבירה<sup data-n=\"2104\">128</sup> אלא א\"כ נכנס בו רוח שטות החופה ומכסה שנדמה לו שאינו דבר רע כ\"כ, (אבל אילו הי' יודע שזהו רע לא הי' עושה כלל), אבל עמלק הוא קליפה שכנגד הדעת היינו שיודע היטב\n\nואמנם<sup data-n=\"8336\">טז</sup> בחי'יז קיר ברזל דעמלק הוא היפך זה ממש שמקצר ימיו של אדם הנ\"ל, לפי שרצונו להגביה א\"ע לקבל מבחי' דכחשוכה כאורה<sup data-n=\"8338\">יח</sup> ורצונו לקצר ח\"ו ימיו של אדם דז\"א דהיינו להרס ח\"ו בנין הקדושה כו'<sup data-n=\"8337\">יז</sup>.",[["2093","117","<b>המזבח לא נברא . . והברזל נברא</b>: מדות שם."],["2094","118","<b>וקרבן בגימ' ארך אפים</b>: מאו\"א מערכת קרבן אות כא."],["2095","119","<b>אריכא</b>: בגוכתי\"ק: אריכו."],["2096","120","<b>נושא עון</b>: תשא לד, ז. שלח יד, יח. מיכה ז, יח."],["2097","121","<b>בתפלה שבמקום קרבנות</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["2098","122","<b>כל המאריך באחד</b>: ברכות יג, ב. ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' קעג ואילך [נדפס גם בסה\"מ תרכ\"ט ע' קסח ואילך]. ראה גם לקמן מאמר ד\"ה בגמ' וכו' קא מפלגי פ\"ג."],["2099","123","<b>דלאו מכל אינון מדות</b>: ת\"ז בהקדמה יז, ב."],["2100","124","<b>כי לא אדם</b>: שמו\"א טו, כט."],["2101","125","<b>ראשית גוים עמלק</b>: בלק כד, כ."],["2102","126","<b>ז' גוים הם ז' מדות הרעות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370426\" data-slug=\"torah-or\" data-id=\"3901370426\">תו\"א מג\"א צה, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370442\" data-slug=\"torah-or\" data-id=\"3901370442\">צט, סע\"א</a>. מאמרי אדה\"א קונטרסים ע' רמא. וש\"נ. ש\"א סא, ב ובהערה 20. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550236\" data-slug=\"torat-chaim\" data-id=\"2300550236\">תו\"ח יתרו ח\"ב ער, ג</a>. וש\"נ."],["2103","127","<b>עמלק שהוא . . הדעת</b>: ראה מאורי אור מערכת עמלק אות עט. לעיל מאמר ד\"ה זכור את יום השבת פ\"ד הערה יד."],["2104","128","<b>אין אדם עובר עבירה</b>: סוטה ג, א. ראה מאמרי אדה\"א דברים ח\"ב ע' תרמה. וש\"נ.\n\n<b>טז</b> ) <b>ואמנם</b>: נרשם אחרי פיסקא והכותל הב' (וקודם פיסקא ואמנם הברזל) באמצע העמוד, ובצד הימני של העמוד בהפסק קו באה הוראה להמעתיק: להעתיק בשפולי העמוד.\n\n<b>יח</b> ) <b>דכחשוכה כאורה</b>: ראה הערה 129.\n\n<b>יז</b> ) <b>ואמנם בחי' . . כו'</b>: בגוכתי\"ק: (ואמנם בחי' . . כו'). ואולי מפני שבאה בפנים לכן ניתוספו סוגרים."]]],[2001910236,"שהוא רע היפך הקדושה (וז\"ע שמקצר ימיו של אדם) ואעפ\"כ רצונו בזה ומגביה א\"ע לקבל חיות מהקדושה מבחי' אשר שם כחשוכה כאורה<sup data-n=\"2105\">129</sup> שוין כו', וזהו אם תגביהי כנשר<sup data-n=\"2106\">130</sup> לקבל ממקום גבוה ע\"ד דרך הנשר בשמים<sup data-n=\"2107\">131</sup> כו' אך אעפ\"כ משם אורידך נאום הוי'<sup data-n=\"2108\">132</sup> שאעפ\"כ גם משם נמשך השפע דרך שם הוי' המברר שיומשך השפע למקום הראוי דוקא כמ\"ש במ\"א, וז\"ע הקיר ברזל דעמלק שהוא היפך הקיר דקדושה. אך ע\"י הרהורי תשובה, בחי' לב נשבר ונדכה<sup data-n=\"2109\">133</sup> עי\"ז עושים חלונות וחרכים בהכותל להיות מאיר אוא\"ס ב\"ה דרך חלונות וחרכים. ובאמת מצינו לשון חרכים גם בקדושה, והיינו שמחמת ריבוי האור א\"א להאיר כ\"א ע\"י חרכים שהם נקבי העין חוטם פה אוזן דא\"ק כו' (וזהו הנה זה עומד אחר כתלינו כו' מציץ כו', פי' כתלינו לשון רבים ב' בחי' כותל הנ\"ל, שכותל דעמלק נק' ג\"כ כתלינו מפני כי לא אמרו בגמ' שחומת ברזל מפסקת בין אביהם שבשמים לישראל, כ\"א בין ישראל לאבשב\"ש, והיינו שזהו ע\"י שעוונותיכם היו מבדילים (ישעי' נ\"ט ב') כמ\"ש בת\"א<sup data-n=\"2110\">134</sup>. ועכ\"ז ע\"י התשובה דלב נשבר עושים חלונות וחרכים, שהגם שאין שוברים כל הכותל עכ\"ז הנה זה עומד כו', פי' זה הוא לשון גילוי שעומד להאיר לנו ע\"י בחי' חלונות וחרכים שעושים ע\"י בחי' לב נשבר דתשובה הנ\"ל. וי\"ל שחלונות נעשים ע\"י תשובה עילאה, וחרכים ע\"י בחי' תשובה תתאה. והכותל הב' הוא בחי' כותל דקדושה הנ\"ל ך\"ו ת\"ל יחוד ה' ואלקי' פניו אל הקיר כו' שי\"ל שבחי' החרכים שבכותל זה זהו ע\"ד משנת\"ל שמחמת ריבוי האור דא\"ק א\"א להאיר כ\"א ע\"י חרכים דאח\"פ, ובחי' נקבי העין דבחי' כי עין בעין נראה שז\"ע ציץ לשון ראי' כו', והעושה כ\"ז הוא משה דוקא כשי\"ת).\nש\"פ שמיני<sup data-n=\"2111\">135</sup>\nה) <b>והנה</b> כתי' ועשית ציץ זהב טהור<sup data-n=\"2112\">136</sup>, שמשה דוקא הוא העושה בחי' הציץ לאהרן כהנא רבא, וצ\"ל מה תלוי ענין הציץ במשה דוקא, והענין הוא דענין קריאת שמו משה זהו ע\"ש כי מן המים משיתיהו<sup data-n=\"2113\">137</sup>, ופי' מן המים היינו מן בחי' מים",[["2105","129","<b>כחשוכה כאורה</b>: ראה תהלים קלט, יב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380124\" data-slug=\"likkutei-torah\" data-id=\"4001380124\">לקו\"ת צו יב, א</a>. סה\"מ תר\"ם ח\"א ע' שו. וש\"נ."],["2106","130","<b>אם תגביהי כנשר</b>: עובדי' א, ד [ושם: תגביה, וכ\"ה בגוכתי\"ק. הלשון שבפנים — ראה לקמן מאמר ד\"ה והנה תורה היא בחי' קו האמצעי קרוב לסופו. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 88. סה\"מ תרכ\"ז ע' רנח. תרל\"ח ע' קכו. וש\"נ]."],["2107","131","<b>דרך הנשר בשמים</b>: משלי ל, יט."],["2108","132","<b>משם אורידך נאום הוי'</b>: סיום הכתוב אם תגביה [עובדי' א, ד]. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370122\" data-slug=\"torah-or\" data-id=\"3901370122\">תו\"א וישלח כו, ב</a>. מאמרי אדה\"ז תקס\"ו ע' פד ואילך [ובמהדורת תשס\"ד ע' קסח ואילך]."],["2109","133","<b>לב נשבר ונדכה</b>: תהלים נא, יט. ראה גם סה\"מ תר\"ם ח\"ב ע' תקמ הערה ז."],["2110","134","<b>שעוונותיכם היו . . בת\"א</b>: תצוה כאן פג, א."],["2111","135","<b>ש\"פ שמיני</b>: ניתוסף ע\"י המו\"ל — ראה לעיל הערה 1."],["2112","136","<b>ועשית ציץ זהב טהור</b>: תצוה כח, לו. ראה גם לקמן שולי הגליון נז בסופו."],["2113","137","<b>כי מן המים משיתיהו</b>: שמות ב, י. ראה מאמרי אדה\"א שמות ח\"ב ע' שצד ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540049\" data-slug=\"torat-chaim\" data-id=\"2300540049\">תו\"ח שמות ח\"א מג, א</a>. וש\"נ. ראה גם פלח הרמון מג\"א כאן ע' שנו."]]],[2001910237,"דלעילא משיתיהו, כי הנה כתי' יהי רקיע כו' ויהי מבדיל<sup data-n=\"2114\">138</sup>, ואח\"כ כתיב ויעש אלקים את הרקיע ויבדל<sup data-n=\"2115\">139</sup> בין המים כו' שנא' ב\"פ הבדלה, ויהי מבדיל, ויבדל, והיינו שיש ב' בחי' הבדלות האחד הוא בחי' ההבדלה שבין קודש לחול, וה\"ז כמו באדם הקרומא דפסיק באמצעות מיעא דבר נש<sup data-n=\"2116\">140</sup>, והוא החצר הכבד המפסיק בין איברי הנשימה לאיברי המזון, שאנו רואים שלמטה מחצר הכבד היינו באיברי המזון יש שם תערובות פסולת שמתברר מהמאכל כו', משא\"כ למעלה מחצר הכבד ששם משכן איברי הנשימה אין שם פסולת כו', ועד\"ז יובן בנמשל למעלה שלמטה מן הפרסא ורקיע המבדיל בין קודש לחול שם מעורב טו\"ר, וכנודע שבבריאה מעורב טו\"ר<sup data-n=\"2117\">141</sup> (ודע שכל תערובות אינו בי\"ס דבי\"ע ח\"ו רק בהעולמות עצמן כ\"כ בע\"ח שער הקליפות פ\"ג רק שבבריאה רובו טוב ומיעוטו רע<sup data-n=\"2118\">142</sup>, גם הטוב גובר על הרע כמ\"ש במאה\"ז בחקתי דקי\"ד ע\"ב ד\"ה דומה דודי לצבי<sup data-n=\"2119\">143</sup>), אך למעלה מן הפרסא ורקיע המבדיל הוא בחי' קודש ואין שם שום תערובות רע כלל וכלל כי לא יגורך רע<sup data-n=\"2120\">144</sup> כתיב, (והגם שיש קליפה לעו\"ז<sup data-n=\"2122\">146</sup> גם נגד עולם האצי'<sup data-n=\"2121\">145</sup>, אמנם אינם עומדים באצי' כ\"א בבריאה כי באצי' לא יגורך רע כמ\"ש בע\"ח<sup data-n=\"2123\">147</sup> ועמ\"ש מזה בד\"ה\n\nדהנה<sup data-n=\"8339\">יט</sup> נת\"ל<sup data-n=\"8340\">כ</sup> שיש ב' בחי' כותל הא' בקדושה קיר דחזקי' פניו אל הקיר בחי' הארת פנים דחכ' אדם דח\"ס שתאיר פניו דז\"א ושזה יומשך אל הקיר בחי' מל' ש' אד', ויש בזה חרכים שהוא מה שהגילוי מבחי' גבוה שמחמת שהאור שם בריבוי א\"א להיות כ\"א ע\"י חרכים כו', ויש בחי' כותל שבלעו\"ז שהוא בחי' קיר ברזל דעמלק שהוא בחי' עוונותיכם היו מבדילים, וע\"י התשובה דלב נשבר הגם שאין שוברין כל הכותל מ\"מ עושים חלונות וחרכים, וכדי שיעשו החלונות וחרכים זהו ע\"י משה דוקא, כי משה דוקא יכול להעביר קליפת עמלק, וצ\"ל מפני מה משה דוקא ויובן בהקדם ענין קריאת שם משה ל' שזהו ע\"ש כי מן המים משיתיהו.",[["2114","138","<b>יהי רקיע . . מבדיל</b>: בראשית א, ו."],["2115","139","<b>ויעש אלקים . . ויבדל</b>: בראשית א, ז. ראה גם לקו\"ת ואתחנן יא, ב ובהנסמן במ\"מ לשם."],["2116","140","<b>הקרומא דפסיק . . דבר נש</b>: ראה זהר בראשית לב, ב."],["2117","141","<b>שבבריאה מעורב טו\"ר</b>: ראה ע\"ח המצויין בסמוך בפנים. סה\"מ תר\"ם ח\"ב ע' תתו. וש\"נ. ביאוה\"ז דבסמוך."],["2118","142","<b>שבבריאה . . מיעוטו רע</b>: ראה גם סה\"מ תרל\"ח ע' קסז ד\"ה וכפשוטו."],["2119","143","<b>כמ\"ש . . דומה דודי לצבי</b>: ראה ביאוה\"ז להצ\"צ בחוקותי כרך א ע' תמד."],["2120","144","<b>לא יגורך רע</b>: תהלים ה, ה. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380322\" data-slug=\"likkutei-torah\" data-id=\"4001380322\">לקו\"ת במדבר ג, ג</a>."],["2122","146","<b>לעו\"ז</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["2121","145","<b>קליפה . . נגד עולם האצי'</b>: ראה לקו\"ת שמיני כא, א. לעיל בהמאמר מגילה נקראת הערה 18."],["2123","147","<b>עומדים . . בבריאה . . כמ\"ש בע\"ח</b>: ראה אוה\"ת ויצא כרך ה' ע' תתמה: ”כ\"מ בע\"ח שער הקליפות פ\"ב . . בשער ק\"נ פ\"ט\" ע\"ש. לעיל בהמאמר מגילה נקראת הערה 20.\n\n<b>יט</b> ) <b>דהנה</b>: בגוכתי\"ק באה הערה זו בין שאר ההערות השייכים לקמן ללא ציון מקומה. בכת\"י מעתיק [ראה לעיל הערה 1], נרשם זה בפ\"ה ונרשם בהיפך העמוד. ראה הערה 135 שכאן מתחיל מאמר חדש, ומזה מובן הבא לקמן.\n\n<b>כ</b> ) <b>נת\"ל</b>: פ\"ד."]]],[2001910238,"אני חומה פ\"ד<sup data-n=\"2124\">148</sup> בענין ושדי כמגדלות), וזהו ההבדלה שבין קדש לחול שבחול מעורב טו\"ר, ובבחי' קדש לא יגורך רע וביניהם יש רקיע המבדיל. ואמנם יש עוד בחי' הבדלה ב' הוא ההבדלה שבין קודש לקדש, ודוגמתו במשל באדם הוא הקרומא דחפיא על מוחא<sup data-n=\"2125\">149</sup> (מלבד הקרומים שהמוח מונח בתוכו, כ\"א קרום רוחני, ונק' קרומא דאוירא<sup data-n=\"2126\">150</sup>), שהוא הרקיע המבדיל היינו הפרסא שמפסיק בין בחי' אויר לבחי' חכמה, והיינו כי חכמה דאצי' אתפתחין לל\"ב שבילין<sup data-n=\"2127\">151</sup>, אך בחי' חכמה סתימאה סתים ונעלם (ולא אתפתח שזהו מפני הקרומא דחפיא על מוחא סתימאה כמ\"ש באד\"ר דקך\"ח ע\"ב) ובמשה דכתי' בי' כי מן המים משיתיהו היינו מבחי' מים דלעילא שלמעלה מן הפרסא שעל מוחא סתימאה (והיינו שהי' מים החכמה דמו\"ס כו', וענין השם הוא המקשר הנשמה בגוף כמ\"ש בלק\"ת בד\"ה את שבתותי תשמרו פ\"ב<sup data-n=\"2128\">152</sup> שהנשמה קודם בואה לגוף אינה נק' בשם כלל, כמ\"ש בלק\"ת בד\"ה מי מנה ספ\"א<sup data-n=\"2130\">154</sup> בענין ולאדם לא מצא עזר, וגם לגוף עצמו אין השם מועיל, כ\"א השם מקשר הנשמה בגוף והחיות הנמשך מהנשמה ומחי' הגוף נשרש בהשם<sup data-n=\"2129\">153</sup>, א\"כ שם משה שהוא ע\"ש כי מן המים דים החכמה דחכמה סתימאה משיתיהו, הנה נשרש\n\nהשם<sup data-n=\"8341\">כא</sup> חיותו, ומשה משה לא פסיק טעמא<sup data-n=\"8342\">כב</sup> שגם בגוף הי' כמו בשרשו, וע' בד\"ה שבתותי<sup data-n=\"8343\">כג</sup> (בש' הרמב\"ן<sup data-n=\"8344\">כד</sup> בפי' עזר) שהשם מחבר הנשמה בגוף א\"כ א\"צ למה שלא פסיק.\nע'ד בס' הדרת מלךה דצ\"ב סע\"או בשם הע\"חז בענין הסתכלות מצחא דז\"אח או או\"א בעתיקא והב' הוא הסתכלות עתיק בהם, ושם אם ההסתכלות היא במצח או בעיינין, ושם הסתכלות עין א' או ב' עיינין, ומזה יובן משנת\"ל ספ\"א ענין הסתכלות דעלמא עילאה בעלמא תתאה ע\"י בחי' עיינין ובחי' ש\"ע נהורין שביאר בהדרת מלך דצ\"ב ע\"בט.",[["2124","148","<b>בד\"ה אני חומה פ\"ד</b>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770389\" data-slug=\"or-hatorah-hb\" data-id=\"8316770389\">אוה\"ת שה\"ש כרך ב ע' תשנז</a>. כרך ג ריש ע' א'י."],["2125","149","<b>הקרומא דחפיא על מוחא</b>: ראה זהר אד\"ר נשא קכח, ב."],["2126","150","<b>קרומא דאוירא</b>: ראה זהר ספרא דצניעותא תרומה קעו, ב. אד\"ר שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380672\" data-slug=\"likkutei-torah\" data-id=\"4001380672\">לקו\"ת מטות פז, ג</a>."],["2127","151","<b>אתפתחין לל\"ב שבילין</b>: אד\"ר שם."],["2128","152","<b>בלק\"ת . . פ\"ב</b>: בהר מא, ג.\nראה גם לקמן בפנים לאחרי המאמר (אצל הערה סו) פיסקא בלק\"ת."],["2130","154","<b>בלק\"ת . . ספ\"א</b>: בלק סז, ג."],["2129","153","<b>שהנשמה קודם . . בהשם</b>: ע\"פ לשון לקו\"ת שם.\n\n<b>כא</b> ) <b> השם</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים.\n\n<b>כב</b> ) <b>ומשה משה לא פסיק טעמא</b>: שמות ג, ד. זהר וירא קכב, ב. נשא אד\"ר קלח, א. בלק קפז, ב. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550300\" data-slug=\"torat-chaim\" data-id=\"2300550300\">תו\"ח משפטים ח\"ב רפג, ג</a>. וש\"נ. סה\"מ תר\"ל ע' נו ואילך.\n\n<b>כג</b> ) <b>בד\"ה שבתותי</b>: בהר מא, ג.\n\n<b>כד</b> ) <b>בש' הרמב\"ן</b>: לבראשית ב, יט."]]],[2001910239,"בשמו בחי' חכ\"ס להחיות הגוף שלו למטה כו'), ולכן הי' יכול להמשיך בחי' תורה כי תורה היא רק בחי' נובלות חכ' שלמעלה (כמארז\"ל במד\"ר בראשית פי\"ז<sup data-n=\"2131\">155</sup>, וי\"ל שזהו כמ\"ש בביאור שני דיונתי שבלק\"ת<sup data-n=\"2132\">156</sup> כי התורה הנגלית היא בחי' הארת חכ' המתלבשת במדות, ולכן הם שתא סדרי משנה<sup data-n=\"2133\">157</sup> כנגד ששה מדות<sup data-n=\"2134\">158</sup> עליונות, וזהו ג\"כ ענין כשר פסול טמא טהור חייב וזכאי שהוא בחי' חסד וגבורה, שכשר טהור וזכאי זהו מצד החסד בחי' ימין מקרבת<sup data-n=\"2135\">159</sup> שיוכל להתעלות ליכלל באור א\"ס, ופסול טמא חייב היינו בחי' גבורה שמאל דוחה<sup data-n=\"2136\">160</sup> שא\"א להתעלות כו', והכל ע\"פ החכ' המתלבשת במדות, אבל לגבי בחי' עצם חכמתו ית' שחכים ולא בחכ' ידיעא<sup data-n=\"2137\">161</sup> שהיא רמה ונשגבה למעלה מהמדות נק' התורה רק נובלות חכמה לבד, ומשה הוא מעצמיות חכ' עילאה מקור התורה לכן נא' במשה כבד פה<sup data-n=\"2138\">162</sup> לגבי אורייתא דבע\"פ כו' וכבד לשון לגבי תושב\"כ, שלא הי' יכול להשפיל א\"ע להיות נמשך ממנו התורה שהיא נובלות חכ' כ\"כ בביאור הנ\"ל, אמנם ביאור זה נראה שזהו ע\"פ מ\"ש במ\"א שנק' התורה נובלות חכמה שלמעלה, כי מה שנמשך מבחי' ח\"ע להתהוות אותיות התורה אינה אלא מבחי' אחוריים וחיצוניות החכמה שהיא נובלות חכמה (בביאור תורה צוה שבלק\"ת<sup data-n=\"2139\">163</sup>) וע' שם<sup data-n=\"2140\">164</sup> בענין וזרח משעיר<sup data-n=\"2141\">165</sup> דכתי' במ\"ת שפירושו שער יו\"ד שהתורה שהיא חכ' דאצי' נמשכה מבחי' ח\"ס ע\"י שערות לבד שהשערה עצמה היא בחי' וא\"ו והאור שבתוך השערה הוא בחי' יוד<sup data-n=\"2142\">166</sup> כנודע שהשערה חלולה<sup data-n=\"2143\">167</sup> ומלובש בתוכה יניקת המוח, והענין הוא הגם דאוריי' מחכ' נפקת<sup data-n=\"2144\">168</sup> הוא בחי' ח\"ע דאצי', אמנם התהוות החכ'<sup data-n=\"2145\">169</sup> מלמעלה מן החכ' הוא רק מאין כמ\"ש והחכ' מאין תמצא<sup data-n=\"2146\">170</sup>, שהתהוות החכ' מהכתר הוא מבחי' אין, כי מה שלמעלה מהחכ' אינה ממהות חכ' כלל, ולכן חכ' שבכתר נק' חכ' סתימאה, וכנ\"ל שסתום ונעלם, ואינה נק'",[["2131","155","<b>פי\"ז</b>: סימן ה."],["2132","156","<b>בביאור שני דיונתי שבלק\"ת</b>: שה\"ש יט, ב. הבא בסמוך בפנים הוא ע\"פ לשון הלקו\"ת שם."],["2133","157","<b>שתא סדרי משנה</b>: ראה זהר בראשית מב, א. במד\"ר פי\"ב, יז. פי\"ג, טוטז. שבת לא, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111064\" data-slug=\"likkutei-sichot\" data-id=\"1300111064\">לקו\"ש בשלח כרך יא ע' 56</a> הערה 13."],["2134","158","<b>שתא . . ששה מדות</b>: ראה ת\"ז בהקדמה ה, א. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה ד\"ה ועבדתם את ה\"א ובהערה 87."],["2135","159","<b>ימין מקרבת</b>: סוטה מז, א."],["2136","160","<b>שמאל דוחה</b>: סוטה שם."],["2137","161","<b>שחכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה יז, ב."],["2138","162","<b>כבד פה</b>: שמות ד, י. ראה זהר רע\"מ צו כח, א. מאמרי אדה\"א דברים ח\"ג ע' תתצו. וש\"נ. תו\"ח שמות ח\"א מז. ד. וש\"נ. קונט' בר מצוה תרנ\"ג ע' נב (סה\"מ תרמ\"ד מהדורת תשס\"ב ע' שכב). לקמן מאמר ד\"ה כל אשר חפץ ה' עשה על יד הערה 53."],["2139","163","<b>מ\"ש במ\"א . . תורה צוה שבלק\"ת</b>: ברכה צה, רע\"ב."],["2140","164","<b>וע' שם</b>: צה, ג. הבא בסמוך בפנים הוא ע\"פ לשון הלקו\"ת שם."],["2141","165","<b>וזרח משעיר</b>: ברכה לג, ב."],["2142","166","<b>שהשערה . . וא\"ו והאור . . יוד</b>: ראה לקו\"ת להאריז\"ל תולדות עה\"פ (כה, כא) ויעתר יצחק."],["2143","167","<b>שהשערה חלולה</b>: ראה נזיר לט, א."],["2144","168","<b>דאוריי' מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["2145","169","<b>אמנם התהוות החכ'</b>: הבא בסמוך בפנים הוא ע\"פ לשון לקו\"ת שם צה, ב ואילך."],["2146","170","<b>והחכ' מאין תמצא</b>: איוב כח, יב. ראה אגה\"ק סי\"ז קכו, רע\"א. מאמרי אדה\"א דברים ח\"ג ע' תשעט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670072\" data-slug=\"torat-chaim\" data-id=\"2300670072\">תו\"ח בראשית ז, ד</a> ובהערה 49. בא ח\"א קא, ג. וש\"נ. לקמן מאמר ד\"ה והנה תורה היא בחי' קו האמצעי על יד הערה 224 ואילך."]]],[2001910240,"בשם חכ' כ\"א ע\"ש שהיא מקור החכ' שבאצי', אך אין התהוות החכ' דאצי' בדרך עו\"ע מבחי' ח\"ס כ\"א ע\"י בחי' דילוג הערך, וכמ\"ש בע\"ח<sup data-n=\"2147\">171</sup> ובאד\"ז דרצ\"ב ע\"ב<sup data-n=\"2148\">172</sup> או\"א במזלא אתכלילן וביה תליין כו', והיינו שאו\"א יונקי' מבחי' שערות דתקוני דיקנא הנמשכים ממו\"ס, שאם היות השערה נמשכה מהמוח מ\"מ ה\"ז רק מבחי' מותרי מוחין לבד ואינו בערך לבחי' עצם המוחין דח\"ס, כי ניקב קרום של מוח טריפה<sup data-n=\"2149\">173</sup>, והשערות יכולים לגוזזם בלי שום כאב, ונק' השערות דתקוני דיקנא בשם צומח שבמדבר כמ\"ש מזה בביאור תורה צוה שבלק\"ת פ\"א<sup data-n=\"2150\">174</sup>, ובמ\"א בד\"ה בחללא דגלגלתא קרומא דאוירא בבה\"ז נשא דקך\"ח<sup data-n=\"2151\">175</sup> שהם בחי' צומח שבחי, ולכן נק' התורה דמחכמה נפקת בשם נובלות חכ' שלמעלה היינו בחי' נובלות והארה מועטת שנמשך מבחי' ח\"ס היא בחי' חכ' שלמעלה להתהוות החכ' הוא בחי' תושב\"כ כו'), ולכן כלליות התורה הם ך\"ד ספרין דאורייתא<sup data-n=\"2152\">176</sup> הם רק כד מים החכ' לבד (וכמ\"ש וכדה על שכמה<sup data-n=\"2153\">177</sup>, וכמשל ביטול הכד אחד לגבי הים או המעיין, כך ערך תושב\"כ לגבי עצם בחי' ח\"ס כו'), אבל משה (נת' שנשמתו שהחי' גופו) הי' מים החכמה (שלמעלה מפרסא ראשונה) עצמו, ולכן נק' התורה על שמו כמ\"ש זכרו תורת משה עבדי<sup data-n=\"2154\">178</sup>, וכתי' תורה צוה לנו משה<sup data-n=\"2155\">179</sup> (לפי שמשה הוא<sup data-n=\"2156\">180</sup> מים החכ' סתימאה עצמו הוא דוקא המשיך בחי' תורה כד מים החכ' כו'), ולכן (מובן ג\"כ) שמשה דוקא הי' יכול להעביר קליפת עמלק לגמרי כי מחמת עוצם הגילוי דבחי' משה הי' ממילא נדחה הרע דבחי' עמלק, וכמ\"כ ע\"י לימוד התורה נדחה ג\"כ הרע דעמלק (שאם היותה נובלות חכ' עכ\"ז הנה היא כד מים החכמה כו' וגם כמשנ\"ת לקמן בענין פיתוחי חותם שבתורה שזהו מבחי' תיקון ואמת וזהו בחי' המאור שבה כו'). אך הנה\n\nבביאור<sup data-n=\"8345\">כה</sup> ב' דיונתי נובלות הארת החכ' שבמדות, ובביאור תורה צוה נובלות אותיות בחי' אחרונה מחכ', וגם מה שזרח משעיר שער יו\"ד שערות דדיקנא צומח שבמו\"ס, וע' בבה\"ז נשא בביאור האד\"ר דקך\"ח ב' קרוב לסוף המאמר.",[["2147","171","<b>בע\"ח</b>: שער הולדת או\"א וזו\"נ שט\"ז, פ\"ו מזהר אד\"ז האזינו רפט, ב."],["2148","172","<b>ע\"ב</b>: בלקו\"ת כאן צה, רע\"ג: ע\"א."],["2149","173","<b>ניקב קרום של מוח טריפה</b>: חולין מב, א (במשנה)."],["2150","174","<b>שבלק\"ת פ\"א</b>: ברכה כאן צה, ג."],["2151","175","<b>בד\"ה בחללא דגלגלתא . . דקך\"ח</b>: ביאוה\"ז נשא פט, ג.\nראה גם לקמן בפנים (לאחרי המאמר), אצל הערה עו, פיסקא בבה\"ז נשא דקך\"ח ע\"ב."],["2152","176","<b>ך\"ד ספרין דאורייתא</b>: ראה שמו\"ר פכ\"ד, ה. שהש\"ר פ\"ד, יא. תנחומא תשא טז. ילקוט שמעוני תשא לא, יח (רמז שצא). זהר אד\"ז האזינו רצג, ב. ת\"ז בהקדמה יד, א. תכ\"א מו, ב. מז, א. תקונא שתיתאה קמה, א."],["2153","177","<b>ך\"ד ספרין . . וכדה על שכמה</b>: ח\"ש כד, טו. ראה לקמן מאמר ד\"ה וידבר כו' קדושים תהיו ובהערה 99."],["2154","178","<b>זכרו תורת משה עבדי</b>: מלאכי ג, כב."],["2155","179","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["2156","180","<b>הוא</b>: בגוכתי\"ק: שהוא.\n\n<b>כה</b> ) <b>בביאור</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים."]]],[2001910241,"זהו כשהתורה היא תורת משה, היינו כשלומד תורה בבחי' ביטול (אז ע\"י בחי' עוצם האור דבחי' תורה אור נדחה הרע דעמלק). וזהו ועשית ציץ שמשה דוקא הוא העושה הציץ כו', ופי' זהב טהור היינו ההמשכה מבחי' זהב טהור בחי' בינה<sup data-n=\"2157\">181</sup> (וכמשנת\"ל שהציץ הוא סימן דעלמא עילאה בחי' הארת הכתר בחי' ע\"י וא\"א המאירים בבינה עולם התענוג).\n<b>ופתחת</b><sup data-n=\"2158\">182</sup> עליו פתוחי חותם<sup data-n=\"2159\">183</sup> פי' חותם, פי' חותם<sup data-n=\"2160\">184</sup> היינו כמארז\"ל חותמו של הקב\"ה אמת<sup data-n=\"2161\">185</sup>, ואין אמת אלא תורה<sup data-n=\"2162\">186</sup>, (וכמ\"ש תורת אמת היתה בפיהו (מלאכי ב' וא\"ו) וכתי' אמת קנה (משלי ך\"ג ך\"ג) שקאי על התורה שנק' אמת לפי שבה מאיר מבחי' תיקון ואמת שפנוי משערות, וזהו כי באור פניך<sup data-n=\"2163\">187</sup> נתת לנו תורת חיים היינו בחי' אור פני מלך<sup data-n=\"2164\">188</sup>, שהוא בחי' מה שחכמת אדם דח\"ס תאיר פניו דז\"א כמ\"ש תתן אמת ליעקב שז\"ע יגמה\"ר שאמר משה<sup data-n=\"2165\">189</sup> שהמשיך בחי' יגת\"ד דא\"א בז\"א, להיות גם בז\"א יגמה\"ר כמ\"ש באדרא דנשא דקל\"א ע\"ב ודקל\"ח ע\"א וכאשר נמשך בז\"א אז דוקא נק' ואמת, ומז\"א מאיר במל' שנק' עלמא תתאה<sup data-n=\"2166\">190</sup> שז\"ע עיניך יונים<sup data-n=\"2167\">191</sup> שכמו זוג יונים שהזיווג שלהם הוא ע\"י הסתכלות<sup data-n=\"2168\">192</sup> כו' וכך המל' מקבלת מז\"א בחי' הארת פנים מה שמקבל מא\"א, והגם שהאמת הוא למעלה בעתיקא ושם דוקא מקור האמת וכן הוא במו\"ס, אך אינו בגילוי עדיין, וכנ\"ל בענין ח\"ס שסתים ונעלם מפני הקרומא דחפייא על מו\"ס, אך כאשר נמשך בז\"א הוא מתגלה, וזהו תתן אמת ליעקב דוקא, וע' מזה בלק\"ת בפ' מסעי<sup data-n=\"2169\">193</sup> ד\"ה הנה גבי\n\nמוכתיב<sup data-n=\"8346\">כו</sup> ויקם עדות ביעקב<sup data-n=\"8347\">כז</sup> ותורה שם בישראל.",[["2157","181","<b>זהב טהור בחי' בינה</b>: ראה אוה\"ת תצוה כאן ע' א'תרפט [ומציין ”ועמ\"ש בענין פז ע\"פ הנחמדים מזהב ומפז רב\" (יהל אור) אוה\"ת תהלים יט, יא]. ס\"ע א'תשה ואילך. ע' א'תשנב.\nראה גם בענין זהב בינה פרדס שער הגוונים ש\"י, פ\"ג. שעה\"כ שכ\"ג, פ\"ז מערכת זהב. מאו\"א מערכת זהב אות יא. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380455\" data-slug=\"likkutei-torah\" data-id=\"4001380455\">לקו\"ת בהעלותך לו, ב</a> ס\"ד."],["2158","182","<b>ופתחת</b>: מכאן ואילך לא נרשמו פרקים."],["2159","183","<b>ופתחת עליו פתוחי חותם</b>: המשך הכתוב ועשית ציץ זהב טהור — תצוה כח, לו."],["2160","184","<b>פי' חותם פי' חותם</b>: כנראה שאחד מהם מיותר."],["2161","185","<b>חותמו של הקב\"ה אמת</b>: שבת נה, א."],["2162","186","<b>ואין אמת אלא תורה</b>: ראה ירושלמי ר\"ה פ\"ג, ה\"ח. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' שסט."],["2163","187","<b>כי באור פניך</b>: סיום תפלת העמידה."],["2164","188","<b>אור פני מלך</b>: ע\"פ משלי טז, טו."],["2165","189","<b>יגמה\"ר שאמר משה</b>: תשא לד, ו-ז."],["2166","190","<b>במל' שנק' עלמא תתאה</b>: ראה זהר בראשית לד, א ובמק\"מ שם. אוה\"ת (יהל אור) תהלים ע' תטו ואילך."],["2167","191","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א."],["2168","192","<b>זוג יונים . . הסתכלות</b>: ראה מאמרי אדה\"ז תקס\"ד ע' קלז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381186\" data-slug=\"likkutei-torah\" data-id=\"4001381186\">לקו\"ת שה\"ש יד, ב</a>. תו\"ח ח\"ש קלב, סע\"א ואילך ובהנסמן לשם. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תקפז."],["2169","193","<b>בלק\"ת בפ' מסעי</b>: צג, ב ואילך.\n\n<b>כו</b> ) <b>וכתיב</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים.\n\n<b>כז</b> ) <b>ויקם עדות ביעקב</b>: תהלים עח, ה."]]],[2001910242,"המסעות, ביאור אלה מסעי, השלישי פ\"ד ופ\"ה, וז\"ע חותמו של הקב\"ה אמת, אין אמת אלא תורה, כי עיקר בחי' אמת היינו כשמשיג החכמה ויודע שכן הוא, משא\"כ כשהיא עדיין בבחי' העלם ועין לא ראתה<sup data-n=\"2170\">194</sup>, הרי אינו ידוע האמת, ולכן ח\"ס עצמה כמו שהיא נעלמת ולא שכיח ולא אתפתח אין שייך לקרותה עדיין אמת עד שנמשך ממנה הארה וגילוי בבחי' תרין תפוחין שהוא בחי' אור פני מלך חיים, ובחי' אור פני מלך נמשך בתורה כמ\"ש כי באור פניך נתת לנו תורת חיים וע' בביאור מסעי הנ\"ל דצ\"ג סע\"ד שזהו בחי' המאור* שבה מחזירן למוטב<sup data-n=\"2171\">195</sup>, והנה ע\"י בחי' אמת זה דתורה שהוא חותמו של הקב\"ה אמת), הנה חותם אותיות תחום ואותיות חומת<sup data-n=\"2172\">196</sup> פי' שע\"י התורה שנק' חותמו של הקב\"ה בחי' אמת נדחה התחום הוא בחי' הגבול, שמזה מסתעף אח\"כ בחי' חומת דעמלק**.\n\n*)וי\"ל<sup data-n=\"8348\">כח</sup> המאור שבה הוא מקור האור דחכמה ע\"ד אויר אור יו\"ד<sup data-n=\"8349\">כט</sup>, וגם בכלל י\"ל שענין מו\"ס וחכ'<sup data-n=\"8350\">ל</sup> שזהו זהו<sup data-n=\"8351\">לא</sup> בחי' אור מים שבתורה, וצ\"ע אולי בחי' תתן אמת ליעקב זהו מה שנשמות נמשכים מיחוד זו\"נ שזהו מחמת הסתכלות ז\"א בא\"א<sup data-n=\"8352\">לב</sup> זהו ענין אחר מבחי' אור מים רקיע<sup data-n=\"8353\">לג</sup>, ולכן נק' מאור המאור שבה.\n**)מה<sup data-n=\"8354\">לד</sup> שמתחום נסתעף חומת דעמלק לכאורה י\"ל שזהו מחמת הגבלה דש' אלקים ק\"ך צרופי'<sup data-n=\"8355\">לה</sup> מסתעף ק\"ך צירופים אלקים שעמלק מקבל מהם ממ\"ח צירופים אחרונים<sup data-n=\"8356\">לו</sup>, ע\"ד לשמש שם אהל<sup data-n=\"8357\">לז</sup> שבסידור דרוש חרבות צורים<sup data-n=\"8358\">לח</sup> וע' בהעתקה (ר\"ה) מאמר זה<sup data-n=\"8359\">לט</sup> שכ' שע\"ב צירופי' הראשוני' שמק\"ך צירופי' דאלקי' אחרים יכולים להתברר, והיינו ע\"ב סנהדרין<sup data-n=\"8360\">מ</sup>.",[["2170","194","<b>ועין לא ראתה</b>: ע\"פ ישעי' סד, ג."],["2171","195","<b>המאור שבה מחזירן למוטב</b>: ראה ירושלמי חגיגה פ\"א, ה\"ז. פתיחתא דאיכ\"ר ב. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540980\" data-slug=\"torat-chaim\" data-id=\"2300540980\">תו\"ח שמות ח\"א טז, ג</a>. וש\"נ. סה\"מ תר\"ם ח\"ב ע' תש. וש\"נ."],["2172","196","<b>חותם . . תחום . . חומת</b>: ראה ע\"ח שער הירח של\"ה, פ\"ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקצח. מאמרי אדה\"א נ\"ך ע' תסד. שע\"ת פב, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540863\" data-slug=\"torat-chaim\" data-id=\"2300540863\">תו\"ח בשלח ח\"א רלג, א</a>. סה\"מ תרל\"ח ריש ע' קפב. ובהנסמן בהנ\"ל.\n\n<b>כח</b> ) <b>וי\"ל</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים. ואולי שייך כאן.\n\n<b>כט</b> ) <b>אויר . . אור יו\"ד</b>: ראה לקמן הערה 214.\n\n<b>ל</b> ) <b>מו\"ס וחכ' . . אור מים שבתורה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כב, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540634\" data-slug=\"torat-chaim\" data-id=\"2300540634\">לקמן מאמר ד</a>\"ה בגמ' וכו' קא מפלגי פ\"ג.\n\n<b>לא</b> ) <b>שזהו זהו</b>: תיבת שזהו נכתבה בסיום השיטה, ותיבת זהו נכתבה בריש שיטה הבאה.\n\n<b>לב</b> ) <b>הסתכלות ז\"א בא\"א</b>: ראה זהר אד\"ר נשא קכח, ב. קלה, ב. לעיל פ\"ה וספ\"א בשולי הגליון ד\"ה ע' בס'.\n\n<b>לג</b> ) <b>אור מים רקיע</b>: ראה זהר תרומה קלו, ב. קסז, א. תו\"ח שמות ח\"א לג, ג. וש\"נ. סה\"מ תרל\"ח ע' קמג ואילך. ע' קסא ואילך ובהנסמן שם. לקמן שם.\n\n<b>לד</b> ) <b>מה</b>: נרשם בשולי היריעה בהיפך הגליון ללא ציון מקומו בפנים. ואולי שייך כאן.\n\n<b>לה</b> ) <b>דש' אלקים ק\"ך צרופי'</b>: ראה ע\"ח שער הזיווגים שט\"ו, פ\"ו. שער השמות שמ\"ד, פ\"ה. הנסמן במאמרי אדה\"א שמות ח\"א ע' קלז.\n\n<b>לו</b> ) <b>ממ\"ח צירופים אחרונים</b>: ראה פע\"ח שחה\"מ שכ\"א, פ\"ה. שער הכוונות ענין הפסח דרוש א'. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370486\" data-slug=\"torah-or\" data-id=\"3901370486\">תו\"א יתרו קט, ד</a>. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'סא. סה\"מ תר\"ם ח\"א ע' שנה. וש\"נ.\n\n<b>לז</b> ) <b>לשמש שם אהל</b>: תהלים יט, ה.\n\n<b>לח</b> ) <b>שבסידור דרוש חרבות צורים</b>: ראה שם שער המילה קמב, ג. וכנראה שהכוונה כאן הוא להגהות הצ\"צ ע\"ז שנדפסו באוה\"ת שבועות ע' קיב. ס\"ע קטז ואילך.\n\n<b>לט</b> ) <b>בהעתקה (ר\"ה) מאמר זה</b>: הנחת ר' הלל מפאריטש ממאמר ד\"ה מגילה נקראת שנדפס לפנ\"ז — נדפס בפלח הרמון שמות-מג\"א כאן ריש ע' שנד.\n\n<b>מ</b> ) <b>ע\"ב סנהדרין</b>: ראה זבחים יא, ב. זהר רע\"מ שופטים ערה, ב. מאמרי אדה\"א דברים ח\"ב ע' תרג. וש\"נ. נ\"ך ע' כ. וש\"נ."]]],[2001910243,"קדש להוי'<sup data-n=\"2173\">197</sup> ויש בזה ב' פירושי' הא' מ\"ש בפרד\"ס<sup data-n=\"2175\">199</sup> קדש להוי' המשכת בחי' הקדש להוי'<sup data-n=\"2174\">198</sup> והיינו כמ\"ש שאו ידיכם קדש<sup data-n=\"2176\">200</sup> וברכו את הוי' כי יש קדש וקדוש, קדוש הוא קדוש וא\"ו<sup data-n=\"2177\">201</sup> שהוא מה שנמשך מבחי' קדש, ויש בחי' קדש בעצם שהוא קדוש ומובדל, וע\"י הציץ הוא בחי' המשכת בחי' קדש להוי' היינו בהוי' שבסדר השתלשלות, ובת\"א פי' ע\"ד מארז\"ל קדש למ\"ד מלמטה והוי' מלמעלה<sup data-n=\"2179\">203</sup> שבחי' קדש למ\"ד הם למטה מבחי' הוי'<sup data-n=\"2178\">202</sup>. והענין הוא דהנה קדש למד הם מ\"ע ומצות ל\"ת<sup data-n=\"2180\">204</sup> קדש הוא בחי' מ\"ע ולמ\"ד הוא בחי' מל\"ת, ולכן מברכין על עשיית המצות אשר קדשנו במצותיו לפי שמ\"ע נק' בחי' קדש, ומל\"ת הוא בחי' למ\"ד כי רוב הל\"ת מתחילין בלמד (וי\"ל שגם אותם שאינם מתחילים בלמד (כמו כ\"מ שנאמר השמר פן ואל אינו אלא ל\"ת<sup data-n=\"2181\">205</sup>) מ\"מ מאחר שעיקר ענין הל\"ת שלא תעשה זאת ה\"ז כאלו מתחילין בלמד לא תעשה כו'), וכלליות כל המל\"ת שהוא מ\"ש לא יהי' לך<sup data-n=\"2182\">206</sup> אלקים אחרים (בעשה\"ד כנודע שאנכי כולל כל הרמ\"ח מ\"ע ולא יהי' לך כולל כל הל\"ת כמ\"ש בסש\"ב פ\"ך ובזח\"א<sup data-n=\"2183\">207</sup> יתרו דצ\"א ע\"א) מתחיל בלמ\"ד, וב' בחי' אלו מ\"ע ומל\"ת זהו מ\"ש אני חומה ושדי כמגדלות<sup data-n=\"2184\">208</sup>, אני חומה זו תורה<sup data-n=\"2185\">209</sup> בדרך כלל (כדאיתא בפסחים דפ\"ז ע\"א ובפ\"ק דב\"ב דף ז' סע\"ב) ובדרך פרט אני חומה זו מ\"ע",[["2173","197","<b>קדש להוי'</b>: המשך הכתוב ועשית ציץ . . ופתחת — תצוה כח, לו."],["2175","199","<b>בפרד\"ס</b>: [ובסיום הפסקא הפרדס] כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["2174","198","<b>מ\"'ש בפרד\"ס . . הקדש להוי'</b>: ראה שם שעה\"כ שכ\"ג, פי\"ח מערכת ציץ. אוה\"ת תצוה כאן ע' א'תשלב ואילך."],["2176","200","<b>שאו ידיכם קדש</b>: תהלים קלד, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">לקו\"ת שה\"ש כא, סע\"ב</a> ואילך."],["2177","201","<b>קדש וקדוש . . וא\"ו</b>: ראה לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י הערה 112.\nראה גם לקמן בפנים (לאחרי המאמר), אצל הערה סט, פיסקא לענין קדש להוי'."],["2179","203","<b>קדש למ\"ד . . מלמעלה</b>: שבת סג, ב. סוכה ה, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550059\" data-slug=\"torat-chaim\" data-id=\"2300550059\">תו\"ח תצוה ח\"ב שנו, א</a> הערה 3."],["2178","202","<b>ובת\"א . . למטה מבחי' הוי'</b>: תצוה כאן פג, ג. פד, א."],["2180","204","<b>קדש למד הם מ\"ע . . ל\"ת</b>: ראה גם אוה\"ת תצוה כאן ע' א'תשי. מטות ע' א'רעט. פלח הרמון מג\"א כאן ע' שסה."],["2181","205","<b>השמר פן ואל . . ל\"ת</b>: ערובין צו, א."],["2182","206","<b>לא יהי' לך</b>: יתרו כ, ג."],["2183","207","<b>ובזח\"א</b>: באוה\"ת כאן: בזח\"ב."],["2184","208","<b>אני חומה ושדי כמגדלות</b>: שה\"ש ח, י."],["2185","209","<b>אני חומה . . זו תורה</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' א' ואילך. לקו\"ת ואתחנן י, א. סה\"מ תרל\"ח ע' קפב. וש\"נ."]]],[2001910244,"ושדי כמגדלות זו מל\"ת<sup data-n=\"2186\">210</sup> שהם גבוהים מבחי' מ\"ע, וכמשל המגדל עושין אותו על החומה כו' שז\"ע מגדל הפורח באויר שארז\"ל (בחגיגה דט\"ו סע\"ב) שאחיתופל בעי תלת מאה בעיי בענין מגדל הפורח באויר (וע' בענין מגדל הפורח באויר בד\"ה וידבר משה אל ראשי המטות דתרטו\"ב סי\"ג<sup data-n=\"2187\">211</sup>, ובד\"ה אני חומה<sup data-n=\"2188\">212</sup> שבח\"מ בסופו), שפי' מגדל הוא מל\"ת והם פורחין באויר, פי' שמגיעים עד בחי' אויר קדמון<sup data-n=\"2189\">213</sup>, כנודע שיש בחי' אויר ובחי' אור, ובחי' אויר הוא אור יו\"ד<sup data-n=\"2190\">214</sup> כמ\"ש במ\"א, והנה עכ\"ז קדש למ\"ד למטה והוי' למעלה, שבחי' ש' הוי' הוא הגבה למעלה מבחי' מ\"ע ומל\"ת, והיינו שהגם שמצ\"ע ומצל\"ת הם גבוהים מאד כנ\"ל עכ\"ז הם באתעדל\"ת אתעדל\"ע<sup data-n=\"2191\">215</sup>, והיינו שגם בחי' מצות ל\"ת הוא באתעדל\"ת אתעדל\"ע, והוא שע\"י הלא (היינו שמונע א\"ע מבלי לעשותו) עי\"ז ממשיכים<sup data-n=\"2192\">216</sup> כו', והטעם הוא מחמת שהאור דמצות ל\"ת גבוה מאד א\"א להמשיך אותו בבחי' קום ועשה כ\"א ע\"י לא כו', אך עכ\"ז ה\"ז נחשב באתעדל\"ת אתעדל\"ע (שע\"י הלא שמונע א\"ע הנה ע\"י אתעדל\"ת זו ממשיך אתעדל\"ע כו') אך בחי' ש' הוי' הוא בחי' ומדריגה שא\"א להגיע לשם בבחי' אתעדל\"ת והוא כמו ענין טל וגשם שארז\"ל כנס\"י שאלו שלא כהוגן<sup data-n=\"2193\">217</sup> ויבא כגשם לנו<sup data-n=\"2194\">218</sup>, והקב\"ה השיבם כהוגן אהי' כטל לישראל<sup data-n=\"2195\">219</sup>, פי' שגשם הוא באתעדל\"ת אתעדל\"ע כמ\"ש ואד יעלה מן הארץ<sup data-n=\"2196\">220</sup> כו' שמזה נעשה הגשם כמ\"ש במ\"א, ואף שגשם הוא מדרגה גבוה מאד שנמשך מבחי' מזלות ונוצר ונקה<sup data-n=\"2197\">221</sup> שז\"ע יורה ומלקוש<sup data-n=\"2198\">222</sup>, אך הנה עכ\"ז הוא באתעדל\"ת אתעדל\"ע כו'. אבל הקב\"ה השיבם כהוגן",[["2186","210","<b>אני חומה זו מ\"ע . . מל\"ת</b>: ראה גם אוה\"ת תצוה כאן ע' א'תשי. פלח הרמון מג\"א כאן ע' שסה."],["2187","211","<b>בד\"ה וידבר משה . . סי\"ג</b>: אוה\"ת מטות ע' א'רעח ואילך."],["2188","212","<b>ובד\"ה אני חומה</b>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770391\" data-slug=\"or-hatorah-hb\" data-id=\"8316770391\">אוה\"ת שה\"ש כרך ב ס\"ע תשנט</a> ואילך."],["2189","213","<b>אויר קדמון</b>: ראה גם עבודת הקדש ח\"א שער היחוד רפ\"ב. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אויר. מאו\"א מערכת אוירא אות קנג. מערכת טהירו אות יז. עמק המלך שער זה. סידור שער החנוכה רעג, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תע ואילך."],["2190","214","<b>אויר הוא אור יו\"ד</b>: ראה זהר בראשית טז, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370194\" data-slug=\"torah-or\" data-id=\"3901370194\">מג, ב</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תנ. וש\"נ. סה\"מ תרל\"ה ח\"א ס\"ע קצז ואילך. וש\"נ. תר\"ם ח\"ב ע' תפה."],["2191","215","<b>באתעדל\"ת אתעדל\"ע</b>: ראה זהר לך פח, א. מאמר ד\"ה לרוקע נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קצד [ובמקביליו ובהנסמן במ\"מ לשם]. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a> ובהערה 189."],["2192","216","<b>מצות ל\"ת . . שע\"י הלא . . ממשיכים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380067\" data-slug=\"likkutei-torah\" data-id=\"4001380067\">לקו\"ת פקודי ו, ד</a>."],["2193","217","<b>כנס\"י שאלו שלא כהוגן</b>: ראה תענית ד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381015\" data-slug=\"likkutei-torah\" data-id=\"4001381015\">לקו\"ת האזינו עג, א</a> ואילך. (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381020\" data-slug=\"likkutei-torah\" data-id=\"4001381020\">עד, ב</a>). מאמרי אדה\"א שמות ח\"א ס\"ע א' קצו ואילך. אוה\"ת האזינו ע' א'תרמח."],["2194","218","<b>ויבא כגשם לנו</b>: הושע ו, ג [ושם: ויבוא — וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380329\" data-slug=\"likkutei-torah\" data-id=\"4001380329\">לקו\"ת במדבר ה, ב</a>. אבל בכ\"מ הוא כבפנים ומהם: לקו\"ת (שם ה, ג). ר\"ה סד, א-<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381009\" data-slug=\"likkutei-torah\" data-id=\"4001381009\">ב. האזינו עא, ג</a>. עג, א. ד. שה\"ש מה, ד — ובהמשך שם ויבוא. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 101]."],["2195","219","<b>אהי' כטל לישראל</b>: שם יד, ו."],["2196","220","<b>ואד יעלה מן הארץ</b>: בראשית ב, ו. ראה ת\"ז רתנ\"ב. ראה גם מאמרי אדה\"א שמות שם. דברים ח\"ד ע' א'קצד ואילך. וש\"נ. פירוש המלות י, א. המשך וככה תרל\"ז פס\"ו. פלח הרמון שה\"ש ע' פ."],["2197","221","<b>שגשם . . מזלות ונוצר ונקה</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשסג ואילך. אוה\"ת האזינו ע' א'תרמו. כרך ה ע' ב'קמא ואילך."],["2198","222","<b>יורה ומלקוש</b>: עקב יא, יד."]]],[2001910245,"אהי' כטל לישראל בחי' שלמעלה מאתעדל\"ת שהוא בחי' טל כמ\"ש במ\"א (וע' מענין טל וגשם בד\"ה האזינו השמים<sup data-n=\"2199\">223</sup> ובהביאור<sup data-n=\"2200\">224</sup>), וזהו ג\"כ בחי' קדש למד מלמטה שהוא בחי' אתעדל\"ת אתעדל\"ע, והוי' מלמעלה בחי' אתעדל\"ע שא\"א להגיע באתעדל\"ת. ובאמת ב' הפירושים שבקדש להוי' אמת, כי פי' הפרדס שפי' המשכת בחי' קדש להוי' היינו בש' הוי' דלתתא, ופי' הת\"א שפי' מארז\"ל קדש למד מלמטה והוי' מלמעלה היינו לגבי בחי' ש' הוי דלעילא שזהו מ\"ש ויקרא הוי' הוי'<sup data-n=\"2201\">225</sup> שיש ב' שמות הוי' ופסיק טעמא בגוייהו, ומשה המשיך להיות נמשך בחי' ש' הוי' דלעילא בבחי' קדש למ\"ד לפי ששרש משה גבוה מאד נעלה כנ\"ל בענין מן המים משיתיהו.*\nוהי' על מצח אהרן כו' תמיד לרצון<sup data-n=\"2202\">226</sup> כו', הנה איתא בזהר שבשבת במנחה מאיר בחי' רעדכ\"ר<sup data-n=\"2203\">227</sup>, ולכאו' צ\"ל הלא מנחה דימות החול הוא בחי' דין<sup data-n=\"2204\">228</sup> שז\"ע משארז\"ל יצחק תיקן תפלת המנחה<sup data-n=\"2205\">229</sup>, כי יצחק הוא בחי' גבורות<sup data-n=\"2206\">230</sup>.** אך הענין\n\n<i>*)בסוף פיסקא זו נרשם בשולי היריעה ולא צוין מקומו בפנים:</i>\nוצ\"ע איך המשיך משה זה בציץ שיאיר בחי' אתעדל\"ע מצ\"ע, וי\"ל שזהו ועשית שנא' לו מפי הגבורה היינו בחי' גבורה דעתיק שמלובש במו\"ס<sup data-n=\"8361\">מא</sup> שמשם טלא דבדולחא עצמו שלמעלה משיורי טלא<sup data-n=\"8362\">מב</sup> כו', גשם וב' מזלות דונוצר ונקה.\n**)יצחק<sup data-n=\"8363\">מג</sup> גבורות תיקן מנחה היינו להמתיק הגבורות שמתעוררי' אז ך\"ד ב\"ד<sup data-n=\"8364\">מד</sup> דז\"א וכן זהיר בתפלת המנחה<sup data-n=\"8365\">מה</sup> להמתיק הגבורות, ר\"ה<sup data-n=\"8366\">מו</sup>.",[["2199","223","<b>בד\"ה האזינו השמים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381015\" data-slug=\"likkutei-torah\" data-id=\"4001381015\">לקו\"ת האזינו עג, א</a> ואילך."],["2200","224","<b>ובהביאור</b>: אולי הכוונה להנסמן בהערה 221."],["2201","225","<b>ויקרא הוי' הוי'</b>: תשא לד, ו. ראה גם לעיל בהמאמר מגילה נקראת כאן פ\"ה. וש\"נ."],["2202","226","<b>והי' על מצח . . תמיד לרצון</b>: תצוה כח, לח. ראה גם לעיל בהמאמר מגילה נקראת כאן ספ\"ה. וש\"נ."],["2203","227","<b>שבשבת במנחה . . רעדכ\"ר</b>: זהר יתרו פח, סע\"ב. אד\"ר נשא קכט, א [ושם: רעוא דרעוין. ראה זהר אד\"ז האזינו רפח, ב]."],["2204","228","<b>הלא מנחה . . דין</b>: ראה זהר לך צה, ב. ח\"ש קלב, ב. שמות כא, א ואילך. יתרו שם. תרומה קנו, א. נשא קכא, א. אד\"ר ואד\"ז שם. שערי זהר לברכות שבהערה הבאה."],["2205","229","<b>יצחק תיקן תפלת המנחה</b>: ברכות כו, ב. זהר נח עב, סע\"א. שמות כא, ב. ולהעיר מס' יוחסין מערכת אברהם הובא בסה\"מ תרל\"א ח\"א ע' מה בשולי היריעה."],["2206","230","<b>יצחק . . גבורות</b>: ראה פרדס שער הכינויים שכ\"ב, פ\"ד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם.\n\n<b>מא</b> ) <b>גבורה דעתיק שמלובש במו\"ס</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ו-ז.\n\n<b>מב</b> ) <b>טלא דבדולחא . . משיורי טלא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381017\" data-slug=\"likkutei-torah\" data-id=\"4001381017\">לקו\"ת האזינו עג, ג</a>. סה\"מ תר\"ם ח\"ב ע' תשפ ואילך וע' תתקלג. וש\"נ.\n\n<b>מג</b> ) <b>יצחק</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים. ואולי שייך כאן.\n\n<b>מד</b> ) <b>ך\"ד </b> [בגוכתי\"ק אינו ברור כ\"כ ואולי כתוב הך\"ד]<b> ב\"ד</b>: כ\"ד בתי דינין — ראה זהר אד\"ר נשא קלו, ב. אד\"ז האזינו רצג, סע\"א.\n\n<b>מה</b> ) <b>זהיר בתפלת המנחה</b>: ברכות ו, ב.\n\n<b>מו</b> ) <b>ר\"ה</b>: הנחת ר' הלל מפאריטש ממאמר זה — נדפס בפלח הרמון שמות-מג\"א כאן ע' שסו."]]],[2001910246,"הוא דהנה מצח הוא החופה על המוחין לבלי יתגלה בחי' המוחין (דהיינו טעם הדבר), אך הנה עכ\"ז יש יתרון המעלה בבחי' מצח שענין בחי' המצח הוא בחי' נצחון שעניינו שיהי' יתד תקוע במקום נאמן<sup data-n=\"2207\">231</sup> (היינו שתמיד יהי' כן ולא ישתנה כלל), והענין הוא דהנה אנו רואי' שכאשר מאירים המוחין אזי יכול לסבול גם דבר והיפוכו כי ע\"פ החכמה ימצא טעם גם להמנגד שלו שאמר לו בהיפך, כי יש שכל לזכות וכמ\"כ להיפך כו' (והיינו כי עצם ענין השכל וטעם של איזה דבר יכולים להפכו הן לזכות והן לחוב<sup data-n=\"2208\">232</sup>, וכמו הטעם שיצר לב האדם רע חייב תחלה שיבא מבול על הארץ כמ\"ש וכל יצר מחשבות לבו<sup data-n=\"2209\">233</sup> רק רע כל היום כו' כמ\"ש אמחה את האדם<sup data-n=\"2210\">234</sup> כו', ואח\"כ כשהריח ה' את ריח הניחוח שהקריב נח, כתי' לא אוסיף לקלל עוד כו' כי יצר לב האדם רע מנעוריו<sup data-n=\"2211\">235</sup>, הרי שטעם זה הספיק שלא יהי' מבול עוד שנמצא ענין השכל והטעם בעצם הוא דבר שיכולים להפכו מחוב לזכות, וזהו בטעם שכל אחד, שנמצא טעם שכל אחד סובל שני הפכים, וכ\"ש שיוכל השכל והטעם לסבול שכל וטעם של האומר לו היפוכו, היינו עד\"מ כשהשכל והטעם שלו מראה לטהר עכ\"ז יסבול טעם ושכל חבירו שמראה לטמא, כי הרי אומר לו שכל וסברא ע\"ז, ומאחר שגם טעם שכל אחד יכולים להפכו מחוב לזכות כ\"ש שיוכל לסבול טעם ושכל שמראה היפך שכלו), אבל בבחי' הפסק דין כמו בשו\"ע שפוסק הדין עד\"מ שזהו טהור, א\"א לסבול ההיפך עד\"מ מה שיאמר אחד שזהו טמא, והיינו מחמת שבהפסק דין אינו מלובש המוחין בשלימות שיוכל ע\"י לסבול ההיפך, כ\"א שמוחין מכוסי' בפסק דין של הדבר, וכמו האדם שכשאומר לאחד כך רצונו בלא טעם, הנה הטעם לזה מכוסה וכמוס אצלו לבד ואינו אומר רק פסק הדברים ואז לא יוכל לסבול ההיפך כו', משא\"כ כאשר מאירים המוחין אז יוכל לסבול המנגד שלו שאומר היפוכו, לפי שבשכל ימצא טעם גם להאומר היפוכו כו'. וזהו ההפרש בין בחי' המוחין לבחי' המצח כו', שבחי' המצח ז\"ע תפלת המנחה דחול שהוא בחי' דין היינו בחי' הפס\"ד שא\"א לשנות, אמנם בשבת בהגלות נגלות בחי' מצחא דעתיקא שהוא בחי' רצון לרצון אשר לית שמאלא בהאי עתיקא<sup data-n=\"2212\">236</sup> אזי הוא תוקף החסדים, וז\"ע הציץ שהי' על מצח אהרן דכתי' בו והי' על מצחו תמיד לרצון, שבאמת יש יתרון המעלה בבחי' המצח (בעצם מלבד בחי' הציץ שהוא ענין התגלות הארת מצחא דעתיקא ע\"י בחי' הסתכלות, יש מעלה בעצם המצח ג\"כ), והיינו כי ההתבוננות שהוא מחב\"ד מוחין",[["2207","231","<b>יתד תקוע במקום נאמן</b>: ע\"פ ישעי' כב, כה. כג."],["2208","232","<b>השכל וטעם . . לזכות והן לחוב</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370068\" data-slug=\"torah-or\" data-id=\"3901370068\">תו\"א וירא טו, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670408\" data-slug=\"torat-chaim\" data-id=\"2300670408\">תו\"ח בראשית יד, א</a> ובהערה 3. הנסמן בסה\"מ תר\"ם ח\"א ע' רכח. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה קא מיפלגי במתיבתא דרקיע על יד הערה 84 ואילך."],["2209","233","<b>וכל יצר מחשבות לבו</b>: בראשית ו, ה."],["2210","234","<b>אמחה את האדם</b>: שם ו, ז."],["2211","235","<b>לא אוסיף . . רע מנעוריו</b>: נח ח, כא."],["2212","236","<b>לית שמאלא בהאי עתיקא</b>: ראה זהר אד\"ר נשא קכט, א. ע\"ח שער עתיק שי\"ב, פ\"ב. שער הארת המוחין של\"ב, פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."]]],[2001910247,"שבנפשו זהו רק בעת התפלה*, אבל אחר התפלה חולף ועובר ההתבוננות, אך מצד בחי' המצח מתקיים כל היום, והוא כי המצח הוא בחי' נצחון דהיינו מה שנשאר אצלו הרשימה וההסכם מבחי' ההתבוננות שהי' בשעת התפלה שיהי' כן כל היום בבחי' נצח לבד, וז\"ע המצח אף שהוא חופה על המוחין (היינו שאין מאירים המוחין בגלוי), עכ\"ז יש בו יתרון (שהוא תמיד כל היום<sup data-n=\"2213\">237</sup>, ולכן הציץ שפי' מל' יציץ אה\"ר ואהבה בתענוגים, ומלשון מציץ מן החרכים בחי' ראי' ע\"י בחי' עיינין בחי' אסתכלותא דעלמא עילאה שבה בחי' עת\"י, וגם ענין בחי' ציץ בחי' אסתכלותא דמצחא דעתיקא במצחא דז\"א<sup data-n=\"2214\">238</sup>, כמ\"ש בזהר וע' בביאור שני דועשית ציץ (בס' יונתי (תקס\"ו<sup data-n=\"2215\">239</sup>) דף ך\"ו ע\"ב) הוא על מצחו תמיד לרצון, שענין המצח בעצם הוא תמיד כנ\"ל, ולכן ע\"י הציץ תמיד יהי' לרצון מבחי' רעדכ\"ר שמאיר ממצחא דעתיקא ע\"י ההסתכלות בחי' עיינין כו' וכ\"ז המשיך משה שמשה הוא העושה כו', ולכן מובן איך שע\"י גילוי כזה נדחה הרע דעמלק כו'**.\n\n*)הלואי<sup data-n=\"8367\">מז</sup> שיתפלל אדם<sup data-n=\"8368\">מח</sup> כל היום היינו שאמר זה דרך בקשה, אבל באמת א\"א להיות כן לזה הוא בחי' המצח בחי' נצחון (בדרוש).\nי\"ל<sup data-n=\"8369\">מט</sup> בע\"ס<sup data-n=\"8370\">נ</sup> טרודי' בעסק וא\"א להיות בהתבוננות כל היום ואפי' בעלי תורה טרודי' לקשר מחשבה במחשבה ודבור בדבור התורה וא\"א להיות כ\"א התבוננות כלליות כמ\"ש והודעת לבניך<sup data-n=\"8371\">נא</sup> כו' יום אשר עמדת<sup data-n=\"8372\">נב</sup> מה להלן באימה<sup data-n=\"8373\">נג</sup> כו' אף כאן ואיך אלא שז\"ע לאמור שבעשה\"ד<sup data-n=\"8374\">נד</sup>, להיות תען לשוני<sup data-n=\"8375\">נה</sup>, כעונה אחר הקורא כמ\"ש בת\"א ד\"ה בחדש השלישי<sup data-n=\"8376\">נו</sup>.\n**)לכאו'<sup data-n=\"8377\">נז</sup> צ\"ל עמלק הי' קודם עשיית הציץ<sup data-n=\"8378\">נח</sup>, אך רבינו ז\"ל אמר כן, וצ\"ל שמשה עשה אח\"כ הציץ (והציץ ענינו מציץ שבירת הכותל דעמלק), שזהו מפני כי שרשו מן המים כנ\"ל לכן המשיך תורה, ממילא מובן איך שדחה עמלק, וגם צ\"ל מ\"ש על ועשית דציץ שמשה הוא העושה הלא בכל המשכן והכלים נא' ועשית<sup data-n=\"8379\">נט</sup> ואינו דומה לעשיית הבגדים ששם נא' ג' לשונות<sup data-n=\"8380\">ס</sup> ועשית, ועשו כל חכם לב<sup data-n=\"8381\">סא</sup>, וסתם ועשו.",[["2213","237","<b>היום</b>: אוצ\"ל: היום)."],["2214","238","<b>אסתכלותא . . דעתיקא . . דז\"א</b>: ראה זהר ויקרא טו, סע\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380812\" data-slug=\"likkutei-torah\" data-id=\"4001380812\">לקו\"ת פ' ראה כד, א</a>-ב. אבל כנראה הכוונה למקומות הזהר שהובאו בריש המאמר שבהערה הבאה."],["2215","239","<b>בביאור שני . . תקס\"ו</b>: נדפס ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550221\" data-slug=\"torat-chaim\" data-id=\"2300550221\">תו\"ח תצוה ח\"ב שסא, סע\"ד</a> ואילך.\n\n<b>מז</b> ) <b>הלואי</b>: נרשם בשני שורות מלמטה למעלה בצד השמאלי של העמוד. מתחיל לערך כאן ללא ציון מקומו בפנים. ואולי שייך כאן.\n\n<b>מח</b> ) <b>הלואי שיתפלל אדם</b>: ראה ברכות כא, א.\n\n<b>מט</b> ) <b>י\"ל</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים.\n\n<b>נ</b> ) <b>בע\"ס</b>: בעלי עסקים.\n\n<b>נא</b> ) <b>והודעתם לבניך</b>: ואתחנן ד, ט.\n\n<b>נב</b> ) <b>יום אשר עמדת</b>: ואתחנן שם, י.\n\n<b>נג</b> ) <b>מה להלן באימה</b>: ברכות כב, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670248\" data-slug=\"torat-chaim\" data-id=\"2300670248\">תו\"ח נח מט, סע\"ג</a> ואילך ובהערה 25. יתרו ח\"ב רנג, ד ואילך. שע\"ת מא, א. מאמרי אדה\"א הנחות תקע\"ז ע' קכב.\n\n<b>נד</b> ) <b>לאמור שבעשה\"ד</b>: יתרו כ, א.\n\n<b>נה</b> ) <b>תען לשוני</b>: תהלים קיט, קעב.\n\n<b>נו</b> ) <b>בת\"א בד\"ה בחדש השלישי</b>: יתרו סז, ב.\n\n<b>נז</b> ) <b>לכאו'</b>: נרשם בשולי היריעה ללא ציון מקומו בפנים. ואולי שייך כאן.\n\n<b>נח</b> ) <b>עמלק הי' . . הציץ</b>: בשלח יז, ח.\n\n<b>נט</b> ) <b>בכל המשכן והכלים נא' ועשית</b>: פרט לארון [תרומה כה, י ועשו ארון — אבל בהמשך לזה — שם יא ואילך — וצפית, ועשית, ויצקת, וכו']. תרומה שם, כג ואילך [שולחן]. שם, לא ואילך [מנורה]. כו, א ואילך [יריעות]. שם, טו ואילך [קרשים והקמת המשכן]. שם, לא ואילך [פרוכת וכו']. כז, א ואילך [מזבח הנחושת]. כז, ט ואילך [חצר המשכן]. תצוה ל, א ואילך [מזבח הקטרת]. תשא ל, יז [כיור]. שם, כב ואילך [שמן המשחה וקטרת] .\n\n<b>ס</b> ) <b>לעשיית הבגדים . . ג' לשונות</b>: תצוה כח, ב [ועשית]. שם, ג [חכמי לב . . ועשו את בגדי אהרן]. שם, ד [ועשו בגדי קדש].\n\n<b>סא</b> ) <b>ועשו כל חכם לב</b>: ראה בהערה שלפנ\"ז."]]],[2001910248,"ומעתה יובן ג\"כ ענין ויקרא אל משה<sup data-n=\"2216\">240</sup>, שהוא ל' אוקיר אנוש מפז<sup data-n=\"2217\">241</sup>, ובבלעם נאמר ויקר לשון קרי<sup data-n=\"2218\">242</sup>, והנה קרי וקיר ברזל גימט' כתר<sup data-n=\"2219\">243</sup> דקליפה שהוא בחי' כרת<sup data-n=\"2220\">244</sup>, ולעו\"ז יש בקדושה בחי' קיר דקדושה ובחי' יקר דמשה כי אוקיר ל' יקר גימט' כתר<sup data-n=\"2221\">245</sup> דקדושה, והיינו דכמו שיש בקדושה בחי' כתר שהוא הממוצע<sup data-n=\"2222\">246</sup> בין המאציל לנאצלים כמ\"כ בחי' כתר דקליפה בחי' כרת הוא הממוצע בין הקדושה לקליפה<sup data-n=\"2223\">247</sup> שע\"י מקבלים הקליפות חיות מהקדושה. והנה ע\"י בחי' משה כתר דקדושה דוחין בחי' כרת דקליפה בחי' עמלק ובלעם כו'. וזהו ענין מגלה נקראת באחד עשר כו' ובט\"ו לא פחות ולא יותר<sup data-n=\"2224\">248</sup>, והיינו לפי שי\"א הוא בחי' ו\"ה וט\"ו הוא בחי' י\"ה<sup data-n=\"2225\">249</sup>, והענין לפי שעמלק הוא בחי' כס י\"ה<sup data-n=\"2226\">250</sup> שהוא",[["2216","240","<b>ויקרא אל משה</b>: ויקרא א, א."],["2217","241","<b>אוקיר אנוש מפז</b>: ישעי' יג, יב."],["2218","242","<b>ויקר לשון קרי</b>: בלק כג, ד. ראה רש\"י ולקח טוב שם. ב\"ר פנ\"ב, ה. ויק\"ר פ\"א, יג הועתק לעיל במאמר ד\"ה מגילה נקראת פ\"א."],["2219","243","<b>קרי וקיר . . גימט' כתר</b>: הובא גם לעיל במאמר ד\"ה מגילה נקראת פ\"ו. וראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 111."],["2220","244","<b>כתר . . כרת</b>: ראה ת\"ז תס\"ט קח, ב. בעה\"ט יתרו כ, יד. פרדס שער התמורות שכ\"ה, פ\"ד. לקו\"ת להאריז\"ל משלי יד. עמה\"מ שער עולם התוהו ש\"ו, פס\"ג לו, רע\"א. מאו\"א מערכת כרת אות טו. ויקהל משה זאלקווא תקל\"ה יג, ב. מאמרי אדה\"ז תקס\"ז ע' קנד וע' קנז. נדפס גם ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370483\" data-slug=\"torah-or\" data-id=\"3901370483\">תו\"א יתרו קט, סע\"א</a>. שם ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380847\" data-slug=\"likkutei-torah\" data-id=\"4001380847\">לקו\"ת פ' ראה לג, א</a>. וראה שם חוקת נט, א."],["2221","245","<b>קיר . . יקר . . גימט' כתר</b>: הובא גם לעיל במאמר ד\"ה מגילה נקראת פ\"ו."],["2222","246","<b>כתר שהוא הממוצע</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תס. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540828\" data-slug=\"torat-chaim\" data-id=\"2300540828\">תו\"ח שמות ח\"א יא, ג</a>. וש\"נ."],["2223","247","<b>כתר . . כרת . . הקדושה לקליפה</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 113. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380597\" data-slug=\"likkutei-torah\" data-id=\"4001380597\">לקו\"ת בלק סט, ד</a>."],["2224","248","<b>מגילה נקראת . . ולא יותר</b>: ראה מגילה פ\"א, מ\"א."],["2225","249","<b>שי\"א . . ו\"ה וט\"ו . . י\"ה</b>: של\"ה תצוה שכט, א. פ' זכור של, ב. לעיל מאמר ד\"ה מגילה נקראת ובהערה 252."],["2226","250","<b>שעמלק . . כס י\"ה</b>: בשלח יז, טז. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370371\" data-slug=\"torah-or\" data-id=\"3901370371\">תו\"א תצוה פג, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550337\" data-slug=\"torat-chaim\" data-id=\"2300550337\">תו\"ח תצוה ח\"ב שסה, ג</a>. אוה\"ת תצוה ס\"ע א'תרצד ואילך."]]],[2001910249,"המכסה ומעלים בחי' י\"ה לבלי יגלה כנ\"ל<sup data-n=\"2227\">251</sup>, ולכן בנס דפורים כאשר נתלה המן<sup data-n=\"2228\">252</sup> למעלה מחמשים<sup data-n=\"2229\">253</sup> עי\"ז הי' הגילוי בחי' י\"ה בו\"ה, וזהו אחד עשר וט\"ו. אך הנה באופן הגילוי יש הפרש בין כרכי' המוקפות חומה<sup data-n=\"2230\">254</sup> לבחי' כפרים ועיירות גדולות שהכפרים ועיירות גדולות קורין בי\"ד ומוקפות חומה בט\"ו, וצ\"ל מהו שייך הקפות חומה מימות יהושע בן נון שיהי' קורין בט\"ו. אך הענין הוא דהנה למטה עיקר מלחמת עמלק הי' עם יהושע<sup data-n=\"2231\">255</sup>, כי יהושע הוא היפך בחי' הקיר ברזל כו' כי יהושע הוא בחי' מל'<sup data-n=\"2232\">256</sup> דקדושה שזהו מארז\"ל פני יהושע כפני לבנה<sup data-n=\"2233\">257</sup> בחי' מל'<sup data-n=\"2234\">258</sup> וקיר ברזל הוא בחי' עמלק מ'<sup data-n=\"2235\">259</sup> דקליפה, ולכן יהושע הי' נכנס בעובי הקורה בעת המלחמה עם עמלק ואף שנאמר בחר לנו אנשים<sup data-n=\"2236\">260</sup>, אך עכ\"ז למטה הי' יהושע הלוחם<sup data-n=\"2237\">261</sup>, וכמ\"ש ויחלוש יהושע את עמלק<sup data-n=\"2238\">262</sup> כו', והנה יהושע כשקידש את הארץ קידש את הכרכים המוקפים חומה<sup data-n=\"2239\">263</sup> בקדושה היותר<sup data-n=\"2240\">*264</sup> משאר קדושת הארץ, ולכן בכרכים המוקפות חומה קורין בט\"ו כי שם גילוי בחי' י\"ה, והיינו לפי שהחומה הוא ג\"כ בחי' מקיף כו', משא\"כ בכפרים ועיירות גדולות אף ששם ג\"כ הי' הגילוי מבחי' י\"ה אך היינו בחי' י\"ה כאשר מתלבש בו\"ה*. וביאור<sup data-n=\"2241\">264</sup> הענין הוא כמו שארז\"ל על ישעי' ויחזקאל בן כרך שראה את המלך ובן כפר<sup data-n=\"2242\">265</sup> שראה את המלך והיינו לפי שישעי' שראה את המלך ראה מרכבה דבריאה<sup data-n=\"2243\">266</sup> ששם משכן\n\n<i>*)נרשם בצד הימני של העמוד:</i>\nעכ\"נ<sup data-n=\"8382\">סב</sup>.",[["2227","251","<b>כנ\"ל</b>: ראה לעיל מאמר ד\"ה מגילה נקראת פ\"ד."],["2228","252","<b>בנס דפורים . . נתלה המן</b>: תלאוהו ביום ב' דפסח — ראה שו\"ע אדה\"ז הל' פסח סת\"צ, ס\"ב."],["2229","253","<b>נתלה המן למעלה מחמשים</b>: ראה גם שה\"א כח, ב. מאמרי אדה\"א נ\"ך ע' תלה. וש\"נ."],["2230","254","<b>כרכי' המוקפות חומה</b>: ראה מגילה פ\"א, מ\"א."],["2231","255","<b>עיקר מלחמת עמלק . . יהושע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470198\" data-slug=\"or-hatorah-hb\" data-id=\"8316470198\">אוה\"ת בשלח ס\"ע תרסו</a>."],["2232","256","<b>יהושע . . מל'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540749\" data-slug=\"torat-chaim\" data-id=\"2300540749\">תו\"ח בשלח ח\"א קנח, ב</a>."],["2233","257","<b>פני יהושע כפני לבנה</b>: ב\"ב עה, סע\"א. ראה מאמרי אדה\"א נ\"ך ע' תסא ואילך."],["2234","258","<b>לבנה בחי' מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"ב מערכת לבנה."],["2235","259","<b>עמלק מ'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470194\" data-slug=\"or-hatorah-hb\" data-id=\"8316470194\">אוה\"ת בשלח ע' תרסב</a>."],["2236","260","<b>בחר לנו אנשים</b>: בשלח יז. ט."],["2237","261","<b>למטה הי' יהושע הלוחם</b>: ראה גם זהר בשלח סה, ב הועתק גם לעיל בסיום המאמר ד\"ה מגילה נקראת."],["2238","262","<b>ויחלוש יהושע את עמלק</b>: בשלח יז, יג. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקלה."],["2239","263","<b>יהושע . . קידש . . המוקפים חומה</b>: ראה כלים פ\"א, מ\"ז ובמפרשים שם."],["2240","*264","<b>היותר</b>: כ\"ה בגוכתי\"ק."],["2241","264","<b>וביאור</b>: מכאן ואילך לא העתיק בכת\"י המעתיק — ראה לעיל הערה 1."],["2242","265","<b>ישעי' ויחזקאל . . ובן כפר</b>: ראה חגיגה יג, ב. ראה גם סה\"מ תרכ\"ט ע' רלז. וש\"נ. תר\"ם ח\"א ע' לז ואילך. וש\"נ."],["2243","266","<b>שישעי' . . מרכבה דבריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. לקוטי הש\"ס להנ\"ל יבמות מט, ב ד\"ה מנשה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540375\" data-slug=\"torat-chaim\" data-id=\"2300540375\">תו\"ח בא ח\"א קיד, סע\"ג</a>. וש\"נ. סה\"מ תרמ\"ז ע' קלו. ע' קמב. (סה\"מ תרמ\"ו — תר\"ן בהוצאה החדשה — נמצא בדפוס).\n\n<b>סב</b> ) <b>עכ\"נ</b>: עד כאן נאמר."]]],[2001910250,"השרפי'<sup data-n=\"2244\">267</sup> שאומרי' קדוש<sup data-n=\"2245\">268</sup> שמשיגי' איך שהוא ית' קדוש ומובדל כי אימא מקננא בבריאה<sup data-n=\"2246\">269</sup>. אבל יחזקאל ראה המרכבה בבחי' יצירה<sup data-n=\"2247\">270</sup> ועשי'<sup data-n=\"2248\">271</sup> לכן הוא כמו בן כפר. וזהו כרכי' כו' קורין בט\"ו לפי ששם גילוי בחי' י\"ה אכן כפרים ועיירות גדולות קורין בי\"ד פי' עיירות גדולות הוא ע\"ד מ\"ש במשנה מגלה פ\"א מ\"ג איזהו עיר גדולה כל שיש בה עשרה בטלנים, פי' שמאיר שם בחי' ע\"ס<sup data-n=\"2249\">272</sup> כי לפעמים אינו מאיר כ\"א רק בחי' ז' מדות, אבל בעיר גדולה מאיר בחי' עשר ספירות לכן הם קורין בי\"ד כי יד על כס י\"ה בחי' יד הרמה<sup data-n=\"2250\">273</sup> כו'.\n\nחזקי'<sup data-n=\"8383\">סג</sup> פניו אל הקיר, וכמו\"כ המתפלל, צ\"ל שזהו ע\"י סמיכות גאולה לתפלה<sup data-n=\"8384\">סד</sup> והטוב בעיניך עשיתי<sup data-n=\"8385\">סה</sup> שזהו ע\"י ק\"ש שמע ובשכמל\"ו, או שמע מ' ע', והוי' אחד יחו\"ע ויחו\"ת עי\"ז יוכל אח\"כ בתפלה להמשיך ש' הוי' בש' אד' בחי' קיר.\nבלק\"ת<sup data-n=\"8386\">סו</sup> ד\"ה את שבתותי פ\"ב שהשם מקשר הנשמה להגוף, וא\"כ משה ע\"ש כי מן המים נמצא שנשמתו שבגוף הי' ע\"ש כי מן המים דח\"ס, וצריך להקדים ענין כל אשר האדם הוא שמו<sup data-n=\"8387\">סז</sup>, שהשם אינו הסכם<sup data-n=\"8388\">סח</sup> כו' וע' בד\"ה ביום השמיני שלח סוף ס' תרל\"ה<sup data-n=\"8389\">*סט</sup>.\nלענין קדשסט להוי'<sup data-n=\"8390\">סט</sup> בענין קדש וקדוש, קדוש וא\"ו אולי יש להעיר ממ\"ש בביאור תורה ציוה בענין וזרח משעיר שער יו\"ד שערות דמו\"ס בחי' צומח והיו\"ד הוא אור שבשערות, וזהו מבחי' מדות שבח\"ס שכ\"ז הוא מקור לגליא שבתורה אותיות ותושבע\"פ ביאור האותיות בד\"ה תורה צוה<sup data-n=\"8391\">ע</sup>, אבל בציץ נת' לעיל שנמשך מבחי' תיקון ואמת בחי' ש\"ע נהורין שמאירים בפנים תיקון ואמת שפנוי משערות והוא בחי' המשכה בפנימיות מחכמת אדם דח\"ס להאיר פניו דז\"א ובתורה י\"ל שזהו פנימיות התורה וע\"ז קאי ענין באור פניך נתת לנו תורת חיים שנת' בביאור מסעי הג'<sup data-n=\"8392\">עא</sup> פ\"ג ד' ה' בענין תיקון ואמת, ובציץ הוא ע\"י אסתכלותא דעלמא עילאה בעלמא תתאה, אפ\"ל שזהו המשכת בחי' קדש מוחא סתימאה עצמה שיתגלה מההעלם שע\"י הקרומא דאוירא בפנים דז\"א להאיר פניו, וע\"י עיניך יונים כמשנ\"ת בביאור מסעי הג' פ\"ה<sup data-n=\"8393\">עב</sup> נמשך גם במל' וזהו בעלמא תתאה, אך כשנמשך בז\"א זהו ג\"כ הכוונה בעלמא תתאה שז\"א מקור לגבול כמשנ\"ת בתחלת הביאור בענין שיעור קומה כו' מקור לגבול כו', ונמצא כי זהו פי' קדש להוי' שיומשך מבחי' קדש ח\"ס קדש מלה בגרמיא (זח\"ג אמור דצ\"ד<sup data-n=\"8394\">עג</sup>) שהוא ח\"ס (כ\"פ בביאור מסעי הג' פ\"ג<sup data-n=\"8395\">עד</sup>) להוי' דז\"א שהוא מקור לעולמות והיינו ה' לשון מהוה<sup data-n=\"8396\">עה</sup>.\nבבה\"ז<sup data-n=\"8397\">עו</sup> נשא דקך\"ח ע\"ב, צומח שבח\"ס זהו חו\"ג דא\"א שמתלבשים בחו\"ב דאצי'<sup data-n=\"8398\">עז</sup>, אבל בחי' צומח שבחי שבח\"ס זהו שערות דיגת\"ד שהם האור שנמשך דרך מותרי מוחין ממ\"ה דח\"ס להשערות דיגת\"ד שהם מבחי' ב\"ן דתהו, ומבחי' מ\"ה הנ\"ל נמשך להיות נושא עון זדונות נעשו<sup data-n=\"8399\">עח</sup> כזכיות<sup data-n=\"8400\">עט</sup>. ועכ\"ז לפמשנ\"ת בסוף האזינו הא'<sup data-n=\"8401\">פ</sup> וכ\"ה באמת זהו רק שיורא טלא דבדולחאמב, אבל בחי' טלא דבדולחא זהו מו\"ס עצמו וע' בס' קס\"ג דךב\"ב בד\"ה כי טל אורות<sup data-n=\"8402\">פא</sup>.\nמשיב<sup data-n=\"8403\">פב</sup> הרוח ומוריד הגשם<sup data-n=\"8404\">פג</sup>.\nבס'<sup data-n=\"8405\">פד</sup> תרט\"ו ד\"ה ראו כי כו' נתן לכם את השבת דקס\"ה ע\"א<sup data-n=\"8406\">פה</sup>, מן חצי פ\"א קשה לזווגם כקרי\"ס, עד סוף פ\"ד בדף קס\"ח בסופו, אפל\"כ<sup data-n=\"8407\">פו</sup> דרוש קרי\"ס טוב ומובן ויש הנחה ממנו בס' בש\"ו<sup data-n=\"8408\">פז</sup> דרמ\"ו ע\"א המתחיל ראו עם ביאור קשה לזווגם<sup data-n=\"8409\">פח</sup>.",[["2244","267","<b>דבריאה . . השרפי'</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש יג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380325\" data-slug=\"likkutei-torah\" data-id=\"4001380325\">לקו\"ת</a> להאריז\"ל ישעי' פ\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380325\" data-slug=\"likkutei-torah\" data-id=\"4001380325\">לקו\"ת במדבר ד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380515\" data-slug=\"likkutei-torah\" data-id=\"4001380515\">שלח נ, סע\"ד</a>. האזינו עה, ב. ביאוה\"ז בשלח לט, ד."],["2245","268","<b>השרפי' שאומרי' קדוש</b>: ישעי' ו, ב-ג. ראה חולין צא, ב ואילך ובתוד\"ה ברוך (שם צב, רע\"א)."],["2246","269","<b>אימא מקננא בבריאה</b>: ת\"ז ת\"ו כג, א. ראה ע\"ח שער סדר אבי\"ע שמ\"ז, פ\"ג. שער דרושי כללות אבי\"ע שמ\"ב, פי\"ג. תניא פל\"ט."],["2247","270","<b>יחזקאל ראה . . יצירה</b>: ראה ע\"ח שער ק\"נ שמ\"ט, פ\"ב. מאמרי אדה\"א נ\"ך ע' קמא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540375\" data-slug=\"torat-chaim\" data-id=\"2300540375\">תו\"ח בא ח\"א קיד, סע\"ג</a> ובהערה 194. סה\"מ תר\"ם ח\"א ע' לח. וש\"נ."],["2248","271","<b>יחזקאל ראה . . ועשי'</b>: ראה גם שעה\"י קמה, ב. אוה\"ת מג\"א ס\"ע ערה [נדפס גם בסה\"מ תרכ\"ט ע' פג]. סה\"מ תרכ\"ט ע' רלז."],["2249","272","<b>עשרה בטלנים . . ע\"ס</b>: ראה גם טור ברקת הל' מגילה סתרפ\"ח, ס\"א (קלז, ד). צויין אליו ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640205\" data-slug=\"or-hatorah-hb\" data-id=\"8316640205\">אוה\"ת ש\"ש ע' א'תסז</a>. (יהל אור) תהלים ע' רה [ושם: בטו\"ב ה' מגילה סי' תרס\"ח]. שה\"ש ח\"א ס\"ע קפד ואילך [ושם: בטו\"ב בה' פורים]. מג\"א ס\"ע רעח [נדפס גם בסה\"מ תרכ\"ט ע' פו]. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' ח. פלח הרמון מג\"א כאן ע' שסט."],["2250","273","<b>יד הרמה</b>: ראה תו\"א מג\"א צה, ג ואילך.\n\n<b>סג</b> ) <b>חזקי'</b>: קטעים הבאים לקמן נרשמו על שלשה עלים קטנים בהנחת ריווח ובהפסקת קו קצר בין קטע לחבירו. אמנם לא הועתקו בכת\"י המעתיק — ראה לעיל הערה 1. לאידך חלק מהם כן הועתקו בבוך תרמ\"א 2086 — כת\"י מעתיק.\nלקטע זה ראה לעיל פ\"ד.\n\n<b>סד</b> ) <b>סמיכות גאולה לתפלה</b>: ברכות ט, ב.\n\n<b>סה</b> ) <b>והטוב בעיניך עשיתי</b>: מלכים-ב כ, ג. ישעי' לח, ג.\n\n<b>סו</b> ) <b>בלק\"ת</b>: לקטע זה ראה לעיל פ\"ה.\n\n<b>סז</b> ) <b>כל אשר האדם הוא שמו</b>: ע\"פ בראשית ב, יט.\n\n<b>סח</b> ) <b>שהשם אינו הסכם</b>: ראה גם סה\"מ תרל\"ב ח\"ב ע' תקמו. וש\"נ. תרל\"ח ע' קסב. וש\"נ.\n\n<b>*סט</b> ) <b>ביום השמיני שלח . . תרל\"ה</b>: סה\"מ תרל\"ה ח\"ב ע' תנא ואילך. וש\"נ. נדפס גם בסה\"מ תרל\"ח שם.\nהמאמר ביום השמיני שלח כתבו כ\"ק אדמו\"ר מהר\"ש בהמשך אחד, ואח\"כ נחלק לד' מאמרים. ראה הערה 1 בסה\"מ תרל\"ה שם. והכוונה כאן למאמר דש\"ת. ראה גם לקמן מאמר ד\"ה בגמ' וכו' קא מפלגי הערה ח.\n\n<b>סט</b> ) <b>לענין קדש להוי'</b>: לקטע זה ראה לעיל פיסקא קדש להוי'.\n\n<b>ע</b> ) <b>בד\"ה תורה צוה</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381103\" data-slug=\"likkutei-torah\" data-id=\"4001381103\">לקו\"ת ברכה צד, א</a> ואילך.\n\n<b>עא</b> ) <b>בביאור מסעי הג'</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380703\" data-slug=\"likkutei-torah\" data-id=\"4001380703\">לקו\"ת מסעי</a> צב, ואילך.\n\n<b>עב</b> ) <b>בביאור מסעי הג' פ\"ה</b>: לקו\"ת שם צד, ד.\n\n<b>עג</b> ) <b>דצ\"ד</b>: ע\"ב [ושם: בגרמי'].\n\n<b>עד</b> ) <b>בביאור מסעי הג' פ\"ג</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, א</a>.\n\n<b>עה</b> ) <b>ה' לשון מהוה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים שער ד, ספ\"י. סה\"מ תר\"ם ח\"א ע' קצח. וש\"נ.\n\n<b>עו</b> ) <b>בבה\"ז</b>: לקטע זה ראה לעיל ספ\"ה על יד הערה 175 כמצויין בפנים.\n\n<b>עז</b> ) <b>חו\"ג דא\"א . . בחו\"ב דאצי'</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שנד.\n\n<b>עח</b> ) <b>זדונות נעשו כזכיות</b>: ראה יומא פו, ב.\n\n<b>עט</b> ) <b>כזכיות</b>: ע\"כ הועתק בבוך תרמ\"א 2086 — כת\"י מעתיק. ראה לעיל הערה סג.\nתיבה זו נרשמה בסיום הע' [קד, ב] ובע' הבא [קה, א] בראשיתו נרשם ענין אחר ואח\"כ העביר עלי קו ורשם בצדו [הטעם שנמחק כי] ”הועתק\". ואח\"כ בשורה חדשה נרשם עוד הפעם תיבת כזכיות וההמשך כבפנים.\n\n<b>פ</b> ) <b>בסוף האזינו הא'</b>: לקו\"ת האזינו עג, ג.\n\n<b>פא</b> ) <b>בס' קס\"ג . . כי טל אורות</b>: לע\"ע לא נתברר לאיזה ספר-בוך הכוונה. מאמר זה נדפס במאמרי אדה\"ז תקס\"ג ח\"א ע' רא ואילך.\n\n<b>פב</b> ) <b>משיב</b>: נרשם בלי הפסק קו אבל בהנחת ריווח מקטע שלפנ\"ז. ראה לעיל הערה סג.\n\n<b>פג</b> ) <b>משיב הרוח ומוריד הגשם</b>: נוסח ג\"ר דשמו\"ע. ענין גשם הוזכר לעיל בפיסקא קדש להוי'.\n\n<b>פד</b> ) <b>בס'</b>: נרשם בעלה בפ\"ע.\n\n<b>פה</b> ) <b>בס' תרט\"ו . . ע\"א</b>: נדפס באוה\"ת בשלח כרך ח ע' ב'תתקע.\n\n<b>פו</b> ) <b>אפל\"כ</b>: אפשר לכתוב.\n\n<b>פז</b> ) <b>בס' בש\"ו</b>: בראשית שמות ויקרא. הכולל הנחות של ר' דוב [בעריל] קאליסקער ממאמרי כ\"ק אדמו\"ר הצ\"צ ונק' בשם ”בוך בש\"ו\" [בראשית שמות ויקרא]־ ולפעמים נק' בשם ”ס' וכל שיח\" ע\"ש פתיחתו במאמר ד\"ה וכל שיח השדה. ראה עוד ע\"ד הנ\"ל ב”ספריית ליובאוויטש\" ע' ל ואילך. ע' לז ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד-תרט\"ו ע' שו-שז.\n\n<b>פח</b> ) <b>עם ביאור קשה לזווגם</b>: שם רנ, ב. נדפסו במאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' עג ואילך."]]],[2001910251,"<h3>בגמ' וכו' קא מפלגי</h3>\n<b>ש\"פ תזריע</b>\n<b>בגמ'</b><sup data-n=\"2251\">1</sup> ב\"מ פ' הפועלים<sup data-n=\"2252\">2</sup> דפ\"ו ע\"א קא מפלגי במתיבתא דרקיעא<sup data-n=\"2253\">3</sup> אם בהרת כו' ואם שער לבן כו' טהור, ספק הקב\"ה אומר טהור, וכולהו מתיבתא דרקיעא אמרי טמא, אמרי מאן נוכח רבה בר נחמוני<sup data-n=\"2254\">4</sup> דאמר רבה בר נחמוני אני יחיד כו', שלכאו' צ\"ל איך שייך לומר שהמתיבתא דרקיע פליגי עם קוב\"ה כי מה ערך הנברא לגבי הבורא עד שנאמר שהנבראים פליגי עם קוב\"ה שהוא הבורא ית', וכמו\"כ צ\"ל מ\"ש בזהר קוב\"ה אתי לאשתעשע<sup data-n=\"2255\">5</sup> עם צדיקייא בגנתא דעדן איך שייך לומר שהבורא אתי לשמוע דברי פנימיות התורה שלומדים הצדיקים בג\"ע. אך יובן",[["2251","1","<b>בגמ' ב\"מ פ' הפועלים דפ\"ו ע\"א קא מפלגי במתיבתא דרקיעא</b>: מאמר זה הוא מאמר ד\"ה אדם כי יהי' תרל\"ה פרקים ב-ד (השני — בסה\"מ תרל\"ה ח\"א ע' רכ — רכו) בהוספת התחלה. והמשכו לש\"פ מצורע הוא ד\"ה וענין מתיבתא דרקיע שמתחיל בפ\"ה [השני בסה\"מ שם ע' רכו ואילך).\nלמאמר זה ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380169\" data-slug=\"likkutei-torah\" data-id=\"4001380169\">לקו\"ת תזריע כב, סע\"ב</a> ואילך (ובהנסמן במ\"מ לשם). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940027\" data-slug=\"or-hatorah-hb\" data-id=\"8159940027\">אוה\"ת</a> <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940040\" data-slug=\"or-hatorah-hb\" data-id=\"8159940040\">תזריע ח\"ב ע' תקלא</a> ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תמג ואילך. ובארוכה שם ע' תנו ואילך. ראה גם סה\"מ תרל\"ט ח\"א ע' קנח ואילך. ע' רסג ואילך וע' שמו ואילך. עזר\"ת ע' קעו ואילך.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפס לקמן בחלק הנחותיו [ומשם נעתק התאריך שמופיע בריש המאמר כאן: ”ש\"פ תזריע\"].\nהמאמר פרט לההתחלה הוא כת\"י מעתיק.\nמאמר זה כפי שנרשם במפתח הכ\"י [כדלקמן] הוא ד\"ה קא מפליגי במתיבתא דרקיע אלא שבו נכללו 2 מאמרים לש\"פ תזריע וש\"פ מצורע ובו 4 פרקים שבסה\"מ תרל\"ה [שממנו הועתק כנ\"ל] נרשמו פרקים ב-ה.\nאלא שבהמאמר שלפנינו דש\"פ תזריע נסמנו הפרקים א-ג. והמאמר דש\"פ מצורע שהעתיק המעתיק מסה\"מ תרל\"ה העתיק גם את הפרק כפי שמופיע שם שהוא פ\"ה. ועפ\"ז הנה הפרקים הם א [שלא נסמן] ב. ג. ה.\nבמפתח בוך זה 1130 נרשמו שלשה דרושים והם: א) ד\"ה זה קא מפליגי במתיבתא דרקיע בדף קך, א [אמנם הדרוש נחלק לב' פרשיות פרקים א-ג פ' תזריע ופ\"ה לפ' מצורע]. ב) לה\"ע טהרת המצורע בדף קךו, א. ג) בלקו\"ת ד\"ה אם בהרת בדף קל, א, אבל כנראה שאח\"כ נשתנה הפתיחה ל”ועוי\"ל ענין ק\"נ דאצי'\" — ראה לקמן מאמר ד\"ה זה.\nבבוך תרמ\"א 2086 — כת\"י מעתיק —. נרשמו הדרושים א-ב הנ\"ל. והדרוש הג' לא נרשם שם במפתח, אף שמופיע בהבוך בע' בפ\"ע (בפתיחה ”ועוי\"ל ענין ק\"נ דאצי'\").\nלקמן בהנחות מכ\"ק אדמו\"ר מהורש\"ב נרשמו שני דרושים [והם א' הנ\"ל] א) ד\"ה זה קא מיפלגי. ב) ד\"ה זאת תהי' שהוא הנחה פ\"ה הנ\"ל בתוס' התחלה."],["2252","2","<b>פ' הפועלים</b>: וכ\"ה בלקו\"ת וסה\"מ תרל\"ה ותרל\"ט כאן. ובמאמרי אדה\"א ויקרא ח\"ב ע' תנו: השוכר את הפועלים."],["2253","3","<b>דרקיעא</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380169\" data-slug=\"likkutei-torah\" data-id=\"4001380169\">לקו\"ת תזריע כב, סע\"ב</a>: דרקיע. וראה שם כד, ב (רפ\"ה)."],["2254","4","<b>נחמוני</b>: כ\"ה בגוכתי\"ק. וראה גם הנחת כ\"ק אדמו\"ר מהר\"ש במאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ס\"ע כו: ר\"ש בר נחמני . . ולר\"ש בר נחמוני."],["2255","5","<b>קוב\"ה אתא לאשתעשע</b>: ראה זהר אחרי סז, ב. לך עז, א. הנסמן בסה\"מ תרל\"ה כאן. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן. מאמרי אדה\"ז על פרשיות התורה ח\"ב ס\"ע תקצז. תקס\"ב ח\"ב ע' תלד. תקס\"ז ע' קכד. ביאוה\"ז אחרי — להצ\"צ — כרך א ע' שמו ואילך. שם כרך ב בראשית ע' תרכא ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'שנ ואילך. סה\"מ תרל\"ח ע' שכט. לקמן מאמר ד\"ה להבין וכו' זאת תהי' תורת המצורע על יד הערה 100."]]],[2001910252,"בהקדים ענין קוב\"ה ומתיבתא דרקיע וצדיקים, ומתחלה צ\"ל מהו שם קוב\"ה<sup data-n=\"2256\">6</sup> שקראו אותו התנאים ואמוראים בגמ' ובמדרש ובזהר, הלא בתורה לא נזכר שם זה כ\"א שם הוי' או שם אלקי' או שם אל, וגם כתי' ואמרו לי מה שמו מה אומר אליהם כו' אהי\"ה<sup data-n=\"2257\">7</sup> כו' וארז\"ל לפי מעשי אני נקרא<sup data-n=\"2258\">8</sup>, ומהו ענין שם הקב\"ה. הנה הקב\"ה הוא בחי' קדוש וברוך, פי' קדוש הוא בחי' מובדל<sup data-n=\"2259\">9</sup> שהוא ית' קדוש ומובדל מגדר עולמות ואינו כמו הנשמה שמחיה את הגוף שמתפעלת ממקרי הגוף<sup data-n=\"2260\">10</sup> מפני שהיא מתלבשת בתוך הגוף, אבל הוא ית' הוא קדוש ומובדל וכתי' אני הוי' לא שניתי<sup data-n=\"2261\">11</sup> בין קודם שנבה\"ע בין אחר שנבה\"ע שהתהוות העולם אינו פועל שום שינוי בו ית', אך עכ\"ז הנה בחי' זו שייך לבחי' עולם שזהו נק' סוכ\"ע<sup data-n=\"2262\">12</sup>, שהחיות הלז הוא סובב ומקיף ואינו מתלבש בבחי' פנימיות שלכן אין העולם פועל בו שום שינוי ח\"ו, אעפ\"כ הנה חיות זה שייך לעולם שלכן נק' סוכ\"ע שסובב ומקיף את העולם שנמצא שייך לעולם, וה\"ז כמשל השמים שהם מקיפים את הארץ כו', והנה כתי' שמים לרום<sup data-n=\"2263\">13</sup>, כי גבהו שמים מארץ<sup data-n=\"2264\">14</sup>, שהשמים המה גבוהים ורחוקים מבחי' הארץ, עכ\"ז הנה הריחוק שמים מהארץ הוא בשיעור מצומצם<sup data-n=\"2265\">15</sup> דוקא כך או כך ואם היו השמים רחוקים יותר מהשיעור הקצוב להם לא היו פועלים פעולתם בארץ, וכתי' וממגד תבואות שמש<sup data-n=\"2266\">16</sup> שהארץ מקבלת ההשפעה מבחי' שמים, הרי אף שהשמים הם מובדלים במדרגה מבחי' הארץ עכ\"ז הם שייכים לארץ*, כך יובן למעלה בבחי' החיות הנק' סוכ\"ע אף\n\n<i>*)נרשם בשולי היריעה ולא נסמן מקומו בפנים, ואולי שייך כאן:</i>\nלהעיר מפסוקי' אענה את השמים<sup data-n=\"8410\">א</sup> והם יענו את הארץ, והארץ תענה את הדגן (הושע ב' ך\"ג ך\"ד).",[["2256","6","<b>מהו שם קוב\"ה</b>: ראה גם (בנוסף להערה 1) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">לקו\"ת שה\"ש כא, ב</a> (וסה\"מ תר\"ם ח\"א ס\"ע קצו ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158100090\" data-slug=\"or-hatorah-hb\" data-id=\"8158100090\">אוה\"ת שה\"ש כרך ג' ע' תתצג</a>). שם מ, ג ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550570\" data-slug=\"torat-chaim\" data-id=\"2300550570\">תו\"ח תרומה ח\"ב שיז, ב</a> ואילך. וש\"נ. סה\"מ תרל\"ד ס\"ע צז ואילך. וראה גם תו\"ח בא ח\"א קכב, ב."],["2257","7","<b>ואמרו לי מה שמו . . אהי\"ה</b>: שמות ג, יג. יד."],["2258","8","<b>לפי מעשי אני נקרא</b>: שמו\"ר פ\"ג, ו. תנחומא שמות כ. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380299\" data-slug=\"likkutei-torah\" data-id=\"4001380299\">לקו\"ת ויקרא בהוספות נא, ד</a>. סהמ\"צ להצ\"צ קטז, ב."],["2259","9","<b>קדוש . . מובדל</b>: ראה [בנוסף להנ\"ל] <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא פמ\"ו (סו, א</a>). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380210\" data-slug=\"likkutei-torah\" data-id=\"4001380210\">לקו\"ת אמור לא, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540089\" data-slug=\"torat-chaim\" data-id=\"2300540089\">תו\"ח וארא ח\"א נא, ד</a> ובהערה 10."],["2260","10","<b>הנשמה . . שמתפעלת ממקרי הגוף</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא פמ\"ב (ס, ב</a>). שער היחוד והאמונה פ\"ז (פג, ב). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370061\" data-slug=\"torah-or\" data-id=\"3901370061\">תו\"א וירא יג, ג</a>. לקו\"ת שם. ואתחנן ד, ב. סה\"מ תרל\"ד ס\"ע צח ואילך. תרל\"ט ח\"א ע' שמז. לקמן מאמר ד\"ה הים ראה וינוס על יד הערה 39. ד\"ה רני ושמחי על יד הערה 31."],["2261","11","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם לקו\"ת אמור שם ואילך. סה\"מ תר\"ם ח\"א ע' שסט ואילך. וש\"נ."],["2262","12","<b>שייך לבחי' עולם . . סוכ\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380957\" data-slug=\"likkutei-torah\" data-id=\"4001380957\">לקו\"ת ר\"ה נט, ג</a>. שערי אורה פט, א ובהערה 1. לקמן מאמר ד\"ה הים ראה וינוס על יד הערה 38 ואילך."],["2263","13","<b>שמים לרום</b>: משלי כה, ג."],["2264","14","<b>כי גבהו שמים מארץ</b>: ישעי' נה, ט."],["2265","15","<b>הריחוק שמים מהארץ . . מצומצם</b>: ראה חגיגה יג, א. לעיל מאמר ד\"ה ועבדתם את ה\"א ובהערה 68."],["2266","16","<b>וממגד תבואות שמש</b>: ברכה לג, יד ובפרש\"י שם. ראה סידור שער המילה קמב, א [אוה\"ת שבועות ריש ע' קי. סידור ס\"ע שיג ואילך]. מאמרי אדה\"ז הנחות הר\"פ ע' קלה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670200\" data-slug=\"torat-chaim\" data-id=\"2300670200\">תו\"ח בראשית כא, ג</a> ואילך. מאמרי אדה\"א במדבר ח\"ג ע' א'קצ. דברים ח\"ד ע' א'תמא. נ\"ך ע' קכב וע' קכז ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830004\" data-slug=\"or-hatorah-hb\" data-id=\"8158830004\">אוה\"ת</a> על מארז\"ל ע' ד [שלח ע' תקל].\n\n<b>א</b> ) <b>אענה את השמים</b>: ראה גם סידור שער הל\"ג בעומר שג, א. אוה\"ת תהלים כרך ב' ע' תתקמו ואילך."]]],[2001910253,"שהוא קדוש ומובדל עכ\"ז הוא שייך לעולם שלכן נק' סוכ\"ע שהוא שייך לעולם כו', וזהו קדוש וא\"ו, פי' וא\"ו הוא בחי' המשכה מבחי' קדש<sup data-n=\"2267\">17</sup> שקדש הוא בחי' אוא\"ס למעלה מבחי' סוכ\"ע והוא בחי' כתר<sup data-n=\"2268\">18</sup> שבחי' זו שייך גם בלא התהוות העולמות שאף אם לא הי' מתהוה עולמות כלל הי' ג\"כ שייך בחי' קדש, קדש מלה בגרמי'<sup data-n=\"2269\">19</sup> כו'*, וקדוש הוא קדוש וא\"ו היינו המשכה מבחי' קדש העליון שהוא בחי' הארת הכתר המאיר בז\"א, ונק' קדוש וא\"ו ע\"ש ההמשכה שהוא\"ו הוא תמונת הקו וההמשכה, והוא ענין המשכה דרך שערות שהשערה הוא בחי' צמצום מאד, עכ\"ז הוא נמשך ממקום גבוה מאד שצומח מבחי' המוחין כו' כמ\"ש במ\"א בד\"ה ביום ההוא יגלח אד'<sup data-n=\"2270\">20</sup> בתער השכירה כו', וע\"פ קבלה נק' המשכת הוא\"ו בשם קו וחוט שהוא ההמשכה מאוא\"ס ב\"ה כו', כמ\"ש בד\"ה ביום ההוא הנ\"ל, וז\"ע קדוש שהוא בחי' סוכ\"ע.\nב) <b>ופי'</b> ברוך הוא המשכה בבחי' פנימיות ממכ\"ע וכמשארז\"ל בגמ' פ\"ק דברכות דף יו\"ד ע\"א מה הקב\"ה מלא את<sup data-n=\"2271\">21</sup> כל העולם, אף הנשמה מליאה<sup data-n=\"2272\">22</sup> את כל הגוף, ובמד\"ת<sup data-n=\"2273\">23</sup> מה הנפש ממלאה את הגוף כך הקב\"ה ממלא את כל העולם<sup data-n=\"2274\">24</sup> שהוא בחי' חיות הנמשך בבחי' פנימיות ולא בבחי' מקיף כנ\"ל, והנה ברוך הוא ל' בריכת המים<sup data-n=\"2275\">25</sup>, גם ל' המבריך את הגפן<sup data-n=\"2276\">26</sup> שפי' שמטה את הגפן. והנה בתיבת ברוך יש ב' פירושי'<sup data-n=\"2277\">*27</sup>, הא' ברוך הוא ל' מקור הברכות שזהו ר\"ת ברוך ראש<sup data-n=\"2278\">27</sup> ומקור כל\n\n<i>*)נרשם בצד העמוד:</i>\nלהעיר מביאור אלה מסעי השלישי<sup data-n=\"8411\">ב</sup> פ\"ג דצ\"ג ע\"א.",[["2267","17","<b>קדוש וא\"ו . . מבחי' קדש</b>: ראה זהר אמור צג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380432\" data-slug=\"likkutei-torah\" data-id=\"4001380432\">לקו\"ת בהעלותך ל, סע\"ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380920\" data-slug=\"likkutei-torah\" data-id=\"4001380920\">נצבים נ, ב</a> ואילך. יו\"כ סט, ב ואילך. שה\"ש כא, ב ואילך. לו, ד. אוה\"ת תזריע כרך ד ע' א'נג."],["2268","18","<b>שקדש הוא . . בחי' כתר</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"ט מערכת קדוש ובמערכת קדש."],["2269","19","<b>קדש מלה בגרמי'</b>: זהר אמור צד, ב."],["2270","20","<b>בד\"ה ביום ההוא יגלח אד'</b>: ראה מאמרי אדה\"ז נביאים ע' מח ואילך. אוה\"ת ישעי' כרך ב ע' תשסט ואילך."],["2271","21","<b>את</b>: בגמ'־ <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380211\" data-slug=\"likkutei-torah\" data-id=\"4001380211\">לקו\"ת אמור לא, ב</a>־ ובסה\"מ תרל\"ה כאן ליתא. וכנראה שהיא הוספת המעתיק."],["2272","22","<b>מליאה</b>: שם: מלאה."],["2273","23","<b>ובמד\"ת</b>: ובמדרש תהלים קג, א. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשצא וע' תשצה."],["2274","24","<b>כל העולם</b>: במדרש שם: עולמו. בלקו\"ת שם: העולם. ובסה\"מ שם כבפנים."],["2275","25","<b>ברוך הוא ל' בריכת המים</b>: ע\"פ קהלת ב, ו. ראה גם לעיל מאמר ד\"ה קדש ישראל לה' רפ\"ג. וש\"נ."],["2276","26","<b>המבריך את הגפן</b>: כלאים פ\"ז, מ\"א. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370171\" data-slug=\"torah-or\" data-id=\"3901370171\">תו\"א מקץ לז, ג</a>. סה\"מ תר\"ם ח\"א ע' רלח. וש\"נ."],["2277","*27","<b>בתיבת ברוך יש ב' פירושי'</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 44."],["2278","27","<b>ר\"ת ברוך ראש . . כמ\"ש בפרד\"ס</b>: בלקו\"ת תזריע כאן מציין [שעה\"כ שכ\"ג, פ\"ב] בערך ברוך. מת\"ז ת\"ע קכ, ב. ראה גם פרדס שער אם הא\"ס הוא הכתר ש\"ג, פ\"ה.\n\n<b>ב</b> ) <b>מביאור אלה מסעי השלישי</b>: בלקו\"ת."]]],[2001910254,"ברכה<sup data-n=\"2279\">28</sup> כמ\"ש בפרד\"ס<sup data-n=\"2280\">29</sup>, והוא בחי' יסוד דאבא שנק' ברוך<sup data-n=\"2281\">30</sup> כו', והפי' הב' מל' והמלך שלמה ברוך<sup data-n=\"2282\">31</sup> שפי' שהמלך שלמה מתברך היינו שמקבל הברכה כו', ובפי' שלמה יש ב' פי' הא' שקאי על המל' שהמלך שלמה הוא בחי' מל'<sup data-n=\"2283\">32</sup> הוא מקבל הברכה מבחי' יסוד אבא, והב' שמלך שלמה קאי על בחי' יסוד ז\"א<sup data-n=\"2284\">33</sup>, ונק' שלמה שהוא בחי' שהשלום שלו<sup data-n=\"2285\">34</sup>, שהיסוד הוא ג\"כ בחי' מקבל ומקשר* כו'. וזהו ברכו את הוי' המבורך<sup data-n=\"2286\">35</sup>, שדקדקו הפשטנים מהו ברכו את הוי', ותירצו שהוא מקור הברכות, והיינו כנ\"ל בפי' הא' ברוך ראש ומקור כל ברכה, רק מ\"ש המבורך לא הבינו, אך לפי הנ\"ל קאי המבורך על בחי' ז\"א ומל' שהם מבורכים שמקבלים הברכה, וא\"כ פי' ברוך הוי' המבורך היינו להמשיך בחי' ברוך מקור הברכה היינו יסוד דאבא בהמבורך בז\"א ומל'. וזהו חייב אדם לברך<sup data-n=\"2287\">36</sup> מאה ברכות בכל יום, היינו בחי' המשכות בבחי' פנימיות. וזהו שהי' בריאת העולמות בב' דוקא, כי בי\"ת הוא סי' ברכה, שלכאו' צ\"ל מפני מה לא נברא העולם באלף<sup data-n=\"2288\">37</sup> שהאלף הוא גבוה במדרגה\n\n<i>*)בצד העמוד כאן נרשם:</i>\nלענין יסוד מקבל ומקשר ע' בד\"ה שלש רגלי' בס' רג\"ל<sup data-n=\"8412\">ג</sup>, ובד\"ה ענין ספה\"ע בס' רך\"ז<sup data-n=\"8413\">ד</sup> מהזח\"ג פנחס רנ\"ד<sup data-n=\"8414\">ה</sup> חמשה אינון כו', וע' בד\"ה שלש רגלי' (רי\"ז)<sup data-n=\"8415\">ו</sup> שלמה עולה שע\"ה נהורין כמדומה בשם המאו\"א<sup data-n=\"8416\">ז</sup>.",[["2279","28","<b>ברכה</b>: בת\"ז ובפרדס שם: ברכות. אבל כ\"ה גם בלקו\"ת שם."],["2280","29","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["2281","30","<b>יסוד דאבא שנק' ברוך</b>: פע\"ח שער הברכות ש\"ב, פ\"א. מאו\"א מערכת ברוך אות לט."],["2282","31","<b>והמלך שלמה ברוך</b>: מלכים-א ב, מה. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540841\" data-slug=\"torat-chaim\" data-id=\"2300540841\">תו\"ח בשלח ח\"א קס, ג</a>. וש\"נ."],["2283","32","<b>שהמלך שלמה . . מל'</b>: ראה ע\"ח שער פנימיות וחצוניות ש\"מ, דרוש יג."],["2284","33","<b>שמלך שלמה . . יסוד ז\"א</b>: ראה זהר רע\"מ ויקרא ד, א. מאו\"א מערכת שלמה אות מה [הועתק בסמוך הערה ז]. המשך מים רבים תרל\"ו פקל\"ז. תרל\"ה כאן ריש ע' רכג. ע' רד ואילך."],["2285","34","<b>שלמה . . שהשלום שלו</b>: שה\"ש ג, יא. ראה שהש\"ר פ\"א, א [יא]. פ\"ג, יא [א]. זהר שמות ה, א. יד, א. שבועות לה, ב."],["2286","35","<b>ברכו את הוי' המבורך</b>: נוסח התפלה. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380778\" data-slug=\"likkutei-torah\" data-id=\"4001380778\">לקו\"ת עקב טז, א</a>."],["2287","36","<b>חייב אדם לברך</b>: מנחות מג, ב."],["2288","37","<b>לא נברא העולם באלף</b>: ראה ב\"ר פ\"א, י. תנחומא — באבער — יתרו טז. וש\"נ.\n\n<b>ג</b> ) <b>בד\"ה שלש רגלי' בס' רג\"ל</b>: סה\"מ תרל\"ג ח\"א ע' קמה. נדפס גם לקמן [עם הוספות] על יד הערה 50 ואילך.\n\n<b>ד</b> ) <b>ובד\"ה ענין ספה\"ע בס' רכ\"ז</b>: ד\"ה להבין ענין ספה\"ע בסה\"מ תרכ\"ז ע' רסב. וש\"נ.\n\n<b>ה</b> ) <b>רנ\"ד</b>: ע\"א.\n\n<b>ו</b> ) <b>בד\"ה שלש רגלי' (רי\"ז)</b>: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080260\" data-slug=\"or-hatorah-hb\" data-id=\"8160080260\">אוה\"ת משפטים ע' א'קעה</a>.\n\n<b>ז</b> ) <b>בשם המאו\"א</b>: באוה\"ת שם: כמ\"ש במא\"א שין סעיף מ\"ה ויסוד נק' שלמה, והוא ממשיך ג\"כ שע\"ה נהורין גימ' שלמה יעו\"ש. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 52 ואילך.\nבמאו\"א שם (הועתק בחלקו באוה\"ת ויקרא כרך א ע' רס): שלמה גי' ש\"ע נהורין עם ו' אותיות של אל\"ף למ\"ד כי בזמנו השכינה היתה בפנים והי' לה ש\"ע נהורין הללו והיסוד נק' שלמה כי הוא מושך יופי הפנים לו יוסף יפה תואר."]]],[2001910255,"מבחי' הב' כו', שלכן במ\"ת התחיל באלף כמ\"ש אנכי<sup data-n=\"2289\">38</sup> כו' כמ\"ש במ\"א, אך הענין הוא דהנה אלף הוא ר\"ת ארור<sup data-n=\"2290\">39</sup>, והיינו שמבחי' אלף מחמת שהוא גבוה מאד לכן יכולים גם הקליפות לקבל משם שזהו א' ר\"ת ארור כנען<sup data-n=\"2291\">40</sup> שאפי' בחי' כנען יכול לקבל ג\"כ מבחי' א' כו' כמ\"ש בזהר ר\"פ ויגש<sup data-n=\"2292\">41</sup>, אבל ב' הוא סי' ברכה<sup data-n=\"2293\">*42</sup>, והיינו שמבחי' ב' אין הקליפות יכולים לקבל כ\"א שיומשך השפעה פנימיות לישראל דוקא. וזהו איהו ברוך ואיהי ברכה<sup data-n=\"2294\">42</sup>, פי' איהו ברוך יסוד דאבא נק' ברוך ראש ומקור כל ברכה, ואיהי ברכה המל' בחי' כנס\"י<sup data-n=\"2295\">43</sup> נק' ברכה שמקבלת הברכה מבחי' ברוך כי נש\"י דוקא הם הכלי לקבל בחי' ברוך שהוא בחי' פנימיות, וכמשל השכל שורה דוקא במוח שהמוח הוא כלי לקבל אור השכל משא\"כ אבר אחר אינו יכול לקבל גילוי אור השכל, כך נש\"י הם כלי לקבל בחי' השפעה פנימיות בחי' ברוך. וזהו הקב\"ה, קדוש הוא בחי' סוכ\"ע וברוך הוא בחי' ממכ\"ע, והנה הקב\"ה הוא יחוד סוכ\"ע בממכ\"ע<sup data-n=\"2296\">44</sup>, ונש\"י הם הממשיכים להיות יחוד סוכ\"ע בממכ\"ע שנש\"י הם כלי להמשיך גם בחי' סוכ\"ע, שזהו מ\"ש ג\"פ קדוש<sup data-n=\"2297\">45</sup> היינו להמשיך בחי' סוכ\"ע, וזהו מ\"ש קדושים תהיו כו' כי קדוש אני<sup data-n=\"2298\">46</sup> שמפני שאתם צריכים להמשיך אותו ית' שאני קדוש לכן תהיו אתם קדושים שתהיו בחי' כלי להמשכה זו, ולכן קראו התנאים והאמוראים את הבורא ית' בשם הקב\"ה או קוב\"ה מפני כי שם קוב\"ה מורה על יחוד סובב בממלא והוא כללות ההשתלשלות כו' (משא\"כ ש' אל או ש' אלקים המה פרטיי'<sup data-n=\"2299\">47</sup> כו' כמ\"ש במ\"א). וזהו מ\"ש בזהר פ' חיי שרה דקכ\"ג ע\"א, קוב\"ה דאתכליל מאתר עילאה סתימא דכ\"ס במאה ברזא דמאה ברכאן, ופי' במק\"מ קוב\"ה מל' דאתכליל מאתר עילאה סד\"ס אריך, והיינו כנ\"ל בפי' קדוש וא\"ו שהוא\"ו הוא בחי' המשכה מבחי' קדש בחי' כתר כו'.\nג) <b>ומעתה</b> צ\"ל ענין מתיבתא דרקיע, הנה יש ז' רקיעים<sup data-n=\"2300\">48</sup> וכתי' ודמות על ראשי החיה<sup data-n=\"2301\">49</sup> רקיע כעין הקרח הנורא, והנה רקיע זו הוא רקיע תמינאה",[["2289","38","<b>במ\"ת התחיל באלף כמ\"ש אנכי</b>: יתרו כ, ב. ראה גם לעיל מאמר ד\"ה קדש ישראל לה' פ\"ג ובהנסמן שם."],["2290","39","<b>אלף הוא ר\"ת ארור</b>: ראה זהר שבהערה 41. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380793\" data-slug=\"likkutei-torah\" data-id=\"4001380793\">לקו\"ת פ' ראה יט, ב</a>. סה\"מ תרל\"א ח\"א ס\"ע סא ואילך. וש\"נ. סה\"מ תר\"ם ח\"א ע' שו. וש\"נ."],["2291","40","<b>ארור כנען</b>: נח ט, כה. ראה גם סה\"מ תרל\"א ח\"א ע' סב."],["2292","41","<b>בזהר ר\"פ ויגש</b>: רה, ב."],["2293","*42","<b>ב' הוא סי' ברכה</b>: זהר שם. בהקדמה ג, סע\"א (צויין ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כאן כב, ג</a>)."],["2294","42","<b>איהו ברוך ואיהי ברכה</b>: ראה זהר תרומה קסב, א. ואתחנן רסד, ב. סידור ערב שבת קסה, סע\"ב ואילך. שער הל\"ג בעומר שה, ד."],["2295","43","<b>המל' בחי' כנס\"י</b>: ראה זהר בלק קצז, א."],["2296","44","<b>הקב\"ה הוא יחוד סוכ\"ע בממכ\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381151\" data-slug=\"likkutei-torah\" data-id=\"4001381151\">לקו\"ת שה\"ש ה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381214\" data-slug=\"likkutei-torah\" data-id=\"4001381214\">כא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381290\" data-slug=\"likkutei-torah\" data-id=\"4001381290\">מ, ג</a>."],["2297","45","<b>מ\"ש ג\"פ קדוש</b>: ישעי' ו, ג. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380217\" data-slug=\"likkutei-torah\" data-id=\"4001380217\">לקו\"ת אמור לב, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380222\" data-slug=\"likkutei-torah\" data-id=\"4001380222\">לד, א</a> ואילך."],["2298","46","<b>קדושים תהיו כו' כי קדוש אני</b>: קדושים יט, ב.\nבסה\"מ תרל\"ה כאן ע' רכד העיר: ולכאו' [תיבת] ”כו'\" — מיותר."],["2299","47","<b>ש' אל . . אלקים המה פרטיי'</b>: ראה גם לעיל מאמר ד\"ה ועבדתם את ה\"א הערות 130-131. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כאן כג, ג</a>. סה\"מ תר\"ם ח\"א ע' רלא ואילך."],["2300","48","<b>ז' רקיעים</b>: חגיגה יב, ב. ראה סה\"מ תרל\"ח ע' קיז הערה 431."],["2301","49","<b>ודמות על ראשי החיה</b>: יחזקאל א, כב. ראה סה\"מ תרל\"ט ח\"א ע' קס וע' רסד."]]],[2001910256,"שאינו בחשבון הז' רקיעים כו', כמ\"ש בזהר פ' לך דפ\"ה סע\"ב ושם שהוא למעלה מז' רקיעים<sup data-n=\"2302\">50</sup>, ולהבין ענין רקיע זה יובן בהקדם ענין אור מים רקיע<sup data-n=\"2303\">51</sup>, שבמע\"ב כתי' ה\"פ אור<sup data-n=\"2304\">52</sup> ה\"פ מים<sup data-n=\"2305\">53</sup> ה\"פ רקיע<sup data-n=\"2306\">54</sup>, ויובן זה בנפש האדם הנה אור הוא בחי' משכיל מקור הכל שאינו נרגש כלל והרי הוא כדמיון האור שאינו נרגש במישוש כלל, ובחי' מים הוא כדמיון הברקת השכל שהוא רק הברקה בעלמא שאינו מושג עדיין אך מ\"מ הוא מורגש והרי זה כמו המים שיורדים מגבוה לנמוך<sup data-n=\"2307\">55</sup>, פי' גבוה הוא בחי' המשכיל מקור השכל שאינו מורגש כלל והמים הם יורדים מגבוה שנמשכים מבחי' משכיל, אך עכ\"ז הם מורגשים מעט אבל אינו בבחי' השגה והבנה כ\"א מרחפת שמרופף השכל עדיין שזה כמשל מי שנופל אצלו השכלה בעת הלימוד הנה השכל שנפל אצלו הוא מרופף עד שכשמעמיק בשכלו אז נמשך בבחי' השגה כו' וה\"ז כדמיון המים שהם ניידי<sup data-n=\"2308\">56</sup> כו', ובחי' רקיע הוא כאשר בא אור השכל בהשגה והבנה היטב כי רקיע הוא כמ\"ש רקיע כעין הקרח שהקרח הוא מה שנגלדו המים ונתחזקו היטב והיינו כאשר בא השכל בהשגה והבנה היטב על בוריו, ולמעלה נק' בחי' אור מים רקיע* בחי' כח\"ב, אור הוא בחי' כתר ומים הוא בחי' חכמה ורקיע הוא בחי' בינה. והנה על בחי' רקיע זה שהוא הקרח שעל ראשי החיות נא' מבטן מי יצא הקרח<sup data-n=\"2309\">57</sup>, פי' מי הוא מה שאינו מושג כלל<sup data-n=\"2310\">58</sup> אשר ע\"ז נא' מי יתן מציון ישועת ישראל<sup data-n=\"2311\">59</sup>, מי גילה לבני רז זה<sup data-n=\"2312\">60</sup> כו', ולהבין זה הנה כתי' שאו מרום עיניכם וראו מי ברא אלה<sup data-n=\"2313\">61</sup>, פי' אלה הוא לשון גילוי, והנה אלה גימ' ל\"ו<sup data-n=\"2314\">62</sup>, והיינו ופ\"ו גימ' ל\"ו שקאי על ו\"ק גשמיי'\n\n<i>*)בשולי היריעה נרשם:</i>\nוע' מענין אור מים רקיע לקמן בד\"ה ביום השמיני שלח<sup data-n=\"8417\">ח</sup>.",[["2302","50","<b>רקיע . . מז' רקיעים</b>: ראה גם סה\"מ תרל\"ה כאן ע' רכד בהערה."],["2303","51","<b>אור מים רקיע</b>: ראה זהר תרומה קלו, ב. קסז, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540634\" data-slug=\"torat-chaim\" data-id=\"2300540634\">תו\"ח שמות ח\"א לג, ג</a>. וש\"נ. סה\"מ תרל\"ח ע' קמג ואילך. ע' קסא ואילך ובהנסמן שם."],["2304","52","<b>ה\"פ אור</b>: בראשית א, ג-ה."],["2305","53","<b>ה\"פ מים</b>: שם א, ו-ז."],["2306","54","<b>ה\"פ רקיע</b>: שם א, ו-ח."],["2307","55","<b>המים שיורדים מגבוה לנמוך</b>: ראה תענית ז, א."],["2308","56","<b>המים שהם ניידי</b>: ראה ערובין מו, א."],["2309","57","<b>מבטן מי יצא הקרח</b>: איוב לח, כט. ראה זהר שהובא בפנים בריש הפרק. סה\"מ תרל\"ה כאן ע' רכה בהערה."],["2310","58","<b>מי . . שאינו מושג כלל</b>: ראה סה\"מ עזר\"ת כאן ע' קפ: ובזהר [תרומה קלט, ב] אי' מי הוא טמירא דכל טמירין דלא אתייעדא ולא אתגלי'."],["2311","59","<b>מי יתן מציון ישועת ישראל</b>: תהלים יד, ז. נג, ז."],["2312","60","<b>מי גילה לבני רז זה</b>: שבת פח, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380335\" data-slug=\"likkutei-torah\" data-id=\"4001380335\">לקו\"ת במדבר ו, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380367\" data-slug=\"likkutei-torah\" data-id=\"4001380367\">יד, ד</a> ואילך."],["2313","61","<b>שאו מרום . . מי ברא אלה</b>: ישעי' מ, כו. ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרל."],["2314","62","<b>אלה גימ' ל\"ו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380068\" data-slug=\"likkutei-torah\" data-id=\"4001380068\">ז, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670519\" data-slug=\"torat-chaim\" data-id=\"2300670519\">תו\"ח נח נו, ב</a> ובהערה 15. משפטים ח\"ב רצא, ד ובהערה 268.\n\n<b>ח</b> ) <b>לקמן בד\"ה ביום השמיני שלח</b>: סה\"מ תרל\"ה ח\"ב ע' תנד ואילך. וש\"נ. נדפס גם בסה\"מ תרל\"ח שם ע' קמג ואילך.\nבד\"ה ביום השמיני שלח הכוונה כאן למאמר דש\"ת — ראה גם לעיל מאמר ד\"ה להבין וכו' בענין הציץ הערה *סט."]]],[2001910257,"למטה, ולמעלה הם ו\"ק רוחניים<sup data-n=\"2315\">63</sup>, ומחמת שיש כמה מדרגות בו\"ק שיש ו\"ק דעשי' ו\"ק דיצי' ו\"ק דבריאה זהו ענין אלה גימ' ל\"ו ופ\"ו, וכ\"ז הוא בבחי' גילוי, משא\"כ מי הוא דבר שאינו מושג כלל, ופי' שאו מרום עיניכם וראו מי ברא אלה שתראו איך שבחי' מי שאינו מושג מחיה תמיד בחי' אלה, וזהו אחד דק\"ש שארז\"ל כל המאריך באחד<sup data-n=\"2316\">64</sup> מאריכין לו ימיו ושנותיו, פי' שמאריך באחד כי הנה אחד ח\"ד הוא בחי' ז' רקיעים וארץ וד' רוחות<sup data-n=\"2317\">65</sup> שהוא בחי' אלה, וענין מאריך באחד היינו שממשיך בחי' מי א' דאחד בז' רקיעים כו' שיתבונן היטב איך שבחי' מי מחיה תמיד בחי' אלה ז' רקיעים ועי\"ז הם בטלים אליו ית', וזהו מ\"ש מי יתן והי' לבבם זה להם ליראה<sup data-n=\"2318\">66</sup> כו', ומזה למדו רז\"ל הכל בידי שמים<sup data-n=\"2319\">67</sup> חוץ מיראת שמים, וא\"כ לכאו' צ\"ל ממי מבקש שיראו אותו, אך הענין הוא דהנה שמים הוא בחי' ז\"א<sup data-n=\"2320\">68</sup> והכל בידי שמים שהכל נמשך מבחי' המדות חו\"ג כו' חוץ מיראת שמים שאינו בידי שמים כ\"א למעלה מבחי' שמים דהיינו מבחי' מי שאינו מושג, וזהו שאמר מי יתן שבחי' מי יתן והי' לבבם זה ליראה כו'. וזהו שאנו מבקשים ויחד לבבינו כו' וליראה<sup data-n=\"2321\">69</sup> כו', וזהו הרקיע שעל ראשי החיות שהוא רקיע כעין הקרח, פי' חיות בחי' חיון עילאין בחי' מרכבה דאצי' ז\"א, וראשי החיות הם בחי' המוחין דז\"א, ועל ראשי החיות הוא בחי' הרקיע בחי' בינה שנמשך מבחי' מי כנ\"ל, (וכנודע שיש חיון עילאין וחיון תתאין<sup data-n=\"2322\">70</sup> כמ\"ש בלק\"ת בד\"ה אם בהרת פ\"ב<sup data-n=\"2324\">72</sup>, חיון תתאין הם המרכבה דבי\"ע<sup data-n=\"2323\">71</sup> מחנה מיכאל<sup data-n=\"2325\">73</sup> כו' וחיון עילאין הם האבות אברהם יצחק ויעקב חג\"ת דאצי'<sup data-n=\"2326\">74</sup>, והרקיע שעל ראשם הוא בינה וכמ\"ש בזהר פ' ויקהל דרי\"ג סע\"א), וע\"פ הקבלה מי הוא בחי' ע\"י<sup data-n=\"2327\">75</sup> ולפעמים נק' מי כתר<sup data-n=\"2328\">76</sup>, ומה שאמרו לפעמים מי בינה<sup data-n=\"2329\">77</sup> היינו כי מי הוא גימ' נ'<sup data-n=\"2330\">78</sup> והוא בחי' שער הנ' דבינה שבו התגלות עתיק כי התגלות עתיק הוא בבינה<sup data-n=\"2331\">79</sup> דוקא כמו בגשמי'",[["2315","63","<b>ו\"ק גשמיי' . . רוחניים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380283\" data-slug=\"likkutei-torah\" data-id=\"4001380283\">לקו\"ת בחוקותי מח, ב</a>. מאמרי אדה\"ז תקס\"ב ח\"א ע' קמב ואילך. שע\"ת קכה, ג. אמרי בינה פתח השער ובהנסמן לשם."],["2316","64","<b>כל המאריך באחד</b>: ברכות יג, ב."],["2317","65","<b>ח\"ד . . ז' . . וד' רוחות</b>: ראה שו\"ע אדה\"ז הל' ק\"ש סס\"א, ס\"ו. סה\"מ תר\"ם ח\"א ע' קט הערה 50."],["2318","66","<b>מי יתן . . ליראה</b>: ואתחנן ה, כו. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380368\" data-slug=\"likkutei-torah\" data-id=\"4001380368\">לקו\"ת במדבר טו, א</a> ואילך. אוה\"ת ואתחנן ע' קצה ואילך. סה\"מ תר\"ם ח\"א ע' קיד וע' שלה."],["2319","67","<b>הכל בידי שמים</b>: ברכות לג, ב."],["2320","68","<b>שמים . . ז\"א</b>: ראה זהר בשלח סב, ב. אד\"ז האזינו רפח, א. סה\"מ תרל\"ח ע' צו. וש\"נ."],["2321","69","<b>ויחד לבבינו. . וליראה</b>: ברכת (אהבת עולם אהבתנו) ק\"ש. ראה גם לקו\"ת במדבר שם."],["2322","70","<b>חיון עילאין . . וחיון תתאין</b>: ראה בסמוך הערה 72."],["2324","72","<b>בלק\"ת בד\"ה אם בהרת פ\"ב</b>: תזריע כב, ד. ראה גם לעיל שם הערה 85."],["2323","71","<b>מרכבה דאצי' . . המרכבה דבי\"ע</b>: ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה הערה 86."],["2325","73","<b>מחנה מיכאל</b>: ראה זהר במדבר קיח, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381034\" data-slug=\"likkutei-torah\" data-id=\"4001381034\">לקו\"ת האזינו עז, ד</a>."],["2326","74","<b>אברהם יצחק ויעקב חג\"ת</b>: ראה מאו\"א מערכת אבות סכ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540325\" data-slug=\"torat-chaim\" data-id=\"2300540325\">תו\"ח וארא ח\"א סא, ד</a>. וש\"נ."],["2327","75","<b>מי . . ע\"י</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380293\" data-slug=\"likkutei-torah\" data-id=\"4001380293\">לקו\"ת בחוקותי נ, ד</a>. ניצוצי אורות לזהר תרומה קלט, ב אות א."],["2328","76","<b>מי כתר</b>: ראה עמק המלך שער קרית ארבע שי\"ד, פ\"ז."],["2329","77","<b>מי בינה</b>: זהר משפטים קיז, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550228\" data-slug=\"torat-chaim\" data-id=\"2300550228\">תו\"ח פקודי ח\"ב תמג, ד</a> ובהערה 78."],["2330","78","<b>מי הוא גימ' נ'</b>: ראה גם פרדס שעה\"כ שכ\"ג, פי\"ג מערכת מי. שער ההקדמות דרוש ו בכניסת המוחין ובהגדלת ז\"א (קע, ב). מאו\"א מערכת מי אות סח."],["2331","79","<b>התגלות עתיק הוא בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">תו\"ח לך פא, ב</a>. ביאוה\"ז להצ\"צ אחרי ע' שסד."]]],[2001910258,"כאשר מבין השכל היטב אזי מתענג מהשכל, אבל כשהשכל הוא עדיין בבחי' הברקה בעלמא אינו מתענג ממנו כלל, וכך יובן למעלה כאשר האור בא בבחי' ההשגה דהיינו בחי' בינה אזי מאיר בחי' התענוג וזהו בחי' רקיע.",[]],[2001910259,"<h3>וענין מתיבתא דרקיע</h3>\n<b>ש\"פ מצורע</b>\nה) <b>וענין</b> מתיבתא דרקיע<sup data-n=\"2332\">1</sup> הוא בחי' געה\"ע<sup data-n=\"2333\">2</sup> שבבחי' געה\"ע שהוא בבריאה<sup data-n=\"2334\">*3</sup> מלובש בחי' רקיע בחי' בינה כמ\"ש בת\"ז אימא מקננא בכורסיא<sup data-n=\"2335\">3</sup> כו', כי בד\"כ יש ב' בחי' געה\"ע וגעה\"ת<sup data-n=\"2336\">4</sup>, ואף שיש כמה בחי' ג\"ע אך זה בדרך פרט, אבל בד\"כ יש ב' בחי' געה\"ת וגעה\"ע וכמו\"כ יש ב' מתיבתות<sup data-n=\"2337\">5</sup> כמ\"ש בזהר דהיינו מתיבתא דרקיע כנ\"ל ומתיבתא דמט\"ט, וכמו שלמטה בגשמי' היו ב' מתיבתות מתיבתא דסוריא<sup data-n=\"2338\">6</sup> ומתיבתא דנהרדעא<sup data-n=\"2339\">7</sup> כו'. והנה הזוכים לישב במתיבתא דרקיע הם נשמות הצדיקים גדולים תנאים ואמוראים, ולהבין ענין תנאים ואמוראים, הנה שם תנאים<sup data-n=\"2340\">8</sup> הוא מל' והאתנים מוסדי ארץ<sup data-n=\"2341\">9</sup>, אתנים אותיות תנאים<sup data-n=\"2342\">10</sup>, ואיתן גימ' תניא<sup data-n=\"2343\">11</sup>,",[["2332","1","<b>וענין מתיבתא דרקיע</b>: מאמר זה הוא המשך למאמר ד\"ה בגמ' וכו' קא מפלגי במתיבתא דרקיע שנדפס לפנ\"ז. ראה בהנרשם שם הערה 1.\nפרק זה שהוא פ\"ה שנדפס בסה\"מ תרל\"ה ח\"א ס\"ע רכו ואילך. נמצא גם לקמן בהמאמר שנדפס לאח\"ז. ושם ישנו הן פתיחה וכן המשך נוסף. וראה בהנסמן בריש המאמר שם.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפס לקמן בחלק הנחותיו ושם הפתיחה: זאת תהי' תורת המצורע."],["2333","2","<b>מתיבתא דרקיע . . געה\"ע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כאן כב, ד</a>. סהמ\"צ להצ\"צ קג, ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940116\" data-slug=\"or-hatorah-hb\" data-id=\"8159940116\">אוה\"ת תזריע כרך ב ע' תקלב</a>. ויקרא כרך א ע' רנג ואילך."],["2334","*3","<b>געה\"ע שהוא בבריאה</b>: ראה גם לקמן מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום ובהערה 66."],["2335","3","<b>אימא מקננא בכורסיא</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["2336","4","<b>בד\"כ . . געה\"ע וגעה\"ת</b>: ראה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כתר יתנו לך ובהערה 85."],["2337","5","<b>ב' מתיבתות</b>: ראה זח\"א בהשמטות רסו, א. שלח קסג, א. ז\"ח יתרו לו, ב ובניצוצי זהר שם.\nראה גם הגהות הרח\"ו לזהר שלח שם. אוה\"ת תזריע שם."],["2338","6","<b>דסוריא</b>: וכ\"ה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן. ס\"מ עזר\"ת ע' קפ. בסה\"מ תרל\"ה כאן ע' רכז העיר לכאו' צ\"ל: דסורא."],["2339","7","<b>דסוריא . . דנהרדעא</b>: ראה אגרת רב שרירא גאון ח\"ג, פ\"ב. ועוד. סדר הדורות ג\"א תתקע\"ט ד\"ה רב ושמואל."],["2340","8","<b>שם תנאים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370222\" data-slug=\"torah-or\" data-id=\"3901370222\">תו\"א שמות מט, ב</a>-ג."],["2341","9","<b>והאתנים מוסדי ארץ</b>: מיכה ו, ב."],["2342","10","<b>אתנים אותיות תנאים</b>: זהר סבא משפטים קי, ב. רע\"מ תצא רעח ב. ת\"ז תכ\"א מג, סע\"ב. מו, ב."],["2343","11","<b>ואיתן גימ' תניא</b>: ראה זהר שם. ת\"ז שם מד, רע\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540864\" data-slug=\"torat-chaim\" data-id=\"2300540864\">תו\"ח שמות ח\"א יב, ג</a>. וש\"נ. סה\"מ עזר\"ת שם [ושם: אותיות תניא — וכ\"ה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן]. תרל\"ה כאן בהערה."]]],[2001910260,"ואמוראים<sup data-n=\"2344\">12</sup> מל' את ה' האמרת היום<sup data-n=\"2345\">13</sup> ומל' כי אמרתי עולם חסד יבנה<sup data-n=\"2346\">14</sup>. ופי' תנאים מל' אתנים, כי הנה כתי' משכיל<sup data-n=\"2347\">15</sup> לאיתן*, פי' משכיל הוא בחי' אור כנ\"ל<sup data-n=\"2348\">16</sup> בפי' אור מים רקיע, ואיתן הוא בחי' רקיע בחי' חוזק כמשארז\"ל איתן כמשמעו קשה<sup data-n=\"2349\">17</sup>, ופי' משכיל לאיתן היינו ההארה המאיר מבחי' משכיל לבחי' איתן והיינו בחי' ההברקה שמבריק כו'. ולהבין ענין התנאים והאמוראים צ\"ל מה שהתנאים והאמוראים היו יכולים לעשות נסים<sup data-n=\"2350\">18</sup> גדולים ונפלאים, ר' פנחס<sup data-n=\"2351\">19</sup> בן יאיר שא' גינאי חלוק לי מימך<sup data-n=\"2352\">20</sup> מה שבהאסף משה וס' רבוא מישראל בשעת קי\"ס הי' פלא. ויובן זה בהקדם ענין תורה ותפלה, הנה ארז\"ל על מה אבדה הארץ<sup data-n=\"2353\">21</sup> על שלא ברכו בתורה<sup data-n=\"2354\">22</sup> תחלה, ואין הפי' שלא ברכו ברכת התורה כ\"א שלא המשיכו בתו' כי אוריי' מח\"ע נפקת<sup data-n=\"2355\">23</sup>, אאלפך חכ'<sup data-n=\"2356\">24</sup> ששרש התורה היא מבחי' חכ', אכן התורה ירדה למטה ונתלבשה בו\"ק כשר פסול כו' וצריכין להמשיך שרש התורה בתורה זהו ע\"י בחי' ומדרגת התפלה שהתפלה היא הקדמה בכדי להמשיך שרש התורה בתורה כו'. כי הנה ענין התפלה הוא להתבונן בגדולת ה' א\"ס ב\"ה איך שלגדולתו אין חקר<sup data-n=\"2357\">25</sup> ואיך שכל השתלשלו' העולמות מריש כ\"ד עד סוכד\"ר מקור התהוותן וחיותן הוא רק מהארה בעלמא כו', וזהו ענין אחד דק\"ש איך דכולא קמי' כלא חשיב<sup data-n=\"2358\">26</sup>, אי לזאת לא יחפוץ בשום דבר\n\n<i>*)נרשם בשולי הגליון ואולי שייך לכאן:</i>\nאיתן פי' בלק\"ת<sup data-n=\"8418\">א</sup> סוף ביאור בשעה שהקדימו דט\"ו ע\"ב שער החמשים דבינה ועליו אמרו אותיות איתן משמשות לעתיד<sup data-n=\"8419\">ב</sup>.",[["2344","12","<b>ואמוראים</b>: ראה אוה\"ת תזריע כרך ב ע' תקלא. סה\"מ עזר\"ת ע' קפא."],["2345","13","<b>את ה' האמרת היום</b>: תבוא כו, יז."],["2346","14","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["2347","15","<b>משכיל לאיתן</b>: שם פט, א."],["2348","16","<b>כנ\"ל</b>: במאמר שלפנ\"ז פ\"ג."],["2349","17","<b>איתן כמשמעו קשה</b>: סוטה מה, ב במשנה. מו, סע\"א ואילך."],["2350","18","<b>שהתנאים והאמוראים . . נסים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תמג. וש\"נ. ס\"ע תנו ואילך. שמות ח\"א ע' קע ואילך. תקע\"ז ע' רכח ואילך. סהמ\"צ להצ\"צ קג, ב. סה\"מ תרל\"ה כאן ע' רכז. תרל\"ט ח\"א ע' קנט. וש\"נ. ע' רסג. ע' שמו. פלח הרמון ויקרא ע' ק."],["2351","19","<b>ונפלאים ר' פנחס</b>: בסה\"מ תרל\"ה כאן העיר אוצ\"ל: ונפלאים כמו ר' פנחס."],["2352","20","<b>גינאי חלוק לי מימך</b>: חולין ז, א. ראה גם סה\"מ תרל\"ח ע' שעט. וש\"נ."],["2353","21","<b>על מה אבדה הארץ</b>: ירמי' ט, יא."],["2354","22","<b>שלא ברכו בתורה</b>: ב\"מ פה, ב. נדרים פא, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">לקו\"ת פ' ראה כט, א</a>."],["2355","23","<b>אוריי' מח\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["2356","24","<b>אאלפך חכ'</b>: ע\"פ איוב לג, ג. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380217\" data-slug=\"likkutei-torah\" data-id=\"4001380217\">לקו\"ת אמור לב, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380836\" data-slug=\"likkutei-torah\" data-id=\"4001380836\">פ' ראה ל, א</a>."],["2357","25","<b>שלגדולתו אין חקר</b>: ע\"פ תהלים קמה, ג."],["2358","26","<b>דכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג.\n\n<b>א</b> ) <b>פי' בלק\"ת</b>: במדבר.\n\n<b>ב</b> ) <b>אותיות איתן משמשות לעתיד</b>: שהן באין בריש התיבה להורות על שימוש הפעולה להבא אפע\"ל יפע\"ל תפע\"ל נפע\"ל — <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת פ' ראה יח, א</a>."]]],[2001910261,"כ\"א לה' לבדו, וזהו ואהבת את הוי'<sup data-n=\"2359\">27</sup> שלא יהי' רצון אחר כ\"א לה' לבדו, אך איך ימלא חפצו ורצונו שאינו חפץ כ\"א לה' לבדו הלא לית מח' תפיסא בי'<sup data-n=\"2360\">28</sup> זהו מ\"ש אח\"כ והיו הדברים האלה<sup data-n=\"2361\">29</sup> אשר אנכי מצוך וקאי על התורה שאורייתא וקוב\"ה כולא חד<sup data-n=\"2362\">30</sup> כו', וזהו והיו הדברים האלה אשר אנכי כו', פי' שאף שהתורה היא בבחי' אלה דהיינו בבחי' ו\"ק<sup data-n=\"2363\">31</sup> למטה עכ\"ז נמצא בה בחי' אנכי מי שאנכי<sup data-n=\"2364\">32</sup> שרש התורה, והיינו בהקדם ענין התפלה דוקא, שע\"י התפלה ממשיכים תוס' אור בחכמה שרש התורה. וזהו שארז\"ל אבא בנימין אומר, על תפלתי שתהא סמוכה למטתי<sup data-n=\"2365\">33</sup>, כי לימוד התורה צ\"ל אחר התפלה כדי שיהי' המשכת הכתר בחכ' דתורה שזהו ע\"י התפלה דוקא בחי' בכל מאדך, כמ\"ש בביאור שני דיונתי שבלק\"ת רפ\"ד<sup data-n=\"2366\">34</sup>, וממילא נמשך תוס' אור גם בתורה כמו שנתלבשה בו\"ק כו'. וענין ל' אמוראים הוא מל' את ה' האמרת כו' כי אמרתי עולם חסד יבנה ל' אמירה ודבור, הנה מצינו שהכתוב מזהיר על דבור התורה<sup data-n=\"2367\">*35</sup> כמ\"ש בהרבה מקומות, וידבר ה' אל משה לאמר<sup data-n=\"2368\">35</sup> כו', וגם בגמ' הזהירו ע\"ז<sup data-n=\"2369\">36</sup>, וז\"ע ודברת בם<sup data-n=\"2370\">37</sup> שבק\"ש, כי הנה שרש הדבור הוא מבחי' גבוה מאד שזהו מ\"ש ויהי האדם לנפש חיה, ות\"י לרוח ממללא<sup data-n=\"2371\">38</sup>, שהדבור הוא מבחי' חי'<sup data-n=\"2372\">39</sup> שלמעלה מבחי' נשמה, וגם מעלת המדבר הוא במה שיש לו בחי' הדבור כו', וגם הנה אנו רואים שע\"י הרוח מוציאים<sup data-n=\"2373\">40</sup> השלהבת מן הגחלת שכבה ויש בה ניצוץ א' הנה ע\"י הרוח שנופחים בה מוציאים אותה מהעלם אל הגילוי, כך הנה למעלה איתא בס\"י עשר ספירות<sup data-n=\"2374\">41</sup> בלי מה כשלהבת קשורה בגחלת, וע\"י דבור התורה שהוא בחי' רוח",[["2359","27","<b>ואהבת את הוי'</b>: ואתחנן ו, ה."],["2360","28","<b>לית מח' תפיסא בי'</b>: ת\"ז בהקדמה יז, א."],["2361","29","<b>והיו הדברים האלה</b>: ואתחנן ו, ו. ראה הנסמן לעיל במאמר ד\"ה הקבצו ושמעו בנ\"י הערה 113."],["2362","30","<b>שאורייתא וקוב\"ה כולא חד</b>: מובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא (פ\"ד</a> ופכ\"ג) בשם הזהר. ראה מאמרי אדה\"א ויקרא ח\"א ע' רפה. וש\"נ. אוה\"ת חוקת ע' תשס."],["2363","31","<b>אלה . . ו\"ק</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380068\" data-slug=\"likkutei-torah\" data-id=\"4001380068\">ז, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670519\" data-slug=\"torat-chaim\" data-id=\"2300670519\">תו\"ח נח נו, ב</a> ובהערה 15. משפטים ח\"ב רצא, ד ובהערה 268."],["2364","32","<b>אנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["2365","33","<b>אבא בנימין . . סמוכה למטתי</b>: ראה ברכות ה, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381112\" data-slug=\"likkutei-torah\" data-id=\"4001381112\">לקו\"ת</a> שבהערה הבאה. ברכה צו, ב. ואתחנן ד, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550507\" data-slug=\"torat-chaim\" data-id=\"2300550507\">תו\"ח תצוה ח\"ב שנ, ב</a> ואילך. סה\"מ תרכ\"ז ע' רפח בשולי הגליון."],["2366","34","<b>בביאור שני דיונתי שבלק\"ת רפ\"ד</b>: שה\"ש כ, רע\"ד."],["2367","*35","<b>שהכתוב מזהיר על דבור התורה</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 65."],["2368","35","<b>וידבר ה' אל משה לאמר</b>: ל' הכתוב וארא ו, י. כט. בא יג, א. ועוד. ראה גם לקמן מאמר ד\"ה כתר יתנו לך ובהערה 104. סה\"מ תרצ\"ז ע' 263. עטר\"ת ס\"ע שצד ואילך. תרכ\"ו ע' פה ד\"ה קדיש [נדפס גם בסה\"מ תרכ\"ט ריש ע' קפד]. תרנ\"ד ע' רנא [נדפס גם בסה\"מ תרנ\"ו ע' שדמ]. הערה בסה\"מ תרל\"ה כאן ס\"ע רכח."],["2369","36","<b>בגמ' הזהירו ע\"ז</b>: ערובין נד, א."],["2370","37","<b>ודברת בם</b>: ואתחנן ו, ז. ראה ספרי ופרש\"י שם. יומא יט, ב ובפרש\"י שם ד\"ה בם (הב'). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071278\" data-slug=\"likkutei-sichot\" data-id=\"1300071278\">לקו\"ש פסח כרך ז ע' 266</a> הערה 2. פקודי כרך טז ע' 462 ואילך ובהערות שם."],["2371","38","<b>ויהי האדם . . ות\"י לרוח ממללא</b>: נסמן לעיל מאמר ד\"ה מגילה נקראת הערה 249."],["2372","39","<b>שהדבור הוא מבחי' חי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370014\" data-slug=\"torah-or\" data-id=\"3901370014\">תו\"א בראשית ד, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">מקץ מב, ב</a>."],["2373","40","<b>שע\"י הרוח מוציאים</b>: השווה (לענין תפלה) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380216\" data-slug=\"likkutei-torah\" data-id=\"4001380216\">לקו\"ת אמור לב, ג</a>."],["2374","41","<b>איתא בס\"י עשר ספירות</b>: ראה שם פ\"א, מ\"ז."]]],[2001910262,"מוציאים הע\"ס מהעלם אל הגילוי להיות חסד דרועא ימינא<sup data-n=\"2375\">42</sup> מאיר למטה בגילוי, כי הרוח שרשו גבוה מאד והוא מבחי' אויר* שלמעלה מבחי' אור<sup data-n=\"2376\">43</sup> והוא בחי' אור יו\"ד<sup data-n=\"2377\">44</sup> כמ\"ש במ\"א, וזהו שהיו התנאים והאמוראים יכולים לעשות נסים גדולים לפי שע\"י תורתם ועבודתם המשיכו מבחי' גבוה מאד מבחי' מי כנ\"ל לכן היו יכולים לשנות היפך הטבע וכמו ע\"ד שארז\"ל מי שאמר לשמן<sup data-n=\"2378\">45</sup> וידליק יאמר לחומץ וידליק, פי' כי מבחי' מי יכול להיות שגם בחי' חומץ ידלק כמו שמן כי בחי' מי הוא למעלה מבחי' התחלקות הצירופים שבין שמן לחומץ כו' לכן יכול להיות שיאיר בחי' האור הנמשך בצירוף אותיות שמן בצירופי אותיות חומץ, וכמו מי יתן טהור מטמא<sup data-n=\"2379\">46</sup> שמבחי' מי יכול להיות טהור מטמא כו'.\n\n<i>*)נרשם בצד העמוד:</i>\nלענין אויר ע' בביאור ציץ<sup data-n=\"8420\">ג</sup> משה<sup data-n=\"8421\">ד</sup> למעלה מהבדלה שבין קדש לקדש ובאדם הוא קרום המפסיק בין המוח לאויר (לבד קרום של מוח שהמוח בתוכו) קדמון וע' בלק\"ת בביאור החלצו<sup data-n=\"8422\">ה</sup> בענין קרומא דאוירא<sup data-n=\"8423\">ו</sup>.",[["2375","42","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה יז, א."],["2376","43","<b>הרוח . . אויר . . אור</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370194\" data-slug=\"torah-or\" data-id=\"3901370194\">מג, ב</a>."],["2377","44","<b>אויר . . אור יו\"ד</b>: נסמן לעיל במאמר ד\"ה להבין וכו' בענין הציץ הערה 214."],["2378","45","<b>מי שאמר לשמן</b>: ראה תענית כה, א (כגי' הע\"י). מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קעח. ע' ערב ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541044\" data-slug=\"torat-chaim\" data-id=\"2300541044\">תו\"ח שמות ח\"א כ, א</a>. וש\"נ."],["2379","46","<b>מי יתן טהור מטמא</b>: איוב יד, ד. ראה לקו\"ת חוקת ס, א.\n\n<b>ג</b> ) <b>בביאור ציץ משה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370374\" data-slug=\"torah-or\" data-id=\"3901370374\">תו\"א תצוה פד, א</a>-ב.\n\n<b>ד</b> ) <b>ציץ משה</b>: ציץ שעשה משה.\n\n<b>ה</b> ) <b>בלק\"ת בביאור החלצו</b>: מטות פז, ג.\n\n<b>ו</b> ) <b>קרומא דאוירא</b>: ראה זהר ספרא דצניעותא תרומה קעו, ב. אד\"ר נשא קכח, ב."]]],[2001910263,"<h3>לה\"ע וכו' זאת תהי'</h3>\n<b>לא הועתק</b>\n<b>להבין</b> ענין טהרת המצורע<sup data-n=\"2380\">1</sup> שהוא ע\"י שני צפורים, כמ\"ש ולקח למטהר שתי צפרים<sup data-n=\"2381\">2</sup> חיות טהורות כו' ואח\"כ נא' ושילח את הציפור החיה<sup data-n=\"2382\">3</sup> ע\"פ השדה.\n<b>זאת</b> תהי' תורת המצורע<sup data-n=\"2383\">4</sup>, וארז\"ל במד\"ר במקומו<sup data-n=\"2384\">5</sup> מפסוק (משלי ואו)<sup data-n=\"2385\">6</sup> שש הנה שנא ה' המוציא שם רע, שעבור לה\"ר ורכילות והוצאת שם רע לוקים בנגעים כמו הנחש שהוציא שם רע על בוראו לכן לקה בנגעים כמארז\"ל במד\"ר בראשית פ' ך'<sup data-n=\"2386\">7</sup> שאררו בצרעת, הלין סלעיא דביה, צרען אינון (ופי' המ\"כ החברבורות כמו סלעים של<sup data-n=\"2387\">8</sup> הנחש צרעת הם), וכן ע\"י לב חורש מחשבות און<sup data-n=\"2388\">9</sup> עי\"ז לוקים ג\"כ בצרעת, ע\"ש במד\"ר. וצ\"ל מהו ענין לה\"ר ורכילות והוצאת ש\"ר ולב חורש מחשבת און שהם חטא ופגמו הדבור ומחשבה כמארז\"ל הלב חושב<sup data-n=\"2389\">10</sup> להיות לוקים עי\"ז\n\n<i>נרשם בשולי היריעה:</i>\nשחוטה מוח בינה דנוגה, חיה חכמה דנוגה בלק\"ת מהאריז\"ל במקומו<sup data-n=\"8424\">א</sup>.",[["2380","1","<b>להבין ענין טהרת המצורע וכו' זאת תהי' תורת המצורע</b>: מאמר זה הוא המשך למאמר ד\"ה בגמ' וכו' קא מפלגי במתיבתא דרקיעא שנאמר בש\"פ תזריע שנדפס לעיל. והמאמר שנדפס לפנ\"ז מש\"פ מצורע ד\"ה וענין מתיבתא דרקיע הוא המשך למאמר הנ\"ל כפי שאמרו כ\"ק אדמו\"ר מהר\"ש [בהשמטת הפתיחה], וכאן נרשם המאמר כפי שכתבו [וכאן ישנו המשך נוסף, אלא מהנחת כ\"ק אדמו\"ר מהורש\"ב משמע שהמשך נוסף זה לא נאמר], ולא ניתן להעתיקו, כפי שנרשם בריש המאמר כאן לא הועתק.\nמאמר זה פרט להפתיחה והסיום שנרשם בגוכתי\"ק הוא כת\"י מעתיק, והוא העתק פרקים ה-ח בסה\"מ תרל\"ה ח\"א ע' רכו-רלד. אלא שבמאמר ד\"ה בגמ' וכו' קא מפלגי במתיבתא דרקיעא נרשמו הפרקים א-ג ובמאמר ד\"ה וענין מתיבתא דרקיע נרשם פ\"ה כנ\"ל במאמר שנדפס לפנ\"ז. הנה במאמר דידן לא נרשמו פרקים.\nלמאמר זה ראה הנרשם לעיל במאמר ד\"ה בגמ' וכו' קא מפלגי במתיבתא דרקיע הערה 1. המאמר שנדפס שלפנ\"ז ד\"ה וענין מתיבתא דרקיע נרשם כאן בתחילת המאמר על יד הערה 22 ואילך.\nבנידן הפתיחה הנה לע\"ע לא נתברר איזה פתיחה נרשמה לראשונה אם ”להבין ענין טהרת המצורע\" או כפי שנאמר בעת אמירת הדרוש ”זאת תהי' תורת המצורע\", ומשנה לא זזה ממקומה, ובפרט שכנ\"ל שהמאמר לא ניתן להעתיק. ואף שבמפתח הבוך נרשמה הפתיחה להבין ענין טהרת המצורע, אולי המעתיק לא דק בזה ורשם רק התיבות הראשונות שראה.\nהנחת כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפס לקמן בחלק הנחותיו ושם הפתיחה: זאת תהי' תורת המצורע."],["2381","2","<b>ולקח למטהר שתי צפרים</b>: מצורע יד, ד."],["2382","3","<b>ושילח את הצפור החיה</b>: שם, שם, ז."],["2383","4","<b>זאת תהי' תורת המצורע</b>: מצורע יד, ב."],["2384","5","<b>במד\"ר במקומו</b>: ראה ויק\"ר פט\"ז, א."],["2385","6","<b>משלי ואו)</b>: פסוק טז."],["2386","7","<b>פ' ך'</b>: סימן ד."],["2387","8","<b>של</b>: שם: שעל."],["2388","9","<b>לב חורש מחשבות און</b>: משלי ו, יח. ראה גם סה\"מ תרל\"ב ח\"ב ע' תסו א\"כ י\"ל וכו'."],["2389","10","<b>הלב חושב</b>: קה\"ר פ\"א, טז [ושם: מחשב]. זהר מדהנ\"ע תולדות קלח, ב: והלב הוא החושב.\n\n<b>א</b> ) <b>בלק\"ת מהאריז\"ל במקומו</b>: ר\"פ מצורע הועתק לקמן בפנים בסיום המאמר."]]],[2001910264,"בצרעת. וגם צ\"ל מה שלענין טהרת המצורע ה\"צ שתי צפרים, והאחת שחטו<sup data-n=\"2390\">11</sup>, והשנית שלחו ע\"פ השדה. ובכדי להבין ענין הנגעי' נקדים ענין הפלוגתא שקא מפלגי במתיבתא דרקיע<sup data-n=\"2391\">12</sup> בדין דבהרת שאם בהרת קדמה כו', ספק הקב\"ה אומר טהור וכולהו מתיבתא דרקיע כו', וצ\"ל מ\"ע מתיבתא דרקיע, ונת'<sup data-n=\"2392\">13</sup> שענין בחי' רקיע הוא רקיע תמינאה<sup data-n=\"2393\">14</sup> שלמעלה מז' רקיעים<sup data-n=\"2394\">15</sup> שהוא בחי' רקיע כעין הקרח<sup data-n=\"2395\">16</sup>, אשר מבטן מי<sup data-n=\"2396\">17</sup> בחי' עת\"י<sup data-n=\"2397\">18</sup> יצא הקרח, שהרקיע הוא שער הנו\"ן דבינה שנק' שער האיתן<sup data-n=\"2398\">19</sup> ובו הוא גילוי התענוג כו' שהתגלות עתיק הוא בבינה<sup data-n=\"2399\">20</sup> דוקא כמו שבגשמיות כאשר מבין השכל על בוריו אז מתענג ממנו כו' כך למעלה עיקר גילוי הענג הוא בבינה שנק' רקיע<sup data-n=\"2400\">21</sup>, ומבחי' רקיע זה מאיר במתיבתא דרקיע שהוא בחי'<sup data-n=\"2402\">23</sup> ג\"ע העליון<sup data-n=\"2401\">22</sup>. שבבחי' געה\"ע שהוא בבריאה<sup data-n=\"2403\">*24</sup> מלובש בחי' רקיע בחי' בינה כמ\"ש בת\"ז אימא מקננא בכורסיא<sup data-n=\"2404\">24</sup> כו', כי בד\"כ יש ב' בחי' געה\"ע וגעה\"ת<sup data-n=\"2405\">25</sup>, ואף שיש כמה בחי' ג\"ע אך זה בדרך פרט, אבל בד\"כ יש ב' בחי' געה\"ת וגעה\"ע וכמו\"כ יש ב' מתיבתות<sup data-n=\"2406\">26</sup> כמ\"ש בזהר דהיינו מתיבתא דרקיע כנ\"ל ומתיבתא דמט\"ט, וכמו שלמטה בגשמי' היו ב' מתיבתות מתיבתא דסוריא<sup data-n=\"2407\">27</sup> ומתיבתא דנהרדעא<sup data-n=\"2408\">28</sup> כו'. והנה הזוכים לישב במתיבתא דרקיע הם נשמות הצדיקים גדולים תנאים ואמוראים, ולהבין ענין תנאים ואמוראים, הנה שם תנאים<sup data-n=\"2409\">29</sup> הוא מל' והאתנים מוסדי ארץ<sup data-n=\"2410\">30</sup>, אתנים אותיות תנאים<sup data-n=\"2411\">31</sup>,",[["2390","11","<b>והאחת שחטו</b>: מצורע יד, ה."],["2391","12","<b>שקא מפלגי במתיבתא דרקיע</b>: ראה ב\"מ פ\"ו, א. לעיל מאמר ד\"ה זה."],["2392","13","<b>ונת'</b>: לעיל שם רפ\"ג ואילך."],["2393","14","<b>רקיע תמינאה</b>: זהר לך פה, סע\"ב. ראה גם סה\"מ תרל\"ה כאן ע' רכד בהערה."],["2394","15","<b>מז' רקיעים</b>: חגיגה יב, ב. ראה סה\"מ תרל\"ח ע' קיז הערה 431."],["2395","16","<b>רקיע כעין הקרח</b>: יחזקאל א, כב."],["2396","17","<b>מבטן מי</b>: איוב לח, כט."],["2397","18","<b>מי בחי' עת\"י</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380293\" data-slug=\"likkutei-torah\" data-id=\"4001380293\">לקו\"ת בחוקותי נ, ד</a>. ניצוצי אורות לזהר תרומה קלט, ב אות א."],["2398","19","<b>שער הנו\"ן . . שער האיתן</b>: מגלה עמוקות אופן נ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380369\" data-slug=\"likkutei-torah\" data-id=\"4001380369\">לקו\"ת במדבר טו, ב</a>."],["2399","20","<b>שהתגלות עתיק הוא בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">תו\"ח לך פא, ב</a>. ביאוה\"ז להצ\"צ אחרי כרך א ע' שסד."],["2400","21","<b>בבינה שנק' רקיע</b>: ראה גם לעיל שם ובהערה ח."],["2402","23","<b>בחי'</b>: מכאן עד פיסקא ומעתה יובן נדפס גם לעיל במאמר ד\"ה וענין מתיבתא דרקיע."],["2401","22","<b>במתיבתא דרקיע . . ג\"ע העליון</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380171\" data-slug=\"likkutei-torah\" data-id=\"4001380171\">לקו\"ת תזריע כאן כב, ד</a>. סהמ\"צ להצ\"צ קג, ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940116\" data-slug=\"or-hatorah-hb\" data-id=\"8159940116\">אוה\"ת תזריע כרך ב ע' תקלב</a>. ויקרא כרך א ע' רנג ואילך."],["2403","*24","<b>געה\"ע שהוא בבריאה</b>: ראה גם לקמן מאמר ד\"ה א\"ר אלעזר א\"ר חנינא ת\"ח מרבים שלום ובהערה 66."],["2404","24","<b>אימא מקננא בכורסיא</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["2405","25","<b>בד\"כ . . געה\"ע וגעה\"ת</b>: ראה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כתר יתנו לך ובהערה 85."],["2406","26","<b>ב' מתיבתות</b>: נסמן לעיל ע' קפד."],["2407","27","<b>דסוריא</b>: וכ\"ה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן. ס\"מ עזר\"ת ע' קפ. בסה\"מ תרל\"ה כאן ע' רכז העיר לכאו' צ\"ל: דסורא."],["2408","28","<b>דסוריא . . דנהרדעא</b>: ראה אגרת רב שרירא גאון ח\"ג, פ\"ב. ועוד. סדר הדורות ג\"א תתקע\"ט ד\"ה רב ושמואל."],["2409","29","<b>שם תנאים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370222\" data-slug=\"torah-or\" data-id=\"3901370222\">תו\"א שמות מט, ב</a>-ג."],["2410","30","<b>והאתנים מוסדי ארץ</b>: מיכה ו, ב."],["2411","31","<b>אתנים אותיות תנאים</b>: זהר סבא משפטים קי, ב. רע\"מ תצא רעח ב. ת\"ז תכ\"א מג, סע\"ב. מו, ב."]]],[2001910265,"ואיתן גימ' תניא<sup data-n=\"2412\">32</sup>, ואמוראים<sup data-n=\"2413\">33</sup> מל' את ה' האמרת היום<sup data-n=\"2414\">34</sup> ומל' כי אמרתי עולם חסד יבנה<sup data-n=\"2415\">35</sup>. ופי' תנאים מל' אתנים, כי הנה כתי' משכיל<sup data-n=\"2416\">36</sup> לאיתן*, פי' משכיל הוא בחי' אור כנ\"ל<sup data-n=\"2417\">37</sup> בפי' אור מים רקיע, ואיתן הוא בחי' רקיע בחי' חוזק כמשארז\"ל איתן כמשמעו קשה<sup data-n=\"2418\">38</sup>, ופי' משכיל לאיתן היינו ההארה המאיר מבחי' משכיל לבחי' איתן והיינו בחי' ההברקה שמבריק כו'. ולהבין ענין התנאים והאמוראים צ\"ל מה שהתנאים והאמוראים היו יכולים לעשות נסים<sup data-n=\"2419\">39</sup> גדולים ונפלאים, ר' פנחס<sup data-n=\"2420\">40</sup> בן יאיר שא' גינאי חלוק לי מימך<sup data-n=\"2421\">41</sup> מה שבהאסף משה וס' רבוא מישראל בשעת קי\"ס הי' פלא. ויובן זה בהקדם ענין תורה ותפלה, הנה ארז\"ל על מה אבדה הארץ<sup data-n=\"2422\">42</sup> על שלא ברכו בתורה<sup data-n=\"2423\">43</sup> תחלה, ואין הפי' שלא ברכו ברכת התורה כ\"א שלא המשיכו בתו' כי אוריי' מח\"ע נפקת<sup data-n=\"2424\">44</sup>, אאלפך חכ'<sup data-n=\"2425\">45</sup> ששרש התורה היא מבחי' חכ', אכן התורה ירדה למטה ונתלבשה בו\"ק כשר פסול כו' וצריכין להמשיך שרש התורה בתורה זהו ע\"י בחי' ומדרגת התפלה שהתפלה היא הקדמה בכדי להמשיך שרש התורה בתורה כו'. כי הנה ענין התפלה הוא להתבונן בגדולת ה' א\"ס ב\"ה איך שלגדולתו אין חקר<sup data-n=\"2426\">46</sup> ואיך שכל השתלשלו' העולמות מריש כ\"ד עד סוכד\"ר מקור התהוותן וחיותן הוא רק מהארה בעלמא כו', וזהו ענין אחד דק\"ש איך דכולא קמי' כלא חשיב<sup data-n=\"2427\">47</sup>, אי לזאת לא\n\n<i>*)נרשם בשולי היריעה ואולי שייך לכאן:</i>\nאיתן פי' בלק\"ת<sup data-n=\"8425\">ב</sup> סוף ביאור בשעה שהקדימו דט\"ו ע\"ב שער החמשים דבינה ועליו אמרו אותיות איתן משמשות לעתיד<sup data-n=\"8426\">ג</sup>.",[["2412","32","<b>ואיתן גימ' תניא</b>: ראה זהר שם. ת\"ז שם מד, רע\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540864\" data-slug=\"torat-chaim\" data-id=\"2300540864\">תו\"ח שמות ח\"א יב, ג</a>. וש\"נ. סה\"מ עזר\"ת שם [ושם: אותיות תניא — וכ\"ה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן]. תרל\"ה כאן בהערה."],["2413","33","<b>ואמוראים</b>: ראה אוה\"ת תזריע כרך ב ע' תקלא. סה\"מ עזר\"ת ע' קפא."],["2414","34","<b>את ה' האמרת היום</b>: תבוא כו, יז."],["2415","35","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["2416","36","<b>משכיל לאיתן</b>: שם פט, א."],["2417","37","<b>כנ\"ל</b>: במאמר ד\"ה בגמ' וכו' קא מפלגי במתיבתא דרקיעא פ\"ג."],["2418","38","<b>איתן כמשמעו קשה</b>: סוטה מה, ב במשנה. מו, סע\"א ואילך."],["2419","39","<b>שהתנאים והאמוראים . . נסים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תמג. וש\"נ. ס\"ע תנו ואילך. שמות ח\"א ע' קע ואילך. תקע\"ז ע' רכח ואילך. סהמ\"צ להצ\"צ קג, ב. סה\"מ תרל\"ה כאן ע' רכז. תרל\"ט ח\"א ע' קנט. וש\"נ. ע' רסג. ע' שמו. פלח הרמון ויקרא ע' ק."],["2420","40","<b>ונפלאים ר' פנחס</b>: בסה\"מ תרל\"ה כאן העיר אוצ\"ל: ונפלאים כמו ר' פנחס."],["2421","41","<b>גינאי חלוק לי מימך</b>: חולין ז, א. ראה גם סה\"מ תרל\"ח ע' שעט. וש\"נ."],["2422","42","<b>על מה אבדה הארץ</b>: ירמי' ט, יא."],["2423","43","<b>שלא ברכו בתורה</b>: ב\"מ פה, ב. נדרים פא, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">לקו\"ת פ' ראה כט, א</a>."],["2424","44","<b>אוריי' מח\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["2425","45","<b>אאלפך חכ'</b>: ע\"פ איוב לג, ג. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380217\" data-slug=\"likkutei-torah\" data-id=\"4001380217\">לקו\"ת אמור לב, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380836\" data-slug=\"likkutei-torah\" data-id=\"4001380836\">פ' ראה ל, א</a>."],["2426","46","<b>שלגדולתו אין חקר</b>: ע\"פ תהלים קמה, ג."],["2427","47","<b>דכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג.\n\n<b>ב</b> ) <b>פי' בלק\"ת</b>: במדבר.\n\n<b>ג</b> ) <b>אותיות איתן משמשות לעתיד</b>: שהן באין בריש התיבה להורות על שימוש הפעולה להבא אפע\"ל יפע\"ל תפע\"ל נפע\"ל — <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת פ' ראה יח, א</a>."]]],[2001910266,"יחפוץ בשום דבר כ\"א לה' לבדו, וזהו ואהבת את הוי'<sup data-n=\"2428\">48</sup> שלא יהי' רצון אחר כ\"א לה' לבדו, אך איך ימלא חפצו ורצונו שאינו חפץ כ\"א לה' לבדו הלא לית מח' תפיסא בי'<sup data-n=\"2429\">49</sup> זהו מ\"ש אח\"כ והיו הדברים האלה<sup data-n=\"2430\">50</sup> אשר אנכי מצוך וקאי על התורה שאורייתא וקוב\"ה כולא חד<sup data-n=\"2431\">51</sup> כו', וזהו והיו הדברים האלה אשר אנכי כו', פי' שאף שהתורה היא בבחי' אלה דהיינו בבחי' ו\"ק<sup data-n=\"2432\">52</sup> למטה עכ\"ז נמצא בה בחי' אנכי מי שאנכי<sup data-n=\"2433\">53</sup> שרש התורה, והיינו בהקדם ענין התפלה דוקא, שע\"י התפלה ממשיכים תוס' אור בחכמה שרש התורה. וזהו שארז\"ל אבא בנימין אומר, על תפלתי שתהא סמוכה למטתי<sup data-n=\"2434\">54</sup>, כי לימוד התורה צ\"ל אחר התפלה כדי שיהי' המשכת הכתר בחכ' דתורה שזהו ע\"י התפלה דוקא בחי' בכל מאדך, כמ\"ש בביאור שני דיונתי שבלק\"ת רפ\"ד<sup data-n=\"2435\">55</sup>, וממילא נמשך תוס' אור גם בתורה כמו שנתלבשה בו\"ק כו'. וענין ל' אמוראים הוא מל' את ה' האמרת כו' כי אמרתי עולם חסד יבנה ל' אמירה ודבור, הנה מצינו שהכתוב מזהיר על דבור התורה<sup data-n=\"2436\">*56</sup> כמ\"ש בהרבה מקומות, וידבר ה' אל משה לאמר<sup data-n=\"2437\">56</sup> כו', וגם בגמ' הזהירו ע\"ז<sup data-n=\"2438\">57</sup>, וז\"ע ודברת בם<sup data-n=\"2439\">58</sup> שבק\"ש, כי הנה שרש הדבור הוא מבחי' גבוה מאד שזהו מ\"ש ויהי האדם לנפש חיה, ות\"י לרוח ממללא<sup data-n=\"2440\">59</sup>, שהדבור הוא מבחי' חי'<sup data-n=\"2441\">60</sup> שלמעלה מבחי' נשמה, וגם מעלת המדבר הוא במה שיש לו בחי' הדבור כו', וגם הנה אנו רואים שע\"י הרוח מוציאים<sup data-n=\"2442\">61</sup> השלהבת מן הגחלת שכבה ויש בה ניצוץ א' הנה ע\"י הרוח שנופחים בה מוציאים אותה מהעלם אל הגילוי, כך הנה למעלה איתא בס\"י",[["2428","48","<b>ואהבת את הוי'</b>: ואתחנן ו, ה."],["2429","49","<b>לית מח' תפיסא בי'</b>: ת\"ז בהקדמה יז, א."],["2430","50","<b>והיו הדברים האלה</b>: ואתחנן ו, ו. ראה הנסמן לעיל במאמר ד\"ה הקבצו ושמעו בנ\"י הערה 113."],["2431","51","<b>שאורייתא וקוב\"ה כולא חד</b>: מובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא (פ\"ד</a> ופכ\"ג) בשם הזהר. ראה מאמרי אדה\"א ויקרא ח\"א ע' רפה. וש\"נ. אוה\"ת חוקת ע' תשס."],["2432","52","<b>אלה . . ו\"ק</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380058\" data-slug=\"likkutei-torah\" data-id=\"4001380058\">לקו\"ת פקודי ד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380068\" data-slug=\"likkutei-torah\" data-id=\"4001380068\">ז, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670519\" data-slug=\"torat-chaim\" data-id=\"2300670519\">תו\"ח נח נו, ב</a> ובהערה 15. משפטים ח\"ב רצא, ד ובהערה 268."],["2433","53","<b>אנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["2434","54","<b>אבא בנימין . . סמוכה למטתי</b>: ראה ברכות ה, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381112\" data-slug=\"likkutei-torah\" data-id=\"4001381112\">לקו\"ת</a> שבהערה הבאה. ברכה צו, ב. ואתחנן ד, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550507\" data-slug=\"torat-chaim\" data-id=\"2300550507\">תו\"ח תצוה ח\"ב שנ, ב</a> ואילך. סה\"מ תרכ\"ז ע' רפח בשולי הגליון."],["2435","55","<b>בביאור שני דיונתי שבלק\"ת רפ\"ד</b>: שה\"ש כ, רע\"ד."],["2436","*56","<b>שהכתוב מזהיר על דבור התורה</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 65."],["2437","56","<b>וידבר ה' אל משה לאמר</b>: ל' הכתוב וארא ו, י. כט. בא יג, א. ועוד. ראה גם לקמן מאמר ד\"ה כתר יתנו לך ובהערה 104. סה\"מ תרצ\"ז ע' 263. עטר\"ת ס\"ע שצד ואילך. תרכ\"ו ע' פה ד\"ה קדיש [נדפס גם בסה\"מ תרכ\"ט ריש ע' קפד]. תרנ\"ד ע' רנא [נדפס גם בסה\"מ תרנ\"ו ע' שדמ]. הערה בסה\"מ תרל\"ה כאן ס\"ע רכח."],["2438","57","<b>בגמ' הזהירו ע\"ז</b>: ערובין נד, א."],["2439","58","<b>ודברת בם</b>: ואתחנן ו, ז. ראה ספרי ופרש\"י שם. יומא יט, ב ובפרש\"י שם ד\"ה בם (הב'). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071278\" data-slug=\"likkutei-sichot\" data-id=\"1300071278\">לקו\"ש פסח כרך ז ע' 266</a> הערה 2. פקודי כרך טז ע' 462 ואילך ובהערות שם."],["2440","59","<b>ויהי האדם . . ות\"י לרוח ממללא</b>: נסמן לעיל מאמר ד\"ה מגילה נקראת הערה 249."],["2441","60","<b>שהדבור הוא מבחי' חי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370014\" data-slug=\"torah-or\" data-id=\"3901370014\">תו\"א בראשית ד, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">מקץ מב, ב</a>."],["2442","61","<b>שע\"י הרוח מוציאים</b>: השווה (לענין תפלה) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380216\" data-slug=\"likkutei-torah\" data-id=\"4001380216\">לקו\"ת אמור לב, ג</a>."]]],[2001910267,"עשר ספירות<sup data-n=\"2443\">62</sup> בלי מה כשלהבת קשורה בגחלת, וע\"י דבור התורה שהוא בחי' רוח מוציאים הע\"ס מהעלם אל הגילוי להיות חסד דרועא ימינא<sup data-n=\"2444\">63</sup> מאיר למטה בגילוי, כי הרוח שרשו גבוה מאד והוא מבחי' אויר שלמעלה מבחי' אור<sup data-n=\"2445\">64</sup> והוא בחי' אור יו\"ד<sup data-n=\"2446\">65</sup> כמ\"ש במ\"א, וזהו שהיו התנאים והאמוראים יכולים לעשות נסים גדולים לפי שע\"י תורתם ועבודתם המשיכו מבחי' גבוה מאד מבחי' מי כנ\"ל לכן היו יכולים לשנות היפך הטבע וכמו ע\"ד שארז\"ל מי שאמר לשמן<sup data-n=\"2447\">66</sup> וידליק יאמר לחומץ וידליק, פי' כי מבחי' מי יכול להיות שגם בחי' חומץ ידלק כמו שמן כי בחי' מי הוא למעלה מבחי' התחלקות הצירופים שבין שמן לחומץ כו' לכן יכול להיות שיאיר בחי' האור הנמשך בצירוף אותיות שמן בצירופי אותיות חומץ, וכמו מי יתן טהור מטמא<sup data-n=\"2448\">67</sup> שמבחי' מי יכול להיות טהור מטמא כו'.\n<b>ומעתה</b> יובן ענין הנגעים, כי הנה הנגעים הם שנים שהם ארבע<sup data-n=\"2449\">68</sup>, והם לעו\"ז<sup data-n=\"2450\">69</sup> כנגד לאה ורחל ושתי השפחות, והיינו שאת ובהרת הם לעו\"ז כנגד לאה ורחל וכמו שלאה ורחל הי' להם שפחות בלהה וזלפה שפחה לזו ושפחה לזו כך בלעו\"ז הוא בחי' ספחת<sup data-n=\"2451\">70</sup> שהיא טפל לשאת וטפל לבהרת<sup data-n=\"2452\">71</sup>, וי\"ל של' ספחת הוא מל'\n\n<i>נרשם בשולי היריעה:</i>\nלענין אויר ע' בביאור ציץד משה<sup data-n=\"8427\">ה</sup> למעלה מהבדלה שבין קדש לקדש ובאדם הוא קרום המפסיק בין המוח לאויר (לבד קרום של מוח שהמוח בתוכו) קדמון וע' בלק\"ת בביאור החלצו<sup data-n=\"8428\">ו</sup> בענין קרומא דאוירא<sup data-n=\"8429\">ז</sup>.\nא ''.כ/ד)בביאור ציץ משה: ראה תו\"א תצוה פד, א-ב.",[["2443","62","<b>איתא בס\"י עשר ספירות</b>: ראה שם פ\"א, מ\"ז."],["2444","63","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה יז, א."],["2445","64","<b>הרוח . . אויר . . אור</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370194\" data-slug=\"torah-or\" data-id=\"3901370194\">מג, ב</a>."],["2446","65","<b>אויר . . אור יו\"ד</b>: נסמן לעיל במאמר ד\"ה להבין וכו' בענין הציץ הערה 214."],["2447","66","<b>מי שאמר לשמן</b>: ראה תענית כה, א (כגי' הע\"י). מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קעח. ע' ערב ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541044\" data-slug=\"torat-chaim\" data-id=\"2300541044\">תו\"ח שמות ח\"א כ, א</a>. וש\"נ."],["2448","67","<b>מי יתן טהור מטמא</b>: איוב יד, ד. ראה לקו\"ת חוקת ס, א."],["2449","68","<b>שנים שהם ארבע</b>: נגעים פ\"א, מ\"א."],["2450","69","<b>לעו\"ז</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["2451","70","<b>שאת ובהרת . . לאה ורחל . . ספחת</b>: ראה מאו\"א מערכת ד' מראות נגעים ס\"ט. לקו\"ת להאריז\"ל ס\"פ תזריע [צויין ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200110\" data-slug=\"or-hatorah-hb\" data-id=\"8159200110\">אוה\"ת תזריע כרך ג ע' תתכג</a>]. ראה גם סה\"מ תרל\"ב ח\"ב ע' תנז.\nמאו\"א הנ\"ל הועתק עם הגהות באוה\"ת תזריע כרך ב ע' תקכט [נדפס גם במהדורת תשנ\"ב בכרך א ע' שמט]. סה\"מ תרל\"ב ח\"ב ע' תנד. וראה גם לקמן פיסקא ועפמשנ\"ת."],["2452","71","<b>ספחת . . טפל לשאת . . לבהרת</b>: שבועות ו, ב. ראה גם לקו\"ת מלכים-א עה\"פ (י, כט) ותצא המרכבה ממצרים.\n\n<b>ה</b> ) <b>ציץ משה</b>: ציץ שעשה משה.\n\n<b>ו</b> ) <b>בלק\"ת בביאור החלצו</b>: מטות פז, ג.\n\n<b>ז</b> ) <b>קרומא דאוירא</b>: ראה זהר ספרא דצניעותא תרומה קעו, ב. אד\"ר נשא קכח, ב."]]],[2001910268,"שפחות כו' והיינו שהנגעים הם ק\"נ דאצי'<sup data-n=\"2453\">72</sup>. ולכאו' צ\"ל איך שייך לומר ק\"נ דאצי'<sup data-n=\"2454\">73</sup> הלא כתי' לא יגורך רע<sup data-n=\"2455\">74</sup> שבאצי' איהו וחיוהי וגרמוהי חד<sup data-n=\"2456\">75</sup>. אך הענין דהנה ק\"נ דאצי' אינה רע כלל רק שהוא מקור<sup data-n=\"2457\">76</sup> שיתהוה מזה רע בהשתלשלות, וכנודע מענין נחש הנחושת* וכמ\"ש והי' כל הנשוך וראה אותו וחי<sup data-n=\"2458\">77</sup> וארז\"ל וכי נחש ממית או נחש מחי' אלא בזמן שישראל מסתכלין כלפי מעלה ומשעבדין את לבן לאביהן שבשמים היו מתרפאין<sup data-n=\"2459\">78</sup>, ומבואר במ\"א שהיו מביטי' למעלה והגביהו הרע בשרשו ששם אינו רע כלל, לכן הי' חי, הרי כי בשורש אינו רע כלל, ואעפ\"כ נק' ק\"נ דאצי' מפני כי הוא מקור לרע כו' כמ\"ש במ\"א באריכות**. והנה הד' מראות נגעים הם לבינות<sup data-n=\"2460\">79</sup> והיינו שהוא בחי' לבן<sup data-n=\"2461\">80</sup> הארמי היפך לובן העליון<sup data-n=\"2462\">81</sup> דקדושה, וענין הנגעים הוא בא מהתגברות הדם על המים כנ\"ל<sup data-n=\"2463\">82</sup> בשם המד\"ר<sup data-n=\"2464\">83</sup>, ולמעלה הנה מים ודם הם חו\"ב<sup data-n=\"2465\">84</sup> וכאשר המים מעורב עם הדם אין יכולים הקליפות לקבל יניקה כלל כי ימותו\n\n<i>*)נרשם בשולי היריעה:</i>\nלהעיר<sup data-n=\"8430\">ח</sup> מענין נחש נחושת ת\"ת דק\"נ בסד\"ה ויעש משה נחש דס\"ב ב'<sup data-n=\"8431\">ט</sup>, וענין ק\"נ בד\"ה ויקחו אליך הא' ד\"ס ע\"ב<sup data-n=\"8432\">י</sup>, ובענין מי יתן טהור מטמא סוף ביאור זאת חקת פ\"ו.\n<i>**)נרשם מלמטלמ\"ע בצד השמאלי של העמוד:</i>\nזהו המבואר ממ\"ש בלק\"ת פ' חקת בד\"ה ויעש משה נחש נחשת דס\"א ע\"ד<sup data-n=\"8433\">יא</sup>.",[["2453","72","<b>שהנגעים הם ק\"נ דאצי'</b>: ראה ע\"ח שער ק\"נ שמ\"ט, ספ\"ו."],["2454","73","<b>איך שייך . . ק\"נ דאצי'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380173\" data-slug=\"likkutei-torah\" data-id=\"4001380173\">לקו\"ת תזריע כאן כג, ב</a> ואילך. אוה\"ת שמיני ע' מח. המאמר שנדפס לאח\"ז."],["2455","74","<b>לא יגורך רע</b>: תהלים ה, ה. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380322\" data-slug=\"likkutei-torah\" data-id=\"4001380322\">לקו\"ת במדבר ג, ג</a>."],["2456","75","<b>איהו וחיוהי וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב. סה\"מ תר\"ם ח\"א ע' מג. וש\"נ."],["2457","76","<b>ק\"נ דאצי' . . מקור</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560189\" data-slug=\"or-hatorah-hb\" data-id=\"8316560189\">אוה\"ת</a> תזריע כרך ב ע' תקלג ואילך. בראשית כרך ג ע' תקסא ואילך. סה\"מ תרל\"ח ע' קלח ואילך."],["2458","77","<b>והי' כל הנשוך . . וחי</b>: חוקת כא, ח."],["2459","78","<b>וכי נחש . . היו מתרפאין</b>: ר\"ה כט, א (במשנה)."],["2460","79","<b>הד' מראות נגעים הם לבינות</b>: נגעים פ\"א, מ\"א."],["2461","80","<b>נגעים . . לבן</b>: ראה סידור שבהערה הבאה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940252\" data-slug=\"or-hatorah-hb\" data-id=\"8159940252\">אוה\"ת תזריע ע' רנב</a>. כרך ב ס\"ע תקכז ואילך [נדפס גם במהדורת תשנ\"ב בכרך א ס\"ע שמז ואילך]."],["2462","81","<b>לבן . . לובן העליון</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380176\" data-slug=\"likkutei-torah\" data-id=\"4001380176\">לקו\"ת תזריע כד, א</a> כאן ומציין לפרדס ש\"ג פ\"ז. לקמן על יד הערה 145 מציין לסידור שער הל\"ג בעומר דש, ג ואילך. מאמרי אדה\"א בראשית ע' רכב. וש\"נ. תו\"ח ויצא קסח, ד ובהערה 31."],["2463","82","<b>מהתגברות הדם . . כנ\"ל</b>: בסה\"מ תרל\"ה כאן מציין: ראה לעיל רד\"ה אדם כי יהי' — שם ע' קצ וע' ריב."],["2464","83","<b>בשם המד\"ר</b>: ויק\"ר פט\"ו, ב."],["2465","84","<b>מים ודם הם חו\"ב</b>: ראה פרדס שעה\"כ שכ\"ג פ\"ד מערכת דם [וראה שם פי\"ג מערכת מים. תניא פ\"ג. סה\"מ תר\"ם ח\"א ע' רטז. וש\"נ]. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תעג ואילך.\n\n<b>ח</b> ) <b>להעיר</b>: מתחילה נרשם תיבת: ע', וממעל לשורה נרשם תיבת: להעיר, ותיבת ע' לא נמחק.\n\n<b>ט</b> ) <b>דס\"ב ב'</b>: בלקו\"ת חוקת.\n\n<b>י</b> ) <b>ד\"ס ע\"ב</b>: בלקו\"ת שם.\n\n<b>יא</b> ) <b>דס\"א ע\"ד</b>: שם הוא התחלת המאמר. וראה גם שם סב, ב. וראה גם לעיל הערה 76."]]],[2001910269,"ולא בחכ'<sup data-n=\"2466\">85</sup> כי מבחי' החכ' אין יכולים לקבל, אכן כאשר מסתלק אור אבא בחי' מים אז מתגבר בחי' הדם אזי יכול להתהוות הנגע<sup data-n=\"2467\">86</sup>. וזהו ענין אם בהרת קדמה לשער לבן טמא, פי' בהרת היא הנגע, והנה מבחי' הנגע עצמה אינם יכולים הקליפות לקבל כי מבחי' החיות עצמה א\"א לקבל כ\"א כאשר צומח אח\"כ שער לבן הנה ע\"י השערה נמשך להם החיות ולכן טמא, אבל כשהשער לבן קדמה לבהרת טהור פי' שהשער לבן הי' קודם הבהרת וממילא לא הי' אז הסתלקות אור אבא לכן השערה שנצמח אז היא בחי' שער לבן דקדושה ולכן אף שאח\"כ נתהוה הנגע הנה מהנגע עצמה שהיא החיות עצמה א\"א להם לקבל לכן הוא טהור.\n<b>ספק</b> קוב\"ה אומר טהור וכולהו מתיבתא דרקיע אמרי טמא, פי' כי המתיבתא דרקיע אמרו ע\"פ ההשגה בתורה שספיקא דאורייתא לחומרא<sup data-n=\"2468\">87</sup> לכן אמרו ספיקו טמא, אכן קוב\"ה אמר טהור שיש בחי' למעלה מהשגה שמאיר בהשגה דהיינו בג\"ע שהוא מ\"ש וה' עליהם יראה<sup data-n=\"2469\">88</sup> ויצא כברק חצו שהוא בחי' ההברקה בחי' מים כנ\"ל<sup data-n=\"2470\">89</sup> שמאיר ברקיע בחי' בינה, וכן הוא גם במתיבתא דרקיע אמרי טהור<sup data-n=\"2471\">90</sup> לפי שספק זה אף שהוא בדבר דאורייתא אעפ\"כ ספיקו טהור דוגמת ספק ממזר שהוא דאורייתא אעפ\"כ ספיקו טהור<sup data-n=\"2472\">91</sup> מפני שהוא גזירת הכתוב, וכמו ספק טומאה בר\"ה טהור<sup data-n=\"2473\">92</sup> וילפינן זה מסוטה ממ\"ש ונסתרה והיא נטמאה<sup data-n=\"2474\">93</sup> ור\"ה לאו מקום סתירה הוא כו' לכן ספק טומאה בר\"ה טהור, ולכאורה הנה גבי סוטה ניחא כו' מפני שר\"ה לאו מקום סתירה הוא אך איך למדים דין זה גבי כל שאר הטומאות שברה\"ר ספיקו טהור אף שלא שייך בהם כלל הטעם מה שבר\"ה לאו מקום סתירה הוא כו', אלא שזהו גזירת הכתוב שספק טומאה בר\"ה הוא טהור מפני כי ר\"ה הוא טורי דפרודא<sup data-n=\"2475\">94</sup> לכן א\"א להרבות טומאה בר\"ה כדי שלא יומשך שפע יניקה רבה בקליפות, כמ\"כ",[["2466","85","<b>ימותו ולא בחכ'</b>: איוב ד, כא. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' רצט."],["2467","86","<b>מסתלק אור אבא . . נגע</b>: ראה זהר תזריע מט, ב (ובביאוה\"ז שם). ע\"ח שער לאה ורחל של\"ח, פ\"ז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380173\" data-slug=\"likkutei-torah\" data-id=\"4001380173\">לקו\"ת תזריע כג, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380180\" data-slug=\"likkutei-torah\" data-id=\"4001380180\">מצורע כד, ג</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' תכג ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תנג וע' תעג ואילך. סהמ\"צ להצ\"צ ק, ב ואילך."],["2468","87","<b>שספיקא דאורייתא לחומרא</b>: ביצה ג, ב."],["2469","88","<b>וה' עליהם יראה</b>: זכרי' ט, יד. ראה גם לקו\"ת ואתחנן ב, סע\"ד."],["2470","89","<b>הברקה בחי' מים כנ\"ל</b>: ראה לעיל מאמר ד\"ה בגמ' וכו' קא מפלגי במתיבתא דרקיעא פ\"ג."],["2471","90","<b>במתיבתא דרקיע אמרי טהור</b>: בסה\"מ תרל\"ה כאן העיר: אוצ\"ל: אמר (או: אמר קוב\"ה) טהור, והכוונה, דאף שלהשגת מתיבתא דרקיע הוא טמא, מ\"מ מאיר גם בהם (בחי' שלמע' מהשגה) מה שקוב\"ה אמר טהור."],["2472","91","<b>ספק ממזר . . ספיקו טהור</b>: קדושין עג, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380176\" data-slug=\"likkutei-torah\" data-id=\"4001380176\">לקו\"ת תזריע כאן כד, סע\"א</a>-ב. סהמ\"צ להצ\"צ מהדורת אותיות מרובעות ע' קד וע' 226 [ושם שו\"ה בפסק ממזר כי ממזר כי — אוצ\"ל: בספק ממזר כי].\nראה גם שו\"ת הצ\"צ חיו\"ד סקמ\"ב, ס\"ב. ס\"ג."],["2473","92","<b>ספק טומאה ברה\"ר טהור</b>: טהרות פ\"ד, מי\"א. סוטה כח, ב."],["2474","93","<b>ונסתרה והיא נטמאה</b>: נשא ה, יג. ראה תוד\"ה התם חולין ט, ב. תוד\"ה והלל נדה ב, א. תוספת הרא\"ש נדה ג, א ד\"ה אי."],["2475","94","<b>רה\"ר הוא טורי דפרודא</b>: ראה תניא ספל\"ג ובמ\"מ הגהות והערות קצרות לשם. מאמרי אדה\"א שמות ח\"א ע' רצו־ דברים ח\"ב ע' תעט ובהנסמן בהנ\"ל."]]],[2001910270,"כאן בדין דבהרת ג\"כ ספיקו טהור ואינו טמא כ\"א כאשר נודע לנו ברור שהבהרת קדמה לשער א\"כ נמשך ע\"י השער לבן שבתוך הבהרת יניקה לקליפות אכן אם ספק שיכול להיות שהשער לבן קדמה לבהרת וא\"כ השער לבן הוא מקדושה כנ\"ל<sup data-n=\"2476\">95</sup>, ואף שהוא ספק שאינו שקול כמ\"ש התוס'<sup data-n=\"2477\">96</sup> שאין דרך שיצמח השער לבן קודם הבהרת עכ\"ז ספיקו טהור (וכמו בספק טומאה בר\"ה טהור אף שאינו ספק שקול, ולהפך ברה\"י טמא<sup data-n=\"2478\">97</sup> אף שהספק אינו שקול ונראה יותר שהוא טהור אעפ\"כ ספיקו טמא כו') ומפני שהוא גזירת הכתוב כך שאם לא נודע לנו<sup data-n=\"2479\">98</sup> שהבהרת קדמה אינו טמא כלל, או שאינו נמשך מזה יניקה לקליפות כו', וזהו קוב\"ה אומר טהור שהוא מבחי' שלמעלה בהשגה<sup data-n=\"2480\">99</sup> שמאיר בג\"ע, והמתיבתא דרקיע שהם ע\"פ ההשגה מבחי' רקיע הנ\"ל אמרו טמא כי כל ספיקא דאוריי' לחומרא, ואף שזכו לגילוי זה שלמעלה מהשגה שהוא בחי' קוב\"ה אומר טהור (וזהו ענין גם מ\"ש בזהר קוב\"ה אתי לאשתעשע<sup data-n=\"2481\">100</sup> עם צדיקייא בגינתא דעדן שהוא בחי' הברק שמאיר בג\"ע שלמעלה מן ההשגה) אעפ\"כ לא ידעו טעם הדבר עד שאמרו<sup data-n=\"2482\">101</sup> מאן נוכח רב\"נ<sup data-n=\"2483\">102</sup> דאמר רב\"נ אני יחיד בנגעים יחיד<sup data-n=\"2484\">103</sup> באהלות, פי' יחיד הנה סנהדרי גדולה היו של שבעים ואחד<sup data-n=\"2485\">104</sup> שנא' אספה לי שבעים איש מזקני ישראל<sup data-n=\"2486\">105</sup> ומשה על גביהם, הרי שבעים ואחד, ולמדו כן לדורות שיהיו ע\"א סנהדרין והי' אותו שכנגד משה<sup data-n=\"2487\">106</sup> מופלא שבסנהדרין<sup data-n=\"2488\">107</sup>, והנה כתי' ויאצל משה מן הרוח<sup data-n=\"2489\">108</sup> אשר עליו ויתן על ע' איש הזקנים והיינו שהשבעים היו כנגד משה<sup data-n=\"2490\">109</sup> כמו ערך אצי' לגבי המאציל, ולא כמו הנבראים נגד הבורא כי הנבראים הם מאין ליש רק כמו אצילות לגבי המאציל שהוא ענין העלם וגילוי שיצא לגילוי מתוך ההעלם וכמו במשה והזקנים שנאצל ההארה מבחי' משה ונתגלה על ע' הזקנים, וע\"פ הקבלה<sup data-n=\"2491\">110</sup> הנה ע' זקנים הם בחי' ז\"ת דבינה<sup data-n=\"2492\">111</sup> וכ\"א כלול מיו\"ד היינו ע', ומשה הוא בחי' יסוד דאבא<sup data-n=\"2493\">112</sup> בחי' חכמה, והנה השראת",[["2476","95","<b>כנ\"ל</b>: סוף פיסקא שלפנ\"ז."],["2477","96","<b>ספק שאינו שקול כמ\"ש התוס'</b>: ד\"ה ר\"י אומר נדה יט, א."],["2478","97","<b>בר\"ה טהור . . ברה\"י טמא</b>: ראה לעיל הערה 93."],["2479","98","<b>שאם לא נודע לנו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380176\" data-slug=\"likkutei-torah\" data-id=\"4001380176\">לקו\"ת תזריע כאן כד, סע\"א</a>. מאמרי אדה\"ז הנחות הר\"פ ס\"ע קנה [נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940119\" data-slug=\"or-hatorah-hb\" data-id=\"8159940119\">אוה\"ת תזריע כרך ב</a>' מהדורת תשנ\"ג ע' תקלה בשולי היריעה]."],["2480","99","<b>בהשגה</b>: בסה\"מ תרל\"ה כאן ע' רלב העיר: אוצ\"ל: מהשגה."],["2481","100","<b>קוב\"ה אתי לאשתעשע</b>: ראה זהר אחרי סז, ב. לך עז, א. לעיל מאמר ד\"ה בגמ' וכו' קא מפלגי במתיבתא דרקיעא ובהערה 5."],["2482","101","<b>עד שאמרו</b>: ב\"מ פו, א."],["2483","102","<b>רב\"נ</b>: שם: נוכח רב\"נ."],["2484","103","<b>יחיד</b>: שם: אני יחיד."],["2485","104","<b>סנהדרי . . שבעים ואחד</b>: סנהדרין ב, סע\"א (במשנה)."],["2486","105","<b>אספה לי . . ישראל</b>: בהעלותך יא, טז."],["2487","106","<b>אותו שכנגד משה</b>: ראה רמב\"ם הל' סנהדרין פ\"א, ה\"ג. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450578\" data-slug=\"or-hatorah-hb\" data-id=\"8316450578\">אוה\"ת חנוכה ח\"ב ס\"ע 578</a> ואילך."],["2488","107","<b>מופלא שבסנהדרין</b>: ראה הוריות ד, ב (במשנה)."],["2489","108","<b>ויאצל משה מן הרוח</b>: בהעלותך יא, כה בהוספת תיבת משה — ראה סה\"מ תרל\"ה כאן ע' רלג בהערה."],["2490","109","<b>שהשבעים היו כנגד משה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370063\" data-slug=\"torah-or\" data-id=\"3901370063\">תו\"א וירא יד, א</a>. לקו\"ת ואתחנן יב, א."],["2491","110","<b>וע\"פ הקבלה</b>: ראה אוה\"ת בהעלותך ע' שפט ואילך. חנוכה שם ע' רצ."],["2492","111","<b>ע' זקנים . . ז\"ת דבינה</b>: ראה רמ\"ז ס\"פ שופטים."],["2493","112","<b>ומשה . . יסוד דאבא</b>: ראה גם לעיל מאמר ד\"ה מגילה נקראת על יד הערה 13 מלקו\"ת להאריז\"ל פ' בלק [ד\"ה ענין בלק ובלעם הב']. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות כרך ו ע' 244</a> ואילך."]]],[2001910271,"אוא\"ס ב\"ה הוא בחכ' דוקא שלכן נק' החכמה אחד האמת כו' כמ\"ש בסש\"ב פל\"ה בהג\"ה, ע\"כ נק' חכמה אוא\"ס ושאר הספירות נגד החכמה הם כערך הנאצלים לגבי המאציל. והנה רבה בר נחמני בדורו הי' כמו משה בדורו, שרב\"נ הי' יחיד בנגעים פי' שהי' מבחי' החכ' שהוא ברק המבריק<sup data-n=\"2494\">113</sup> שלמעלה מן ההשגה בבחי' רקיע כנ\"ל לכן אמר טהור כו', ומצא סמך לזה מן התורה כמשארז\"ל בנזיר דס\"ה<sup data-n=\"2495\">114</sup> דאמר קרא לטהרו או לטמאו<sup data-n=\"2496\">115</sup> הואיל ופתח הכתוב בטהרה תחלה כו' לכן טהור, והיינו שהוא בחי' שלמעלה מהשגה שנמצא בהשגה דהיינו בבחי' תורה כו'.\n<b>ועוי\"ל</b> בפי' ספק, כי הנה לשון ספק לא מצינו בקרא<sup data-n=\"2497\">116</sup> ובאשם תלוי כתי' והודע אליו חטאתו אשר חטא או לא נודע<sup data-n=\"2498\">117</sup>, אבל ל' ספק אינו כתי' בתורה כ\"א הוא ל' תרגום שע\"פ יתומים היינו ואין אב אמותינו כאלמנות<sup data-n=\"2499\">118</sup> ת\"י<sup data-n=\"2500\">119</sup> כארמלתא<sup data-n=\"2501\">120</sup> דאזל<sup data-n=\"2502\">121</sup> בעלה<sup data-n=\"2503\">122</sup> בקרווי ימא ומספקא<sup data-n=\"2504\">123</sup> אם אינון קיימין, נמצא של' ספק כתי' גבי גלות, וכמשארז\"ל ע\"פ היתה כאלמנה ולא אלמנה ממש כאשה שהלך בעלה למדנה\"י<sup data-n=\"2505\">124</sup>. והענין הוא דהנה איתא בזהר קוב\"ה בגלותא סליק לעילא לעילא<sup data-n=\"2506\">125</sup>, פי' קוב\"ה דא וא\"ו<sup data-n=\"2507\">126</sup> בעלה דה\"א בחי' מל' בזמן הגלות הוא סליק לעילא בבחי' ים דהיינו ים החכמה<sup data-n=\"2508\">127</sup>, וז\"ש בת\"י בקרווי ימא בבחי' ים החכ' כו', ותורה היא רק כד מים החכמה<sup data-n=\"2509\">128</sup> כמ\"ש במ\"א, אבל עצם בחי' הים אינו מושג וקוב\"ה בגלותא סליק לעילא בבחי' ים החכמה עצמו, וזהו אמותינו הוא בחי' כנס\"י אימא תתאה<sup data-n=\"2510\">129</sup>",[["2494","113","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה קא מיפלגי במתיבתא דרקיעא ובהערה 81."],["2495","114","<b>דס\"ה</b>: ע\"ב. ראה גם חידושי אגדות מהרש\"א ב\"מ פו, א ד\"ה ספק."],["2496","115","<b>לטהרו או לטמאו</b>: תזריע יג, נט."],["2497","116","<b>לשון ספק . . בקרא</b>: ראה גם סהמ\"צ להצ\"צ מהדורת אותיות מרובעות ע' קיד. נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940119\" data-slug=\"or-hatorah-hb\" data-id=\"8159940119\">אוה\"ת תזריע כרך ב ע' תקלה</a>."],["2498","117","<b>והודע אליו . . לא נודע</b>: ראה ויקרא ה, יז-יח וברש\"י ד\"ה ולא ידע ואשם והביא.\nהלשון ”והודע אליו חטאתו אשר חטא\" ראה שם ד, כג. כח ”או הודע אליו חטאתו אשר חטא\". הלשון ”או לא נודע\" ראה שם ה, יז (ולא ידע). יח (והוא לא ידע)."],["2499","118","<b>יתומים היינו . . כאלמנות</b>: איכה ה, ג."],["2500","119","<b>ת\"י</b>: בסהמ\"צ ואוה\"ת שבהערה 116: איתא בתרגם. ראה מגילה ג, א. שו\"ת זכר יהוסף — לר' יוסף זכרי' שאוועל — סקכ\"א."],["2501","120","<b>כארמלתא</b>: בתרגום ואוה\"ת: כאמרלן. בסהמ\"צ: כאמרלין."],["2502","121","<b>דאזל</b>: בתרגום: דאזלו. בסהמ\"צ ובאוה\"ת: דאזלי."],["2503","122","<b>בעלה</b>: בתרגום ובסהמ\"צ: גבריהון. באוה\"ת: גובריהן."],["2504","123","<b>ומספקא</b>: שם: ומספקא להון."],["2505","124","<b>היתה כאלמנה . . למדנה\"י</b>: איכה א, א וברש\"י. איכ\"ר שם ג. תענית כ, א. סנהדרין קד, סע\"א."],["2506","125","<b>קוב\"ה בגלותא . . לעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. מאמרי אדה\"א קונטרסים ע' שסג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540232\" data-slug=\"torat-chaim\" data-id=\"2300540232\">תו\"ח שמות ח\"א לט, סע\"א</a> ואילך ובהערה 72. סה\"מ תר\"ם ח\"א ע' שיב. וש\"נ."],["2507","126","<b>קוב\"ה דא וא\"ו</b>: ראה סידור שחרית נח, ב ואילך."],["2508","127","<b>ים החכ'</b>: ראה לעיל מאמר ד\"ה זכור את יום השבת הערה 167."],["2509","128","<b>ותורה . . כד מים החכמה</b>: ראה גם לקמן מאמר ד\"ה וידבר כו' קדושים תהיו ובהערה 99."],["2510","129","<b>כנס\"י אימא תתאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310057\" data-slug=\"tanya\" data-id=\"3401310057\">תניא פנ\"ב</a>."]]],[2001910272,"כאלמנות שאזיל בעלה בחי' וא\"ו למדינת הים בחי' ים החכ'. והנה מצד אריכות הגלות זהו הספק אי אינון קיימין, פי' שהספק הוא ע\"ד מ\"ש כי אם מאוס מאסתנו קצפת עלינו עד מאד<sup data-n=\"2511\">130</sup>, ואיתא במד\"ר ע\"פ זה אם מאוס לית סבר (פי' תקוה ח\"ו) ואם קצף אית סבר, כי כל הכועס לסוף מתרצה, וזהו שהספק אם מאוס ח\"ו אם קצף. והנה ספק זה נפשט לקולא והוא ממ\"ש זכרי'<sup data-n=\"2512\">131</sup>* שהי' אחר ירמי'<sup data-n=\"2513\">132</sup> (שהי' אצלו ספק) ואתם תהיו לי<sup data-n=\"2514\">133</sup> ארץ חפץ, וכתי' ואוריש אתכם כל הגוים<sup data-n=\"2515\">134</sup>, וא\"כ בהכרח שיהי' גם ספק זה אם בהרת קדמה כו' או שער לבן קדמה ג\"כ לקולא שיהי' ספיקו טהור מפני שהד' מראות נגעים הם כנגד ד' מלכיות<sup data-n=\"2516\">135</sup> שאת זו בבל ספחת זו מדי שהמן הי' קשה לישראל כספחת כו' ונגע צרעת זו אדום כמ\"ש במד\"ר פ' תזריע כו', וא\"כ בהכרח שיהי' נפשט לקולא שספיקו טהור בכדי שלא יהי' יניקה לקליפות וכמו הספק דמאוס וקצף נפשט לקולא כו', ולכן קוב\"ה אומר טהור כו' ורב\"נ שהי' יחיד בנגעים כנ\"ל<sup data-n=\"2517\">136</sup> בפי' יחיד כמו משה בדורו בחי' ים החכמה לכן אמר טהור כו'.\n<b>ועפמשנ\"ת</b><sup data-n=\"2518\">137</sup> בענין ד' מראות נגעים שהם לעו\"ז נגד לאה ורחל ושתי השפחות** מובן המד\"ר שפי' מצורע מוציא שם רע<sup data-n=\"2519\">138</sup> שזהו חטא\n\n<i>*)נרשם בשולי היריעה:</i>\nמלאכי שהי' אחר ירמי'<sup data-n=\"8434\">יב</sup> (שהי' ספק אצלו) ואשרו אתכם כל הגוים כי תהיו אתם ארץ חפץ אמר ה' צבאות (במלאכי ג' י\"ב)\nורצאתי אתכם (יחזקאל מ\"ג ך\"ז)\n<i>**)בצד הימיני של העמוד נרשם (בהפסק קו):</i>\nתקס\"ז נייר חלק<sup data-n=\"8435\">יג</sup>",[["2511","130","<b>כי אם . . עד מאד</b>: איכה ה, כב. ראה איכ\"ר שם (ובמת\"כ). שם פ\"א, כג (וביפה ענף שם).\nפי' המדרש באו\"א ראה מאמרי אדה\"ז הקצרים ע' רפו."],["2512","131","<b>זכרי'</b>: ראה בשולי הגליון כאן."],["2513","132","<b>זכרי' שהי' אחר ירמי'</b>: ראה ב\"ב יד, ב. הקדמת הרמב\"ם לספר היד. ירמי' — ראה סדר הדורות ג\"א רצ\"ח. זכרי' — ראה שם ג\"א ת\"ח (ד\"ה אנשי). תמ\"ב (ד\"ה חגי)."],["2514","133","<b>ואתם תהיו לי</b>: כ\"ה בכ\"מ ומהם — מאמרי אדה\"ז תקס\"ו ע' קכד [במהדורת תשס\"ד ע' שכג]. תק\"ע ע' כט. ש\"א צב, ב. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' נז. ע' סא. סה\"מ תרל\"ב ח\"א ע' קעח. תרל\"ה כאן ע' רלד. לשון הכתוב הובא בשולי הגליון כאן."],["2515","134","<b>ואוריש אתכם כל הגוים</b>: לשון הכתוב הובא בשולי הגליון כאן."],["2516","135","<b>שהד' מראות נגעים . . מלכיות</b>: ראה ויק\"ר פט\"ו, ט."],["2517","136","<b>כנ\"ל</b>: בפיסקא שלפנ\"ז."],["2518","137","<b>ועפמשנ\"ת</b>: לעיל פיסקא ומעתה."],["2519","138","<b>מצורע מוציא שם רע</b>: ראה ויק\"ר פט\"ז, ב. ו. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 3.\n\n<b>יב</b> ) <b>מלאכי שהי' אחר ירמי'</b>: ראה הערה 132.\n\n<b>יג</b> ) <b>תקס\"ז נייר חלק</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940119\" data-slug=\"or-hatorah-hb\" data-id=\"8159940119\">אוה\"ת תזריע כרך ב ע' תקכט</a>.\nראה גם אוה\"ת תזריע כרך ב ס\"ע תקלה: ”וכמ\"ש מזה באריכות בהגהות לדרוש בהרת ונכתב בנייר חלק שבבוך מו\"ח תקס\"ז\". לקמן מאמר ד\"ה ועוי\"ל ענין ק\"נ דאצי' (שנדפס לאח\"ז) בתחילתו: תקס\"ז נייר לבן דף קו, א. סה\"מ תרל\"ב ח\"ב ע' שצח: ”וע' בהגהות על דרוש בהרת שבלק\"ת (על נייר לבן בספר תקס\"ו\". שם ע' תנא: ”וע' בהגהות לדרוש בהרת בנייר לבן שבס' תקס\"ז כמדומה\". שם ע' תנג: ”הגהות לדרוש בהרת שבלק\"ת בנייר לבן בס' תקס\"ז\". ראה בהנרשם שם.\nולהעיר מאוה\"ת ואתחנן כרך ו ע' ב'רסג: ”עד אות ח הוא בנייר שבתוך בוך שימני כחותם תקס\"ז כ\"י דו\"ח\". המשך תער\"ב ח\"ג ע' א'תלו: ”ע' בנייר שבסוף ס' תקס\"ו\"."]]],[2001910273,"שבדבור, וכן איתא שם במד\"ר שעל חטא לב חורש מחשבת און לוקה בצרעת שזהו מן הששה דברים, שחשיב (במשלי סי' וא\"ו) שש הנה שנא ה', שב' אלו הם נגד לאה ורחל שהם שאת ובהרת, וכמ\"ש במאו\"א אות ד' סעי' ט', שאת לאה (ר\"ל מה שכנגד לאה והיינו מחשבה רעה של היצה\"ר לשון לאות שנלאה ומתשת כח, והיינו בחי' לב חורש מחשבת און), בהרת רחל (ר\"ל מה שכנגד רחל והוא הדבור הרע והיינו מוציא ש\"ר ורכילות ולה\"ר<sup data-n=\"2520\">139</sup>, ולכן נטהר המצורע מטומאתו צ\"ל שתי צפרים דוקא שבכדי לטהר טומאת המצורע צריכים להמשיך בחי' זו בקדושה, דהנה כמו שיש לבן בקדושה ולו שתי בנות<sup data-n=\"2521\">140</sup> לאה ורחל, שם הגדולה לאה<sup data-n=\"2522\">141</sup> ה' גדולה ה' ראשונה דש' הוי' בינה, ושם הקטנה רחל<sup data-n=\"2525\">144</sup> ה' קטנה היינו ה' אחרונה<sup data-n=\"2524\">143</sup> דש' הוי' שהם בינה ומל'<sup data-n=\"2523\">142</sup>, כן יש בחי' לבן בלעו\"ז שהוא נגד לובן העליון כמ\"ש בסידור בד\"ה עד הגל<sup data-n=\"2526\">145</sup>, ולו שני בנות היינו שאת ובהרת, שהם סוד ב' צפרין דאיתא בזהר ויחי דרי\"ז ע\"א<sup data-n=\"2527\">146</sup>, ולכן כשנטהר המצורע צ\"ל ב' צפרין דאיתא בזהר ויצא דקס\"ב סע\"ב ודף קס\"ג ע\"א, שענין וללבן שתי בנות ז\"ע מ\"ש ישבעו כו' ארזי לבנון אשר נטע אשר שם<sup data-n=\"2528\">147</sup> צפרים יקננו, וא\"כ לאה ורחל הם נק' שני צפרים ע\"ד שבינה נק' קן צפור<sup data-n=\"2529\">148</sup>, ועמ\"ש בד\"ה כי יקרא קן צפור<sup data-n=\"2530\">149</sup>, וכן מל' נקרא צפור ע\"ד גם צפור מצאה בית (בתילים סי' פ\"ד<sup data-n=\"2532\">151</sup>) דקאי על השכינה<sup data-n=\"2531\">150</sup>, ולכן בטהרת המצורע צ\"ל שני צפרים שהם בנות לבן שממנו מקור טומאת צרעת, ושלח את הצפור החיה<sup data-n=\"2533\">152</sup> אפ\"ל דוגמת שעיר המשתלח, ובבחי'<sup data-n=\"2534\">153</sup> פ'",[["2520","139","<b>ולה\"ר</b>: אוצ\"ל: ולה\"ר)."],["2521","140","<b>לבן . . שתי בנות</b>: ראה הערה הבאה."],["2522","141","<b>שם הגדולה לאה</b>: ויצא כט, טז. ראה זהר רע\"מ פינחס רמד, ב. ע\"ח שער יעקב ולאה של\"ז, פ\"ד. הנסמן במאמרי אדה\"א בראשית ע' רכב."],["2525","144","<b>ושם הקטנה רחל</b>: ראה הערה 141."],["2524","143","<b>ה' ראשונה . . אחרונה . . בינה ומל'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["2523","142","<b>לאה . . רחל . . בינה ומל'</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"ב מערכת לאה ופ\"כ מערכת רחל."],["2526","145","<b>בסידור בד\"ה עד הגל</b>: שער הל\"ג בעומר דש, ג ואילך. וראה גם לעיל הערה 81."],["2527","146","<b>ע\"א</b>: אוצ\"ל: רע\"ב."],["2528","147","<b>בזהר . . ישבעו . . אשר שם</b>: תהלים קד, טז. יז. ראה גם מאמרי אדה\"א נ\"ך ע' קעו ואילך. וש\"נ."],["2529","148","<b>שבינה נק' קן צפור</b>: ראה מאו\"א מערכת קן צפור אות לג וביאיר נתיב שם — הובא באוה\"ת שבהערה הבאה."],["2530","149","<b>בד\"ה כי יקרא קן צפור</b>: ראה אוה\"ת תצא ע' תתקמח ואילך."],["2532","151","<b>בתילים סי' פ\"ד</b>: פסוק ד. ראה גם אוה\"ת שם ע' תתקיא. ס\"ע תתקל ואילך."],["2531","150","<b>מל' נקרא צפור . . השכינה</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"ח מערכת צפור — הובא באוה\"ת שם ע' תתקיח."],["2533","152","<b>ושלח את הצפור החיה</b>: מצורע יד, ז."],["2534","153","<b>ובבחי'</b>: בבוך תרמ\"א 2086 כת\"י מעתיק: ובבחיי."]]],[2001910274,"מצורע<sup data-n=\"2535\">154</sup> העיר לענין ושלח את הצפור מענין שעיר המשתלח, ובלק\"ת מהאריז\"ל במקומו<sup data-n=\"2536\">155</sup> איתא וז\"ל קיצור הדברים ב'<sup data-n=\"2537\">156</sup> צפרים אלו הם סוד הנזכר בזהר פ' ויחי דרי\"ז<sup data-n=\"2538\">157</sup>, השחוטה הוא מוח<sup data-n=\"2539\">158</sup> בינה<sup data-n=\"2540\">159</sup> דנוגה והחיה חכמה דנוגה הנק' חיה כנודע<sup data-n=\"2541\">160</sup> מסוד והחכמה תחי'<sup data-n=\"2542\">161</sup> בעליה עכ\"ל.",[["2535","154","<b>ובבחיי פ' מצורע</b>: עה\"פ (יד, ז) — הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200108\" data-slug=\"or-hatorah-hb\" data-id=\"8159200108\">אוה\"ת</a> תזריע כאן ע' תקכט. וראה גם ציוני שם — הובא באוה\"ת מצורע כרך ג ע' תתכא. ושם ע' תתכד בשם הרמב\"ן (יד, ד)."],["2536","155","<b>ובלק\"ת מהאריז\"ל במקומו</b>: הובא באוה\"ת תזריע כאן ע' תקכט ושם: (ובלק\"ת מהאריז\"ל) כאן."],["2537","156","<b>ב'</b>: בלקו\"ת שם: כי ב'."],["2538","157","<b>בזהר פ' ויחי דרי\"ז</b>: שם: בפרשת ויחי."],["2539","158","<b>מוח</b>: שם: סוד מוח."],["2540","159","<b>בינה</b>: באוה\"ת: דבינה."],["2541","160","<b>כנודע</b>: שם: כידוע."],["2542","161","<b>והחכמה תחי'</b>: שם: החכמה תחיה את."]]],[2001910275,"<h3>ועוי\"ל ענין ק\"נ דאצי'</h3>\n<b>ל\"נ ולא הועתק</b>\n<b>ועוי\"ל</b> ענין<sup data-n=\"2543\">1</sup> ק\"נ דאצי'* (היינו לתרץ<sup data-n=\"2544\">2</sup> איך שייך לומר לשון קליפה מאחר שזהו אצילות), כי<sup data-n=\"2545\">3</sup> הנה באצילות דקדושה יש ג\"כ אורות וכלים, ולדעת הר\"מ<sup data-n=\"2547\">5</sup>\n\n<i>*)נרשם בצד הימיני של העמוד בהפסק קו:</i>\nתקס\"ז נייר לבן דק\"ו ע\"א<sup data-n=\"8436\">א</sup>\n*)והיינו<sup data-n=\"8437\">ב</sup> שמק\"ך צירופי אלקי'<sup data-n=\"8438\">ג</sup> מקבלי' גם ק\"ך צירופי' דבחי' אל אחר<sup data-n=\"8439\">ד</sup> כו' וז\"ע עמלק גימ' רם<sup data-n=\"8440\">ה</sup>, ובלעם נכד לבן הארמי<sup data-n=\"8441\">ו</sup> שזהו ממש ענין הסתעפות הנגע שנמשך מלבן שבלעו\"ז כתי' בו ויקר אלקי'<sup data-n=\"8442\">ז</sup> אין ויקר אלא לשון טומאה במד\"ר פ' ויקרא<sup data-n=\"8443\">ח</sup>, שזהו מה שנמשך ע\"י ק\"נ דאצי' כמ\"ש בלק\"ת בד\"ה בהרת ספ\"ג<sup data-n=\"8444\">ט</sup>, והיינו מבחי' מ\"ח צירופי' אחרוני'<sup data-n=\"8445\">י</sup> ע' בביאור ציץ<sup data-n=\"8446\">יא</sup>.",[["2543","1","<b>ועוי\"ל ענין ק\"נ דאצי'</b>: לדרוש זה — פיסקא ראשונה לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940114\" data-slug=\"or-hatorah-hb\" data-id=\"8159940114\">אוה\"ת תזריע ח\"ב ע' תקל</a> (עם הוספות). לפיסקא שני' ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>-ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940114\" data-slug=\"or-hatorah-hb\" data-id=\"8159940114\">אוה\"ת תזריע שם ריש ע' תקל</a>. לפיסקא ג' ראה אוה\"ת תזריע שם ס\"ע תקלג ואילך. לפיסקא ד' ע\"פ לשון אוה\"ת שם ע' תקלד.\nמאמר זה נרשם בגוכתי\"ק. במפתח לבוך זה 1130 נרשם דרוש זה ”בלקו\"ת ד\"ה אם בהרת [ע'] קל, א\". וכן בפנים הבוך (קל, א) מתחיל כנ\"ל ובראשו נרשם: ”ל\"נ ולא הועתק\". שמזה משמע לכאורה שזהו הפתיחה של המאמר. אבל כנראה שאח\"כ נשתנה הפתיחה ל”ועוי\"ל ענין ק\"נ דאצי'\" שנמצא שם קל, ב (אחרי רשימת ה' שורות העליונות). ושם ע' קלד נרשם הדרוש עוה\"פ בכת\"י מעתיק (עם הגהות ותיקונים בגוכתי\"ק) בפתיחה: ”ועוי\"ל ענין ק\"נ דאצי'\".\nבבוך תרמ\"א 2086 (כת\"י מעתיק) בתחילתו בהמפתח לא נרשם דרוש זה. אף שמופיע בהבוך בע' בפ\"ע בפתיחא ”ועוי\"ל ענין ק\"נ דאצי'\". ראה גם הנרשם לעיל במפתח המאמרים לדרוש זה."],["2544","2","<b>ועוי\"ל ענין ק\"נ . . לתרץ</b>: ראה בהמאמר להבין וכו' זאת תהי' תורת המצורע שנדפס לפנ\"ז על יד הערה 73 ואילך."],["2545","3","<b>כי</b>: מכאן לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940114\" data-slug=\"or-hatorah-hb\" data-id=\"8159940114\">אוה\"ת תזריע ח\"ב ע' תקל</a> (ובמהדורת תשנ\"ב נדפס גם בח\"א ע' שנ) עם הוספות. סה\"מ תרל\"ב ח\"ב ע' תנו-ז."],["2547","5","<b>מרקנטי</b>: וכ\"ה גם בסהמ\"צ להצ\"צ מח, א. ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940015\" data-slug=\"or-hatorah-hb\" data-id=\"8159940015\">אוה\"ת</a> שבהערה 3: מראקנטי. ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940114\" data-slug=\"or-hatorah-hb\" data-id=\"8159940114\">אוה\"ת</a> שבהערה שלפנ\"ז הוא טעוה\"ד ובמפתח המאמרים שבריש הספר שם: מרקאנטי — וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080350\" data-slug=\"or-hatorah-hb\" data-id=\"8160080350\">אוה\"ת ואתחנן ע' רכז</a>. ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300008\" data-slug=\"or-hatorah-hb\" data-id=\"8316300008\">אוה\"ת</a> ויקרא ח\"ב ע' תלא: בריקנטי. קדושים ע' קלד: הריקאנטי. בסה\"מ תרל\"ב שם: מראקאנטי.\n\n<b>א</b> ) <b>תקס\"ז . . ע\"א</b>: הכוונה שהבא להלן בפיסקא זו הוא לשון אוה\"ת תזריע ח\"ב ע' תקל ובמהדורת תשנ\"ב נדפס גם בח\"א ע' שנ (עם הוספות).\nבנידון ”תקס\"ז נייר לבן\" ראה גם המאמר להבין וכו' זאת תהי' תורת המצורע שנדפס לפנ\"ז הערה יג.\n\n<b>ב</b> ) <b>והיינו</b>: הערה זו נרשמה בפנים כאן בין חצאי עיגול ועה\"ג בצד הימיני של העמוד (בהפסק קו מלמעלמ\"ט) נרשם הוראה להמעתיק: ”הג\"ה זו שבשני חצאי עגולים להעתיק למטה\".\n\n<b>ג</b> ) <b>שמק\"ך צירופי אלקי'</b>: ראה ע\"ח שער הזיווגים שט\"ו, פ\"ו. שער השמות שמ\"ד, פ\"ה. הנסמן במאמרי אדה\"א שמות ח\"א ע' קלז.\n\n<b>ד</b> ) <b>ק\"ך צירופי' דבחי' אל אחר</b>: ראה לקו\"ת להאריז\"ל בשלח בסופו ד\"ה עמלק. מאו\"א מערכת מר אות צב. לעיל מאמר ד\"ה מגילה נקראת ובהערה כא.\n\n<b>ה</b> ) <b>עמלק גימ' רם</b>: ראה לקו\"ת להאריז\"ל שם. סה\"מ תרכ\"ט ע' קנג. המשך וככה תרל\"ז פס\"ב.\n\n<b>ו</b> ) <b>ובלעם נכד לבן הארמי</b>: ראה זהר וישלח קסו, ב. קסז, א. זהר חדש בלק נד, ג.\n\n<b>ז</b> ) <b>ויקר אלקי'</b>: בלק כג, ד.\n\n<b>ח</b> ) <b>אין ויקר . . במד\"ר פ' ויקרא</b>: ראה ויק\"ר פ\"א, יג. וראה גם לעיל מאמר ד\"ה להבין וכו' בענין הציץ ובהערה 242.\n\n<b>ט</b> ) <b>בלק\"ת בד\"ה בהרת ספ\"ג</b>: תזריע כג, ד.\n\n<b>י</b> ) <b>מ\"ח צירופי' אחרוני'</b>: ראה פע\"ח שחה\"מ שכ\"א, פ\"ה. שער הכוונות ענין הפסח דרוש א'. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370486\" data-slug=\"torah-or\" data-id=\"3901370486\">תו\"א יתרו קט, ד</a>. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'סא. סה\"מ תר\"ם ח\"א ע' שנה. וש\"נ.\n\n<b>יא</b> ) <b>בביאור ציץ</b>: ראה גם לעיל שם (מאמר ד\"ה להבין וכו' בענין הציץ) על יד הערה לד ואילך."]]],[2001910276,"מרקנטי<sup data-n=\"2546\">4</sup> עיקר אצילות הם האורות, ולא כן הכלים, והאריז\"ל<sup data-n=\"2548\">6</sup> פירש שגם הכלים הם אצילות ממש, ועכ\"ז אינן בערך לאצילות האורות, ושרש האורות מש' הוי'<sup data-n=\"2549\">7</sup>, והכלים מש' אלקים וש' שדי שאמר לעולמו די<sup data-n=\"2550\">8</sup>, אשר זהו כח המגביל שיהי' נמשך בבחי' גבול, כי משלימות הא\"ס שיהי' בו ג\"כ כח הגבול<sup data-n=\"2551\">9</sup>, וא\"כ לפ\"ז נאמר דפי' ק\"נ דאצי' אינו רק בחי' הכלים לבד שהם מבחי' ש' אלקים*, ונקרא אצי' מבחי' כח הגבול, אך הכלים דע\"ס דקדושה הם בבחי' הביטול, כי באצילות מאיר חכמה<sup data-n=\"2552\">10</sup> כח מה<sup data-n=\"2553\">11</sup> (ולכן<sup data-n=\"2555\">13</sup> שם גם איהו וגרמוהי חד<sup data-n=\"2554\">12</sup>), משא\"כ בק\"נ נאמר<sup data-n=\"2556\">14</sup> ראו מ\"ה<sup data-n=\"2557\">15</sup> שמרגיש",[["2546","4","<b>הר\"מ מרקנטי</b>: ראה גם אוה\"ת על ענינים ע' רנח ואילך ובהנסמן בריש המאמר שם. ספר הערכים חב\"ד ח\"ד מערכת אורות דספירות פשיטותם וציורם פ\"ג ע' צג ואילך ובהנסמן שם."],["2548","6","<b>והאריז\"ל</b>: ראה לעיל הערה 4."],["2549","7","<b>ושרש האורות מש' הוי'</b>: ראה גם סה\"מ תרל\"ח ע' כז. וש\"נ."],["2550","8","<b>שדי שאמר לעולמו די</b>: ראה חגיגה יב, א. ב\"ר פ\"ה, ח. פמ\"ו, ג."],["2551","9","<b>משלימות הא\"ס . . כח הגבול</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380778\" data-slug=\"likkutei-torah\" data-id=\"4001380778\">לקו\"ת עקב טז, סע\"א</a>. סה\"מ תר\"ם ח\"א ס\"ע קכט. וש\"נ."],["2552","10","<b>באצי' מאיר חכמה</b>: ראה ע\"ח שער סדר אצי' ש\"ג, פ\"א."],["2553","11","<b>חכמה כח מה</b>: זהר רע\"מ צו כח, א. לד, א. סה\"מ תר\"ם ח\"א ע' שז ובהערה 39. ע' שעו על יד הערה 66."],["2555","13","<b>איהו וגרמוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["2554","12","<b>(ולכן . . חד)</b>: הוספה על אוה\"ת וסה\"מ שבהערה 3."],["2556","14","<b>נאמר</b>: באוה\"ת שבהערה 3: נאמר ראומה. אבל בסה\"מ תרל\"ב שם כבפנים."],["2557","15","<b>ראו מ\"ה</b>: וירא כב, כד. ראה הנסמן במ\"מ ל<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380260\" data-slug=\"likkutei-torah\" data-id=\"4001380260\">לקו\"ת בהר מג, א</a>. מאמרי אדה\"א דברים ח\"ד ע' א'תצג. וש\"נ. סה\"מ תר\"ם ח\"ב ע' תתקיא. וש\"נ."]]],[2001910277,"הביטול ולכן נק' בשם קליפה, ותדע שאפי' בע\"ס דקדושה נק'<sup data-n=\"2558\">16</sup> דא מוחא ודא<sup data-n=\"2559\">17</sup> קליפה<sup data-n=\"2560\">18</sup> בזח\"א פ' בראשית דף ך' ע\"א, וכמו אותיות מחשבה ודבור הם כמו קליפה<sup data-n=\"2561\">19</sup> ולבוש לגבי עצם החכמה, וא\"כ<sup data-n=\"2562\">20</sup> גם הק\"נ דאצילות אף שהיא<sup data-n=\"2563\">21</sup> אצי' מכח המגביל מ\"מ נק' בשם<sup data-n=\"2564\">22</sup> קליפה, אלא שי\"ל שהוא ע\"ד הקליפה הנקרא שומר לפרי<sup data-n=\"2565\">23</sup> כמ\"ש בשל\"ה בהקדמה די\"ט ע\"ב<sup data-n=\"2566\">24</sup> בפי' השומר אחי אנכי<sup data-n=\"2567\">25</sup>, ועמ\"ש בהוספה לת\"א<sup data-n=\"2568\">26</sup> בד\"ה ויקח המן<sup data-n=\"2569\">27</sup> את הלבוש, בענין<sup data-n=\"2570\">28</sup> שמיני שבשמינית<sup data-n=\"2571\">29</sup> ומעטרא לי' כסאסאה לשיבולתא, והיינו בכדי להיות ויגבה לבו בדרכי ה'<sup data-n=\"2572\">30</sup>, אלא שבהשתלשלות מהן בבי\"ע נעשו קליפות ממש, דוגמת נהר דינור יוצא מזיעתן של חיות (שלמטה נעשה מזה דין קשה שעל ראש רשעים יחול<sup data-n=\"2575\">33</sup> בגיהנם<sup data-n=\"2573\">31</sup> כו' כידוע, ובשרשו הזיעה הוא רק בחי' הפסולת<sup data-n=\"2576\">34</sup> שיוצא מתוקף יראתם שזעים מחיל כסא<sup data-n=\"2577\">35</sup>, ובעבודה ז\"ע שאחר ההתבוננות בתפלה יכול להיות נמשך כעס על ההיפך, וז\"ע וחרה אף<sup data-n=\"2578\">36</sup> דכתי' בפ' שני' של ק\"ש כמ\"ש בלק\"ת פ' שלח בד\"ה בפ' נסכים<sup data-n=\"2574\">32</sup>)<sup data-n=\"2579\">37</sup>, וגם בלא\"ה יש הפרש גדול בין ק\"נ דאצי' לק\"נ דבי\"ע כו', שהרי בקדושה אצילות לשון ויאצל<sup data-n=\"2580\">38</sup>",[["2558","16","<b>נק'</b>: באוה\"ת שם: ו\"ק."],["2559","17","<b>דא מוחא ודא קליפה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381287\" data-slug=\"likkutei-torah\" data-id=\"4001381287\">לקו\"ת שה\"ש לט, ד</a>. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתסו ואילך. תקס\"ג ח\"א ע' טז. אוה\"ת במדבר כרך ד ע' א'תסח ואילך."],["2560","18","<b>ודא קליפה</b>: בסה\"מ תרל\"ב שם ריש ע' תנז: לדא ודא קליפה לדא."],["2561","19","<b>בזח\"א . . קליפה</b>: כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940114\" data-slug=\"or-hatorah-hb\" data-id=\"8159940114\">אוה\"ת תזריע</a> מהדורת תשנ\"ג ע' תקל. ובסה\"מ תרל\"ב שם. אבל באוה\"ת שם מהדורת תשכ\"ט ובכרך א מהדורת תשנ\"ב ע' שנ: ליתא. וכנראה נשמט מפני תיבות הדומות: קליפה . . קליפה."],["2562","20","<b>וא\"כ</b>: שם: א\"כ."],["2563","21","<b>שהיא</b>: באוה\"ת שם: שהוא. בסה\"מ תרל\"ב שם כבפנים."],["2564","22","<b>בשם</b>: הוספה על הנ\"ל."],["2565","23","<b>הקליפה הנקרא שומר לפרי</b>: ראה גם סה\"מ תרל\"ח ע' קלה. וש\"נ."],["2566","24","<b>ע\"ב</b>: באוה\"ת וסה\"מ תרל\"ב: ע\"א. ולכאו' צ\"ל כבפנים.\nהשל\"ה הועתק בחלקו בלקו\"ת לג\"פ [ווילנא תרמ\"ד] פ' נח סו, ד ואילך. אוה\"ת נח כרך ג' ע' 1342."],["2567","25","<b>השומר אחי אנכי</b>: בראשית ד, ט."],["2568","26","<b>בהוספה לת\"א</b>: ועד\"ז הוא בסה\"מ תרל\"ב. ובאוה\"ת שם ליתא."],["2569","27","<b>בהוספה לת\"א בד\"ה ויקח המן</b>: מג\"א קיט, ג."],["2570","28","<b>בענין . . ה'</b>: הוספה על אוה\"ת וסה\"מ תרל\"ב הנ\"ל."],["2571","29","<b>שמיני שבשמינית</b>: ראה סוטה ה, א. מאמרי אדה\"א ויקרא ח\"ב ע' תעז. וש\"נ. סה\"מ תר\"ם ח\"א ע' רכ ואילך וש\"נ."],["2572","30","<b>ויגבה לבו בדרכי ה'</b>: דברי הימים-ב יז, ו. ראה גם כש\"ט קה\"ת סשצ\"ג (נז, א ואילך)."],["2575","33","<b>שעל ראש רשעים יחול</b>: ירמי' כג, יט. ל, כג."],["2573","31","<b>נהר דינור . . חיות . . בגיהנם</b>: ראה חגיגה יג, ב. ראה גם סה\"מ תרל\"א ח\"א ע' רעו. וש\"נ."],["2576","34","<b>הזיעה . . הפסולת</b>: ראה גם לקו\"ת המובא בסמוך בפנים. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550765\" data-slug=\"torat-chaim\" data-id=\"2300550765\">תו\"ח ויקהל ח\"ב תט, ד</a> ואילך. וש\"נ. סה\"מ תר\"ם ח\"א ע' כה."],["2577","35","<b>שזעים מחיל כסא</b>: ראה פיוט והחיות ב[נוסח הקדושה אשכנז) מוסף לר\"ה. סה\"מ תר\"ם שם ע' כח."],["2578","36","<b>וחרה אף</b>: עקב יא, יז. ראה גם סה\"מ שם ע' כו ואילך."],["2574","32","<b>(שלמטה . . נסכים)</b>: הוספה על אוה\"ת וסה\"מ תרל\"ב הנ\"ל."],["2579","37","<b>בלק\"ת פ' שלח . . נסכים</b>: מא, א ואילך."],["2580","38","<b>אצילות לשון ויאצל</b>: בהעלותך יא, כה. ראה גם פרדס שבהערה הבאה. סה\"מ תרל\"א ח\"א ע' קלח. וש\"נ."]]],[2001910278,"גילוי ההעלם<sup data-n=\"2581\">39</sup> כו'<sup data-n=\"2582\">40</sup>, משא\"כ הבריאה יש מאין, מעתה ג\"כ יש הפרש גדול עד\"ז בין ק\"נ דאצי' לק\"נ דבי\"ע, ולכן<sup data-n=\"2583\">41</sup> אע\"פ שבק\"נ דבי\"ע יש רע ממש רק שמעורב בטוב<sup data-n=\"2584\">42</sup> כו', לא נאמר כן בק\"נ דאצי' ששם אין רע כלל (או אפ\"ל שאינו רע גמור)<sup data-n=\"2585\">43</sup> כ\"א שאין<sup data-n=\"2586\">44</sup> הביטול כדבעי למהוי, כ\"א<sup data-n=\"2587\">45</sup> ע\"ד ראו מ\"ה, וזהו שרש בחי' לגרמיה כו', רק למטה נמשך מזה כו'<sup data-n=\"2588\">46</sup> (בהשתלשלות גם בחי' רע גמור כו'<sup data-n=\"2589\">47</sup>).\n<b>ועוי\"ל</b> באופן אחר לגמרי<sup data-n=\"2590\">48</sup> שבק\"נ דאצי' חצי' טוב וחצי' רע והרע הוא מה שנפל בה משבה\"כ דתהו, וכמ\"ש בלק\"ת בד\"ה אם בהרת פי' ק\"נ דאצי', שבקדושה יש התכללות ע\"י בחי' הת\"ת שמיחד חו\"ג, וכנודע עמ\"ש<sup data-n=\"2592\">50</sup> בפי' הזח\"ב תרומה דקע\"ה ע\"ב<sup data-n=\"2591\">49</sup>, שמחבר חו\"ג ומבריח מן הקצה אל הקצה שעולה עד הכתר, ומחבר עתיקא קדישא וזעיר אנפין, אבל בק\"נ דאצי' אין בחי' התכללות כלל, ואעפ\"כ מחמת חציה הטוב שבה מקבלת מאצי' דקדושה, רק מפני כי גם בטוב דק\"נ אין בו התכללות לכן מה שמאיר בה מאצילות דקדושה זהו רק בבחי' מקיף ולא בבחי' או\"פ, ולכן יכול להיות חצי' שכלפי חוץ רע, וענין הנגעים הוא שבהסתלק אור אבא מזו\"נ דקדושה אזי לא נמצא בהם ג\"כ ההתכללות גמור ואזי יכול להיות יניקה לק\"נ דאצילות מעור דזו\"נ דקדושה, והיינו ע\"י השער לבן שצומח בנגע דבהרת (וצ\"ל שהגם שיש בהם בחי' ההתכללות שיש בתיקון שכל מדה כלולה מכל הששה מדות אמנם זהו התכללות שמצד הכלים ועיקר התיקון זהו ההתכללות שמצד האורות שזה נמשך מצד השגחת אפין באפין היינו השגחת עתיקא קדישא בז\"א כמ\"ש בלק\"ת<sup data-n=\"2593\">51</sup>\n\nכי<sup data-n=\"8447\">יב</sup> בבחי' התהו דוקא שהיו נקודות זה תחת זה<sup data-n=\"8448\">יג</sup> לא היו משגיחין הכתר פב\"פ עם הת\"ת מפני שחסד וגבורה היו מפסיקין בניהם כמ\"ש הפי' מתלמיד האריז\"ל על ספד\"צ<sup data-n=\"8449\">יד</sup>, אבל לא בתיקון, וגם החכ' נק' חיוהי כמ\"ש בע\"ח שער מ\"א פ\"ז<sup data-n=\"8450\">טו</sup> וכלי החכ' היא ג\"כ מ\"ה<sup data-n=\"8451\">טז</sup> לכן הגם שנמשך מהכתר ע\"י חכמה לת\"ת נק' זה פב\"פ, היינו אפין באפין, ואולי אפין באפין זהו שלא ע\"י החכמה, ומביאור דהחלצו ספ\"ב<sup data-n=\"8452\">יז</sup> משמע שזהו ע\"י החכמה.\n*)ועפ\"ז<sup data-n=\"8453\">יח</sup> יובן מה שנת' בביאור דציץ<sup data-n=\"8454\">יט</sup> שאסתכלותא דעתיקא בז\"א<sup data-n=\"8455\">כ</sup> זהו עין בעין<sup data-n=\"8456\">כא</sup> כי גם זה נמשך ע\"י החכמה שנק' עין<sup data-n=\"8457\">כב</sup> חכמים עיני העדה<sup data-n=\"8458\">כג</sup> ואין עין אלא נבואה<sup data-n=\"8459\">כד</sup> גילוי ההעלם<sup data-n=\"8460\">כה</sup> כשמאיר בבינה עלמא עילאה<sup data-n=\"8461\">כו</sup> שמתגלה העלם דברק המבריק<sup data-n=\"8462\">כז</sup> דחכ' כו'.\n*)טו\"ב<sup data-n=\"8463\">כח</sup>",[["2581","39","<b>אצילות . . גילוי ההעלם</b>: ראה לקמן הערה 61."],["2582","40","<b>כו'</b>: באוה\"ת וסה\"מ תרל\"ב הנ\"ל ליתא."],["2583","41","<b>ולכן</b>: שם: לכן."],["2584","42","<b>בטוב</b>: שם: ממש בטוב."],["2585","43","<b>(או . . גמור)</b>: הוספה על אוה\"ת וסה\"מ תרל\"ב הנ\"ל."],["2586","44","<b>שאין</b>: שם: אין."],["2587","45","<b>למהוי כ\"א</b>: שם ליתא."],["2588","46","<b>כו'</b>: בסה\"מ תרל\"ב ניתוסף: כנ\"ל."],["2589","47","<b>(בהשתלשלות . . כו')</b>: הוספה על אוה\"ת וסה\"מ תרל\"ב הנ\"ל."],["2590","48","<b>ועוי\"ל באופן אחר לגמדי</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380174\" data-slug=\"likkutei-torah\" data-id=\"4001380174\">לקו\"ת תזריע כג, ג</a>-ד. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940114\" data-slug=\"or-hatorah-hb\" data-id=\"8159940114\">אוה\"ת תזריע שם ריש ע' תקל</a>."],["2592","50","<b>עמ\"ש</b>: בכת\"י מעתיק: ממ\"ש."],["2591","49","<b>הת\"ת . . הזח\"ב תרומה דקע\"ה ע\"ב</b>: מובא גם בכ\"מ ומהם: (בנוסף ללקו\"ת כאן כב, ג. כג, ג.ועוד. לקמן בפיסקא הבאה) אוה\"ת ויצא ריג, ב — נדפס גם באוה\"ת דברים ע' לו. תרומה כרך ח ע' ג'נא. תזריע כרך ב' ע' תקכא. סה\"מ תרכ\"ז ע' שח וע' שטז. תרכ\"ט ע' קכה. תר\"ם ח\"א ע' רלג. וש\"נ."],["2593","51","<b>בלק\"ת</b>: מטות.\n\n<b>יב</b> ) <b>כי</b>: נרשם בצד השמאלי של העמוד בשני קטעים הפוכים, חלקו הראשון נרשם מלמטלמ\"ע, ובהפסק קו שבתחתיתו נרשם הוראה להמעתיק: ”להעתיק למטה\", נרשם המשכו חלקו השני מלמעלמ\"ט, ללא ציון מקומו בפנים.\nראה גם להבא לקמן <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380670\" data-slug=\"likkutei-torah\" data-id=\"4001380670\">לקו\"ת מטות פז, סע\"א</a>. ד.\n\n<b>יג</b> ) <b>בבחי' התהו . . תחת זה</b>: ראה ע\"ח שער הכללים פ\"א. שער התיקון ש\"י, פ\"ה. מאמרי אדה\"א קונטרסים ע' תז. וש\"נ. וראה גם סה\"מ תרל\"ח ע' רסא. וש\"נ. ע' שנג.\n\n<b>יד</b> ) <b>הפי' מתלמיד האריז\"ל על ספד\"צ</b>: המצויין כאן בפנים המאמר בסוף הפיסקא — ובדפי הספר [זהר הרקיע] קד, ב ואילך פיסקא ר\"ל. הועתק לשונו ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380670\" data-slug=\"likkutei-torah\" data-id=\"4001380670\">לקו\"ת מטות פז, סע\"א</a>.\n\n<b>טו</b> ) <b>בע\"ח שער מ\"א פ\"ז</b>: וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380673\" data-slug=\"likkutei-torah\" data-id=\"4001380673\">לקו\"ת שם פז, ד</a>. ולפנינו שמ\"ב, פ\"ה.\n\n<b>טז</b> ) <b>וכלי החכ' . . מ\"ה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380673\" data-slug=\"likkutei-torah\" data-id=\"4001380673\">לקו\"ת מטות פז, סע\"ד</a>.\n\n<b>יז</b> ) <b>ומביאור דהחלצו ספ\"ב</b>: ראה לקו\"ת שם.\n\n<b>יח</b> ) <b>ועפ\"ז</b>: קטע זה נרשם בבפנים המאמר כאן בין חצאי עיגול. ועה\"ג בצד הימני של העמוד (בהפסק קו מלמעלמ\"ט) נרשם הוראה להמעתיק: ”מן ועפ\"ז עד דחכ' כו' אינו שייך לדרוש זה ונצרך להעתיק למטה\".\n\n<b>יט</b> ) <b>בביאור דציץ</b>: נדפס לעיל מאמר ד\"ה להבין שרשי וביאור הדברים בענין הציץ.\n\n<b>כ</b> ) <b>שאסתכלותא דעתיקא בז\"א</b>: ראה לעיל שם הערה 238.\n\n<b>כא</b> ) <b>עין בעין</b>: שלח יד, יד.\n\n<b>כב</b> ) <b>החכ' שנק' עין</b>: ראה לקו\"ת מסעי צד, ד. ביאוה\"ז תשא נה, סע\"א. סהמ\"צ להצ\"צ קלו, ב. פיה\"מ עט, ד. ש\"א סא, ב הערה 31.\n\n<b>כג</b> ) <b>חכמים עיני העדה</b>: שלח טו, ד. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540580\" data-slug=\"torat-chaim\" data-id=\"2300540580\">תו\"ח בא ח\"א קב, א</a> ובהערה 248.\n\n<b>כד</b> ) <b>ואין עין אלא נבואה</b>: שמו\"ר פל\"ח, ד. הובא גם בהמאמר שבהערה הבאה רפ\"ב.\n\n<b>כה</b> ) <b>נבואה גילוי ההעלם</b>: ראה לעיל מאמר ד\"ה להבין וכו' בענין הציץ פ\"ב ואילך.\n\n<b>כו</b> ) <b>בבינה עלמא עילאה</b>: ראה זהר בראשית לד, א ובמק\"מ שם. אוה\"ת (יהל אור) תהלים ע' תטו ואילך.\n\n<b>כז</b> ) <b>דברק המבריק</b>: ראה גם בענין ברק המבריק לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה קא מיפלגי במתיבתא דרקיעא ובהערה 81.\n\n<b>כח</b> ) <b>טו\"ב</b>: נרשם בריש צד הימני של העמוד (בהפסק קו מלמעלמ\"ט בינו להפנים). והכוונה שהבא להלן מיוסד על הגהות ללקו\"ת משנת ”טו\"ב\" — תרי\"ז. הגהות אלו נדפסו באוה\"ת תזריע כרך ב ע' תקלא ואילך. ולהבא לקמן ראה שם ס\"ע תקלג ואילך."]]],[2001910279,"בביאור החלצו דפ\"ז ע\"ב, וי\"ל שאז נעשה בבחי' פרצוף שכל ספירה כלולה מעשר כמ\"ש בביאור והניף פ\"א, בלק\"ת פ' אמור דל\"ז ע\"ד<sup data-n=\"2594\">52</sup>, שז\"ע המשכת אורות עליונים כי הכתר הוא הממוצע<sup data-n=\"2595\">53</sup> המחבר וממשיך הארת המאציל א\"ס ב\"ה בנאצלים, וזאת נודע כי אור הכתר מאיר באצי' ע\"י החכ' כמ\"ש בע\"ח דאור א\"ס מתלבש באצי' בחכמה<sup data-n=\"2596\">54</sup> לבדו, הובא בלק\"ת<sup data-n=\"2597\">55</sup> בדרוש בהרת פ\"ד, ולכן כאשר אור אבא אינו מאיר לא נמצא בזו\"נ ההתכללות מצד האורות שזהו עיקר התיקון*, ולכן יכול להסתעף סיבת הנגעים שנמשך יניקה לק\"נ דאצי'). ועפ\"ז יש להעיר ממ\"ש בלק\"ת ד\"ה החלצו<sup data-n=\"2599\">57</sup>, בענין מדין שאינו מז' עממין מדות הרעות ניאוף וכדומה, כ\"א ריב ומדון<sup data-n=\"2600\">58</sup> שנאת חנם דקות הרע שזה כבד יותר לברר, מפני שאינו שב ע\"ז כלל שחושב שבדין הוא שישנא אותו מפני שהנכון אתו נגד בעלי מריבו כו', ושרש ענין ריב ומדון זהו היפך ההתכללות, כ\"א ענפין מתפרדין<sup data-n=\"2601\">59</sup>, וזהו עולם התהו<sup data-n=\"2598\">56</sup> כו', שלא היו משגיחין אפין באפין כמ\"ש בספד\"צ, תרומה קע\"ו ב' עד לא הוו מתקלא לא היו משגיחין אפין באפין.",[["2594","52","<b>וי\"ל שאז . . ע\"ד</b>: נרשם בגוכתי\"ק מלמעלמ\"ט בצד השמאלי של העמוד ללא ציון מקומו בפנים, ואולי שייך כאן."],["2595","53","<b>הכתר הוא הממוצע</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. מאמרי אדה\"א ויקרא ח\"ב ע' תס. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540828\" data-slug=\"torat-chaim\" data-id=\"2300540828\">תו\"ח שמות ח\"א יא, ג</a>. וש\"נ."],["2596","54","<b>כמ\"ש בע\"ח . . בחכמה</b>: ראה גם לעיל מאמר ד\"ה ובירך את לחמך ובהערה 11."],["2597","55","<b>הובא בלק\"ת</b>: כאן כג, ד."],["2599","57","<b>בלק\"ת ד\"ה החלצו</b>: מטות פו, א."],["2600","58","<b>מדין . . ריב ומדון</b>: ראה גם (בנוסף ללקו\"ת מטות) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550205\" data-slug=\"torat-chaim\" data-id=\"2300550205\">תו\"ח יתרו ח\"ב עדר, ד</a>. וש\"נ."],["2601","59","<b>ענפין מתפרדין</b>: זהר ח\"ש קכג, א."],["2598","56","<b>ועפ\"ז יש . . התהו</b>: השוה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940114\" data-slug=\"or-hatorah-hb\" data-id=\"8159940114\">אוה\"ת תזריע</a> כאן ריש ע' תקל עם הוספות."]]],[2001910280,"<b>ועוי\"ל*</b> בענין ק\"נ דאצילות (היינו שלפי הנ\"ל שבק\"נ יש רע צריכים לתרץ איך שייך לומר לשון אצילות על ק\"נ<sup data-n=\"2602\">60</sup>, והענין הוא דהנה מה שקורא ק\"נ בשם אצילות אין פירושו כמו בכל מקום שאצילות הוא אלקות<sup data-n=\"2603\">61</sup> שהוא גילוי ההעלם ולא כמו בריאה יש מאין כנזכר לעיל, וגם לא כמ\"ש במ\"א בפי' אצי' שהוא כמו בל\"א געטליך, ולא אלקה<sup data-n=\"2604\">62</sup> (בל\"א<sup data-n=\"2605\">63</sup> גאט<sup data-n=\"2606\">64</sup>) כ\"א אפ\"ל ששייך לשון אצילות גם במה שאינו אלקות כלל, ויובן זה ע\"פ מה שנודע שיש נשמות דאצי' שהם למעלה מבחי' נשמות הנבראים, כמ\"ש בת\"א בד\"ה ואלה המשפטים<sup data-n=\"2607\">65</sup> בענין וזרעתי את בית ישראל<sup data-n=\"2608\">66</sup> זרע אדם וזרע בהמה<sup data-n=\"2609\">67</sup> שיש נשמות שנק' בשם זרע אדם שהם נשמות דאצי' ונשמות הנק' בשם זרע בהמה שהם הנשמות דבי\"ע שנק' בשם בהמה כמו המלאכים שנק' בשם",[["2602","60","<b>ק\"נ</b>: אוצ\"ל: ק\"נ)."],["2603","61","<b>שאצילות הוא אלקות</b>: ראה עבודת הקדש חלק היחוד פ\"ב. רפ\"ד. <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא פמ\"ט (סט, א</a>). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370339\" data-slug=\"torah-or\" data-id=\"3901370339\">תו\"א משפטים עו, ב</a>. סה\"מ תרל\"א ח\"א ע' קלח. וש\"נ. סה\"מ תר\"ם ח\"א ע' רמא. וש\"נ. ח\"ב ע' תשמא. וש\"נ."],["2604","62","<b>אצי' . . געטליך ולא אלקה</b>: ראה גם סה\"מ תר\"ם ח\"ב ע' תקכג. וש\"נ."],["2605","63","<b>בל\"א</b>: בלשון אידיש. ראה גם סה\"מ תרל\"ח ע' ה. וש\"נ."],["2606","64","<b>גאט</b>: ראה גם בענין כתיבת תיבה זו מאמרי אדה\"א נ\"ך ע' תקמג-תקמו. קונטרסים ע' תצח. ע' תקפט. ע' תקצד. ע' תקצז. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' פו. אוה\"ת ואתחנן כרך ו ע' ב'רנז-ב'רנט. ישעי' כרך ג ע' א'רלג-א'רלח. ספר השיחות תש\"ג ע' 62 וע' 63 ובהערה שם. סה\"מ תר\"ם ח\"ב ע' תשמח. וש\"נ. אג\"ק ח\"ז ע' כו. ח\"ט ס\"ע סב."],["2607","65","<b>בת\"א בד\"ה ואלה המשפטים</b>: עד, ג ואילך."],["2608","66","<b>וזרעתי את בית ישראל</b>: ירמי' לא, כו [בדילוג]."],["2609","67","<b>זרע אדם וזרע בהמה</b>: ראה גם לעיל מאמר ד\"ה אז ישיר משה ובהערה 121."]]],[2001910281,"בהמות י\"ב בקר<sup data-n=\"2612\">70</sup> דבריאה<sup data-n=\"2610\">68</sup>, ובשם חיות דיצי'<sup data-n=\"2611\">69</sup> שראה יחזקאל<sup data-n=\"2613\">71</sup> כו', כן גם הנשמות נק' בשם זרע בהמה, ויש נשמות דאצי' שנק' זרע אדם כמו נשמת האבות<sup data-n=\"2614\">72</sup> ומשה<sup data-n=\"2615\">73</sup>, ומ\"מ גם הנשמות דאצי' אינם אלקות ממש, ואינם כמו העשר ספירות דאצי' כמ\"ש מזה באגה\"ק סי' ך'<sup data-n=\"2616\">74</sup> ד\"ה איהו וחיוהי, כמ\"כ יוכל להשתלשל גם ק\"נ דאצי', ואינו אלקות ח\"ו ולא כמו ע\"ס דקדושה דאצי' דאיהו וחיוהי חד ואיהו וגרמוהי חד<sup data-n=\"2617\">75</sup>, משא\"כ בנשמות דאצי' וכ\"ש וק\"ו בק\"נ דאצי', והיינו כי הקו וחוט מאיר בספי' התפארת דאצי', (אם ע\"י החכ' דאצי' כמ\"ש בלק\"ת<sup data-n=\"2618\">76</sup> בד\"ה אם בהרת פ\"ד בהג\"ה ע\"ש, וביותר לפי מה שמדברים כאן שהקו ז\"ע חוטא יקירא קדישא שנת' באד\"ר פ' נשא דקל\"ד ע\"א, או ע\"פ מ\"ש במ\"א בענין שהת\"ת עולה עד הכתר<sup data-n=\"2619\">77</sup>, ע\"פ מ\"ש בזהר תרומה דקע\"ה ב'), וזהו סוד קדוש בוא\"ו, וע\"י התפארת מאיר בחו\"ג ג\"כ וכנודע שהתפארת מחבר חו\"ג ע\"י שמאיר בו מבחי' דלאו מכל אינון מדות<sup data-n=\"2620\">78</sup> איהו כלל כמ\"ש באגה\"ק סי' י\"ב ד\"ה והי' מעשה הצדקה שלום, שלכן יש בכחו לחברם, וכאשר מחבר חו\"ג ממילא מאיר גם בהם הארת הקו וחוט, וכן בכל הע\"ס דאצי', משא\"כ אפי' בנשמות דאצי' אין מאיר הארת הקו וחוט, וכ\"ש וק\"ו בק\"נ דאצי' כו', ובודאי יש הפרש גדול בין נשמות דאצי' שהן קדש כמ\"ש קדש ישראל לה'<sup data-n=\"2621\">79</sup>, נשמה שנתת בי טהורה היא<sup data-n=\"2622\">80</sup>, משא\"כ ק\"נ דאצי' (שאין שייך שמות קדש וטהר, שהרי ק\"נ הוא מחצה טוב ומחצה רע כמ\"ש בלק\"ת<sup data-n=\"2623\">81</sup> בדרוש בהרת הנ\"ל, ובפ' חקת<sup data-n=\"2624\">82</sup> בד\"ה ויקחו אליך פרה איתא במשניות פ\"א ע\"ש ובנשמות דאצי' הגם שאין מאיר בהם הקו מ\"מ אף גם לאחר שירדו הנר\"נ דאצי' לעוה\"ז לצדיקים הראשונים אפשר שלא נשתנה מהותן להיות דבר נפרד מאלקות ולכן הי' מסתלקות (מן הגוף) כשרוצה<sup data-n=\"2626\">84</sup> לחטוא בטרם יחטאו<sup data-n=\"2625\">83</sup> כמ\"ש באגה\"ק סי' ך' ד\"ה איהו וחיוהי הנ\"ל, שנמצא אינם בערך כלל לבחי' ק\"נ דאצי' שיש בה מחצה רע כו') רק המכוון מן הדמיון שמדמים ק\"נ דאצי' לנשמות דאצי' זהו איך ששייך לשון אצילות גם בבחי' נשמות דאצי' שאינם אלקות",[["2612","70","<b>י\"ב בקר</b>: ראה מלכים-א ז, כה. מד. דברי הימים-ב ד, טו."],["2610","68","<b>המלאכים שנק' . . בהמות . . דבריאה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו יז, רע\"א</a>. <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא רפל\"ט</a> בהגהה."],["2611","69","<b>המלאכים שנק' בשם . . חיות דיצי'</b>: ראה תניא שם."],["2613","71","<b>דיצי' שראה יחזקאל</b>: ראה גם לעיל מאמר ד\"ה להבין וכו' בענין הציץ ובהערה 270."],["2614","72","<b>נשמות דאצי' . . האבות</b>: ראה גם מאמרי אדה\"ז על מאמרי רז\"ל ע' רצא ואילך. לעיל מאמר ד\"ה הוא אהרן ומשה ובהערה 88."],["2615","73","<b>נשמות דאצי' . . ומשה</b>: ראה גם מאמרי אדה\"א נ\"ך ע' קפז־ סה\"מ תרל\"א ח\"א ע' קלח. תרל\"ב ח\"א ע' מב ואילך־ תרל\"ה ח\"א ע' רסו ובהנסמן בהנ\"ל."],["2616","74","<b>באגה\"ק סי' ך'</b>: תניא קל, א."],["2617","75","<b>דאיהו וחיוהי . . חד</b>: ראה ת\"ז בהקדמה ג, ב. סה\"מ תר\"ם ח\"א ע' מג. וש\"נ."],["2618","76","<b>כמ\"ש בלק\"ת</b>: תזריע כאן כג, ד."],["2619","77","<b>שהת\"ת עולה עד הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (סג, ב). מאמרי אדה\"ז הקצרים ע' תקעט."],["2620","78","<b>דלאו מכל אינון מדות</b>: ת\"ז בהקדמה יז, ב."],["2621","79","<b>קדש ישראל לה'</b>: ירמי' ב, ג."],["2622","80","<b>נשמה . . טהורה היא</b>: ברכת אלקי נשמה (מברכות ס, ב). ראה גם סה\"מ תר\"ם ח\"א ע' נב. וש\"נ. לעיל מאמר ד\"ה מגילה נקראת ספ\"ד."],["2623","81","<b>כמ\"ש בלק\"ת</b>: תזריע כאן כג, ב ואילך."],["2624","82","<b>בלק\"ת . . ובפ' חקת</b>: ס, ב."],["2626","84","<b>כשרוצה</b>: באגה\"ק שם: כשרצו."],["2625","83","<b>דאצי'. . מסתלקות . . בטרם יחטאו</b>: ראה (בנוסף לאגה\"ק כאן קל, א). ת\"ז ת\"ע קכד, סע\"א ובכס\"מ שם. עמה\"מ שער רישא דז\"א פי\"ח (קלה, א). מאמרי אדה\"א נ\"ך ע' קצא ואילך. סה\"מ עזר\"ת ס\"ע קפד ואילך. תר\"ם ח\"א ס\"ע שלג ואילך. וש\"נ."]]],[2001910282,"ממש לברוא בהם וע\"י יש מאין כמו הכלים די\"ס דאצי' שבהם מלובש הקו וחוט, ועכ\"ז נקראים הנשמות נשמות דאצי', עד\"ז יובן שגם בק\"נ שייך לומר לשון אצילות*.\n<b>ועוי\"ל</b><sup data-n=\"2627\">85</sup> שנקראו ק\"נ בשם אצי' ע\"ד ואצלתי מן הרוח<sup data-n=\"2628\">86</sup> אשר עליך ושמתי עליהם היינו על ע' איש הזקנים, הרי המשכת הרוח בע' זקנים<sup data-n=\"2629\">87</sup> נק' אצי', ואצילות זו נמשך ממשה, שנמצא משה נק' כמו מאציל לגבי הע' זקנים שנק' אצילות, שמובן שאצילות בחי' הע' זקנים אין זה ערך כלל לבחי' האצילות דע\"ס דאצי' שנאצל מן המאציל ממש, משא\"כ ע' זקנים אצילותן הוא מנשמת משה שהיא נשמה, ואינה דומה לע\"ס ממש, ועד\"ז יובן ענין ק\"נ דאצי', ושרש אצילותן אפ\"ל שהוא מסיגי מדה\"ד דאצי', שמעטפיה דיצחק<sup data-n=\"2630\">88</sup> כו', וכבר ארז\"ל אליו ולא למדותיו<sup data-n=\"2631\">89</sup> נמצא המדות אין ערוך אליו ממש כי לאו מכל אלין מדות איהו כלל.",[["2627","85","<b>ועוי\"ל</b>: הבא להלן הוא ע\"פ לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940118\" data-slug=\"or-hatorah-hb\" data-id=\"8159940118\">אוה\"ת תזריע שם ע' תקלד</a>."],["2628","86","<b>ואצלתי מן הרוח</b>: בהעלותך יא, יז."],["2629","87","<b>המשכת הרוח בע' זקנים</b>: ראה גם מאמרי אדה\"א קונטרסים ע' רפו. וש\"נ."],["2630","88","<b>שמעטפיה דיצחק</b>: ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940004\" data-slug=\"or-hatorah-hb\" data-id=\"8159940004\">אוה\"ת כאן: ע\"ד</a> רישי' דעשו בעטפוי דיצחק — הובא בכ\"מ בשם הזהר ומהם הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תרסב. קונטרסים ע' שלג. ראה תיוב\"ע ויחי נ, יג."],["2631","89","<b>אליו ולא למדותיו</b>: ואתחנן ד, ז. במאמרי אדה\"ז תקס\"ג ח\"א ע' קכו: שארז\"ל בספרי. ראה פרדס שער הכוונה של\"ב, פ\"ב. מאמרי אדה\"א ויקרא ח\"א ע' נ. וש\"נ. נ\"ך ע' לד. וש\"נ."]]],[2001910283,"<b>ודע</b><sup data-n=\"2632\">90</sup> שמעמד קלי' דאצי' הוא בבריאה<sup data-n=\"2633\">91</sup>.\n\nוענין<sup data-n=\"8464\">כט</sup> בחי' חצי' טוב<sup data-n=\"8465\">ל</sup> שבק\"נ הוא בחי' הרגשת היש, ומ\"מ בחי' ק\"נ יכול להתברר ולהיות בבחי' ביטול לגמרי באוא\"ס וכענין וכל צבא השמים לך משתחוים<sup data-n=\"8466\">לא</sup> שהוא בחי' הביטול שבנבראים דבי\"ע דקדושה, היינו מה שכבר נתברר מהנצוצות דתהו שנפלו בשבה\"כ כמ\"ש בלק\"ת בביאור החלצו<sup data-n=\"8467\">לב</sup>, וז\"ע שלפעמים בחי' נוגה עולה לגמרי בקדושה ועליה נא' והנה טוב מאד כמ\"ש בד\"ה ויקחו אליך הנ\"ל<sup data-n=\"8468\">לג</sup>.\nצ\"ע<sup data-n=\"8469\">לד</sup> בענין משה משה לא פסיק<sup data-n=\"8470\">לה</sup>, ולפמשנ\"ת בביאור ציץ מן המים דח\"ס<sup data-n=\"8471\">לו</sup> עצמה שלמעלה מקרומא דאוירא<sup data-n=\"8472\">לז</sup> משיתיהו בגוף ע\"ש, וגם נת' לעיל<sup data-n=\"8473\">לח</sup> שאפשר שלא נשתנה גם בכל הצדיקים הראשונים, ע' בביאור דהחלצו ספ\"א<sup data-n=\"8474\">לט</sup> בענין משה משה לא פסיק שזהו מצד הדעת המשכת פנימיות רעו\"ד<sup data-n=\"8475\">מ</sup>, שהאור הוא אלקות בבי\"ע כמו באצי', ובביאור ואלה המשפטים<sup data-n=\"8476\">מא</sup>.\nוע'<sup data-n=\"8477\">מב</sup> בביאורמג בחדש השלישי דתקס\"ז<sup data-n=\"8479\">מד</sup>, ובמאה\"ז ויחי דרמ\"ו ע\"פ נפתלי אילה שלוחה דתקס\"ז<sup data-n=\"8480\">מה</sup> שפי' שאותיות הדבור הם דומם ושרשם מבחי' מדבר בחי' כתר<sup data-n=\"8478\">מג</sup>, וכמשנ\"ת מזה בד\"ה אדם כי יהי' בעור בשרו דרל\"ה<sup data-n=\"8481\">מו</sup> פ\"ג וספ\"ו.\nכמ\"ש במד\"ר פ' תזריע פט\"ו<sup data-n=\"8482\">מז</sup> אדם משוקל<sup data-n=\"8483\">מח</sup> חציו מים וחציו דם, בשעה שהוא זוכה לא המים רבי' על הדם ולא הדם רבה<sup data-n=\"8484\">מט</sup> על המים, ובזמן שחוטא כו' פעמים שהדם רבהמט על המים ונעשה מצורע הה\"ד אדם או דם, ואין זה סותר למ\"ש בלק\"ת ד\"ה אם בהרת פ\"ד<sup data-n=\"8485\">נ</sup> וז\"ל והנה הנגע הוא בהרת לבנה ועד\"מ למטה באדם הוא ענין הסתלקות הדם מאותו מקום כי הדם הוא הנפש<sup data-n=\"8486\">נא</sup> עכ\"ל, שהכוונה היא אחת עם מה שכ' המד\"ר לפי שהילוך וסיבוב הדם תלוי במים שבדם, ולכן כשחוטא והדם רבים על המים אין המים מסבבים את הדם ונעשה מצורע שנעשה העור לבן בהרת לבנה שהו\"ע הסתלקות החיות ממקום ההוא כו'.",[["2632","90","<b>ודע</b>: בכת\"י מעתיק (ראה לעיל הערה 1) לא נעתקה שורה זו."],["2633","91","<b>שמעמד קלי' . . בבריאה</b>: ראה אוה\"ת ויצא כרך ה' ע' תתמה: ”כ\"מ בע\"ח שער הקליפות פ\"ב . . בשער ק\"נ פ\"ט\" ע\"ש. לעיל מאמר ד\"ה מגילה נקראת הערה 20.\n\n<b>כט</b> ) <b>וענין</b>: הערה זו נרשמה בפנים כאן בהמשך הפיסקא שלפנ\"ז. ועה\"ג נרשם (בהפסק קו מלמעלמ\"ט בינו להפנים) הוראה להמעתיק: ”מן וענין עד סוף העמוד להעתיק למטה\".\n\n<b>ל</b> ) <b>וענין בחי' חצי' טוב</b>: ע\"פ לשון הלקו\"ת חוקת ס, ב.\n\n<b>לא</b> ) <b>וכענין וכל צבא השמים לך משתחוים</b>: נחמי' ט, ו [ושם: וצבא וכ\"ה בלקו\"ת כאן. ראה גם לעיל מאמר ד\"ה מגילה נקראת ובהערה 108].\n\n<b>לב</b> ) <b>בלק\"ת בביאורהחלצו</b>: מטות פז, סע\"א.\n\n<b>לג</b> ) <b>והנה טוב מאד . . הנ\"ל</b>: בראשית א, לא. לקו\"ת חוקת ס, ב.\n\n<b>לד</b> ) <b>צ\"ע</b>: נרשם בריש הע' בהיפך הע' ללא ציון מקומו בפנים.\n\n<b>לה</b> ) <b>משה משה לא פסיק</b>: שמות ג, ד. זהר וירא קכב, ב. נשא אד\"ר קלח, א. בלק קפז, ב. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550300\" data-slug=\"torat-chaim\" data-id=\"2300550300\">תו\"ח משפטים ח\"ב רפג, ג</a>. וש\"נ. סה\"מ תר\"ל ע' נו ואילך.\n\n<b>לו</b> ) <b>בביאור ציץ מן המים דח\"ס</b>: לעיל מאמר ד\"ה להבין וכו' בענין הציץ פ\"ה.\n\n<b>לז</b> ) <b>מקרומא דאוירא</b>: ראה זהר ספרא דצניעותא תרומה קעו, ב. אד\"ר נשא קכח, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380672\" data-slug=\"likkutei-torah\" data-id=\"4001380672\">לקו\"ת מטות פז, ג</a>.\n\n<b>לח</b> ) <b>נת' לעיל</b>: פיסקא ועוי\"ל בענין ק\"נ דאצי'.\n\n<b>לט</b> ) <b>בביאור דהחלצו ספ\"א</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380672\" data-slug=\"likkutei-torah\" data-id=\"4001380672\">לקו\"ת מטות פז, ג</a>.\n\n<b>מ</b> ) <b>רעו\"ד</b>: זהר וירא ק, א.\n\n<b>מא</b> ) <b>ובביאור ואלה המשפטים</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370340\" data-slug=\"torah-or\" data-id=\"3901370340\">תו\"א משפטים עו, ג</a>.\n\n<b>מב</b> ) <b>וע'</b>: כל הבא לקמן נרשם (בגוכתי\"ק, ובכת\"י המעתיק ליתא — ראה לעיל הערה 1) בהמשך להמאמר בע' בפ\"ע שבראשו נרשם: ”ל\"נ ולא הועתק\". ואח\"כ נרשם חלק ונמחק.\n\n<b>מד</b> ) <b>בביאור בחדש השלישי דתקס\"ז</b>: מאמרי אדה\"ז תקס\"ז ע' קנג ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370483\" data-slug=\"torah-or\" data-id=\"3901370483\">תו\"א יתרו קט, א</a>.\nהטעם לכאורה, שב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940100\" data-slug=\"or-hatorah-hb\" data-id=\"8159940100\">אוה\"ת</a> שבהערה שלפנ\"ז אינו מציין לתו\"א, אלא למאמרי אדה\"ז. כי דרוש הנ\"ל שבאוה\"ת, הוא לכאורה משנת תרט\"ז (ראה רשימת מאמרי דא\"ח של כ\"ק אדמו\"ר הצ\"צ משנת הנ\"ל ס\"ע קי). וההוספות שבתו\"א נדפסו לראשונה בשנת תרכ\"ב.\n\n<b>מה</b> ) <b>ובמאה\"ז . . נפתלי . . דתקס\"ז</b>: מאמרי אדה\"ז תקס\"ז ס\"ע יג ואילך. הנחות הר\"פ ע' א ואילך. אוה\"ת בראשית כרך ו ס\"ע תתשמג ואילך.\n\n<b>מג</b> ) <b>וע' בביאור . . כתר</b>: השוה אוה\"ת תזריע כרך ב ע' תקכא. סה\"מ תרל\"ה ח\"א ע' ר.\n\n<b>מו</b> ) <b>בד\"ה אדם . . דרל\"ה</b>: סה\"מ תרל\"ה ח\"א ס\"ע קצג ואילך [אוצ\"ל: פ\"ד — ע' קצה ואילך]. וע' ר.\n\n<b>מז</b> ) <b>במד\"ר פ' תזריע פט\"ו</b>: סימן ב. מובא גם באוה\"ת תזריע כרך ב ע' תקטז וע' תקלד. סה\"מ תרל\"ה ח\"א ע' קצ וע' ריב.\n\n<b>מח</b> ) <b>משוקל</b>: בויק\"ר שם: הי' משוקל.\n\n<b>מט</b> ) <b>רבה</b>: שם: רבין.\n\n<b>נ</b> ) <b>בלק\"ת ד\"ה אם בהרת פ\"ד</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380176\" data-slug=\"likkutei-torah\" data-id=\"4001380176\">לקו\"ת תזריע</a> ד\"ה קא מפלגי כד, רע\"א.\n\n<b>נא</b> ) <b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."]]],[2001910284,"<h3>שלש רגלים תחוג לי</h3>\n<b>ליל ב' חה\"פ מ\"א</b>\n<b>שלש</b> רגלים תחוג לי<sup data-n=\"2634\">1</sup> בשנה<sup data-n=\"2635\">2</sup>, את חג המצות תשמור כו' למועד חדש האביב<sup data-n=\"2636\">3</sup> כו' וחג הקציר בכורי מעשיך כו' וחג האסיף בצאת השנה באספך מן<sup data-n=\"2638\">5</sup> השדה<sup data-n=\"2637\">4</sup> כו', וי\"ל למה נק' המועדים שהם מועדי הוי'<sup data-n=\"2639\">6</sup> ע\"ש התבואה חדש האביב וחג הקציר כו', וסוכות הוא חג האסיף<sup data-n=\"2640\">7</sup>, שלכך אם הזמן מגיע לאביב והשעורה אינה אביב עדיין צריך לעבר את השנה כדי שיהי' פסח דוקא בחדש האביב<sup data-n=\"2641\">8</sup>, פי' אביב היינו שהתבואה נגמרת ועומדת מחוברת עדיין<sup data-n=\"2642\">9</sup>, וכמשארז\"ל קישות שהתליע באביה<sup data-n=\"2643\">10</sup> שפירשו<sup data-n=\"2644\">11</sup> במחובר, ולכאו' אין זה מובן מה שייכות הרגלים שנא' בהם שלש רגלים תחוג לי, דהיינו לעצמותו, לתבואת הארץ דוקא, ועוד שלפ\"ז הי' צריך שיהיו הרגלים נוהגין בארץ דוקא שתבואות שייכה להארץ וא\"כ גם הרגלים הי' צריך שיהי' בארץ דוקא, ובאמת הרגלים הם נוהגין בארץ ובחו\"ל<sup data-n=\"2645\">12</sup> אף שאין אז זמן בכורי התבואות אצלינו וגם אין לנו תבואות כו'. אך הענין הוא דהנה מתחלה צ\"ל מה שנקראו המועדים בשם רגלים שמזה משמע שהמועדים שייך לרגל<sup data-n=\"2646\">13</sup>, וזהו שלמדו",[["2634","1","<b>שלש רגלים תחוג לי</b>: מאמר זה (וכן פ\"ד ממאמר הבא) הוא מאמר ד\"ה זה דשנת תרל\"ג שנדפס בסה\"מ תרל\"ג ח\"א ע' קמד ואילך עם שינויים והוספות כו'. ראה גם ד\"ה זה באוה\"ת משפטים ע' א'קעג ואילך.\nממאמר זה ישנם עוד שני הנחות והם: א) הנחת כ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק הנחותיו [ומשם ניתוסף בהכותרת כאן התיבות: ליל ב']. ב) הנחה אחרת נדפסה לקמן (בחלק ההנחות).\nהמאמר נרשם בכת\"י מעתיק היינו א) העתק המאמר דתרל\"ג בכותרת: ”ימים ראשונים דחה\"פ מ\"א\" עם הגהות ותיקונים בגוכתי\"ק. ב) וכן נרשמו עוד הגהות וכו' בכמה ע' בפ\"ע בכותרת: ”לד\"ה שלש רגלים קונט' נייר בפ\"ע\". ג) לאח\"ז נרשם קיצור ארוך עם הוספות מעט בכותרת: ”משפטי' כ\"ג י\"ד ט\"ו ט\"ז\". והוא קיצור לפ\"א-ב [וחלק ממנו נכנס בפנים]. ד) לאח\"ז נרשם המאמר עוה\"פ בכת\"י מעתיק בכותרת: ”חה\"פ מ\"א\" עם איזה תיקונים בגוכתי\"ק.\nלמאמר זה צויין להלן במאמר ד\"ה והנה תורה היא בחי' קו האמצעי על יד הערה 180.\nלהלן צויינו חלק מההוספות. חלוקת הקטעים דלהלן הם ע\"פ סה\"מ תרל\"ג."],["2635","2","<b>שלש רגלים תחוג לי בשנה</b>: משפטים כג, יד."],["2636","3","<b>את חג המצות . . חדש האביב</b>: שם כג, טו. ראה גם להבא בסמוך בענין אביב <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301730177\" data-slug=\"likkutei-sichot\" data-id=\"1301730177\">לקו\"ש משפטים כרך לו ע' 109</a> ואילך ובהנסמן שם."],["2638","5","<b>באספך מן</b>: בסה\"מ תרל\"ג כאן: באספך כו' מן. ואולי תיבת כו' נשמטה כאן בשגגת המעתיק."],["2637","4","<b>וחג הקציר . . מן השדה</b>: משפטים שם, טז [בדילוג]."],["2639","6","<b>למה נק' המועדים . . מועדי הוי'</b>: אמור כג, ב. ד. לז. מד. עזרא ג, ה. ראה גם לקמן מאמר ד\"ה וחג הקציר בכורי מעשיך ובהערה 3."],["2640","7","<b>וסוכות הוא חג האסיף</b>: משפטים שם, טז (וברש\"י שם). תשא לד, כב."],["2641","8","<b>אם הזמן . . בחדש האביב</b>: ראה רמב\"ם הל' קדוש החדש פ\"ד, ה\"ב."],["2642","9","<b>פי' אביב . . מחוברת עדיין</b>: ראה גם ספר החקירה להצ\"צ ע' 182."],["2643","10","<b>קישות שהתליע באביה</b>: חולין נח, סע\"א. סז, סע\"א ואילך."],["2644","11","<b>שפירשו</b>: בסה\"מ תרל\"ג כאן: שפי'. ואולי זהו פיענוחו של המעתיק."],["2645","12","<b>הרגלים הם נוהגין בארץ ובחו\"ל</b>: ראה גם רמב\"ם הל' יו\"ט רפ\"א."],["2646","13","<b>שהמועדים שייך לרגל</b>: ראה [ולהבא בסמוך] אוה\"ת משפטים כאן ע' א'קעד ואילך. וראה גם סה\"מ תרל\"ח ע' תקכא ואילך. ע' תקכה. (ע' תלט)."]]],[2001910285,"רז\"ל במשנה חגיגה פ\"א שקטן<sup data-n=\"2647\">14</sup> שאינו יכול לאחוז בידו של אביו ולעלות מירושלים להר הבית פטור, וכן החיגר<sup data-n=\"2648\">15</sup> כו' לפי שנא' שלש רגלים שמשמע מזה שהמועדים שייכים לרגל כו', וצ\"ל מה שייכות המועדים לרגל דוקא, וגם צ\"ל מהו שלש רגלים שהרי רגליים הם שתים.\n<b>אך</b> הענין הוא, דהנה כתי' כה אמר ה'<sup data-n=\"2649\">16</sup> אם בדרכי תלך כו' ונתתי לך מהלכים<sup data-n=\"2650\">17</sup> בין העומדים האלה שהמלאכים נק' עומדים וכמ\"ש כולם עומדים<sup data-n=\"2651\">18</sup> כו' שרפים עומדים<sup data-n=\"2652\">19</sup> כו', והנה בעמידה יש מעלה וחסרון שהמעלה הוא שאין להם ירידה ועומדים תמיד במדרגה אחת, והחסרון הוא שאין להם ג\"כ עלי' גדולה כו', אך הנה אעפ\"כ ע\"י עמידה שלהם שעומדים תמיד במדרגה אחת באוי\"ר ברשפי אש עי\"ז הם ממשיכים המשכת גילוי אלקות, וכמ\"ש ורגליהם רגל ישרה<sup data-n=\"2653\">20</sup>, ואיתא בתוס' חגיגה די\"ג ע\"א שישרה בגימ' תקט\"ו<sup data-n=\"2654\">21</sup>, וכן ואתחנן הוא בגי' תקט\"ו שתקט\"ו תפלות<sup data-n=\"2655\">22</sup> התפלל משה כמנין ואתחנן.\n<b>ולהבין</b> מהו ענין החשבון של תקט\"ו, הענין הוא דהנה אנו רואים שלמעלה הוא הכל על חשבון ת\"ק שנה כמשארז\"ל מהארץ לרקיע מהלך ת\"ק<sup data-n=\"2656\">23</sup> כו', בין רקיע לרקיע כו', ובמד\"ר בראשית פט\"ו<sup data-n=\"2657\">24</sup> עה\"ח מהלך ת\"ק שנה כו', ולהבין מהו ת\"ק דוקא. אך הענין הוא דהנה כתי' לך ה' הגדולה והגבורה<sup data-n=\"2658\">25</sup> כו' וארז\"ל הגדולה זו קרי\"ס והגבורה זו מכת בכורות והת\"ת זו מ\"ת והנצח זו בנין ירושלים<sup data-n=\"2660\">27</sup> וההוד זו בנין<sup data-n=\"2659\">26</sup> בהמ\"ק<sup data-n=\"2661\">28</sup>, שהם חמשה מדות כו' שהעיקר המדות הם חמשה<sup data-n=\"2662\">29</sup> שהם מקור",[["2647","14","<b>במשנה חגיגה פ\"א שקטן</b>: ב, א."],["2648","15","<b>וכן החיגר</b>: חגיגה ב, א (במשנה). ג, א."],["2649","16","<b>כה אמר ה'</b>: זכרי' ג, ז [ושם: ה' צבאות — וכ\"ה בתו\"א שבהערה הבאה. אבל כ\"ה גם (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 14]."],["2650","17","<b>ונתתי לך מהלכים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370139\" data-slug=\"torah-or\" data-id=\"3901370139\">תו\"א וישב ל, סע\"א</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תרסז. וש\"נ. ש\"א ח, ב ובהערה 42."],["2651","18","<b>כולם עומדים</b>: ברכת יוצר."],["2652","19","<b>שרפים עומדים</b>: ישעי' ו, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380236\" data-slug=\"likkutei-torah\" data-id=\"4001380236\">לקו\"ת אמור לז, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380270\" data-slug=\"likkutei-torah\" data-id=\"4001380270\">בחוקותי מה, א</a>."],["2653","20","<b>ורגליהם רגל ישרה</b>: יחזקאל א, ז."],["2654","21","<b>רגל ישרה . . בתוס' חגיגה . . תקט\"ו</b>: ד\"ה ורגלי. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380222\" data-slug=\"likkutei-torah\" data-id=\"4001380222\">לקו\"ת אמור לד, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159780113\" data-slug=\"or-hatorah-hb\" data-id=\"8159780113\">אוה\"ת</a> חנוכה כרך ה ע' 1828 ואילך [בהעלותך ע' תי ואילך]. משפטים כאן ע' א'קעג. ואתחנן ס\"ע קיג ואילך. ובכרך ו' ע' ב'קצג."],["2655","22","<b>ואתחנן . . תקט\"ו שתקט\"ו תפלות</b>: דב\"ר פי\"א, י. ראה גם אוה\"ת סידור ס\"ע קיג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061116\" data-slug=\"likkutei-sichot\" data-id=\"1300061116\">לקו\"ש בשלח כרך ו ע' 105</a>."],["2656","23","<b>מהארץ לרקיע מהלך ת\"ק</b>: ראה חגיגה יג, א."],["2657","24","<b>ובמד\"ר בראשית פט\"ו</b>: סימן ו. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560131\" data-slug=\"or-hatorah-hb\" data-id=\"8316560131\">אוה\"ת בראשית ע' מז</a>. שם כרך ג ע' תקלב."],["2658","25","<b>לך ה' הגדולה והגבורה</b>: דברי הימים-א כט, יא."],["2660","27","<b>והנצח זו בנין ירושלים</b>: ראה (בנוסף לסה\"מ תרל\"ג כאן) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540078\" data-slug=\"torat-chaim\" data-id=\"2300540078\">תו\"ח בשלח ח\"א רכא, ד</a>. וש\"נ. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 24. (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 29."],["2659","26","<b>הגדולה זו . . בנין בהמ\"ק</b>: ראה ברכות נח, סע\"א."],["2661","28","<b>וההוד זו בנין בהמ\"ק</b>: ראה גירסת העין יעקב לברכות נח, סע\"א. סה\"מ תרל\"ג כאן. תרפ\"ט ע' 118. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן שם."],["2662","29","<b>שהעיקר המדות הם חמשה</b>: ראה זהר פינחס רנד, א. סידור שער הל\"ג בעומר דש, א. מאמרי אדה\"א בראשית ע' רפה. וש\"נ. סה\"מ תרכ\"ז ע' רסב. וש\"נ."]]],[2001910286,"להשתל' העולמות וכמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"2663\">30</sup> (וכתי'<sup data-n=\"2665\">32</sup>* זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"2664\">31</sup> וע' בזח\"ג שמיני דל\"ח ע\"א ובפי' המק\"מ שם, שבחי' רחמים וחסדי' שהם שייכים לעולם, לפי שבתחלה עלה במח'<sup data-n=\"2666\">33</sup> לברוא את העולם במדה\"ד, ולפי' הרמ\"ז קאי על עולם התהו<sup data-n=\"2667\">34</sup>, ראה שאין העולם מתקיים נטל מדת החסד שע\"י בחי' המשכת החסד יתקיים העולם, וכמ\"ש אלה תולדות השמים והארץ בהבראם<sup data-n=\"2668\">35</sup> וארז\"ל א\"ת בהבראם אלא באברהם<sup data-n=\"2669\">36</sup>, שהי' מרכבה<sup data-n=\"2670\">37</sup> למדת החסד<sup data-n=\"2671\">38</sup> שבו נברא\n\n*)וכתי'<sup data-n=\"8487\">א</sup> זכור רחמיך וחסדיך כי מעולם המה. ופי' בזח\"ג שמיני דל\"ח ע\"א מהו כי מעולם המה, כד ברא קוב\"ה עלמא נטל<sup data-n=\"8488\">ב</sup> יצחק וברא בי' עלמא, חמא דלא יכול למקים<sup data-n=\"8489\">ג</sup> בלחודוי, נטל אברהם וקיים בי' עלמא הה\"ד אלה תולדות כו' בהבראם א\"ת בהבראם אלא באברהם, חמא דבעינן קיומא יתיר נטל ליעקב ושתף לי' ביצחק וקיים עלמא כו' וע\"ד<sup data-n=\"8490\">ד</sup> באברהם ויעקב אתקיים עלמא ובגין כך כי מעולם המה, והיינו כמארז\"ל בתחלה עלה במח' לברוא את העולם במדה\"ד ראה שאין העולם מתקיים שיתף עמו מדה\"ר וזהו אברהם ויעקב וכמ\"ש במק\"מ, יצחק ב\"ן, אברהם מ\"ה, יעקב הוא חיבר מ\"ה וב\"ן בכל פרצוף ופרצוף<sup data-n=\"8491\">ה</sup>, כי מעולם המה שע\"י נעשה תיקון העולמות, וכן נצח והוד הם ענפי המדות, נצח ענף החסד הוד ענף הגבורה, והיינו שהם בחי' כליות יועצות<sup data-n=\"8492\">ו</sup> איך להשפיע כו', שנמצא ה' מדות חג\"ת נו\"ה הם מקור להשתלשלות העולמות כו'",[["2663","30","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["2665","32","<b>זכור רחמיך וחסדיך. . המה</b>: תהלים כה, ו [בדילוג השם]. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010262\" data-slug=\"or-hatorah-hb\" data-id=\"8159010262\">אוה\"ת</a> (יהל אור) תהלים ע' צב. ר\"ה ע' א'רפח."],["2664","31","<b>(וכתי' . . לעולם כו')</b>: כל זה הוא הוספה על המאמר דשנת תרל\"ג."],["2666","33","<b>שבתחלה עלה במח'</b>: ראה רש\"י בראשית א, א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תכ. ע' א'תמב ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' לא-לב. וש\"נ. סה\"מ תרכ\"ז ע' תלה. תורת שלום ע' 20."],["2667","34","<b>ולפי' הרמ\"ז . . עולם התהו</b>: אולי הכוונה להרמ\"ז לזהר שם: נטל יצחק בעול' התהו."],["2668","35","<b>אלה תולדות השמים והארץ בהבראם</b>: בראשית ב, ד."],["2669","36","<b>א\"ת בהבראם אלא באברהם</b>: זהר לך פו, ב. ויצא קנד, ב. יתרו עט, א. צו לא, א. שמיני לח, א. ז\"ח (מדרש הנעלם) יז, א. ראה גם ב\"ר פי\"ב, ט."],["2670","37","<b>באברהם שהי' מרכבה</b>: ראה גם לעיל מאמר ד\"ה והי' אור הלבנה ובהערה 46."],["2671","38","<b>באברהם . . החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ.\n\n<b>א</b> ) <b>וכתי'</b>: נרשמה בריש הע' שבו נרשמה ההגה שמופיעה בפנים, ולא נעתקה בכת\"י המעתיק [ראה לעיל הערה 1 — ב. ד] בכותרת: ”לד\"ה שלש רגלים, רג\"ל\" [סה\"מ תרל\"ג] ומציין הדף והשיטה איפה שייך. וכנראה שזהו מהדו\"ק מהבא בפנים.\n\n<b>ב</b> ) <b>נטל</b>: בזהר שם: נטיל.\n\n<b>ג</b> ) <b>יכול למקים</b>: שם: יכיל למיקם.\n\n<b>ד</b> ) <b>דבעינן . . וע\"ד </b> [ ועל דא]<b></b>: שם: דבעיין.\n\n<b>ה</b> ) <b>יצחק . . פרצוף ופרצוף</b>: כל זה הוא ע\"פ ל' המק\"מ המצויין בפנים.\n\n<b>ו</b> ) <b>נצח והוד . . כליות יועצות</b>: ברכות סא, א. ראה זהר אד\"ז האזינו רצו, א. אגה\"ק סט\"ו קכב, ב. ביאורי הזהר שלח צא, ג. אוה\"ת בראשית ח, א ואילך. הנסמן במאמרי אדה\"א קונטרסים ע' רכד."]]],[2001910287,"העולם, וכאשר ראה שנצרך קיום יותר, שיתף עמו מדה\"ר היינו מדתו של יעקב<sup data-n=\"2672\">39</sup>, והיינו ע\"ד שמצינו ברקיע שארז\"ל בזהר פ' לך דע\"ז ע\"א, כד<sup data-n=\"2673\">40</sup> ברא קוב\"ה עלמא עבד שמיא מאש וממיא<sup data-n=\"2674\">41</sup> מתערבין כחדא, והיינו חו\"ג, וכ\"ה במד\"ר בראשית פ\"ד<sup data-n=\"2675\">42</sup> נטל אש ומים ופתכן זה בזה, ולא הוי<sup data-n=\"2676\">43</sup> גלדי, ולבתר אתגלידו<sup data-n=\"2677\">44</sup> וקיימו ברוחא עילאה שהיא מדתו של יעקב, שז\"ע שיתף מדה\"ר למדה\"ד דיצחק<sup data-n=\"2678\">45</sup> שעי\"ז דוקא אתקיים עלמא, והיינו כי חו\"ג הם שני הפכים לגמרי, משא\"כ מדת הרחמי' נותן מקום למדת הגבורה, שאם<sup data-n=\"2679\">46</sup> היות שע\"פ הדין אינו מגיע לו מ\"מ צריכים לרחם עליו ועי\"ז מתקיים העולם, וזהו זכור רחמיך דיעקב וחסדיך דאברהם שכאשר שיתף אותם למדה\"ד דיצחק עי\"ז נתקיים העולם וזהו כי מעולם המה, וכן נצח והוד הם ג\"כ שייך לעולם שהם ענפי המדות נצח הוא ענף החסד<sup data-n=\"2680\">47</sup> והוד ענף הגבורה<sup data-n=\"2681\">48</sup> שההשפעה נשפע ע\"י הענפים דוקא, וכמו שאנו רואים באילן הנה גידול הפירות הוא ע\"י הענפים מהאילן ולא על עצם גוף האילן כו', וכך עיקר ההשפעה הוא ע\"י הענפים דחו\"ג שהם נצח והוד, ונמצא שחמשה מדות אלו שייכים לעולם כו'), ומה שנא' כי כל בשמים ובארץ<sup data-n=\"2682\">49</sup> שהוא בחי' יסוד מדה ששית זהו רק בחי' מדה שמחבר\n\nלהעיר<sup data-n=\"8493\">ז</sup> מענין ישמחו השמים<sup data-n=\"8494\">ח</sup>\nחו\"ג<sup data-n=\"8495\">ט</sup> ת\"ת ונו\"ה עיקר הז\"א, יסוד השפעה שמלבר מגופא הולדה השפעה לזולתו בסידור בד\"ה אתה הצבת<sup data-n=\"8496\">י</sup>, וע' בפע\"ח גבי סוכות<sup data-n=\"8497\">יא</sup>.",[["2672","39","<b>מדה\"ר . . של יעקב</b>: ראה זהר לך פז, ב. מאמרי אדה\"א בראשית ע' קנו. וש\"נ."],["2673","40","<b>כד</b>: בזהר שם: דכד."],["2674","41","<b>וממיא</b>: שם: וממים."],["2675","42","<b>במד\"ר בראשית פ\"ד</b>: ראה שם סימן ז."],["2676","43","<b>ולא הוי</b>: המשך לשון הזהר [ושם: ולא הוו]."],["2677","44","<b>אתגלידו</b>: שם: אגלידו."],["2678","45","<b>מדה\"ד דיצחק</b>: ראה פרדס שער הכינויים שכ\"ב, פ\"ד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם."],["2679","46","<b>שאם</b>: כ\"ה בכ\"מ — ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה תקעו בחדש שופר על יד הערה 33. סה\"מ תרל\"ח ע' ה. וש\"נ."],["2680","47","<b>נצח הוא ענף החסד</b>: ראה זהר רע\"מ פינחס רמג, סע\"א. הנסמן במאמרי אדה\"א קונטרסים ע' רכח."],["2681","48","<b>והוד ענף הגבורה</b>: ראה הערה שלפנ\"ז."],["2682","49","<b>כי כל בשמים ובארץ</b>: המשך הכתוב לך ה' הגדולה — דברי הימים-א כט, יא.\n\n<b>ז</b> ) <b>להעיר</b>: נרשם מלמעל\"ט בצדי הע' [בקונט' נייר. ראה לעיל הערה 1 — ב. ד] ולא נרשם מקומו בפנים, וכן לא הועתק בכת\"י המעתיק.\n\n<b>ח</b> ) <b>ישמחו השמי' י\"ה</b>: תהלים צו, יא. דברי הימים-א טז, לא. ת\"ז בהקדמה ט, ב.\n\n<b>ט</b> ) <b>חו\"ג</b>: נרשם בשולי הע' [בקונט' נייר. ראה לעיל הערה 1 — ב. ד] ולא נרשם מקומו בפנים, וכן לא הועתק בכת\"י המעתיק.\n\n<b>י</b> ) <b>בסידור בד\"ה אתה הצבת</b>: צויין בהערה 50.\n\n<b>יא</b> ) <b>וע' בפע\"ח גבי סוכות</b>: ראה שם קרוב לספ\"א. אוה\"ת משפטים ס\"ע א'קעג."]]],[2001910288,"שמים וארץ<sup data-n=\"2683\">50</sup>, וזשארז\"ל (כמדומה שזהו במד\"ר פ' תרומה פל\"ג<sup data-n=\"2684\">51</sup>) כל מה שיש בשמים יש בארץ, והיינו שבחי' כי כל ממשיך מבחי' שמים בארץ, אבל לא שהיא מדה חדשה רק שהיא מחבר כו', וזהו שבשמים הוא הכל על חשבון ת\"ק והיינו לפי ששם מאיר החמשה מדות וכל א' כלול מיו\"ד ויו\"ד מיו\"ד הוא חשבון ת\"ק, נמצא שבשמים מאיר רק בחי' מדות שהוא בחי' ו\"ה, אך הנה ע\"י עבודת המלאכי' שאומרים קדוש באוי\"ר ברשפי אש עי\"ז ממשיכים בחי' ט\"ו שהוא בחי' י\"ה בבחי' ת\"ק שהיא בחי' מדות, כי המדות הם שייכים רק לעולמות<sup data-n=\"2685\">52</sup> וכמ\"ש כי אמרתי עולם חסד יבנה, שכדי שיהי' עולם צריך לבנות את החסד<sup data-n=\"2686\">53</sup> שעד שלא נבה\"ע אינו שייך בחי' חסד כלל כי על מי יתחסד כו' (וכן<sup data-n=\"2687\">54</sup> כתי' זכור רחמיך וחסדיך כי מעולם המה שרחמים וחסדים שייך לאחר שנברא העולם, אבל קודם שנבה\"ע אינו שייך כלל רחמים וחסדים כי על מי ירחם ויתחסד כו'). משא\"כ בחי' י\"ה שהוא אנת חכים ולא בחכ' ידיעא<sup data-n=\"2688\">55</sup> כו' אינם שייכים לעולמות כלל כי אף גם אם לא נבה\"ע שייך ג\"כ בחי' חכ' כו' (וכענין שארז\"ל אלפים שנה קדמה<sup data-n=\"2690\">57</sup> תורה לעולם שנא' אאלפך<sup data-n=\"2692\">59</sup> חכ' אאלפך בינה<sup data-n=\"2693\">60</sup> שבחי' חו\"ב קדמו למעלת העולם<sup data-n=\"2691\">58</sup> כמ\"ש מזה בכ\"ד<sup data-n=\"2689\">56</sup>). וזהו שהמלאכים ע\"י\n\nמלאכים<sup data-n=\"8498\">יב</sup> שרשם מבינה בה\"ז בלק<sup data-n=\"8499\">יג</sup> דק\"ץ ב' ברכו כו' גבורי כח<sup data-n=\"8500\">יד</sup> בינה עד הוד<sup data-n=\"8501\">טו</sup> ת\"ק י\"ה לפי ששרשן מבינה תו\"א ביאור זכור<sup data-n=\"8502\">טז</sup>.",[["2683","50","<b>יסוד . . שמחבר שמים וארץ</b>: ראה זהר בראשית לא, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540129\" data-slug=\"torat-chaim\" data-id=\"2300540129\">תו\"ח וארא ח\"א נג, ד</a> הערה 39. סידור שער הל\"ג בעומר דש, א ואילך."],["2684","51","<b>במד\"ר פ' תרומה פל\"ג</b>: סימן ד [ושם: כל מה שברא הקב\"ה למעלן ברא למטן — ראה גם המשך מים רבים תרל\"ו ס\"פ קנה]. ראה פי' מהרז\"ו שם."],["2685","52","<b>המדות הם שייכים רק לעולמות</b>: ראה גם אוצרות חיים בתחלתו. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380696\" data-slug=\"likkutei-torah\" data-id=\"4001380696\">לקו\"ת מסעי צג, רע\"א</a>. סה\"מ תרל\"ח ס\"ע שצ. וש\"נ. תר\"ם ח\"א ע' קפה. וש\"נ."],["2686","53","<b>כי אמרתי . . לבנות את החסד</b>: ראה גם לעיל מאמר ד\"ה הוא אהרן ומשה ובהערה 106."],["2687","54","<b>(וכן . . כו')</b>: כל זה הוא הוספה על המאמר דשנת תרל\"ג."],["2688","55","<b>אנת חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה יז, ב."],["2690","57","<b>אלפים שנה קדמה תורה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ. מאמר ד\"ה זה תשי\"א יום ב' דחה\"ש."],["2692","59","<b>לעולם שנא' אאלפך</b>: כ\"ה גם במאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ע' סח. סה\"מ תרל\"ג ח\"ב ס\"ע שמח ואילך."],["2693","60","<b>אאלפך חכ' אאלפך בינה</b>: ע\"פ איוב לג, ג. שבת קד, א."],["2691","58","<b>קדמה . . למעלת העולם</b>: ראה גם סה\"מ תרל\"ח ע' טז. וש\"נ. תר\"ם ח\"א ע' קפ. וש\"נ."],["2689","56","<b>(וכענין . . בכ\"ד)</b>: כל זה הוא הוספה על המאמר דשנת תרל\"ג.\n\n<b>יב</b> ) <b>מלאכים</b>: נרשם בשולי הע' [בקונט' נייר. ראה לעיל הערה 1 — ב. ד] ולא נרשם מקומו בפנים, וכן לא הועתק בכת\"י המעתיק .\n\n<b>יג</b> ) <b>בה\"ז בלק</b>: צח ג ואילך. ראה גם לקמן פ\"ג.\n\n<b>יד</b> ) <b>ברכו כו' גבורי כח</b>: תהלים קג, כ.\n\n<b>טו</b> ) <b>בינה עד הוד</b>: נסמן לקמן בפ\"ג הערה 131.\n\n<b>טז</b> ) <b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370321\" data-slug=\"torah-or\" data-id=\"3901370321\">תו\"א</a> ביאור זכור</b>: ראה יתרו עב, ב. ראה גם אוה\"ת משפטים ע' א'קעד."]]],[2001910289,"עבודתם ממשיכים מבחי' י\"ה בו\"ה שהיא בחי' מדות, והיינו שממשיכים שיהי' השם שלם כו', כי פעם כתיב כי יד על כס י\"ה<sup data-n=\"2694\">61</sup> אין השם שלם<sup data-n=\"2695\">62</sup> שאינו מאיר בחי' י\"ה בו\"ה<sup data-n=\"2696\">63</sup>, אך המלאכים ממשיכים בחי' י\"ה בו\"ה שיהי' השם שלם*, וזהו ורגליהם רגל ישרה תקט\"ו שממשיכים בחי' י\"ה בו\"ה** שהוא בחי' מדות כו'.\n<b>אך</b> הנה בנשמות כתי' ונתתי לך מהלכים בין העומדים האלה, דהיינו שלנש\"י יש ב' המעלות דהיינו שהם בחי' עומדים גם בהתלבשות הנפש בגוף וגם מהלכים וכמ\"ש רגלי עמדה במישור (תהילים ססי' ך\"ו<sup data-n=\"2697\">64</sup>), פי' מישור היינו כמו במלאכים רגל ישרה, ועמידת הרגל בנש\"י המלובשי' בגוף היינו שתעמוד במישור שיהיו עומדים תמיד על מדרגתם שלא יפלו ח\"ו וכמ\"ש (דניאל א' ד') ואשר כח בהם לעמוד בהיכל המלך, שהיא מעלה ומדרגה גבוה, וזהו שארז\"ל באשה קראו מושב<sup data-n=\"2698\">65</sup>, אבל עמידה היא בבחי' עלמא דדכורא, כמ\"ש בזח\"ב תצוה דקפ\"ג ע\"א לקיימא על רגלוהי<sup data-n=\"2699\">66</sup> ירכין וגופא כחדא תמן, ירכין וגופא לקיימא כדכורא דקיימא בחיליה ולא כנוקבא\n\nוכן<sup data-n=\"8503\">יז</sup> בע\"ח שהוא מהלך ת\"ק שנה<sup data-n=\"8504\">יח</sup> שיומשך בו מבחי' י\"ה היינו מבחי' ועל יובל ישלח שרשיו<sup data-n=\"8505\">יט</sup> בחי' בינה<sup data-n=\"8506\">כ</sup> מה שמו דההוא נהר יובל שמו<sup data-n=\"8507\">כא</sup> כו'\n*)(וצ\"ל<sup data-n=\"8508\">כב</sup> שזהו מיחוד חיצוני דחו\"ב כמשי\"ת<sup data-n=\"8509\">כג</sup>).\n**)(וי\"ל<sup data-n=\"8510\">כד</sup> רגל ישרה שלהיות שזהו ע\"י העמידה שזהו ברגל)\n*)ענין<sup data-n=\"8511\">כה</sup> הכפיפה שכאשר נמשך אחר דברי' הגשמיים ה\"ה כופה ומשתחוה ראשו כמ\"ש בלק\"ת בד\"ה האזינו פ\"ה<sup data-n=\"8512\">כו</sup>, ונופל י\"ל שגרוע יותר שהרי הכפוף הוא עומד על מדריגתו רק שנכפף משא\"כ הנופל כמ\"ש בסידור ע\"פ זה<sup data-n=\"8513\">כז</sup>, ועד\"ז יובן בלעו\"ז דהיינו ביצה\"ר שי\"ל ז\"ע תאוות היתר ותאוות איסור ח\"ו.",[["2694","61","<b>כי יד על כס י\"ה</b>: בשלח יז, טז."],["2695","62","<b>אין השם שלם</b>: ראה תנחומא ס\"פ תצא. רש\"י ולקח טוב ס\"פ בשלח. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231268\" data-slug=\"likkutei-sichot\" data-id=\"1300231268\">לקו\"ש</a> י\"ג סיון כרך כג ע' 268 הערה 33."],["2696","63","<b>שאינו מאיר בחי' י\"ה בו\"ה</b>: ראה גם לעיל מאמר ד\"ה מגילה נקראת הערה 186."],["2697","64","<b>ך\"ו</b>: בסה\"מ תרל\"ג כאן: ק\"ו. וצ\"ל כבפנים."],["2698","65","<b>באשה קראו מושב</b>: פסחים ג, א. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159780114\" data-slug=\"or-hatorah-hb\" data-id=\"8159780114\">אוה\"ת ואתחנן ע' קיד</a>. כרך ו ע' ב'קצג. משלי כרך א ס\"ע תקסז ואילך."],["2699","66","<b>רגלוהי</b>: בזהר ו<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480169\" data-slug=\"or-hatorah-hb\" data-id=\"8316480169\">אוה\"ת חנוכה כרך ה ע' תתקטז</a>־ <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830008\" data-slug=\"or-hatorah-hb\" data-id=\"8158830008\">בהעלותך ע' תיב</a>־ ואתחנן שם: רגלוי.\n\n<b>יז</b> ) <b>וכן</b>: בהעתק הראשון מהמאמר בע' זה נרשמו שני הגהות משני צדדיו, אבל המעתיק לא העתיקם בהעתק השני [ראה לעיל הערה 1 — א. ד] והגה אחת הוסיפה כ\"ק אדמו\"ר מהר\"ש על העתק השני (ונדפסה בפנים). אמנם הגה זו לא העתיק.\n\n<b>יח</b> ) <b>בע\"ח . . שנה</b>: נסמן לעיל הערה 24.\n\n<b>יט</b> ) <b>ועל יובל ישלח שרשיו</b>: ירמי' יז, ח. ראה אוה\"ת ירמי' כרך א ע' שמה.\n\n<b>כ</b> ) <b>יובל . . בינה</b>: ראה זהר רע\"מ בהר קח, ב. שיעור קומה להרמ\"ק מערכת דברות סי\"ב (ט, ב). מאו\"א מערכת דרור סי\"ג וביאיר נתיב שם. מערכת יובל סל\"ח וביאיר נתיב שם. אוה\"ת שם.\n\n<b>כא</b> ) <b>מה שמו . . יובל שמו</b>: ראה זהר יתרו פג, א. אחרי נח, א. וראה גם בכורות נה, ב. ויק\"ר ספכ\"ב.\n\n<b>כב</b> ) <b>וצ\"ל</b>: נרשם בקיצור ארוך עם הוספות מעט [ראה לעיל הערה 1 — ג].\n\n<b>כג</b> ) <b>כמשי\"ת</b>: ראה לקמן פ\"ג.\n\n<b>כד</b> ) <b>וי\"ל</b>: ראה לעיל הערה כב.\n\n<b>כה</b> ) <b>ענין</b>: ראה לעיל הערה כב.\n\n<b>כו</b> ) <b>בלק\"ת בד\"ה האזינו פ\"ה</b>: כ\"ה בגוכתי\"ק. ראה גם שם יו\"כ סח, ב. הנסמן בהערה 67.\n\n<b>כז</b> ) <b>בסידור ע\"פ זה</b>: שחרית נד, א ואילך."]]],[2001910290,"דארחהא למיתב, והיינו שהעמידה הוא שלא יהי' במדרגת נופלי' וכפופים* וכמ\"ש סומך ה' לכל הנופלים<sup data-n=\"2700\">67</sup> שנפלו ממדרגתם, משא\"כ עומדים הוא שעומדים תמיד על מדרגתם בלי נטי' ח\"ו לימין ושמאל וזהו רגלי עמדה במישור כו', וע' בלק\"ת פ' נשא<sup data-n=\"2701\">68</sup> בד\"ה נשא את ראש בני גרשון דרוש הראשון ססעי' ב' שענין העמידה הוא ביטול הרצון של הרצונות שבעניני עוה\"ז ולהיות בבחי' משלחי רגל השור והחמור<sup data-n=\"2702\">69</sup>, דהיינו למנוע את ההילוך של היצה\"ר, שיש בו ג\"כ הילוך ע\"ד מ\"ש (בש\"ב י\"ב ד') ויבא הלך לאיש העשיר כו' שהוא ההילוך שבלעו\"ז<sup data-n=\"2703\">70</sup> שהולך ומתחזק וכמו שפי' רש\"י שם שמתחלה מדמה את יצה\"ר להלך שעובר לדרכו ואח\"כ לאורח שנעשה אכסנאי ואח\"כ לאיש שהוא בעל הבית, ולכן מה שמונע א\"ע מהילוך זה זהו נק' עמידה בחי' ביטול רצון דיצה\"ר, וכמארז\"ל ישב ולא עבר עבירה נותנים לו שכר כעושה מצוה, ומוקמי לה בגמ' קדושין פ\"ק דל\"ט ע\"ב כגון שבא דבר עבירה לידו וניצול הימנה שזהו כענין העמידה שעומד בכח לכבוש את תאוות היצה\"ר לבלי יניח לו להתפשט בבחי' הילוך שלו ח\"ו, וע' שם בלק\"ת שזהו בחי' קרשים, שארז\"ל במד\"ר ר\"פ תרומה למעלן שרפים עומדים ולמטן עצי שטים עומדים שזהו בחי' קרשי המשכן, שבחי' זו נק' בעבודה בחי' עומדים, וע\"י העמידה עי\"ז ממשיכים ג\"כ מבחי' י\"ה בו\"ה, וזהו שאנו אומרים הללויה<sup data-n=\"2704\">71</sup> היינו שאנו ממשיכים את בחי' י\"ה כו', וז\"ע ט\"ו שבחים שבישתבח<sup data-n=\"2706\">73</sup> שהוא כנגד ט\"ו תיבות שבפסוק את ה' האמרת",[["2700","67","<b>סומך ה' לכל הנופלים</b>: תהלים קמה, יד. ראה סידור שבהערה כז. שחרית לשבת קצד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380878\" data-slug=\"likkutei-torah\" data-id=\"4001380878\">לקו\"ת תצא מ, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380974\" data-slug=\"likkutei-torah\" data-id=\"4001380974\">ר\"ה סג, ד</a>. מאמרי אדה\"ז תקס\"ד ע' רי. דרך חיים מו, א-ד. פיה\"מ נח, א ואילך."],["2701","68","<b>בלק\"ת פ' נשא</b>: כ, ג."],["2702","69","<b>משלחי רגל השור והחמור</b>: ישעי' לב, כ. ראה גם אוה\"ת בהעלותך ע' תיד־ חנוכה שם ע' תתקיז."],["2703","70","<b>שבלעו\"ז</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["2704","71","<b>שאנו אומרים הללויה</b>: ראה זהר ויחי רלב, ב. סידור שחרית נו, ב ואילך ובהנסמן לשם. מאמרי אדה\"א שמות ח\"א ע' יב. וש\"נ. אוה\"ת (יהל אור) תהלים ע' תקנז ואילך וע' תרצג."],["2706","73","<b>ט\"ו שבחים שבישתבח</b>: ראה אבודרהם ברכת ישתבח. מג\"א לשו\"ע או\"ח רסנ\"ג. הגהות כ\"ק אדמו\"ר מהורש\"ב בסוף סידור תו\"א רמג, ג. שער הכולל פ\"ו רנז, ב ואילך.\nבהגהות שבסוף סידור תו\"א שם מביא: ”ובס' אוה\"י למהר\"פ . . עמוד העבודה פ\"ז\". יש להעיר א) ראה אודות ס' אוה\"י [ אור הישר] בהקדמה שם. שם הגדולים להחיד\"א חלק הספרים מערכת אור צדיקים [ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221347\" data-slug=\"likkutei-sichot\" data-id=\"1300221347\">לקו\"ש</a> ל\"ג בעומר כרך כב ריש ע' 331].\nב) עמוד העבודה פ\"ז נדפס גם באור צדיקים למהר\"פ עמוד העבודה פ\"ט.\nג) באור צדיקים בתיקון תפלה אות כז כותב: הט\"ו שבחות . . עד ברכות והודאות ועד בכלל. ואילו בסט\"ז דינים מב\"ש עד ישתבח סי\"א כותב: צ\"ל י\"ג שבחים שבישתבח בנשימה אחת . . י\"ג מדות של רחמים."]]],[2001910291,"היום<sup data-n=\"2707\">74</sup>, וכן ט\"ו ווי\"ן<sup data-n=\"2705\">72</sup> שבאמת ויציב<sup data-n=\"2708\">75</sup> שהוא הכל המשכת בחי' י\"ה בו\"ה, שזהו ע\"י שהם בחי' עומדים וכמו המלאכים כו'.\nב) <b>אך</b> בנשמות יש עוד מעלה שהם נק' מהלכים וכמ\"ש אם בחקתי תלכו<sup data-n=\"2709\">76</sup>, וכן באברהם כתי' התהלך לפני<sup data-n=\"2710\">77</sup>, והיינו כי הילוך הוא בחי' התבוננות מעצמות אוא\"ס שהוא בחי' בכל מאדך בלי גבול<sup data-n=\"2711\">78</sup>, כי בכל לבבך ובכל נפשך<sup data-n=\"2712\">79</sup> הוא בחי' לפי שכלו יהולל איש<sup data-n=\"2713\">80</sup>, דהיינו השגה שע\"פ שכל וטו\"ד שהתבוננות זו היא רק מבחי' ממכ\"ע, משא\"כ בכל מאדך הוא בחי' התבוננות מעצמות אוא\"ס איך שהוא למעלה עד אין קץ<sup data-n=\"2714\">81</sup> ולמטה עד אין תכלית וכולא קמי' כלא<sup data-n=\"2715\">82</sup> ולגדולתו אין חקר<sup data-n=\"2716\">83</sup> כו' שזהו בחי' תשובה שהוא בחילא יתיר<sup data-n=\"2717\">84</sup>, וזהו ענין רגל השלישי שהוא בחי' בריח התיכון המבריח מן הקצה<sup data-n=\"2718\">85</sup> כו', כי במלאכים אין להם רק שתי רגלים וע\"כ הם עומדים תמיד במדרגה אחת וכמ\"ש ויעמידם לעד לעולם, אך בנש\"י שיש להם שלשה רגלים עי\"ז הם נעשים מהלכים בעילוי אחר עילוי עד אין שיעור.\n<b>והנה</b> ע\"י הילוך שמלמטה למעלה עי\"ז נעשה מלמעלה ג\"כ בחי' הילוך וכמ\"ש והתהלכתי בתוככם<sup data-n=\"2719\">86</sup>, היינו שנמשך גילוי תוס' אורות מלמעלה מהשתלשלות ועי\"ז נעשה למטה ג\"כ בחי' גילוי, כי ע\"פ השתלשלות נעשה למטה בחי' העלם והסתר, פי' השתלשלות<sup data-n=\"2720\">87</sup> הוא מה שנמשך בבחי' עו\"ע<sup data-n=\"2721\">88</sup> ולכן ע\"פ השתלשלו' כל מה שנמשך למטה יותר מתמעט האור יותר, שהרי העלול אינו מלביש רק בחי' מחצה התחתון של העילה שהוא מן החזה ולמטה<sup data-n=\"2722\">89</sup>, וא\"כ משכל למדות וממדות לדבור עד\"מ מתמעט כל מה שלמטה במיעוט אחר מיעוט עד שנעשה למטה העלם והסתר,",[["2707","74","<b>את ה' האמרת היום</b>: תבוא כו, יז."],["2705","72","<b>ט\"ו . . שבישתבח . . האמרת . . ווי\"ן</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450596\" data-slug=\"or-hatorah-hb\" data-id=\"8316450596\">אוה\"ת תבוא ע' תתרסו</a> בשם הבחיי תרומה כה, ז. נדפס גם באוה\"ת על סידור ס\"ע קט ואילך. שם ס\"ע קי ואילך. סה\"מ תרנ\"ח ס\"ע ריד ואילך."],["2708","75","<b>ט\"ו ווי\"ן שבאמת ויציב</b>: ראה פע\"ח שער הק\"ש ש\"ח, פכ\"ח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680334\" data-slug=\"torat-chaim\" data-id=\"2300680334\">תו\"ח וישב רי, א</a> הערה 14."],["2709","76","<b>אם בחקתי תלכו</b>: בחוקותי כו, ג. ראה גם לקו\"ת שלח לה, ד. לט, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380270\" data-slug=\"likkutei-torah\" data-id=\"4001380270\">בחוקותי מה, א</a>. מז, ב."],["2710","77","<b>התהלך לפני</b>: לך יז, א."],["2711","78","<b>בכל מאדך בלי גבול</b>: ואתחנן ו, ה. ראה גם אגה\"ק סי\"ז. סה\"מ תר\"ם ח\"א ע' תכט. וש\"נ."],["2712","79","<b>בבל לבבך ובבל נפשך</b>: ואתחנן שם."],["2713","80","<b>לפי שכלו יהולל איש</b>: משלי יב, ח."],["2714","81","<b>אוא\"ס . . למעלה עד אין קץ</b>: ראה ז\"ח יתרו לד, ג. ת\"ז תי\"ט (מ, ב). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670361\" data-slug=\"torat-chaim\" data-id=\"2300670361\">תו\"ח נח סט, ב</a> ובהערה 11."],["2715","82","<b>וכולא קמי' כלא</b>: ראה גם לעיל מאמר ד\"ה להבין וכו' זאת תהי' תורת המצורע הערה 47."],["2716","83","<b>ולגדולתו אין חקר</b>: תהלים קמה, ג."],["2717","84","<b>תשובה שהוא בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540123\" data-slug=\"torat-chaim\" data-id=\"2300540123\">תו\"ח שמות ח\"א לז, א</a>. וש\"נ. פלח הרמון אחרי ע' קפח ואילך."],["2718","85","<b>בריח התיכון . . הקצה</b>: ע\"פ תרומה כו, כח. ויקהל לו, לג."],["2719","86","<b>והתהלכתי בתוככם</b>: בחוקותי כו, יב."],["2720","87","<b>פי' השתלשלות . . שלא בהדרגה כו'</b>: הוספה על סה\"מ תרל\"ג כאן ע' קמז (ששם נמצא כאן 5 שורות)."],["2721","88","<b>עו\"ע</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a>: הנזכר בספרים. שה\"ש א, ב: כמ\"ש בספרים. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."],["2722","89","<b>העלול אינו מלביש . . ולמטה</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ס\"ע תקנח. פיה\"מ ל, א ואילך. סה\"מ תרל\"ב ח\"א ס\"ע קו. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 92 ואילך."]]],[2001910292,"וז\"ע ויעמידם כו' חק נתן<sup data-n=\"2723\">90</sup> כמה יהי' הגילוי בסדר השתלשלו' ולא יעבור שיומשך יותר מהחק שע\"פ סדר השתלשלו', וז\"ע עמידה שעומדים במדריגה אחת, והיינו שגם מה שממשיכים תוס' אור ע\"י העבודה מבחי' י\"ה כנ\"ל ג\"כ בכלל עמידה יחשב שהרי המשכה זו היא מהחכמה שהחכ' היא בחי' ראשית מסדר ההשתלשלו'<sup data-n=\"2724\">91</sup>, ולפ\"ז צ\"ל פי' ויעמידם שהעמיד המלאכים<sup data-n=\"2725\">92</sup> שע\"י עבודתם באהוי\"ר ואמירת קדוש ימשיכו תוס' אור במדות שרש העולם היינו מבחי' ט\"ו י\"ה ועכ\"ז גם ע\"ז חק נתן בסדר השתלשלו' ולא יעבור חוק זה כו', ומאחר שנמשך ע\"פ סדר השתלשלו' הרי למטה הוא העלם והסתר כנ\"ל שבסדר השתלשלות מתמעט למטה מטה כו', משא\"כ ע\"י הילוך שנמשך מלמעלה מסדר השתל' היינו שלא ע\"י בחי' עילה ועלול כ\"א בבחי' דילוג נמשך שיהי' למטה ג\"כ גילוי אלקות כמו למעלה. וזהו שביצ\"מ נא' קול דודי הנה זה בא מדלג<sup data-n=\"2726\">93</sup> שהי' הגילוי מלמעלה מסדר השתלשלות, וכמשארז\"ל עד שנגלה עליהם ממה\"מ<sup data-n=\"2727\">94</sup> הקב\"ה שהי' הגילוי מבחי' שלמעלה מהשתלשלות היינו מלמעלה מהחכ', כי מלכי' זו\"נ מלכי חו\"ב מלך מלכי היינו בחי' הכתר<sup data-n=\"2728\">95</sup> ולכן הי' הגילוי למטה כמו למעלה, ודילוג הוא ע\"י הרגלים כנודע מענין דילוג ברגל אחת<sup data-n=\"2729\">96</sup> שז\"ע בחי' ההילוך שנמשך מלמעלה, שהוא בחי' הדילוג שלא בהדרגה כו'.\n<b>וזהו</b> מ\"ש (תלים ס\"ו וא\"ו) בנהר יעברו ברגל, נהר הוא בחי' נהר היוצא<sup data-n=\"2731\">98</sup> מעדן<sup data-n=\"2730\">97</sup> להשקות את הגן ומשם יפרד והי' לד' ראשים, שמבחי' נהר נמשך אח\"כ ומשם יפרד כו' בחי' עלמא דפרודא<sup data-n=\"2732\">99</sup>, והיינו לפי שהמשכה זו של בחי' נהר נמשך בכל עולם לפי ערכו, ולכך למטה נעשה העלם והסתר גמור ומשם יפרד כו', אך בנהר יעברו ברגל, והיינו שע\"י הרגל השלישי ממשיכים למעלה מבחי' הנהר וכמ\"ש בעבר הנהר ישבו אבותיכם<sup data-n=\"2733\">100</sup>*, עד יעבור עמך הוי'<sup data-n=\"2734\">101</sup> למעלה מש' הוי', והיינו שנמשך המשכה\n\nחג\"ת<sup data-n=\"8514\">כח</sup> דא\"א וכענין או\"א הלבישו לזרועות דא\"א<sup data-n=\"8515\">כט</sup> שעי\"ז הי' יצי\"מ כמ\"ש בסידור ד\"ה עבדי' היינו<sup data-n=\"8516\">ל</sup> בענין ויוציאנו ה' אלקינו ע\"ש)",[["2723","90","<b>ויעמידם כו' חק נתן</b>: תהלים קמח, ו."],["2724","91","<b>שהחכ' . . ראשית . . ההשתלשלו'</b>: ראה רמ\"ז לזהר ואתחנן רסה, ב — בדפי הספר קצד, א [ד\"ה לארקא] וסע\"ב. סה\"מ תר\"ם ח\"א ע' רי. וש\"נ."],["2725","92","<b>ויעמידם שהעמיד המלאכים</b>: ראה גם סה\"מ תר\"ם ח\"א ע' לב. וש\"נ."],["2726","93","<b>קול דודי . . מדלג</b>: שה\"ש ב, ח. ראה רש\"י שם."],["2727","94","<b>עד שנגלה עליהם ממה\"מ</b>: נוסח ההגדה."],["2728","95","<b>מלכי' . . הכתר</b>: ראה גם לעיל מאמר ד\"ה והי' אור הלבנה ובהערה 29."],["2729","96","<b>דילוג ברגל אחת</b>: אהלות פ\"ח, מ\"ה ובפיה\"מ ורע\"ב שם. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381190\" data-slug=\"likkutei-torah\" data-id=\"4001381190\">לקו\"ת שה\"ש טו, ב</a>."],["2731","98","<b>נהר היוצא מעדן</b>: ע\"פ בראשית ב, י."],["2730","97","<b>בנהר יעברו . . היוצא מעדן</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381080\" data-slug=\"likkutei-torah\" data-id=\"4001381080\">לקו\"ת שמע\"צ פח, ד</a>. צו יא, ד. טו, ד."],["2732","99","<b>עלמא דפרודא</b>: ראה זהר בראשית כב, א."],["2733","100","<b>בעבר הנהר ישבו אבותיכם</b>: יהושע כד, ב. ראה גם לעיל מאמר ד\"ה זכור את יום השבת ובהערה 69."],["2734","101","<b>עד יעבור עמך הוי'</b>: בשלח טו, טז. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370059\" data-slug=\"torah-or\" data-id=\"3901370059\">תו\"א לך יג, ד</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370290\" data-slug=\"torah-or\" data-id=\"3901370290\">בשלח סה, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380048\" data-slug=\"likkutei-torah\" data-id=\"4001380048\">לקו\"ת בשלח ב, ג</a>. ש\"א כ, ב ובהערה 31. סה\"מ תר\"ם ח\"א ע' רמו. וש\"נ.\n\n<b>כח</b> ) <b>(חג\"ת</b>: נרשם כאן בפנים [בקיצור ארוך. ראה לעיל הערה 1 — ג. ד]. ולא הועתק בכת\"י המעתיק.\n\n<b>כט</b> ) <b>או\"א הלבישו לזרועות דא\"א</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שנד.\n\n<b>ל</b> ) <b>בסידור ד\"ה עבדי' היינו</b>: סדר הגדה רצה, ג ואילך."]]],[2001910293,"מבחי' ש' הוי' דלעילא וכמ\"ש ויקרא הוי' הוי'<sup data-n=\"2735\">102</sup>, ועי\"ז נמשך המשכה זו למטה ג\"כ שיהי' ג\"כ בבחי' גילוי כמו למעלה ממש והיינו שיהי' בחי' וכל קומה לפניך תשתחוה<sup data-n=\"2736\">103</sup>, שיהי' למטה ג\"כ בחי' השתחוואה כמו למעלה שנא' וצבא השמים לך משתחוים<sup data-n=\"2737\">104</sup>, שזהו ע\"י בחי' ואתה מחי' את כולם<sup data-n=\"2739\">106</sup>, כן ע\"י בחי' כי עין בעין יראו<sup data-n=\"2740\">107</sup> יהי' בחי' וכל קומה לפניך תשתחוה<sup data-n=\"2738\">105</sup>, וזהו שנא' שם נשמחה בו<sup data-n=\"2741\">108</sup> דהיינו בעצמותו ומהותו ממש. וזהו שלש רגלים תחוג לי שע\"י שלש רגלים נמשך מבחי' לי עצמותו ומהותו ממש כו'. אך מתחלה צריך שיהי' בחי' עומדי' שהוא בחי' בכל לבבך ובכל נפשך דהיינו התבוננות מבחי' ממכ\"ע, ואז אח\"כ נעשה בחי' מהלכים, וזהו מהלכים בין העומדים שע\"י שהוא בבחי' עומדים שלא יפול למטה אז נעשה מהלכים כו'.\nג) <b>(ושרש</b> בחי'<sup data-n=\"2742\">109</sup> ההפרש בין מלאכים לנש\"י הוא כמ\"ש במ\"א שיש שני מיני זיווגים באו\"א<sup data-n=\"2743\">110</sup>, זיווג חיצונית<sup data-n=\"2744\">111</sup> הוא מה שזיווגייהו תדיר<sup data-n=\"2745\">112</sup> שהוא מה שחו\"ב הם תרדל\"מ<sup data-n=\"2746\">113</sup> שזהו לצורך קיום העולמות שיומשך תמיד מאין ליש, שהחכ' נק' אין<sup data-n=\"2747\">114</sup> כמ\"ש והחכ' מאין תמצא<sup data-n=\"2748\">115</sup>, והבינה נק' יש<sup data-n=\"2749\">116</sup> כמ\"ש להנחיל אוהבי יש<sup data-n=\"2750\">117</sup>",[["2735","102","<b>ויקרא הוי' הוי'</b>: תשא לד, ו. ראה גם לעיל מאמר ד\"ה מגילה נקראת ובהערה 232."],["2736","103","<b>וכל קומה לפניך תשתחוה</b>: תפלת (שחרית לשויו\"ט) נשמת."],["2737","104","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."],["2739","106","<b>ואתה מחי' את כולם</b>: התחלת הכתוב וצבא השמים — נחמי' ט, ו."],["2740","107","<b>כי עין בעין יראו</b>: ישעי' נב, ח. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380811\" data-slug=\"likkutei-torah\" data-id=\"4001380811\">לקו\"ת פ' ראה כג, ד</a>."],["2738","105","<b>שזהו ע\"י . . לפניך תשתחוה</b>: כל זה הוא הוספה על המאמר דשנת תרל\"ג."],["2741","108","<b>שם נשמחה בו</b>: סיום הכתוב בנהר יעברו — תהלים סו, ו."],["2742","109","<b>(ושרש בחי' . . חו\"ב כו')</b>: כל זה הוא הוספה על המאמר דשנת תרל\"ג."],["2743","110","<b>שני מיני זיווגים באו\"א</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370322\" data-slug=\"torah-or\" data-id=\"3901370322\">תו\"א יתרו עב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380907\" data-slug=\"likkutei-torah\" data-id=\"4001380907\">לקו\"ת נצבים מז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381219\" data-slug=\"likkutei-torah\" data-id=\"4001381219\">שה\"ש כב, ג</a>. ביאוה\"ז פינחס קטו, ב ואילך."],["2744","111","<b>זיווג חיצונית</b>: בלקו\"ת נצבים שם מציין: בע\"ח שער הנסירה רפ\"ב ובפע\"ח שער הק\"ש פ\"ה. ובלקו\"ת שה\"ש שם מציין: בסידור האריז\"ל בכוונת ק\"ש והוא בפע\"ח שער הק\"ש פ\"ו [אוצ\"ל: פ\"ה] ופי\"א . . וכ\"ה בע\"ח שער הזיווגים פ\"א ובשער הנסירה רפ\"ב. ראה גם ע\"ח שער טנת\"א ש\"ה, ספ\"ג. שער מוחין דצלם שכ\"ג, פ\"ו. רמ\"ז לזהר בשלח נד, א."],["2745","112","<b>שזיווגייהו תדיר</b>: ראה זהר אד\"ז האזינו רצ, ב. ע\"ח שער הכללים פי\"ג. סה\"מ תרל\"ח ע' פח. וש\"נ."],["2746","113","<b>שחו\"ב הם תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, ב</a> ובהערה 8."],["2747","114","<b>שהחכ' נק' אין</b>: ראה בסמוך הערה 116."],["2748","115","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["2749","116","<b>והבינה נק' יש</b>: ראה הנסמן בביאוה\"ז להצ\"צ כרך ב ע' תתרא. מאמרי אדה\"א בראשית ע' ב. דרושי חתונה ח\"ב ע' תעג. סה\"מ תרכ\"ט ע' רעח."],["2750","117","<b>להנחיל אוהבי יש</b>: משלי ח, כא."]]],[2001910294,"(ולכאו' צ\"ל מהו הראי' שהחכ' נק' אין הלא כתי' מאין תמצא אבל החכ' עצמו<sup data-n=\"2751\">118</sup> י\"ל שאינה אין, אך זהו מפני שאומר תמצא, לשון מציאה אינו שייך כ\"א שהיא היא הדבר עצמה שנאבד שאל\"כ אינה מציאה ואינו חייב להחזיר, וכשאומר והחכ' מאין תמצא שלשון מציאה היא על החכ' א\"כ מוכרח לומר שהחכ' היא ג\"כ אין כמו האין דכתר שממציא אותה כמ\"ש מזה בד\"ה וככה באריכות<sup data-n=\"2752\">119</sup>, ואכמל\"ב), והמשכה זו באה מחכמה עצמה היינו מבחי' הארת א\"ס מה שמלובש בחכמה<sup data-n=\"2753\">120</sup>, שיש בכח הארה זו להחיות כל העולמות וזהו הנמשך ע\"י מלאכי' (והיינו שמתחילת הבריאה נמשך זה מצד כי חפץ חסד<sup data-n=\"2754\">121</sup> הוא<sup data-n=\"2755\">122</sup>, ואח\"כ באתעדל\"ת תליא מילתא<sup data-n=\"2756\">123</sup> וזהו עבודת המלאכים ונשמות קודם התלבשותם בגוף להמשיך ע\"י עבודתם באהוי\"ר שיומשך מחו\"ב שרש בחי' אין ויש לבחי' המדות דז\"א, ולכן נק' בשם עומדים שעומדים תמיד על בחי' מדריגה א' היינו שיש בזה מעלה שאינם יורדי' ממדריגתם, כמו הנשמה המלובשת בגוף שיורדת להתלבש בגוף ונה\"ב שזהו ירידה עצומה כנודע ומובן, מ\"מ אין להם עליה גדולה ג\"כ שהרי ממשיכים רק מזיווג חיצוני דחו\"ב שרש אין ויש להחיות העולמות כו'). אך הנה בחי' זיווג פנימי דחו\"ב<sup data-n=\"2757\">124</sup> שהוא להמשיך בחי' אור חדש ממש, שרשו נמשך מא\"א ועת\"י עד א\"ס<sup data-n=\"2758\">125</sup> ממש ונק' יחוד פנימי דאו\"א לחדש הנשמות, היינו שיומשכו בחי' נשמות חדשות, והוא הנמשך ע\"י נשמות הצדיקים<sup data-n=\"2759\">126</sup> דוקא, מפני ששרשם מבחי' חכמה<sup data-n=\"2760\">127</sup> שלמעלה מהבינה (שמהבינה הוא שרש המלאכים כמ\"ש בבה\"ז בלק<sup data-n=\"2761\">128</sup> דק\"צ ע\"ב ע\"פ ברכו ה' מלאכיו גבורי כח<sup data-n=\"2762\">129</sup>) ויסו\"א ארוך<sup data-n=\"2763\">130</sup> שנמשך עד יסוד ז\"א ולא כמו הבינה שרק עד הוד אתפשטת<sup data-n=\"2764\">131</sup>, והיחוד",[["2751","118","<b>עצמו</b>: אוצ\"ל: עצמה."],["2752","119","<b>בד\"ה וככה באריכות</b>: תרל\"ז פמ\"ב. ראה גם סה\"מ תרל\"ח ע' רכז. תרל\"ט ח\"ב ע' שעב. תר\"ם ח\"א ע' קפו ובהנסמן בהנ\"ל."],["2753","120","<b>א\"ס מה שמלובש בחכמה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>. פל\"ה בהג\"ה [ראה במ\"מ הגהות והע\"ק לפי\"ח. ופל\"ה]. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380365\" data-slug=\"likkutei-torah\" data-id=\"4001380365\">לקו\"ת במדבר יד, ב</a> [ושם מציין: ”בע\"ח שער מ\"ז פ\"ג\" (ולפנינו הוא פ\"ב) ”ושער ב' במה\"ב פ\"א פ\"ג\" — ולפנינו הוא בשער סדר אצי' ש\"ג]. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540658\" data-slug=\"torat-chaim\" data-id=\"2300540658\">תו\"ח שמות ח\"א ז, ד</a> הערה 333. סה\"מ תרנ\"ח ע' יב."],["2754","121","<b>שמתחילת הבריאה . . חפץ חסד</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, ספ\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380186\" data-slug=\"likkutei-torah\" data-id=\"4001380186\">לקו\"ת אחרי כה, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380908\" data-slug=\"likkutei-torah\" data-id=\"4001380908\">נצבים מז, ב</a>. שעה\"י פי\"א. ש\"א ל, א הערה 15. סה\"מ תרל\"ח ס\"ע מז ואילך ובהנסמן שם."],["2755","122","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["2756","123","<b>באתעדל\"ת תליא מילתא</b>: ראה ע\"ח־ לקו\"ת־ וש\"א שבהערה 121."],["2757","124","<b>זיווג פנימי דחו\"ב</b>: ראה הנסמן לעיל הערה 111. ראה גם (בנוסף להערה 110) מאמרי אדה\"ז תקס\"ט ע' קס. מאמרי אדה\"א בראשית ע' שנז ואילך. דברים ח\"ג ע' תתצ. הנחות תקע\"ז ע' קיז."],["2758","125","<b>אור חדש . . מא\"א ועת\"י עד א\"ס</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380907\" data-slug=\"likkutei-torah\" data-id=\"4001380907\">לקו\"ת נצבים מז, א</a> שמציין בלק\"ת [מהאריז\"ל] פ' וירא — קרוב לתחילתו עה\"פ יח, י והנה בן לשרה אשתך [נז, ב בדפי הספר]."],["2759","126","<b>הנמשך ע\"י נשמות הצדיקים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370322\" data-slug=\"torah-or\" data-id=\"3901370322\">תו\"א יתרו עב, ג</a>."],["2760","127","<b>נשמות הצדיקים . . חכמה</b>: ראה גם ביאוה\"ז שבהערה הבאה צט, א."],["2761","128","<b>שמהבינה . . המלאכים כמ\"ש בבה\"ז בלק</b>: צח ג ואילך."],["2762","129","<b>ברכו ה' מלאכיו גבורי כח</b>: תהלים קג, כ."],["2763","130","<b>ויסו\"א ארוך</b>: ראה ע\"ח שער הכללים פ\"י. מאמרי אדה\"א דברים ח\"ב ע' שעח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550121\" data-slug=\"torat-chaim\" data-id=\"2300550121\">תו\"ח תצוה ח\"ב של, א</a>. וש\"נ."],["2764","131","<b>הבינה שרק עד הוד אתפשטת</b>: ראה זהר רע\"מ פינחס רכג, ב. אמרי בינה שער התפילין קכ, ד. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקפה."]]],[2001910295,"נמשך ע\"י בחי' יסוד ז\"א בחי' יוסף<sup data-n=\"2765\">132</sup> צדיק עליון<sup data-n=\"2766\">133</sup> שז\"ע תוס' מרובה על העיקר, ובחי' זו זהו בחי' צדיק שלמעלה מבחי' ישר רגל ישרה, ועמ\"ש מזה בת\"א בביאור ע\"פ זכור את יוה\"ש לקדשו השני<sup data-n=\"2767\">134</sup>, ומענין צדיק וישר ע' בזח\"ג אחרי דנ\"ט סע\"א צדיק וישר דכר ונוק', וכן יש לפרש זה על חו\"ב כו').\n<b>ומה</b> שנק' מהלכים דוקא כשירדה הנשמה למטה בגוף ונה\"ב ולא קודם ירידתה שאז נק' בשם עומדים לבד וכמ\"ש חי ה' אשר עמדתי לפניו<sup data-n=\"2768\">135</sup>, הענין הוא דהנה אנו רואים שכח הצומח מלובש בארץ<sup data-n=\"2769\">136</sup> דוקא ולא בשמים שבשמים לא יהי' שום צמיחה כו' והיינו לפי שנעוץ תב\"ס<sup data-n=\"2770\">137</sup>, או ע\"ד שאנו רואים שהמאכל שהוא צומח מחי' את האדם<sup data-n=\"2771\">138</sup> שהוא למעלה ממנו הרבה במדרגה, והיינו לפי שמה שהמאכל הוא למטה ממנו לפי שכל הגבוה יותר יכול להשפיל יותר<sup data-n=\"2772\">139</sup> ונפל בו ניצוץ היותר עליון כמ\"ש במ\"א, ע\"כ יש בכחו להחיות את האדם לפי ששרשו הוא למעלה, כי קליפה קדמה לפרי<sup data-n=\"2773\">140</sup> ג\"כ מטעם הנ\"ל. וזהו שאין אדם רואה מתוך הלובן שבעין אלא מתוך השחור<sup data-n=\"2774\">141</sup> דוקא, כי יתרון האור הוא מן החשך<sup data-n=\"2775\">142</sup> דוקא, וכן אנו רואים שהמים כשבוקעין את עפר הארץ אז נעשים מים חיים<sup data-n=\"2776\">143</sup>, אבל מי הים אינו נק' מ\"ח<sup data-n=\"2777\">144</sup> רק ע\"י שבוקעין עפר הארץ דוקא אז נק' מים חיים, וכך עי\"ז שירדה הנשמה למטה בגוף ונה\"ב שהוא בחי' חשך והסתר ואתכפי' סט\"א עי\"ז נעשה יתרון האור, וזהו מ\"ש נר הוי' נשמת אדם<sup data-n=\"2778\">145</sup>, והיינו שכמו שהנר מאיר את החשך כך הנשמה שירדה למטה נק' בשם נר שמאירה את נה\"ב ומהפך את החשך לאור, ולכך",[["2765","132","<b>יסוד ז\"א בחי' יוסף</b>: ראה ע\"ח שער הצלם שכ\"ו, פ\"ג. ביאוה\"ז ויחי כט, ב. ד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקיז ובהנסמן במ\"מ לשם."],["2766","133","<b>יוסף צדיק עליון</b>: ראה זהר ויצא קנג, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370201\" data-slug=\"torah-or\" data-id=\"3901370201\">תו\"א ויגש מד, ג</a>. סה\"מ תר\"ם ח\"ב ע' תרעו. וש\"נ."],["2767","134","<b>בת\"א בביאור . . השני</b>: יתרו עב, א ואילך."],["2768","135","<b>חי ה' אשר עמדתי לפניו</b>: ראה גם לעיל מאמר ד\"ה הקבצו ושמעו בנ\"י ובהערה 67."],["2769","136","<b>שכח הצומח מלובש בארץ</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תקצה ואילך."],["2770","137","<b>שנעוץ תב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["2771","138","<b>שהמאכל . . מחי' את האדם</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380647\" data-slug=\"likkutei-torah\" data-id=\"4001380647\">לקו\"ת מטות פא, ב</a> ואילך. מאמרי אדה\"א דברים ח\"ב ע' תקעה. וש\"נ. שה\"א טז, ב ובהערה 10. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540054\" data-slug=\"torat-chaim\" data-id=\"2300540054\">תו\"ח וארא ח\"א נה, ב</a> ואילך. וש\"נ. סה\"מ מלוקט א' ע' קצא."],["2772","139","<b>שכל הגבוה . . להשפיל יותר</b>: ראה ש\"א שער הפורים נח, א. סה, א. סה\"מ תרל\"ח ע' תב. וש\"נ."],["2773","140","<b>קליפה קדמה לפרי</b>: ראה זהר סבא משפטים קח, רע\"ב. מאמרי אדה\"א ויקרא ח\"א ע' רט. וש\"נ."],["2774","141","<b>שאין אדם . . מתוך השחור</b>: ראה ויק\"ר פל\"א, ח. רש\"י האזינו לב, י. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381037\" data-slug=\"likkutei-torah\" data-id=\"4001381037\">לקו\"ת האזינו עח, ג</a>. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשא. ע' תתצג ובהנסמן במ\"מ לשם. מאמרי אדה\"א הנחות תקע\"ז ע' שלה. פיה\"מ עט, ד — וב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091064\" data-slug=\"likkutei-sichot\" data-id=\"1300091064\">לקוטי שיחות ואתחנן כרך ט ע' 64</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450585\" data-slug=\"or-hatorah-hb\" data-id=\"8316450585\">אוה\"ת האזינו ע' א'תרעט</a>. ע' א'תרפח.\nבאוה\"ת שם מציין למשנה פ\"ו דבכורות — ראה בזה ספר הערכים חב\"ד ח\"ב ע' תקפה ובהשמטה לשם בע' תרצז."],["2775","142","<b>יתרון האור הוא מן החשך</b>: ע\"פ קהלת ב, יג."],["2776","143","<b>שהמים כשבוקעין . . מים חיים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370093\" data-slug=\"torah-or\" data-id=\"3901370093\">תו\"א תולדות כ, א</a>. ב. סהמ\"צ להצ\"צ ע' 306. אוה\"ת חוקת ע' תתס. מאמרי אדה\"א קונטרסים ס\"ע שצח ואילך. וש\"נ. לקמן מאמר ד\"ה כתר יתנו לך רפ\"ג."],["2777","144","<b>מי הים אינו נק' מ\"ח</b>: ראה פרה פ\"ח, ה\"ח. מקואות פ\"ה, מ\"ד. רמב\"ם הל' פרה אדומה פ\"ו, ה\"י. מקואות פ\"ט, ה\"ח. הי\"ב."],["2778","145","<b>נר הוי' נשמת אדם</b>: משלי כ, כז."]]],[2001910296,"המלאכים ביקשו את התורה<sup data-n=\"2779\">146</sup> ולא ניתנה להם כי כלום יצה\"ר יש ביניכם<sup data-n=\"2780\">147</sup>, והיינו אף שהמלאכים ביקשו את התורה מסתמא כמו שהיא ברוחניות<sup data-n=\"2781\">148</sup> אעפי\"כ השיבו להם כלום יצה\"ר יש ביניכם, והיינו לפי שיתרון האור הוא מתוך החשך דוקא. וזהו ענין שלש רגלים דוקא בכל לבבך ובכל נפשך ובכל מאדך כו' ונתתי לך מהלכים בין העומדים האלה, והגילוי הוא במועדים דוקא שבמועדים נמשך גילוי של בחי' שלש רגלים בחי' הילוך ודילוג כו'.",[["2779","146","<b>המלאכים בקשו את התורה</b>: שבת פח, ב."],["2780","147","<b>כלום יצה\"ר יש ביניכם</b>: ראה שם פט, א. מאמרי אדה\"א ויקרא ח\"ב ע' תסט בהערה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560193\" data-slug=\"or-hatorah-hb\" data-id=\"8316560193\">אוה\"ת בראשית כרך ג ע' תקסג</a>. סה\"מ תר\"ם ח\"ב ע' תרד. לעיל מאמר ד\"ה ובירך את לחמך על יד הערה 81."],["2781","148","<b>שהמלאכים ביקשו . . ברוחניות</b>: ראה גם לקמן מאמר ד\"ה כתר יתנו לך פ\"ה. וש\"נ."]]],[2001910297,"<h3>ומעתה כו' הוקבעו המועדים</h3>\n<b>שחוהמ\"פ</b>\nד) <b>ומעתה</b> צ\"ל למה<sup data-n=\"2784\">3</sup> הוקבעו המועדים על זמן התבואה<sup data-n=\"2782\">1</sup> דוקא, והענין דהנה כתי' קדש ישראל לה' ראשית תבואתה (ירמי' ב' ג'), והניקוד הוא",[["2784","3","<b>ומעתה צ\"ל למה</b>: ראה גם אוה\"ת משפטים ע' א'קעח ואילך. הנסמן בסה\"מ תרל\"ג כאן. לקמן מאמר ד\"ה וחג הקציר בכורי מעשיך ובהערה 3."],["2782","1","<b>ומעתה צ\"ל למה הוקבעו המועדים על זמן התבואה</b>: מאמר זה [פרקים ד-ח] הוא העתק מבוך בש\"ו 1063 רפב, ב [מאמר ד\"ה שלש רגלים] עם הגהות ותיקונים מכ\"ק אדמו\"ר מהר\"ש. והוא המשך למאמר ד\"ה שלש רגלים תחוג לי [פרקים א-ג] שנדפס לפנ\"ז.\nלמאמר זה, פ\"ד הוא לשון פ\"ג מד\"ה שלש רגלים תרל\"ג [נדפס בסה\"מ תרל\"ג ח\"א ע' קמח ואילך] פסקא ראשונה בשינוי קצת בתחילתו. פ\"ה לא נרשם — ראה המובא בסמוך. לפ\"ו ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010120\" data-slug=\"or-hatorah-hb\" data-id=\"8159010120\">אוה\"ת משפטים ע' א'קפא</a>. סה\"מ תר\"ל ע' קלג ואילך. ע' רח [אוה\"ת פינחס ע' א'רטו ואילך]. תרל\"ג ח\"א ע' קמט. לפ\"ז ראה גם אוה\"ת משפטים ע' א'קפג ואילך. סה\"מ תר\"ל ע' קלה ואילך. ע' רי ואילך [אוה\"ת פינחס ע' א'ריז ואילך]. לפ\"ח ראה גם אוה\"ת משפטים ע' א'קפה ואילך. סה\"מ תר\"ל ע' קלז. ע' ריג [אוה\"ת פינחס ע' א'רכ]. תרל\"ג ח\"א כאן ע' קמט ואילך.\nממאמר זה ישנם עוד שני הנחות ובהם הפתיחא היא: את חג המצות תשמור. ההנחות הם: א) הנחת כ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן בחלק הנחותיו. ב) הנחה אחרת נדפסה לקמן בחלק ההנחות.\nבוך בש\"ו הנ\"ל הוא הנחות של ר' דוב [בעריל] קאליסקער ממאמרי כ\"ק אדמו\"ר הצ\"צ ונק' בשם ”בוך בש\"ו\" [בראשית שמות ויקרא]־ ולפעמים נק' בשם ”ס' וכל שיח\" ע\"ש פתיחתו במאמר ד\"ה וכל שיח השדה. ראה עוד ע\"ד הנ\"ל ב”ספריית ליובאוויטש\" ע' ל ואילך. ע' לז ואילך. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד-תרט\"ו ע' שעז.\nהמאמר נרשם בכת\"י מעתיק, היינו א) העתק המאמר שלש רגלים כפי שמופיע בתרל\"ג פ\"ג. ב) אח\"כ העתיק המשך המאמר שלש רגלים הנ\"ל מבוך בש\"ו ששם באו הגהות ותיקונים בגוכתי\"ק ללא ציון פרקים. ג) על העתק זה ניתוספו בגוכתי\"ק הגהות ותיקונים ופרקים ה-ז [ופ\"ד לא נרשם]. ד) וכן לספ\"ו נרשמו עוד הגהות וכו' בע' בפ\"ע בכותרת: ”לד\"ה שלש רגלים תחוג לי\". ה) לאח\"ז נרשם המאמר עוה\"פ בכת\"י מעתיק [שהעתיק הנ\"ל א-ד] בכותרת: ”שחוהמ\"פ\" עם איזה תיקונים בגוכתי\"ק. ובמקום פ\"ג הנ\"ל נרשם פ\"ד. ואח\"כ נרשמו פרקים ו-ח [ופ\"ה לא נרשם]."]]],[2001910298,"בחולם שנמצא נעשה הקרי תבואתו<sup data-n=\"2785\">4</sup>, ופי' הת\"י<sup data-n=\"2786\">5</sup> קדש ישראל כתרומה, ראשית תבואתה כראשית קציר לפני העומר שאסור באכילה כן כל אוכליו יאשמו<sup data-n=\"2783\">2</sup>. ולהבין למה נק' ישראל בחי' תבואה ראשית תבואתו, הענין הוא דהנה כתי' וזרעתי' לי בארץ<sup data-n=\"2787\">6</sup>, והיינו שכמו שהזריעה הוא שזורעין גרעין בארץ ונרקב, ועי\"ז נעשה צמיחה<sup data-n=\"2788\">7</sup> בתוס' וריבוי כי כלום אדם זורע סאה<sup data-n=\"2789\">8</sup> אלא כדי להכניס כמה כורין, וכך ישראל נק' בשם זריעה וכמ\"ש אור זרוע<sup data-n=\"2790\">9</sup> דהיינו שירדו למטה בגוף ונה\"ב המעלים ומסתיר על קדושת ה' שאין לה גילוי אלקות כמו שהי' מקודם שירדה למטה שהיתה נהנית מזיו השכינה<sup data-n=\"2791\">10</sup>, שהוא רקבון וביטול, וזהו שהגליות<sup data-n=\"2792\">11</sup> בבל נק' ג\"כ בשם זריעה<sup data-n=\"2793\">12</sup>, וזהו זרובבל<sup data-n=\"2794\">13</sup> שהיא בחי' זריעה והיינו שהוא בחי' ירידה וביטול עצמותו, אך ע\"י זריעה זו נעשה אח\"כ צמיחה בתוס' וריבוי יותר, והיינו שעי\"ז נעשה גילוי יותר וכמ\"ש ברוך ה' אלקי ישראל מן העולם ועד העולם<sup data-n=\"2795\">14</sup> מעלמא דאתכסי' לעלמא דאתגלי'<sup data-n=\"2796\">15</sup>, והפי' הפשוט הוא מעוה\"ז לעוה\"ב<sup data-n=\"2797\">16</sup>, והיינו שע\"י בירור שבעוה\"ז שהוא בחי' זריעה עי\"ז נעשה המשכה מעדאת\"כ לעלמא דאתגלי', ושרש של שני העולמות הוא ב' שמות הוי' וכמ\"ש ויקרא הוי' הוי'<sup data-n=\"2798\">17</sup> שהוא המשכה שלא ע\"פ סדר השתלשלות כו' שזהו בחי' הצמיחה כו'. והנה עיקר הצמיחה יהי' לע\"ל וכפי' הפשוט מעוה\"ז לעוה\"ב שלע\"ל יהי' בחי' הצמיחה הנ\"ל, אך ברגלים נעשה ג\"כ מעין צמיחה זו, וזהו שהרגלים נקבעים על זמן גמר התבואה לפי שהרגלים הוא בחי' צמיחה.",[["2785","4","<b>תבואתה . . תבואתו</b>: ראה גם לעיל מאמר ד\"ה קדש ישראל לה' ובהערה 2."],["2786","5","<b>ופי' הת\"י</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010128\" data-slug=\"or-hatorah-hb\" data-id=\"8159010128\">אוה\"ת</a> ירמי' כרך א ס\"ע שכב ואילך — נדפס גם באוה\"ת פינחס ע' א'רכא ואילך."],["2783","2","<b>ומעתה צ\"ל . . יאשמו</b>: ראה סה\"מ תרל\"ג ח\"א ע' קמח כאן ובהנרשם בשולי היריעה שם."],["2787","6","<b>וזרעתי' לי בארץ</b>: הושע ב, כה. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370274\" data-slug=\"torah-or\" data-id=\"3901370274\">תו\"א בשלח סא, א</a>. הנסמן בסה\"מ תרל\"ג כאן."],["2788","7","<b>גרעין . . ונרקב . . צמיחה</b>: ראה אגה\"ק ס\"ח (קיג, א). מאמרי אדה\"א ויקרא ח\"ב ע' תקצח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540229\" data-slug=\"torat-chaim\" data-id=\"2300540229\">תו\"ח שמות ח\"א ב, ב</a>. וש\"נ. סה\"מ תר\"ם ח\"א ע' רב. וש\"נ."],["2789","8","<b>כלום אדם זורע סאה</b>: ראה פסחים פז, ב [ושם: סאה]. תו\"א בשלח שם [ושם: כור]. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381030\" data-slug=\"likkutei-torah\" data-id=\"4001381030\">לקו\"ת האזינו עו, ד</a> [ושם: קב — וכן הוא בבוך בש\"ו כאן. אלא שכ\"ק אדמו\"ר מהר\"ש תיקן סאה. וראה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 21 ושם: קב. אבל (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 19 ושם: סאה]. מאמרי אדה\"א דברים ח\"ד ע' א'תלד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540390\" data-slug=\"torat-chaim\" data-id=\"2300540390\">תו\"ח שמות ח\"א מ, ג</a> ובהנסמן בהנ\"ל."],["2790","9","<b>אור זרוע</b>: תהלים צז, יא."],["2791","10","<b>נהנית מזיו השכינה</b>: ראה ברכות יז, א."],["2792","11","<b>שהגליות</b>: וכ\"ה בבוך בש\"ו כאן [אלא ששם ליתא תיבת בבל שניתוספה בגוכתי\"ק בין השיטין]. ובבוך 2085. בסה\"מ תרל\"ג ח\"א ע' קמח כאן: שהגלות."],["2793","12","<b>שהגליות בבל נק' בשם זריעה</b>: ראה אוה\"ת בשלח ע' שנג. משפטים ס\"ע א'קעח: רפ\"ח דפסחים [פז, ב] דקאי על גלות בבל. לקו\"ת שבהערה הבאה. בתו\"א שם בתחילתו: בגלות מצרים [וראה גם הנרשם במ\"מ לשם]. באוה\"ת בשלח שם ע' שנו: הגלות דמצרי' ובבל. שם ע' שנט [הוספה על לשון תו\"א שם פיסקא והנה כמו] במצרים ובבל."],["2794","13","<b>זרובבל</b>: ראה סנהדרין לח, רע\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380428\" data-slug=\"likkutei-torah\" data-id=\"4001380428\">לקו\"ת בהעלותך כט, ג</a>. מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע רטו. סה\"מ תרל\"ג ח\"ב ע' שלה. אג\"ק ח\"ו ע' קצא."],["2795","14","<b>ברוך ה' . . ועד העולם</b>: תהלים קו, מח־ דברי הימים-א טז, לו. ראה זהר ויצא קנח, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541020\" data-slug=\"torat-chaim\" data-id=\"2300541020\">תו\"ח שמות ח\"א יח, ג</a>. וש\"נ."],["2796","15","<b>מעלמא דאתכסי' . . דאתגלי'</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, רע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/tanya/3401310031\" data-slug=\"tanya\" data-id=\"3401310031\">תניא פכ\"ו</a>."],["2797","16","<b>מעוה\"ז לעוה\"ב</b>: ראה תרגום ורש\"י לתהלים שם. מצו\"ד לדברי הימים-א שם."],["2798","17","<b>ויקרא הוי' הוי'</b>: תשא לד, ו. ראה גם לעיל מאמר ד\"ה מגילה נקראת ובהערה 232."]]],[2001910299,"וא\"ו)<sup data-n=\"2799\">18</sup> <b>והנה</b> סדר הרגלים<sup data-n=\"2800\">19</sup> רגל הראשון הוא חג המצות שהוא בחדש האביב, וכמ\"ש (בפ' משפטים ך\"ג ט\"ו) את חג המצות תשמור כו' תאכל מצות כו' למועד חדש האביב כי בו יצאת ממצרים. ולהבין למה נצטוו דוקא במצה. והענין הוא דהנה ארז\"ל אין התינוק יודע לקרות או\"א<sup data-n=\"2801\">20</sup> עד שיטעום טעם דגן דוקא דהיינו שכדי שידע התינוק לקרוא אבא כו' אף שהיא הכרה שלא ע\"פ שכל רק שהוא נמשך אחר אביו בלי טו\"ד כלל זהו ע\"י טעם דגן דוקא, כך כדי שיהי' התחברות נש\"י עם אלקות זהו ע\"י טעם דגן דוקא שהוא בחי' מצה, והיינו כי מצה הוא בחי' ביטול ושפלות שאין בה שום טעם כלל, משא\"כ חמץ הוא בחי' הגבהה<sup data-n=\"2802\">21</sup> והתנשאות שהוא בחי' כעס וגאוה, וע\"כ עי\"ז לא יוכל להיות התחברות נש\"י עם אלקות לפי שאין אני והוא יכולים לדור<sup data-n=\"2803\">22</sup>, רק ע\"י מצה דוקא שהוא בחי' ביטול ושפלות, וזהו שפסח הוא בחדש האביב, כי אביב הוא בחי' א\"ב י\"ב<sup data-n=\"2804\">23</sup>, אב הוא בחי' כי אתה אבינו<sup data-n=\"2805\">24</sup>, וי\"ב הם י\"ב שבטים<sup data-n=\"2806\">25</sup> ונתחברים ונעשים אחד, כי אביב הוא ג\"כ לשון התחברות וכמשארז\"ל קישות שהתליעו באבי'<sup data-n=\"2807\">26</sup> שפירשו במחובר כו', והיינו שאז נעשה התחברות נש\"י עם אלקות וע\"כ נק' חדש האביב, וזהו מ\"ש החדש הזה לכם כו' ראשון הוא לכם<sup data-n=\"2808\">27</sup> כו', והיינו שראשון הוא בחי' אני ראשון ואני אחרון<sup data-n=\"2809\">28</sup> יהי' לכם שיתחבר עמכם, וזהו שפסח נק' חדש האביב דהיינו שנש\"י שנק' ראשית תבואתה אז הם אביב שיתחברו אז עם אלקות, אך בפסח אז הוא רק גמירת השעורים<sup data-n=\"2810\">29</sup>, וכמ\"ש כי השעורה אביב<sup data-n=\"2811\">30</sup>, והיינו ששעורה הוא בחי' שיעור ה'<sup data-n=\"2812\">31</sup> בהבראם בה' בראם<sup data-n=\"2813\">32</sup> שהוא בחי' התבוננות איך שהוא מחי' ומהוה את כל העולמות שהוא בחי' ה' אחרונה של ש' הוי'<sup data-n=\"2814\">33</sup>, ושיעור ה' היינו כל חד וחד לפש\"ד<sup data-n=\"2815\">34</sup> שמתבונן באלקות עי\"ז הוא נתחבר, ומה שבפסח דוקא הוא רק מבחי' שעורה, והיינו לפי שבפסח יצאו ממצרים<sup data-n=\"2816\">35</sup>, מצרים הוא בחי' ערות",[["2799","18","<b>וא\"ו</b>: בהעתק הא' נסמן כאן פ\"ה, ופ\"ד לא נסמן. בהעתק הב' נסמן כאן פ\"ו, ופ\"ה לא נסמן. ראה לעיל הערה 1."],["2800","19","<b>והנה סדר הרגלים</b>: ראה גם להבא להלן אוה\"ת משפטים ע' א'קפא ואילך. סה\"מ תר\"ל ע' קלג ואילך. ע' רח [אוה\"ת פינחס ע' א'רטו ואילך — ראה גם לעיל מאמר ד\"ה קדש ישראל לה' הערה 2]. תרל\"ג ח\"א כאן ע' קמט."],["2801","20","<b>אין התינוק יודע לקרות או\"א</b>: ראה ברכות מ, סע\"א. מאמרי אדה\"א דברים ח\"א ע' רמה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540734\" data-slug=\"torat-chaim\" data-id=\"2300540734\">תו\"ח בא ח\"א צה, ב</a>. וש\"נ."],["2802","21","<b>מצה . . ביטול . . חמץ . . הגבהה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380130\" data-slug=\"likkutei-torah\" data-id=\"4001380130\">לקו\"ת צו יג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381188\" data-slug=\"likkutei-torah\" data-id=\"4001381188\">שה\"ש יד, ד</a>. סה\"מ תר\"ם ח\"א ע' ריב."],["2803","22","<b>שאין אני והוא יכולין לדור</b>: סוטה ה, א. ערכין טו, ב."],["2804","23","<b>אביב . . אב י\"ב</b>: ראה גם לעיל מאמר ד\"ה קדש ישראל לה' פ\"ה ובהערה 178."],["2805","24","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["2806","25","<b>וי\"ב הם י\"ב שבטים</b>: ראה גם לעיל שם."],["2807","26","<b>קישות שהתליעו באבי'</b>: ראה חולין נח סע\"א. סז סע\"א ואילך."],["2808","27","<b>החדש . . ראשון הוא לכם</b>: בא יב, ב."],["2809","28","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["2810","29","<b>אביב . . גמירת השעורים</b>: ראה מנחות סח, ב. אבן עזרא משפטים כג, טז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301730177\" data-slug=\"likkutei-sichot\" data-id=\"1301730177\">לקו\"ש משפטים כרך לו ע' 109</a> ואילך."],["2811","30","<b>כי השעורה אביב</b>: וארא ט, לא."],["2812","31","<b>ששעורה . . שיעור ה'</b>: זהר בלק קפח, ב."],["2813","32","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."],["2814","33","<b>ה' אחרונה של ש' הוי'</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' מד. ע' רכח. ח\"ב ע' תשפט. במדבר ח\"ב ע' ת."],["2815","34","<b>כל חד וחד לפש\"ד</b>: ראה תניא בהקדמה (ד, א) ע\"פ זהר וירא קג, רע\"ב. וראה גם זהר ח\"ש קכט, ב."],["2816","35","<b>שבפסח יצאו ממצרים</b>: ראה בא יב, כט ואילך. יג, ב ואילך. משפטים כג, טו. תשא לד, יח. ועוד."]]],[2001910300,"הארץ<sup data-n=\"2817\">36</sup> שהיו משוקעים במ\"ט שע\"ט<sup data-n=\"2818\">37</sup>, ובפסח יצאו ממצרים, וכדי שיתחברו לאלקות זהו ע\"י שעורה דוקא שהוא בחי' מל'<sup data-n=\"2819\">38</sup> כי זה השער לה'<sup data-n=\"2820\">39</sup> דא הוא תרעא לאעלאה<sup data-n=\"2821\">40</sup>, בזאת יבא אהרן<sup data-n=\"2822\">41</sup> אל הקדש שהיא בחי' קבלת עומ\"ש, וכמ\"ש בזהר במדבר דק\"ך ע\"א ובא לו לקרן<sup data-n=\"2823\">42</sup> אמינא בקדמיתא שמתחלה צריך שיהי' בחי' ביטול קבלת עול לבד, וזהו שמניחים הטלית ואח\"כ התפילין<sup data-n=\"2824\">43</sup>, אף שטלית היא רק תשמישי מצוה<sup data-n=\"2825\">44</sup> ותפילין היא תשמישי קדושה<sup data-n=\"2826\">45</sup> אעפ\"כ מניחין הטלית קודם לפי שטלית הוא בחי' פריסו דמלכא<sup data-n=\"2827\">46</sup> קבלת עומ\"ש וכן ש\"י קודם לש\"ר<sup data-n=\"2828\">47</sup> כו', וע\"כ בפסח אז השעורה רק אביב שאז נתחברו נש\"י לאלקות ע\"י שיעור ה'.\nז) <b>אך</b> בשבועות<sup data-n=\"2829\">48</sup> נק' קציר חטים<sup data-n=\"2830\">49</sup> וחג הקציר בכורי מעשיך<sup data-n=\"2831\">50</sup>, ולכאו' אין זה מובן שהרי בשבועות אסור לקצור<sup data-n=\"2832\">*51</sup>, ולמה נק' קציר חטים. אך הענין הוא דהנה כתי' עיניך בשדה אשר יקצרון<sup data-n=\"2833\">51</sup> ופי' בזהר ס\"פ ויקהל דרי\"ח ע\"א עיניך קאי על הסנהדרין שנק' עיני העדה<sup data-n=\"2834\">52</sup>, ולכך נק' הסנהדרין עיני העדה היינו שכמו שכל",[["2817","36","<b>מצרים . . ערות הארץ</b>: מקץ מב, ט. יב. ראה קה\"ר פ\"א, ד בסופה. ע\"ח שער ציור עולמות שמ\"ג, פ\"א."],["2818","37","<b>מצרים . . משוקעים במ\"ט שע\"ט</b>: ראה ז\"ח יתרו לא, א. סה\"מ תר\"ם ח\"א ע' קמב. וש\"נ."],["2819","38","<b>שעורה . . מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פכ\"א מערכת שעורה. מאו\"א מערכת שעורה אות ע."],["2820","39","<b>זה השער לה'</b>: תהלים קיח, כ. ראה זהר בהקדמה ז, ב. ת\"ז ת\"א יח, רע\"א. תכ\"ב סה, א. מאמרי אדה\"ז תקס\"ט ע' נז. מאמרי אדה\"א הנחות תקע\"ז ע' רנו [נדפס גם במאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשה]. סה\"מ תר\"ל ע' קלג."],["2821","40","<b>דא הוא תרעא לאעלאה</b>: ראה זהר בהקדמה ח, רע\"א. יא, ב."],["2822","41","<b>בזאת יבא אהרן</b>: אחרי טז, ג. ראה זהר אחרי נו, ב."],["2823","42","<b>ובא לו לקרן</b>: זבחים נג, רע\"א (במשנה). ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרט ואילך. ביאוה\"ז במדבר קמד, ב ואילך. מאמרי אדה\"ז הנחות הר\"פ ע' נב ואילך. תקס\"ז ע' קסה ואילך. ביאוה\"ז להצ\"צ במדבר כרך א ע' תסד ואילך."],["2824","43","<b>הטלית ואח\"כ התפילין</b>: ראה שו\"ע אדה\"ז הל' תפילין רסכ\"ה. ראה גם אוה\"ת כאן ע' א'קפב [ושם: טלית עם הציצית]. ובאו\"א ראה אמ\"ב שער הציצית צא, ב. צה, ד."],["2825","44","<b>שטלית . . תשמישי מצוה</b>: ראה שו\"ע אדה\"ז הל' ציצית סכ\"א, ס\"ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370446\" data-slug=\"torah-or\" data-id=\"3901370446\">תו\"א מג\"א ק, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380489\" data-slug=\"likkutei-torah\" data-id=\"4001380489\">לקו\"ת שלח מד, ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191435\" data-slug=\"likkutei-sichot\" data-id=\"1300191435\">לקו\"ש</a> אגה\"ת כרך יט ע' 421-422 ובהנסמן שם.\nואולי הכוונה שהציצית התלויות בטלית הם תשמישי מצוה [ראה גם ראשית חכמה שער הקדושה פ\"ו (קרוב לתחילתו ד\"ה עוד מהדברים קמא, א): והטלית תשמישי מצוה. אוה\"ת שבהערה שלפנ\"ז. לקמן בשני ההנחות כאן]. ראה שו\"ע אדה\"ז הל' ציצית שם, ס\"א. הל' תפילין סמ\"ב, ס\"ו."],["2826","45","<b>ותפילין היא תשמישי קדושה</b>: ראה שו\"ע אדה\"ז הל' תפילין סמ\"ב, ס\"ו. אבל כ\"ה בכ\"מ — ראה סה\"מ תר\"ם ח\"א ע' שא. וש\"נ."],["2827","46","<b>שטלית . . פריסו דמלכא</b>: ראה זהר סבא משפטים צז, ב. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרמא. מאמרי אדה\"א במדבר ח\"ג ע' א'רפ לע' א'מד."],["2828","47","<b>ש\"י קודם לש\"ר</b>: ראה שו\"ע אדה\"ז הל' תפילין סכ\"ה , סי\"ב."],["2829","48","<b>אך בשבועות</b>: ראה גם להבא להלן <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010120\" data-slug=\"or-hatorah-hb\" data-id=\"8159010120\">אוה\"ת משפטים ע' א'קפג</a> ואילך. סה\"מ תר\"ל ע' קלה ואילך. ע' רי ואילך [אוה\"ת פינחס ע' א'ריז ואילך]."],["2830","49","<b>בשבועות נק' קציר חטים</b>: תשא לד, כב."],["2831","50","<b>וחג הקציר בכורי מעשיך</b>: משפטים כג, טז."],["2832","*51","<b>בשבועות אסור לקצור</b>: חגיגה יח, א."],["2833","51","<b>עיניך בשדה אשר יקצרון</b>: רות ב, ט."],["2834","52","<b>בזהר . . הסנהדרין שנק' עיני העדה</b>: שלח טו, כד. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 58 בשם המדרש. ראה רות רבה פ\"ד, יב פסוק ט. וש\"נ. צויין אליו באוה\"ת משפטים שם. וסה\"מ תר\"ל ס\"ע קלח. ע' רי [אוה\"ת פינחס שם]."]]],[2001910301,"הרמ\"ח אברים שבאדם<sup data-n=\"2835\">53</sup> נמשכים אחרי העינים, וזהו מ\"ש ולא תתורו אחרי לבבכם<sup data-n=\"2836\">54</sup> ואחרי עיניכם כו' שהעינים הם העיקר<sup data-n=\"2837\">55</sup>, כך כללות נש\"י נמשכים אחר הסנהדרין ולכך נק' עיני העדה. ועוד י\"ל שלכך נק' הסנהדרין עיני העדה לפי שעבודתם היא בבחי' עינים, וכמ\"ש לבבתני באחד מעיניך<sup data-n=\"2838\">56</sup> והקרי באחת מעיניך, והיינו שעיניך הוא בחי' עיניך יונים<sup data-n=\"2839\">57</sup> שכמו שיונים עיקר התענוג שלהם הוא בעינים שמסתכלים<sup data-n=\"2840\">58</sup> זע\"ז, וכך הסנהדרין כל עבודתם הוא לאסתכלא ביקרא דמלכא<sup data-n=\"2841\">59</sup> עיני האדם לא תשבענה<sup data-n=\"2842\">60</sup>, ויש בזה ב' בחי' באחת מעיניך ובאחד מעיניך, היינו שכשהם במדרגת יחו\"ע ביטול במציאות אז נק' באחד מעיניך וכשהם רק בבחי' ביטול היש לבד הוא באחת<sup data-n=\"2843\">61</sup> מעיניך. ופי' הפסוק עיניך בשדה אשר יקצרון היינו מה שע\"י עיניך שהוא בחי' לאסתכלא ביקרא דמלכא עי\"ז הם מקבלים השפעה מלמעלה, כי שדה היא ציון וכמ\"ש ראה ריח בני כריח שדה<sup data-n=\"2845\">63</sup> ופי' ברבות<sup data-n=\"2844\">62</sup> שדה היא ציון, וכמ\"ש ציון שדה תחרש<sup data-n=\"2846\">64</sup>, וכן כתי' וירא והנה באר בשדה<sup data-n=\"2847\">65</sup>, באר זה ציון<sup data-n=\"2848\">66</sup>, והיינו שהם מקבלים ההשפעה ע\"י ציון כי כל השפעות נמשך מציון, וכמ\"ש כי מציון תצא תורה<sup data-n=\"2849\">67</sup>, ברכה מציון<sup data-n=\"2850\">68</sup> כו', וע' במד\"ר פ' קדושים פך\"ד<sup data-n=\"2851\">69</sup> ע\"פ ישלח עזרך<sup data-n=\"2852\">70</sup> כו' ומציון כו', וזהו אשר יקצרון היינו כי קצירה היא בחי' המשכה שנמשך מלמעלה וכמ\"ש זרעו לכם לצדקה וקצרו לפי חסד<sup data-n=\"2853\">71</sup>",[["2835","53","<b>הרמ\"ח אברים שבאדם</b>: אהלות פ\"א, מ\"ח."],["2836","54","<b>ולא תתורו אחרי לבבכם</b>: שלח טו, לט."],["2837","55","<b>שהעינים הם העיקר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370243\" data-slug=\"torah-or\" data-id=\"3901370243\">תו\"א שמות נד, סע\"ג</a> ואילך. אוה\"ת עקב ע' תרכא. משלי כרך א ע' תריט ואילך. מאמרי אדה\"א קונטרסים ע' רפא. סה\"מ תרל\"ב ח\"ב ע' תקצח [ושם: גירסת הגמרא]. וש\"נ. לקמן בשני ההנחות כאן. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291184\" data-slug=\"likkutei-sichot\" data-id=\"1300291184\">לקו\"ש נצבים כרך כט ע' 169</a>."],["2838","56","<b>לבבתני באחד מעיניך</b>: שה\"ש ד, ט."],["2839","57","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א."],["2840","58","<b>שיונים . . שמסתכלים</b>: ראה מאמרי אדה\"ז תקס\"ד ע' קלז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381186\" data-slug=\"likkutei-torah\" data-id=\"4001381186\">לקו\"ת שה\"ש יד, ב</a>. תו\"ח ח\"ש קלב, סע\"א ואילך ובהנסמן לשם. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תקפז."],["2841","59","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["2842","60","<b>עיני האדם לא תשבענה</b>: משלי כז, כ [ושם: ועיני — ראה גם בהמצויין בסמוך]. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381267\" data-slug=\"likkutei-torah\" data-id=\"4001381267\">לקו\"ת שה\"ש לד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381272\" data-slug=\"likkutei-torah\" data-id=\"4001381272\">לה, ד</a>. סהמ\"צ להצ\"צ ע' קפח. פלח הרמון שה\"ש ע' 124 ואילך."],["2843","61","<b>יחו\"ע . . באחד . . ביטול היש . . באחת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381247\" data-slug=\"likkutei-torah\" data-id=\"4001381247\">לקו\"ת שה\"ש כט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381255\" data-slug=\"likkutei-torah\" data-id=\"4001381255\">לא, ג</a>."],["2845","63","<b>ראה ריח בני כריח שדה</b>: תולדות כז, כז."],["2844","62","<b>שדה היא ציון . . ברבות</b>: ראה ב\"ר פס\"ה, כג."],["2846","64","<b>ציון שדה תחרש</b>: ירמי' כו, יח."],["2847","65","<b>וירא והנה באר בשדה</b>: ויצא כט, ב."],["2848","66","<b>באר זה ציון</b>: ראה ב\"ר פ\"ע, ח."],["2849","67","<b>כי מציון תצא תורה</b>: ישעי' ב, ג. מיכה ד, ב."],["2850","68","<b>ברכה מציון</b>: נסמן בהערה הבאה."],["2851","69","<b>במד\"ר . . פך\"ד</b>: סימן ד. ראה גם סה\"מ תר\"ל כאן ס\"ע קלח. חלק הועתק בשינויים בסה\"מ תר\"ל כאן ס\"ע רי ואילך [<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010122\" data-slug=\"or-hatorah-hb\" data-id=\"8159010122\">אוה\"ת פינחס ע' א'ריח</a> ושם: שארז\"ל. ולכאורה צ\"ל כבסה\"מ תר\"ל: שאר\"ל. וכ\"ה באוה\"ת משפטים כאן ע' א'קפג]."],["2852","70","<b>ישלח עזרך</b>: תהלים כ, ג."],["2853","71","<b>זרעו . . וקצרו לפי חסד</b>: הושע י, יב [ושם: קצרו — אבל עד\"ז מובא בכ\"מ ומהם: לקמן מאמר ד\"ה וחג הקציר בכורי מעשיך על יד הערה 20. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 72. מאמרי אדה\"א ויקרא ח\"ב ע' תשטז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540801\" data-slug=\"torat-chaim\" data-id=\"2300540801\">תו\"ח וארא ח\"א פב, ב</a> ובהערה 666. סה\"מ תר\"ל כאן ע' ריא. תר\"ם ח\"א ע' שטז. ח\"ב ע' תתכא]."]]],[2001910302,"שהקצירה היא בחי' תשלום שכר שע\"י הזריעה של צדקה, ועיניך בשדה אשר יקצרון היינו שע\"י עיניך שלמטה למעלה כך נמשך למעלה וכמשארז\"ל כדרך שבא לראות<sup data-n=\"2854\">72</sup> כך בא ליראות מה לראות בשתי עינים כך מלמעלה בשתי עינים, וכתי' עיני<sup data-n=\"2856\">74</sup> ה' אל צדיקים וכתי' עין ה' אל יריאיו<sup data-n=\"2857\">75</sup> בזמן שישראל<sup data-n=\"2855\">73</sup> עושין רצוש\"מ אז עיני ה' אל צדיקים בשתי עינים ובזמן שאין עושין רש\"מ עין הוי' בעין אחת, והיינו כי עין הוא בחי' ראי' והשגחה ויש שתי בחי' השגחות ש' הוי' וש' אלקי' וכשישראל ערש\"מ נמשך ההשגחה מש' הוי' וש' אלקי' שנעשה יחוד ש' הוי' וש' אלקי', ואם אין ערש\"מ אז אינו נמשך כ\"א מש' אלקים לבד. ובזה יובן מה שחג השבועות נק' חג הקציר, והיינו לפי שבשבועות הוא מ\"ת<sup data-n=\"2858\">76</sup> ותורה נמשך מציון כי מציון תצא תורה, וע\"כ נק' חג הקציר שהוא בחי' המשכה שנמשך מלמעלה, וע\"כ בשבועות הוא קציר חטים, חטים הוא ך\"ב אתוון דאורייתא<sup data-n=\"2859\">77</sup> שהוא בחי' אתוון אחרנין<sup data-n=\"2860\">*78</sup>, כי שעורה הוא שיעור ה' הוא בחי' אותיות שנבראו בהם שמו\"א אתוון זעירין, ולכן ה' דבהבראם הוא ה' זעירא<sup data-n=\"2861\">78</sup>, אך אותיות התורה הם אתוון בינונים ואתוון רברבין, וזהו קציר חטים כו', וזהו מ\"ש וחג הקציר בכורי מעשיך שאז הוא זמן הבאת ביכורים בחי' שדה אילן כי יש שדה לבן ושדה אילן<sup data-n=\"2862\">79</sup>, והנה פסח הוא בחי' שדה הלבן בחי' שעורים, שעורים מאכל בהמה<sup data-n=\"2863\">80</sup>, משא\"כ שבועות שהיא בחי' שדה אילן, וכמ\"ש בעצרת על פירות האילן<sup data-n=\"2864\">81</sup> שהיא בחי' כי האדם עץ השדה<sup data-n=\"2865\">82</sup> אדם אדמה לעליון<sup data-n=\"2866\">83</sup> שהוא המשכה מבחי' סוכ\"ע כו', וזהו מ\"ש אח\"כ אשר תזרע בשדה<sup data-n=\"2867\">84</sup> שהקצירה נמשך מבחי' הזריעה שבתחלה, והנה הזריעה הוא בחי' אשריכם זורעי על כל מים<sup data-n=\"2868\">85</sup> וזורעי היינו בחי' מצות וכמ\"ש זרעו לכם לצדקה, אך הנה",[["2854","72","<b>כדרך שבא לראות</b>: ראה חגיגה ב, א. תוד\"ה יראה."],["2856","74","<b>עיני ה' אל צדיקים</b>: תהלים לד, יז."],["2857","75","<b>עין ה' אל יריאיו</b>: תהלים לג, יח."],["2855","73","<b>עיני . . עין . . בזמן שישראל</b>: שהש\"ר פ\"ח, יב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380811\" data-slug=\"likkutei-torah\" data-id=\"4001380811\">לקו\"ת פ' ראה כג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380812\" data-slug=\"likkutei-torah\" data-id=\"4001380812\">כד, א</a>. ג. אוה\"ת (יהל אור) תהלים ע' קכב. סה\"מ תר\"ל שבהערה 48."],["2858","76","<b>שבשבועות הוא מ\"ת</b>: ראה נוסח התפלה וקידוש לשבועות. שו\"ע אדה\"ז חאו\"ח סתצ\"ד, ס\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081021\" data-slug=\"likkutei-sichot\" data-id=\"1300081021\">לקו\"ש שבועות כרך ח ע' 21</a>."],["2859","77","<b>חטים הוא ך\"ב אתוון דאורייתא</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, א. ב)."],["2860","*78","<b>אתוון אחרנין</b>: ראה גם לקמן בשני ההנחות כאן."],["2861","78","<b>דבהבראם הוא ה' זעירא</b>: ראה זהר לך צג, א. אנציק' תלמודית מערכת ה כרך ח ע' לה הערה 121. וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010122\" data-slug=\"or-hatorah-hb\" data-id=\"8159010122\">אוה\"ת</a> בראשית כרך ג ע' 1030 ספ\"ד. ריש ע' תקטז. בלק ע' תתקיט. ישעי' כרך ג' ע' א'ריח. מאמרי אדמו\"ר הצ\"צ תרט\"ו ע' רכה. סה\"מ תרל\"ח ע' רס."],["2862","79","<b>שדה לבן ושדה אילן</b>: שביעית פ\"ב, מ\"א. מוע\"ק פ\"א, מ\"ד."],["2863","80","<b>שעורים מאכל בהמה</b>: ראה מלכים-א ה, ח. פסחים ג, סע\"ב. סוטה יד, א (במשנה)."],["2864","81","<b>בעצרת על פירות האילן</b>: ר\"ה פ\"א, מ\"ב (טז, א)."],["2865","82","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["2866","83","<b>אדם אדמה לעליון</b>: ישעי' יד, יד. ראה עבוה\"ק ח\"א חלק היחוד פי\"ז. של\"ה תולדות אדם ג, א. מאמרי אדה\"א דברים ח\"א ע' קכב. וש\"נ. בראשית ע' קסב. וש\"נ."],["2867","84","<b>אשר תזרע בשדה</b>: המשך הכתוב וחג הקציר — משפטים כג, טז."],["2868","85","<b>אשריכם זורעי על כל מים</b>: ישעי' לב, כ."]]]]});
